.global-localizations {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__title {
        margin-bottom : 32px;
        text-align    : center;
        @include break(medium) {
            font-size   : 24px;
            line-height : 26px;
        }
    }

    &__table-header-wrapper {
        background-color : $white;
        overflow         : auto;
        white-space      : nowrap;
        position         : -webkit-sticky;
        position         : sticky;
        z-index          : 2;
        top              : 86px;
        padding          : 0;
        @include break(ss-small) {
            top : 50px;
        }

        &::-webkit-scrollbar {
            width  : 0;
            height : 0;
        }
    }

    &__table-wrapper {
        overflow : auto;
        //white-space : nowrap;

        &::-webkit-scrollbar {
            width  : 0;
            height : 0;
        }
    }

    table {
        border-collapse : separate !important;
        height          : auto !important;
        width           : 100%;
        min-width       : 1200px;

        tr {
            height : auto !important;

            th, td {
                vertical-align : middle;
                border-right   : 1px solid rgba(59, 55, 230, 0.2);
                border-bottom  : 1px solid rgba(59, 55, 230, 0.2);

                &:first-child {
                    border-left : 1px solid rgba(59, 55, 230, 0.2);
                    position    : -webkit-sticky;
                    position    : sticky;
                    left        : 0;
                    z-index     : 1;
                    width       : 236px;
                    @include break(s-small) {
                        width : 170px;
                    }
                }

                &:nth-child(2) {
                    width : 160px;
                }

                &:nth-child(3) {
                    width : 130px;
                }

                &:nth-child(4) {
                    width : 130px;
                }

                &:nth-child(6) {
                    width : 160px;
                }
            }

            th {
                font-family      : $third_font;
                font-weight      : 600;
                height           : 40px !important;
                padding          : 8px 12px;
                color            : rgba(22, 33, 61, 0.6);
                background-color : $light_blue_tint;
                font-size        : 12px;
                border-top       : 1px solid rgba(59, 55, 230, 0.2);
                text-align       : left;
                line-height: 1.3;
                white-space: normal;

                &:first-child {
                    border-top-left-radius : 8px;
                    border-left            : 1px solid rgba(59, 55, 230, 0.2);
                }

                &:last-child {
                    border-top-right-radius : 8px;
                }
            }

            td {
                background-color : $white;
                height           : 90px !important;
                padding          : 12px;
                font-size        : 15px;
                line-height      : 22px;
                font-family      : $second_font;
                font-weight      : 400;
                color            : rgba(22, 33, 61, 0.7);

                p {
                    color       : rgba(22, 33, 61, 0.7);
                    font-size   : 15px;
                    line-height : 22px;
                }

                img {
                    display        : inline-block;
                    vertical-align : middle;

                    &.aligncenter {
                        display       : block;
                        margin-inline : auto;
                    }
                }

                &.text-center, &.text-center p {
                    text-align : center;
                }

                &.country-field {
                    p {
                        display     : flex;
                        align-items : center;
                    }

                    img {
                        margin-right : 8px;
                        width        : 28px;
                        min-width    : 28px;
                        max-width    : 28px;
                        height       : auto;
                    }
                }

            }

            &:last-child {
                td {
                    &:first-child {
                        border-bottom-left-radius : 8px;
                    }

                    &:last-child {
                        border-bottom-right-radius : 8px;
                    }
                }
            }
        }
    }
}

.admin-bar {
    .global-localizations {
        &__table-header-wrapper {
            top : calc(86px + 32px);
            @media only screen and (max-width : 782px) {
                top : calc(86px + 46px);
            }
            @include break(ss-small) {
                top : calc(50px + 46px);
            }
            @media only screen and (max-width : 600px) {
                top : 50px;
            }
        }
    }
}