.single-news-banner{
    margin-top: 24px;
    margin-bottom: 56px;
    @include break(medium){
        margin-bottom: 48px;
    } 
    &__wrapper{
        display: grid;
        grid-template-columns: 1fr 488px;
        min-height: 428px;
        column-gap: 20px;
        row-gap: 20px;
        @include break(desktop){
            grid-template-columns: 1fr 400px;
        }
        @include break(medium){
            grid-template-columns: 1fr 300px;
            min-height: 280px;
        }
        @include break(medium850){
            grid-template-columns: 1fr 245px;
        }
        @include break(s-small){
            grid-template-columns: 1fr;
            min-height: auto;
        }
    }
    &__content-wrapper{
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        background-color: $dark;
        border-radius: 20px; 
        padding: 24px;
        @include break(s-small){
            min-height: 310px;
            text-align: center;
        }
    }
    &__heading{
        display: flex;
        align-items: center;
        @include break(s-small){
            justify-content: center;
        }
    }
    &__type,
    &__date{
        font-size: 13px;
        line-height: 16px;
        border-radius: 10px;
        padding: 5px 15px;
        border: 1px solid;
        font-family: $third_font;
        font-weight: 600;
    }
    &__type{
        background-color: rgba($color: $purple, $alpha: 0.2);
        border-color: $purple;
        color: $purple;
        margin-right: 8px;
    }
    &__date{
        background-color: rgba($color: $white, $alpha: 0.1);
        border-color: rgba($color: $white, $alpha: 0.7);
        color: rgba($color: $white, $alpha: 0.7);
    }
    &__title{
        font-size: 40px;
        line-height: 48px;
        color: $white;
        margin-top: 24px;
        &.small{
            font-size: 32px;
            line-height: 36px;   
            @include break(medium){
                font-size: 22px;
                line-height: 28px;
            } 
        }
        @include break(medium){
            font-size: 22px;
            line-height: 28px;
        }
    }
    &__bottom{
        margin-top: 16px;
        display: flex;
        align-items: center;
    }
    &__share{
        &-text{
            font-size: 15px;
            line-height: 24px;
            margin-right: 6px;
            color: $white;
        }
        &-wrapper{
            display: flex;
            align-items: center;
        }
        &{
            width: 24px;
            height: 24px;
            display: block;
            margin: 0 6px;
            transition:.3s linear;
            transition-property: margin, transform;
            &:hover{
                transform: scale(1.3333) translateY(-3px);
                //margin: 0 12px;
            }
            svg{
                display: block;
                width: 100%;
                height: 100%;
            }
        }
    }
    &__media{
        position: relative; 
    }
    &__image{
        border-radius: 20px;
        display: block;
        width: 100%;
        height: 100%;
        object-fit: cover;
        position: absolute;
        left: 0;
        top: 0;
        @include break(s-small){
            position: initial;
            height: auto;
        }
        @include break(small-375){
            height: 280px;
        }
    }
}