.content-filter {
    margin   : 0 10px;
    height   : 48px;
    position : relative;
    z-index  : 10;

    &.category {
        width   : 219px;
        z-index : 200;
    }

    &.regions {
        width   : 195px;
        z-index : 250;
    }

    &.solutions-partners {
        width   : 236px;
        margin  : 0;
        z-index : 200;
    }

    &.locations {
        width   : 205px;
        z-index : 250;
    }

    &.careers-locations {
        width   : 205px;
        z-index : 190;
    }

    &.solutions {
        width   : 236px;
        margin  : 0;
        z-index : 200;
    }

    &.products-industries {
        width : 234px;
    }

    &__wrapper {
        border              : 1px solid $blue;
        background-color    : $light_blue_tint;
        border-radius       : 25px;
        position            : absolute;
        width               : 100%;
        left                : 0;
        top                 : 0;
        z-index             : 10;
        max-height          : 48px;
        overflow            : hidden;
        transition          : .3s linear;
        transition-property : max-height;

        &.open {
            .content-filter__heading::after {
                transform : rotate(-180deg);
            }
        }
    }

    &__heading {
        padding     : 12px 36px 12px 20px;
        font-size   : 15px;
        line-height : 24px;
        position    : relative;
        cursor      : pointer;

        * {
            pointer-events : none;
        }

        &::after {
            content             : '';
            display             : block;
            background-image    : url("data:image/svg+xml,%3Csvg width='15' height='8' viewBox='0 0 15 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath fill-rule='evenodd' clip-rule='evenodd' d='M14.7017 1.63282L8.22017 7.71985C7.82243 8.09338 7.17757 8.09338 6.77983 7.71985L0.298304 1.63282C-0.0994347 1.25929 -0.0994347 0.653679 0.298304 0.280149C0.696043 -0.093382 1.3409 -0.0933821 1.73864 0.280149L7.5 5.69084L13.2614 0.280148C13.6591 -0.0933826 14.304 -0.0933826 14.7017 0.280148C15.0994 0.653679 15.0994 1.25929 14.7017 1.63282Z' fill='%2316213D'/%3E%3C/svg%3E%0A");
            width               : 15px;
            height              : 8px;
            position            : absolute;
            right               : 20px;
            top                 : 11px;
            height              : 24px;
            background-position : center;
            background-repeat   : no-repeat;
            transition          : transform .3s linear;
        }
    }

    &__body {
        padding : 0 20px 8px;
    }

    &__list {
        &.max-height {
            max-height      : 338px;
            overflow        : auto;
            scrollbar-width : thin;
            scrollbar-color : $dark $white;

            &::-webkit-scrollbar-track {
                background-color : $white;
            }

            &::-webkit-scrollbar {
                width            : 3px;
                background-color : #F3F6FF;
            }

            &::-webkit-scrollbar-thumb {
                background-color : $dark;
            }
        }
    }

    &__item {
        &:first-child {
            .content-filter__label {
                padding-top : 0;
            }
        }

        &:last-child {
            .content-filter__label {
                padding-bottom : 0;
            }
        }

        &:not(:last-child) {
            margin-bottom : 2px;
            border-bottom : 1px solid $gret_blue;
        }

        &.active.last {
            border-bottom : 0;
        }
    }

    &__label {
        display        : block;
        padding-top    : 2px;
        padding-bottom : 2px;
        cursor         : pointer;
    }

    &__radio {
        display : none;

        &:checked ~ .content-filter__name {
            font-family : $third_font;
            font-weight : 600;
            color       : $blue;
        }
    }

    &__name {
        color       : $black;
        font-size   : 15px;
        line-height : 24px;
        transition  : color .3s linear;
    }
}

.filter-buttons {
    display         : flex;
    justify-content : center;
    @include break(x-small) {
        display               : grid;
        grid-template-columns : repeat(3, 1fr);
        grid-column-gap       : 8px;
        column-gap            : 8px;
    }

    &-news {
        display         : flex;
        grid-column-gap : 0;
        column-gap      : 0;
    }

    &__button {
        padding : 0 4px;
        @include break(x-small) {
            padding : 0;
        }

        &-news {
            padding : 0 4px;
        }
    }

    &__radio {
        display : none;

        &:checked ~ .filter-buttons__name {
            &.all {
                background-color : $blue;
                color            : $white;
            }
            &.media-coverage-il,
            &.media-coverage,
            &.events {
                color            : $white;
                background-color : $malibu;

                * {
                    color : $white;
                }
            }
            &.press-releases-il,
            &.press-releases,
            &.webinars {
                color            : $white;
                background-color : $purple;

                * {
                    color : $white;
                }
            }
        }
    }

    &__name {
        border              : 1px solid;
        border-radius       : 8px;
        padding             : 5px 31px;
        font-size           : 15px;
        line-height         : 24px;
        transition          : .3s linear;
        cursor              : pointer;
        display             : block;
        text-align          : center;
        transition-property : background-color, color;
        @include break(x-small) {
            padding : 5px;
        }

        * {
            display     : block;
            font-size   : 15px;
            line-height : 24px;
            transition  : color .2s linear;
        }

        &-news {
            padding : 5px 31px;
        }

        &-desktop {
            @include break(s-small) {
                display : none;
            }
        }

        &-mobile {
            display : none;
            @include break(s-small) {
                display : block;
            }
        }

        &.all {
            border-color     : $blue;
            background-color : $royal_blue;
        }
        &.media-coverage-il,
        &.media-coverage,
        &.events {
            border-color     : $malibu;
            background-color : $blue_tint;
        }
        &.press-releases-il,
        &.press-releases,
        &.webinars {
            border-color     : $purple;
            background-color : $purple_tint;
        }
    }
}

