        min-height: 580px;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        text-align: center;
        padding: 100px;
        overflow: hidden;
        position: relative;
        isolation: isolate;
        @include break(medium){
            padding-top: 88px;
            padding-bottom: 94px;
            padding-left: 60px;
            padding-right: 60px;
            border-radius: 25px;
            min-height: auto;
