                    width: 38vw;
                    height: 92px;
                    border-radius: 32px;
                    border-width: 1px;
                    left: -65px;
                    bottom: -44px;
                }
                @include break(medium850){
                    width: 34.767vw;
                }
                @include break(s-small){
