    }
    &__title{
        color: $white;
        max-width: 725px;
        font-family: $main_font;
        font-weight: 300;
        @include break(medium){
            max-width: 420px;
        }
        @include break(x-small){
            max-width: 215px;
        }
    }
    &__text{
        margin-top: 16px;
        max-width: 650px;
        color: $white;
        @include break(medium){
            max-width: 500px;
            margin-top: 22px;
        }
        @include break(x-small){
            max-width: 250px;
            margin-top: 12px;
            font-size: 14px;
        }
        @include break(small-375){
            max-width: 220px;
        }
    }
    &__button-wrapper{
        margin-top: 25px;
        @include break(medium){
            margin-top: 29px;
        }
        @include break(x-small){
            margin-top: 15px;
        }
    }
    &__button{
        @extend .blue-btn;
        &:hover{
            background-color: rgba($color: $blue, $alpha: 0.8);
        }
    }
}