.solutions-cards-v2 {
    background-color : $dark;
    margin-top       : $desktop_margin;
    position         : relative;
    isolation        : isolate;
    @include break(medium) {
        margin-top : $mobile_margin;
    }
    @include break(ss-small) {
        padding-top : 55px;
    }
    @include break(s-small) {
        padding-bottom : 45px;
    }

    &::before {
        content          : '';
        display          : block;
        width            : 100%;
        height           : 290px;
        z-index          : -1;
        top              : 0;
        left             : 0;
        position         : absolute;
        background-color : $white;
        @media screen and (max-width : 1280px) {
            height : 240px;
        }
        @media screen and (max-width : 1080px) {
            height : 215px;
        }
        @include break(medium) {
            height : 185px;
        }
        @include break(medium850) {
            height : 161px;
        }
        @media screen and (max-width : 767px) {
            height : 130px;
        }
        @include break(ss-small) {
            display : none;
        }
    }

    &__container {

    }

    &__wrapper {
        position        : relative;
        height          : 1210px;
        display         : flex;
        justify-content : center;
        align-items     : center;
        transition      : transform 1s cubic-bezier(0.165, 0.84, 0.44, 1);
        @media screen and (max-width : 1280px) {
            max-width : 1000px;
            height    : 1010px;
        }
        @media screen and (max-width : 1080px) {
            max-width : 900px;
            height    : 910px;
        }
        @include break(medium) {
            max-width : 770px;
            height    : 777px;
        }
        @include break(medium850) {
            max-width : 688px;
            height    : 695px;
        }
        @media screen and (max-width : 767px) {
            max-width : 550px;
            height    : 555px;
        }
        @include break(ss-small) {
            flex-direction : column;
            height         : auto;
        }
    }

    &__title {
        max-width   : 330px;
        font-size   : 35px;
        line-height : 43px;
        text-align  : center;
        color       : $white;
        @media screen and (max-width : 1080px) {
            font-size   : 28px;
            line-height : 34px;
            max-width   : 300px;
        }
        @include break(medium) {
            font-size   : 22px;
            line-height : 26px;
            max-width   : 205px;
        }
        @media screen and (max-width : 767px) {
            font-size   : 18px;
            line-height : 22px;
            max-width   : 180px;
        }
        @include break(ss-small) {
            max-width   : 260px;
            font-size   : 25px;
            line-height : 29px;
        }
    }

    .figure {
        position : absolute;
        z-index  : -1;
        @include break(ss-small) {
            display : none;
        }

        &-1 {
            width            : 152px;
            height           : 152px;
            background-color : #1C2845;
            left             : 0;
            bottom           : 163px;
            border-radius    : 50%;
            @media screen and (max-width : 1080px) {
                width  : 97px;
                height : 97px;
                bottom : 102px;
            }
        }

        &-2 {
            background-image : url("data:image/svg+xml,%3Csvg width='220' height='213' viewBox='0 0 220 213' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0 191.964C0 209.562 21.0895 218.582 33.8148 206.426L213.053 35.2101C226.097 22.7494 217.277 0.748047 199.238 0.748047H20C8.95429 0.748047 0 9.70235 0 20.748V191.964Z' fill='%231C2845'/%3E%3C/svg%3E%0A");
            width            : 220px;
            height           : 213px;
            right            : 0;
            bottom           : 90px;
            background-size  : contain;
            @media screen and (max-width : 1080px) {
                width  : 120px;
                height : 116px;
                bottom : 12px;
            }
        }
    }

    &__list {
        @include break(ss-small) {
            display               : grid;
            grid-template-columns : repeat(2, 1fr);
            row-gap               : 20px;
            column-gap            : 20px;
            margin-top            : 38px;
            width                 : 100%;
        }
        @include break(x-small) {
            grid-template-columns : 1fr;
            row-gap               : 40px;
            max-width             : 288px;
            margin-left           : auto;
            margin-right          : auto;
        }
    }

    &__card {
        position      : absolute;
        width         : 376px;
        height        : 504px;
        border-radius : 22px;
        overflow      : hidden;
        border        : 1px solid;
        @media screen and (max-width : 1280px) {
            width  : 315px;
            height : 422px;
        }
        @media screen and (max-width : 1080px) {
            width  : 283px;
            height : 380px;
        }
        @include break(medium) {
            width         : 242px;
            height        : 325px;
            border-radius : 12px;
        }
        @include break(medium850) {
            width  : 216px;
            height : 289px;
        }
        @media screen and (max-width : 767px) {
            width  : 173px;
            height : 232px;
        }
        @include break(ss-small) {
            border-radius : 16px;
            position      : relative;
            width         : 100%;
            height        : auto;
        }

        &:hover {
            .solutions-cards-v2__card-hidden {
                max-height : 200px;
            }

            .solutions-cards-v2__card-text,
            .solutions-cards-v2__card-button-wrapper {
                opacity : 1;
            }
        }

        &.blue {
            border-color : $blue;
        }

        &.purple {
            border-color : $purple;
        }

        &.coral {
            border-color : $coral;
        }

        &.light-blue {
            border-color : $light_blue;
        }

        &:nth-child(1) {
            top       : 0;
            left      : 50%;
            transform : translateX(-50%);
        }

        &:nth-child(2) {
            right : 0;
        }

        &:nth-child(3) {
            left : 0;
        }

        &:nth-child(2),
        &:nth-child(3) {
            top : 255px;
            @media screen and (max-width : 1280px) {
                top : 210px;
            }
            @media screen and (max-width : 1080px) {
                top : 190px;
            }
            @include break(medium) {
                top : 165px;
            }
            @include break(medium850) {
                top : 146px;
            }
            @media screen and (max-width : 767px) {
                top : 115px;
            }
        }

        &:nth-child(4) {
            bottom    : 0;
            left      : 50%;
            transform : translateX(-50%);
        }

        @include break(ss-small) {
            &:nth-child(1),
            &:nth-child(2),
            &:nth-child(3),
            &:nth-child(4) {
                left      : auto;
                top       : auto;
                bottom    : auto;
                right     : auto;
                transform : none;
            }
        }

        &-image-wrapper {
            position  : absolute;
            left      : 0;
            top       : 0;
            width     : 100%;
            height    : 100%;
            isolation : isolate;
            @include break(ss-small) {
                height   : auto;
                position : relative;
            }

            &::before {
                content  : '';
                display  : block;
                width    : 100%;
                height   : 100%;
                position : absolute;
                z-index  : 1;
            }

            &.blue::before {
                background-color : rgba($color : $blue, $alpha : 0.16);
            }

            &.purple::before {
                background-color : rgba($color : $purple, $alpha : 0.16);
            }

            &.coral::before {
                background-color : rgba($color : $coral, $alpha : 0.1);
            }

            &.light-blue::before {
                background-color : rgba($color : $light_blue, $alpha : 0.16);
            }
        }

        &-image {
            display    : block;
            width      : 100%;
            height     : 100%;
            object-fit : cover;
            @include break(ss-small) {
                height : auto;
            }
        }

        &-content-wrapper {
            position      : absolute;
            bottom        : 20px;
            left          : 20px;
            width         : calc(100% - 40px);
            padding       : 32px 22px;
            border-radius : 18px;
            text-align    : center;
            @media screen and (max-width : 1280px) {
                width  : calc(100% - 30px);
                bottom : 15px;
                left   : 15px;
            }
            @media screen and (max-width : 1080px) {
                width   : calc(100% - 20px);
                bottom  : 10px;
                left    : 10px;
                padding : 20px 10px;
            }
            @include break(medium) {
                width         : calc(100% - 10px);
                left          : 5px;
                border-radius : 12px;
            }
            @include break(ss-small) {
                border-radius : 16px;
                width         : calc(100% - 20px);
                bottom        : 10px;
                left          : 10px;
                padding       : 27px 15px;
            }

            &.blue {
                background-color : rgba($color : $blue, $alpha : 0.9);
            }

            &.purple {
                background-color : rgba($color : $purple, $alpha : 0.9);
            }

            &.coral {
                background-color : rgba($color : $coral, $alpha : 0.9);
            }

            &.light-blue {
                background-color : rgba($color : $light_blue, $alpha : 0.9);
            }
        }

        &-title {
            font-size   : 19px;
            line-height : 22px;
            color       : $white;
            @media screen and (max-width : 1280px) {
                font-size   : 18px;
                line-height : 20px;
            }
            @media screen and (max-width : 1080px) {
                font-size   : 14px;
                line-height : 16px;
                opacity     : 1;
            }
            @include break(ss-small) {
                font-size   : 18px;
                line-height : 22px;
            }
        }

        &-hidden {
            max-height : 0;
            transition : max-height .4s linear;
            @media screen and (max-width : 1080px) {
                max-height : none;
            }
        }

        &-text {
            padding-top      : 6px;
            font-size        : 13px;
            line-height      : 20px;
            color            : $white;
            opacity          : 0;
            transition       : opacity .3s linear;
            transition-delay : 0.1s;
            @media screen and (max-width : 1080px) {
                opacity : 1;
            }
            @include break(medium) {
                margin-top  : 2px;
                font-size   : 11px;
                line-height : 14px;
            }
            @include break(ss-small) {
                font-size   : 14px;
                line-height : 20px;
            }
        }

        &-button-wrapper {
            margin-top       : 19px;
            opacity          : 0;
            transition       : opacity .3s linear;
            transition-delay : 0.1s;
            @media screen and (max-width : 1080px) {
                opacity : 1;
            }
            @include break(medium) {
                margin-top : 10px;
            }
            @include break(ss-small) {
                margin-top : 13px;
            }
        }

        &-button {
            display             : inline-block;
            border-radius       : 13px;
            background-color    : $white;
            font-size           : 15px;
            line-height         : 24px;
            min-width           : 123px;
            padding             : 9px 15px;
            text-align          : center;
            transition          : .3s linear;
            transition-property : background-color, color;
            @include break(medium) {
                border-radius : 8px;
                font-size     : 11px;
                line-height   : 18px;
                padding       : 6px 10px;
                min-width     : 86px;
            }
            @include break(ss-small) {
                border-radius : 10px;
                color         : $blue;
                font-size     : 15px;
                line-height   : 24px;
                padding       : 7px 15px;
                min-width     : 111px;
            }

            &:hover {
                background-color : $dark;
                color            : $white;
            }
        }
    }
}