@import "../sass/_mixin";
@import "../sass/_variables";

.error-404 {
    &__wrapper {
        display         : flex;
        align-items     : center;
        justify-content : space-between;
        gap             : 80px;
        padding         : 110px 0 140px 100px;
        max-width       : 1200px;
        margin-inline   : auto;

        @include break(desktop) {
            padding : 90px 0 100px 80px;
        }

        @include break(tablet) {
            padding : 40px 0 100px 80px;
            gap     : 55px;
        }
        @include break(small) {
            padding : 40px 0 100px 30px;
            gap     : 30px;
        }

        @include break(s-small) {
            gap             : 0;
            flex-direction  : column;
            justify-content : center;
            text-align      : center;
            padding         : 40px 0 0 0;
        }

    }

    &__media {
        max-width : 432px;

        @include break(desktop) {
            max-width : 350px;
        }
        @include break(tablet) {
            max-width : 212px;
        }
        @include break(s-small) {
            max-width : 264px;
        }
    }

    &__image {
        display   : inline-block;
        width     : 100%;
        height    : auto;
        max-width : 100%;
    }

    &__content-wrapper {
        flex-basis : 0;
        flex-grow  : 1;
        max-width  : 100%;
        padding    : 32px 0;
    }

    &__subtitle {
        font-size   : 104px;
        line-height : 108px;
        @include break(tablet) {
            font-size   : 72px;
            line-height : 82px;
        }
    }

    &__title {
        font-size   : 40px;
        line-height : 64px;
        @include break(tablet) {
            font-size   : 22px;
            line-height : 34px;
        }
    }

    &__text {
        font-size   : 18px;
        line-height : 28px;
        font-weight : 400;
        @include break(tablet) {
            font-size   : 15px;
            line-height : 22px;
        }
    }

    &__button {
        &.blue-btn {
            font-size   : 20px;
            font-family : $third_font;
            padding     : 16px 40px;
            @include break(tablet) {
                font-weight : 300;
                font-size   : 15px;
                line-height : 24px;
                padding     : 10px 30px;
            }
        }


        &-wrapper {
            margin-top : 48px;
            @include break(tablet) {
                margin-top : 32px;
            }
        }
    }

}