.featured-blog{
    margin-top: $desktop_margin;
    margin-bottom: $desktop_margin;
    overflow: hidden;
    @include break(medium){
        margin-top: $mobile_margin;
        margin-bottom: $mobile_margin;
    }
    &__title{
        text-align: center;
        margin-bottom: 38px;
        @include break(medium){
            margin-bottom: 23px;
        }
        @include break(x-small){
            margin-bottom: 25px;
        }
    }
    &__slider{
        &.swiper{
            .swiper-slide{
                padding: 0 101px;
                height: auto;
                @include break(large1370){
                    padding: 0 80px;
                }
                @include break(desktop){
                    padding: 0;
                }
            }
            .swiper-button-prev, .swiper-button-next{
                width: 59px;
                height: 59px;
                svg{
                    width: 25px;
                    height: 21px;
                }
            }
            .swiper-pagination{
                margin-top: 23px;
                display: none;
                @include break(desktop){
                    display: block;
                }
                @include break(x-small){
                    margin-top: 18px;
                }
                &-bullet{
                    width: 11px;
                    height: 11px;
                    margin: 0 7px !important;
                }
            }
        }
    }
    &__slide{
        display: grid;
        height: 100%;
        grid-template-columns: 1fr 396px;
        column-gap: 33px;
        row-gap: 10px;
        border-radius: 50px;
        border: 1px solid $blue;
        background-color: $light_blue_tint;
        padding: 50px 41px 50px 45px;
        @include break(desktop){
            grid-template-columns: 1fr 500px;
        }
        @include break(tablet){
            grid-template-columns: 1fr 396px;
        }
        @include break(medium){

        }
        @include break(medium850){
            grid-template-columns: 1fr 333px;
            column-gap: 39px;
            padding: 25px 45px 25px 25px;
            border-radius: 22px;
        }
        @media screen and (max-width:767px) {
            grid-template-columns: 1fr;
            column-gap: 20px;
            padding: 18px 16px 30px 16px;
            border-radius: 28px;
        }
        &-title{
            font-size: 30px;
            line-height: 36px;
        }
        &-media{

        }
        &-image-link{
            display: block;
            position: relative;
            height: 100%;
            @include break(medium){
                min-height: 161px;
            }
            .mask,
            .figure{
                position: absolute;
                left: 0;
                top: 0;
                background-position: top left;
                background-repeat: no-repeat;
            }
            .mask{
                z-index: 10;
                background-image: url("data:image/svg+xml,%3Csvg width='146' height='151' viewBox='0 0 146 151' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cg clip-path='url(%23clip0_4549_52373)'%3E%3Cpath d='M0.0501941 285.015L0 151.5C0.0100388 143.308 3.46339 135.138 9.12529 129.212L123.237 9.87617C129.27 3.56946 137.622 0 146.356 0H0V317L23 314.5C5.32164 314.5 0.0200776 302.672 0.0501941 285.015Z' fill='%23F3F6FF'/%3E%3C/g%3E%3Cdefs%3E%3CclipPath id='clip0_4549_52373'%3E%3Crect width='146' height='151' fill='white'/%3E%3C/clipPath%3E%3C/defs%3E%3C/svg%3E%0A");
                width: 146px;
                height: 151px;
                left: -1px;
                top: -1px;
                @include break(medium){
                    background-image: url("data:image/svg+xml,%3Csvg width='75' height='78' viewBox='0 0 75 78' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0.00937754 33L0.152553 77.021C0.157666 72.8485 1.7735 68.8343 4.65745 65.8159L62.7814 5.03055C65.8546 1.81815 70.1089 0 74.5576 0H0.00937754L0.00401122 35.5C0.0172442 37 -0.00596265 41.9937 0.00937754 33Z' fill='%23F3F6FF'/%3E%3C/svg%3E");
                    width: 75px;
                    height: 78px;
                }
                @include break(x-small){
                    background-image: url("data:image/svg+xml,%3Csvg width='93' height='97' viewBox='0 0 93 97' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M78.7452 6.13553C82.4706 2.21547 87.6149 0 93 0H0V97C0 91.8609 1.96549 86.9242 5.49035 83.2166L78.7452 6.13553Z' fill='%23F3F6FF'/%3E%3C/svg%3E%0A");
                    width: 93px;
                    height: 97px;
                }
            }
            .figure{
                z-index: 20;
                background-image: url("data:image/svg+xml,%3Csvg width='104' height='107' viewBox='0 0 104 107' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M29.9971 0.121086L96.9136 0.121092C103.103 0.121093 106.247 7.5639 101.932 12.0011L12.0156 104.468C7.63501 108.973 -0.00284738 105.872 -0.00284683 99.5884L-0.00284076 30.1211C-0.00283931 13.5525 13.4286 0.121085 29.9971 0.121086Z' fill='%233B37E6'/%3E%3C/svg%3E%0A");
                width: 104px;
                height: 107px;
                @include break(medium){
                    background-image: url("data:image/svg+xml,%3Csvg width='54' height='56' viewBox='0 0 54 56' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M16.1234 0.937496L50.3207 0.937499C53.4836 0.9375 55.0904 4.74111 52.8853 7.00873L6.93405 54.2636C4.69535 56.5658 0.792075 54.9809 0.792075 51.7697L0.792079 16.2688C0.792079 7.80156 7.65616 0.937496 16.1234 0.937496Z' fill='%233B37E6'/%3E%3C/svg%3E");
                    width: 54px;
                    height: 56px;
                }
                @include break(x-small){
                    background-image: url("data:image/svg+xml,%3Csvg width='66' height='68' viewBox='0 0 66 68' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M18.9998 -4.6225e-06L61.3802 -9.17487e-07C65.3 -5.74803e-07 67.2913 4.71378 64.5585 7.52403L7.61147 66.0867C4.83707 68.9398 -0.000234737 66.9756 -0.000234389 62.996L-0.000230543 19C-0.000229626 8.50658 8.50636 -5.53986e-06 18.9998 -4.6225e-06Z' fill='%233B37E6'/%3E%3C/svg%3E%0A");
                    width: 66px;
                    height: 68px;
                }
            }
        }
        &-image{
            display: block;
            width: 100%;
            height: 100%;
            object-fit: cover;
            border-radius: 32px;
            @include break(tablet){
                border-radius: 15px;
            }
            @include break(s-small){
                border-radius: 20px;
            }
        }
        &-content-wrapper{
            display: flex;
            flex-direction: column;
            justify-content: space-between;
        }
        &-content{
            @include break(medium850){
                max-width: 310px;
            }
            @include break(s-small){
                max-width: none;
                padding-right: 24px;
            }
        }
        &-media-cat{
            text-align: center;
            display: inline-block;
            padding: 3px 15px;
            border: 1px solid;
            font-size: 13px;
            line-height: 20px;
            border-radius: 10px;
            @include break(medium){
                font-size: 12px;
                line-height: 19px;
            }
            @include break(x-small){
                border-radius: 6px;
                padding: 2px 8px;
                font-size: 8px;
                line-height: 12px;
            }
        }
        &-title{
            margin-top: 18px;
            color: $blue;
            transition: color .3s linear;
            @include break(medium){
                margin-top: 16px;
            }
            @include break(s-small){
                min-height: 87px;
                margin-top: 11px;
            }
            @include break(x-small){
                min-height: 66px;
            }
            &:hover{
                color: $dark;
            }
            a{
                @extend .inherit;
            }
        }
        &-content-bottom{
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-top: 10px;

            @include break(medium){
                margin-top: 16px;
            }
            @include break(s-small){
                margin-top: 22px;
            }
            .single-banner {
                &__bottom {
                    margin-top: 0;
                }
                &__share {
                    &-text {
                        color : $black;
                    }
                    &-wrapper {
                        svg path {
                            fill : $black;
                        }
                    }
                }
            }
        }
        &-link{
            @extend .arrow-btn-right;
        }

        .blog-card__author {
            margin-top: 10px;
        }
    }
  
}