.simple-text-banner{
    margin-top: $desktop_margin;
    margin-bottom: $desktop_margin;
    @include break(medium){
        margin-top: $mobile_margin;
        margin-bottom: $mobile_margin;
    }

    &.has-navigation{
        margin-top: 25px;
        @include break(medium){
            margin-top: 20px;
        }
        @include break(s-small){
            margin-top: 16px;
        }
    }
    .breadcrumbs,
    .return-back-link{
        margin-bottom: 10px;
        max-width: 1260px;
        margin-left: auto;
    }
    &__wrapper{
        background-color: $blue;
        border-radius: 30px;
        display: flex;
        justify-content: center;
        align-items: center;
        padding: 65px 45px;
        min-height: 260px;
        position: relative;
        isolation: isolate;
        @include break(medium){
            padding: 82px 20px 70px;
        }
        @include break(x-small){
            padding: 88px 20px;
        }
        .figure,
        .mask{
            position: absolute;
            z-index: -1;
            right: 0;
            bottom: 0;
            background-repeat: no-repeat;
            background-position: bottom right;
        }
        .mask{
            background-image: url("data:image/svg+xml,%3Csvg width='139' height='134' viewBox='0 0 139 134' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M139 0.5C139 8.71837 135.636 16.5775 129.692 22.2457L21.1916 125.713C15.6131 131.033 8.20425 134 0.5 134H139V0.5Z' fill='%23FFFFFF'/%3E%3C/svg%3E%0A");
            width: 139px;
            height: 134px;
            right: -1px;
            bottom: -1px;
        }
        .figure{
            background-image: url("data:image/svg+xml,%3Csvg width='96' height='95' viewBox='0 0 96 95' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M95.5 5.93553L95.5 76.6568C95.5 86.5113 87.5113 94.5 77.6568 94.5L6.11524 94.5C1.74267 94.5 -0.43609 89.2035 2.67083 86.1267L87.1605 2.45735C90.2511 -0.603197 95.5 1.58599 95.5 5.93553Z' fill='%23D7F7FF' stroke='%235ED0F9'/%3E%3C/svg%3E%0A");
            width: 96px;
            height: 95px;
        }
    }
    &__title{
        font-size: 60px;
        line-height: 62px;
        color: $white;
        text-align: center;
        @include break(medium){
            max-width: 450px;
            font-size: 50px;
            line-height: 52px;
        }
        @include break(s-small){
            font-size: 35px;
            line-height: 37px;
        }
    }
}