.single-resources {
    .related-resources {
        margin-top    : $desktop_margin;
        margin-bottom : $desktop_margin;
        @include break(medium) {
            margin-top    : $mobile_margin;
            margin-bottom : $mobile_margin;
        }
    }
}

.related-resources {
    $self: &;
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__wrapper {
        max-width    : 1200px;
        margin-left  : auto;
        margin-right : auto;
    }

    &__title {
        max-width     : 500px;
        margin-left   : auto;
        margin-right  : auto;
        margin-bottom : 40px;
        text-align    : center;
        @include break(medium) {
            margin-bottom : 27px;
        }
        @include break(x-small) {
            margin-bottom : 30px;
            font-size: 22px;
            line-height: 28px;
            font-weight: 600;
        }
    }

    &__slider {
        .swiper-pagination {
            display    : none;
            margin-top : 30px;
            @include break(s-small) {
                display : block;
            }
        }

        .swiper-slide {
            @include break(s-small) {
                height : auto;
            }
        }
    }

    &__list {
        @media screen and (min-width : 571px) {
            display               : grid;
            grid-template-columns : repeat(3, 1fr);
            column-gap            : 14px;
        }
        @media screen and (min-width : 992px) {
            column-gap : 20px;
        }
    }

    .resources-card {
        height : 100%;
    }

    &__button-wrapper {
        margin-top : 49px;
        text-align : center;
        @include break(medium) {
            margin-top : 40px;
        }
        @include break(x-small) {
            margin-top : 34px;
        }
    }

    &__button {
        @extend .blue-btn;
    }

    &.colored {
        padding: 40px 0 60px;
        margin: 0;

        #{ $self }__title {
            color: $white;
        }
        .resources-card {
            border: 1px solid rgba(141, 157, 181, 0.60);
            background: rgba(37, 47, 89, 0.70);

            &__link,
            &__title {
                color: $white;

                &:hover {
                    opacity: 0.8;
                }
            }
            &__link {
                &::after {
                    background-image : url("data:image/svg+xml,%3Csvg width='8' height='11' viewBox='0 0 8 11' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1.5 10L7.5 5.5L1.5 1' stroke='%23ffffff' stroke-width='1.3' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E%0A");
                }
            }
        }
    }
}