.styled-side-image-content {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &.blue {
        .styled-side-image-content__wrapper {
            border-color     : $blue;
            background-color : $blue_tint;
        }

        img {
            border-color : $blue;
        }

        .styled-side-image-content__title {
            color : $blue;
        }
    }

    &.coral {
        .styled-side-image-content__wrapper {
            border-color     : $coral;
            background-color : $coral_tint;
        }

        img {
            border-color : $coral;
        }

        .styled-side-image-content__title {
            color : $coral;
        }
    }

    &.purple {
        .styled-side-image-content__wrapper {
            border-color     : $purple;
            background-color : $purple_tint;
        }

        img {
            border-color : $purple;
        }

        .styled-side-image-content__title {
            color : $purple;
        }
    }

    &.light-blue {
        .styled-side-image-content__wrapper {
            border-color     : $light_blue;
            background-color : $light_blue_tint;
        }

        img {
            border-color : $light_blue;
        }

        .styled-side-image-content__title {
            color : $light_blue;
        }
    }

    &__wrapper {
        display         : flex;
        justify-content : space-between;
        padding         : 23px 51px 23px 23px;
        border-radius   : 50px;
        border          : 1px solid;
        @include break(medium) {
            padding       : 14px 44px 14px 14px;
            border-radius : 29px;
        }
        @include break(medium850) {
            padding : 18px 28px 18px 18px;
        }
        @include break(s-small) {
            padding        : 15px 15px 43px 15px;
            border-radius  : 20px;
            flex-direction : column;
        }
    }

    &__media {
        width    : 50.4%;
        position : relative;
        @include break(medium) {
            width      : 49.22%;
            min-height : 392px;
        }
        @include break(s-small) {
            width         : 100%;
            margin-bottom : 33px;
            min-height    : auto;
        }

        img {
            border        : 1px solid;
            border-radius : 37px;
            object-fit    : cover;
            width         : 100%;
            height        : 100%;
            @include break(s-small) {
                border-radius : 20px;
            }
        }
    }

    &__image {
        display  : block;
        width    : 100%;
        height   : 100%;
        position : absolute;
        left     : 0;
        top      : 0;
        @include break(s-small) {
            height        : auto;
            border-radius : 20px;
            position      : relative;
        }
    }

    &__content-wrapper {
        width        : 46.8%;
        display      : flex;
        align-items  : center;
        padding-left : 20px;
        @include break(medium) {
            width        : 50.78%;
            padding-left : 15px;
        }
        @include break(s-small) {
            width        : 100%;
            padding-left : 0;
        }
    }

    &__content {
        padding-left   : 25px;
        padding-top    : 30px;
        padding-bottom : 30px;
        @include break(tablet) {
            padding-top    : 17px;
            padding-bottom : 17px;
            padding-left   : 20px;
        }
        @include break(s-small) {
            padding : 0 9px;
        }
    }

    &__title {
        margin-bottom : 29px;
        font-family   : $main_font;
        font-weight   : 400;
        @include break(medium) {
            margin-bottom : 15px;
        }
        @include break(s-small) {
            text-align    : center;
            margin-bottom : 23px;
        }
        @include break(x-small) {
            font-size     : 20px;
            line-height   : 23px;
            padding-left  : 13px;
            padding-right : 13px;
        }
    }

    &__text {
        &.big {
            li:not(:last-child) {
                margin-bottom : 28px;
                @include break(medium) {
                    margin-bottom : 20px;
                }
            }
        }

        @include break(s-small) {
            padding-left : 25px;
        }

        p, li {
            font-size   : 16px;
            line-height : 24px;
        }

        li {
            padding-left : 0;

            &:not(:last-child) {
                margin-bottom : 15px;
            }

            &::before {
                left : -13px;
                top  : 12px;
            }
        }

        ul, ol {
            &:last-child {
                margin-bottom : 0;
            }
        }
    }
}