.cky-btn-revisit-wrapper {
    background-color : $blue !important;
}

.cky-consent-container {
    border-radius : 20px !important;
    width         : 430px !important;
    transition    : opacity .3s linear;

    &.active {
        visibility : visible;
        opacity    : 1;
    }

    @include break(x-small) {
        width         : 100% !important;
        border-radius : 0 !important;
    }

    &.cky-box-bottom-left {
        left      : 15px;
        bottom    : 24px;
        isolation : isolate;

        @include break(x-small) {
            left      : 16px;
            bottom    : 23px;
            max-width : calc(100% - 32px) !important;

            &::before {
                content    : '';
                display    : block;
                width      : 100vw;
                left       : -16px;
                bottom     : -23px;
                position   : absolute;
                z-index    : -1;
                background : linear-gradient(0.85deg, #FFFFFF -12.02%, rgba(255, 255, 255, 0) 93.59%);
                height     : calc(100% + 133px);
            }
        }
    }

    .cky-consent-bar {
        background    : $dark !important;
        border-color  : $dark !important;
        color         : $white !important;
        box-shadow    : none !important;
        border        : none;
        padding       : 25px 30px 20px 30px !important;
        border-radius : 20px !important;

        @include break(x-small) {
            border-radius : 30px !important;
            padding       : 28px 35px 25px 35px !important;
        }
    }

    .cky-notice {
        .cky-title {
            color         : $white !important;
            font-weight   : 600;
            font-size     : 16px;
            line-height   : 20px;
            text-align    : center;
            padding-left  : 0 !important;
            padding-right : 0 !important;

            @include break(x-small) {
                font-size     : 22px;
                line-height   : 28px;
                margin-bottom : 13px;
            }
        }

        .cky-notice-group {
            font-style  : 14px;
            line-height : 20px;
            color       : $white;
            font-weight : 300;

            .cky-notice-des {
                color         : $white !important;
                padding-left  : 0 !important;
                padding-right : 0 !important;

                @include break(x-small) {
                    text-align : center;
                }

                p {
                    font-size   : 14px;
                    line-height : 19px;
                    color       : $white;
                }
            }
        }

        .cky-notice-btn-wrapper {
            margin-top : 35px;
            gap        : 20px;

            @include break(x-small) {
                padding-left    : 0 !important;
                padding-right   : 0 !important;
                flex-direction  : initial;
                flex-wrap       : wrap;
                justify-content : center;
                gap             : 20px 16px;
            }

            .cky-btn {
                font-size     : 15px;
                line-height   : 24px;
                margin        : 0;
                color         : $white !important;
                padding       : 6px 10px;
                border        : 1px solid $white !important;
                border-radius : 10px;
                transition    : opacity .3s linear;

                @include break(x-small) {
                    width   : auto;
                    padding : 6px 14px;
                    order   : initial;
                    flex    : none;
                }

                &:last-child {
                    margin : 0;
                }

                &.cky-btn-accept {
                    background   : $blue;
                    border-color : $blue !important;
                }
            }
        }
    }
}

div[data-cky-tag="detail-powered-by"] {
    display : none !important;
}

.cky-overlay {
    background : #16213D !important;

    @include break(x-small) {
        opacity : 0.7;
    }
}

.cky-footer-shadow {
    background : linear-gradient(0deg, #16213D 30.1%, rgba(22, 33, 61, 0) 100%) !important;
}

.cky-modal {
    border-radius    : 20px !important;
    background-color : $dark !important;
    color            : $white !important;

    @media (max-width : 576px) {
        max-width  : 90% !important;
        box-shadow : 0px -20px 26px rgba(22, 33, 61, 0.5) !important;
    }

    .cky-preference-center {
        background-color : $dark !important;
        color            : $white !important;
        border-color     : $dark !important;
        border-radius    : 20px !important;

        @media (max-width : 576px) {
            max-height : 90vh;
        }
    }

    .cky-preference-header {
        padding         : 45px 62px 24px 62px;

        @include break(ss-small) {
            padding : 45px 30px 24px 30px;
        }
        @include break(x-small) {
            padding : 56px 30px 20px 30px;
        }
        text-align      : center;
        position        : relative;
        justify-content : center;

        .cky-preference-title {
            color       : $white !important;
            font-weight : 600;
            font-size   : 16px;
            line-height : 20px;
            font-family : $second_font;

            @include break(x-small) {
                font-size   : 22px;
                line-height : 28px;
            }
        }

        .cky-btn-close {
            position            : absolute;
            right               : 16px;
            top                 : 16px;
            width               : 18px;
            height              : 18px;
            background-image    : url("data:image/svg+xml,%3Csvg width='18' height='19' viewBox='0 0 18 19' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cg clip-path='url(%23clip0_4903_53235)'%3E%3Cpath d='M0.515625 0.503906L17.5475 17.5358' stroke='white'/%3E%3Cpath d='M17.5469 0.503909L0.515025 17.5358' stroke='white'/%3E%3C/g%3E%3Cdefs%3E%3CclipPath id='clip0_4903_53235'%3E%3Crect width='18' height='18' fill='white' transform='translate(0 0.0195312)'/%3E%3C/clipPath%3E%3C/defs%3E%3C/svg%3E%0A") !important;
            background-size     : cover;
            background-position : center;
            background-repeat   : no-repeat;

            @include break(x-small) {
                right : 22px;
                top   : 22px;
            }

            img {
                display : none !important;
            }
        }
    }

    .cky-preference-body-wrapper {
        padding : 0 62px;

        @include break(ss-small) {
            padding : 0 30px;
        }

        &::-webkit-scrollbar {
            background-color : $gret_blue;
            width            : 10px;
        }

        &::-webkit-scrollbar-thumb {
            background-color : $white;
        }

        .cky-preference-content-wrapper {
            border-color : rgba($color : #D7F7FF, $alpha : 0.3);
            padding      : 20px 4px;
            font-size    : 14px;
            line-height  : 20px;
            color        : $white !important;

            @include break(x-small) {
                padding : 14px 0;
            }

            strong {
                color : $white!important;
            }

            * {
                font-size   : 14px;
                line-height : 20px;
                max-width   : 665px;

                @include break(x-small) {
                    font-size   : 13px;
                    line-height : 18px;
                }
            }

            .cky-show-desc-btn {
                font-size   : 14px !important;
                line-height : 20px;
                font-family : $second_font;
                font-weight : 600;
                color       : $gret_blue !important;
                border      : none !important;

                @include break(x-small) {
                    font-size   : 13px !important;
                    line-height : 18px !important;
                }
            }
        }
    }

    .cky-accordion-wrapper {
        .cky-accordion {
            border-color : rgba($color : #D7F7FF, $alpha : 0.3);

            &#ckyDetailCategorynecessary {
                padding-top : 9px;
            }

            .cky-accordion-chevron i {
                color : $white !important;

                &::before {
                    @include break(x-small) {
                        top : 18px;
                    }
                }
            }

            .cky-accordion-item {
                margin-top : 20px;
                @include break(x-small) {
                    margin-top : 0;
                }

                .cky-accordion-chevron {
                    margin        : 0;
                    padding-right : 22px;
                }

                .cky-accordion-header-wrapper {
                    .cky-accordion-header {
                        @include break(x-small) {
                            padding-top    : 10px;
                            padding-bottom : 10px;
                            padding-right  : 5px;
                            margin-bottom  : 18px;
                        }

                        .cky-accordion-btn {
                            color       : $white !important;
                            font-size   : 16px;
                            line-height : 20px;
                            font-family : $second_font;
                            font-weight : 600;

                            @include break(x-small) {
                                font-size   : 15px;
                                line-height : 19px;
                            }
                        }

                        .cky-always-active {
                            color       : $white;
                            font-family : $second_font;
                        }

                    }

                    .cky-accordion-header-des {
                        max-width   : 665px;
                        color       : $white !important;
                        font-size   : 14px;
                        line-height : 20px;
                        margin-top  : 0;

                        @include break(x-small) {
                            margin-bottom : 20px;
                        }

                        p {
                            font-size   : 14px;
                            line-height : 20px;

                            @include break(x-small) {
                                font-size   : 13px;
                                line-height : 18px;
                            }
                        }
                    }
                }

            }

            .cky-audit-table {
                background    : transparent !important;
                border-radius : 0 !important;
                color         : $white !important;

                * {
                    color       : $white;
                    font-size   : 14px;
                    line-height : 20px;
                }
            }

        }
    }

    .cky-switch input[type="checkbox"] {
        width            : 39px;
        height           : 19px;
        background-color : $gret_blue !important;
        border           : 1px solid $light_blue !important;

        &::before {
            width  : 15px;
            height : 15px;
            left   : 2px;
            bottom : 1px;
        }

        &:checked::before {
            background-color : $blue;
            transform        : translateX(19px);
        }
    }

    .cky-prefrence-btn-wrapper {
        padding : 0 62px 30px 62px;
        gap     : 25px 20px;

        @include break(ss-small) {
            padding : 0 30px 30px 30px;
        }
        @media (max-width : 576px) {
            justify-content : center;
            padding         : 0 30px 48px 30px;
        }

        .cky-btn {
            flex                : none;
            margin              : 0;
            font-size           : 15px;
            line-height         : 24px;
            color               : $white !important;
            padding             : 6px 19px;
            border              : 1px solid $white !important;
            border-radius       : 10px;
            opacity             : 1 !important;
            transition          : .3s linear;
            transition-property : background-color, color;

            &:hover {
                background-color : $white !important;
                color            : $blue !important;
            }

            @media (max-width : 576px) {
                width : auto;
                order : inherit;
            }

            &.cky-btn-preferences {
                @media (max-width : 576px) {
                    order : 1;
                }
            }

            &.cky-btn-reject {
                @media (max-width : 576px) {
                    order : 2;
                }
            }

            &.cky-btn-accept {
                background   : $blue;
                border-color : $blue !important;

                @media (max-width : 576px) {
                    order : 3;
                }

                &:hover {
                    color            : $white !important;
                    border-color     : rgba($color : $blue, $alpha : 0.8) !important;
                    background-color : rgba($color : $blue, $alpha : 0.8) !important;
                }
            }
        }
    }
}