.anchor-menu {
    padding-top    : 30px;
    padding-bottom : 20px;
    @include break(medium) {
        margin-top    : 21px;
        margin-bottom : 17px;
    }
    @include break(s-small) {
        margin-top    : 20px;
        margin-bottom : 30px;
    }

    &__wrapper {
        display         : flex;
        justify-content : flex-start;
        gap             : 20px;
        flex-wrap       : wrap;
        @include break(medium) {
            padding : 0;
        }
        @include break(x-small) {
            display               : grid;
            grid-template-columns : repeat(2, 1fr);
            gap                   : 16px;
        }
    }

    &__btn {
        flex                : 1 0 172px;
        max-width           : 172px;
        padding             : 6px 10px;
        font-size           : 16px;
        text-align          : center;
        line-height         : 24px;
        background-color    : $royal_blue;
        color               : $blue;
        transition          : .3s linear;
        transition-property : background-color, color;
        border-radius       : 8px;
        display             : flex;
        justify-content     : center;
        align-items         : center;
        @include break(x-small) {
            max-width : none;
        }
        @include break(small-360) {
            font-size   : 12px;
            line-height : 15px;
            padding     : 0 5px;
            height      : 36px;
        }

        &[data-role="scroll-to"] {
            cursor : pointer;
        }

        // &:first-child{
        //   background-color: $blue;
        //   color: $white;
        //   &[data-role="scroll-to"]:hover{
        //     background-color: $dark;
        //   }
        // }
        @at-root {
            a#{&} {
                &.active,
                &:hover {
                    background-color : $blue;
                    color            : $white;
                    text-decoration  : none !important;
                }
            }
        }
        &.active,
        &:hover {
            background-color : $blue;
            color            : $white;

        }
    }

    &.sticky {
        position         : sticky;
        top              : 80px;
        z-index          : 8000;
        background-color : #fff;
        @include break(s-small) {
            top : 40px;
        }
    }
}

body.admin-bar .anchor-menu.sticky {
    top : 112px;
}