.all-resources__card .popup,
#set-a-meeting-popup,
#content-calculator-popup,
#demoform-banner-popup,
#webinar-form-popup,
#content-banner-popup,
#gated-content-form-popup {
    .popup-wrapper-inner {
        background-color : $dark;
        padding          : 40px 24px;
        border-radius    : 20px;
        isolation        : isolate;
        overflow         : hidden;
        max-width        : 635px;
        width            : 100%;
        @include break(small) {
            max-width  : 95%;
            margin-top : 70px;
        }

        button.popup-close {
            background-image    : url("data:image/svg+xml,%3Csvg width='19' height='19' viewBox='0 0 19 19' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1L18.0318 18.0318M18.0319 1L1.00002 18.0318' stroke='white'/%3E%3C/svg%3E%0A");
            width               : 20px;
            height              : 20px;
            background-position : center;
            background-repeat   : no-repeat;
            top                 : 20px;
            right               : 20px;
            transition          : opacity .4s linear;
        }

        .figure {
            position          : absolute;
            z-index           : -1;
            background-repeat : no-repeat;

            &-1 {
                background-image : url("data:image/svg+xml,%3Csvg width='150' height='88' viewBox='0 0 150 88' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath opacity='0.6' d='M58.0088 74.8C58.0088 82.0901 52.1098 88 44.833 88L-54.8242 88C-62.101 88 -68 82.0901 -68 74.8L-68 -32C-68 -39.2902 -62.101 -45.2 -54.8242 -45.2L18.6011 -45.2C21.578 -45.2 23.9912 -47.6177 23.9912 -50.6C23.9912 -53.5823 26.4045 -56 29.3813 -56L136.824 -56C144.101 -56 150 -50.0901 150 -42.8V16.48C150 23.7702 144.101 29.68 136.824 29.68L71.1846 29.68C63.9078 29.68 58.0088 35.5898 58.0088 42.88V74.8Z' fill='white' fill-opacity='0.2'/%3E%3C/svg%3E%0A");
                width            : 150px;
                height           : 88px;
                left             : 0;
                top              : 0;
                @include break(ss-small) {
                    left : -35px;
                }
            }

            &-2 {
                background-image : url("data:image/svg+xml,%3Csvg width='92' height='86' viewBox='0 0 92 86' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M88.9375 1H53.0625C24.3092 1 1 26.1273 1 57.1234V115.877C1 146.873 24.3092 172 53.0625 172H88.9375C117.691 172 141 146.873 141 115.877V57.1234C141 26.1273 117.691 1 88.9375 1Z' stroke='white' stroke-miterlimit='10'/%3E%3Cpath d='M82.7242 29.5075H59.2704C39.9772 29.5075 24.337 46.3677 24.337 67.1657V105.829C24.337 126.627 39.9772 143.487 59.2704 143.487H82.7242C102.017 143.487 117.658 126.627 117.658 105.829V67.1657C117.658 46.3677 102.017 29.5075 82.7242 29.5075Z' stroke='white' stroke-miterlimit='10'/%3E%3Cpath d='M76.521 58.5432H65.4837C56.407 58.5432 49.0489 66.4752 49.0489 76.2599V94.4584C49.0489 104.243 56.407 112.175 65.4837 112.175H76.521C85.5977 112.175 92.9558 104.243 92.9558 94.4584V76.2599C92.9558 66.4752 85.5977 58.5432 76.521 58.5432Z' stroke='white' stroke-miterlimit='10'/%3E%3C/svg%3E%0A");
                width            : 92px;
                height           : 86px;
                right            : 0;
                bottom           : 0;
                @include break(ss-small) {
                    background-size : contain;
                    width           : 45px;
                    height          : 42px;
                }
            }
        }

        .priority-title {
            text-align : center;
            color      : $white;
        }

        .priority-text {
            text-align  : center;
            color       : $white;
            font-size   : 16px;
            line-height : 24px;
            margin-top  : 8px;
        }

        .priority-form {
            margin-top : 32px;

            &.hbspt-form {
                .hs_error_rollup {
                    text-align : center;
                }

                .hs-recaptcha {
                    display : none !important;
                }

                .hs-error-msgs {
                    .hs-main-font-element,
                    .hs-error-msg {
                        color       : $red;
                        font-size   : 12px;
                        line-height : 14px;
                    }
                }

                fieldset {
                    max-width       : 100% !important;
                    display         : flex;
                    justify-content : center;
                    gap             : 16px;
                    @include break(ss-small) {
                        flex-direction : column;
                        gap            : 0;
                    }

                    &.form-columns-0 {
                        margin-bottom : 16px;
                    }

                }

                .hs-form-field {
                    margin-bottom : 16px;
                    //width: 50%;
                    @include break(ss-small) {
                        width : 100%;
                    }

                    & > label {
                        display : none;
                    }

                    .input {
                        margin : 0;
                    }

                    input[type="text"],
                    input[type="email"],
                    input[type="tel"] {
                        height        : 48px;
                        width         : 100% !important;
                        padding       : 10px 16px;
                        font-size     : 13px;
                        line-height   : 16px;
                        color         : $dark;
                        border        : 1px solid rgba(22, 33, 61, 0.1);
                        border-radius : 10px;

                        &.error {
                            border-color : $red;
                        }

                        &::placeholder {
                            color : rgba(22, 33, 61, 0.4);
                        }
                    }

                    textarea {
                        width         : 100% !important;
                        padding       : 10px 16px;
                        height        : 96px;
                        font-size     : 13px;
                        line-height   : 16px;
                        color         : $dark;
                        border        : 1px solid rgba(22, 33, 61, 0.1);
                        border-radius : 10px;
                        resize        : none;

                        &.error {
                            border-color : $red;
                        }

                        &::placeholder {
                            color : rgba(22, 33, 61, 0.4);

                        }
                    }

                    select {
                        height              : 48px;
                        width               : 100%;
                        padding             : 10px 35px 10px 16px;
                        font-size           : 13px;
                        line-height         : 16px;
                        color               : $dark;
                        border              : 1px solid rgba(22, 33, 61, 0.1);
                        border-radius       : 10px;
                        -moz-appearance     : none; /* Firefox */
                        -webkit-appearance  : none; /* Safari and Chrome */
                        appearance          : none;
                        background-image    : url("data:image/svg+xml,%3Csvg width='14' height='8' viewBox='0 0 14 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M13 1L7 7L1 0.999999' stroke='%2316213D'/%3E%3C/svg%3E%0A");
                        background-position : center right 19px;
                        background-repeat   : no-repeat;

                        &:focus {
                            background-image : url("data:image/svg+xml,%3Csvg width='14' height='8' viewBox='0 0 14 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 7L7 1L13 7' stroke='%2316213D'/%3E%3C/svg%3E");
                        }

                        &.error {
                            border-color : $red;
                        }

                        &::placeholder {
                            color : rgba(22, 33, 61, 0.4);
                        }
                    }

                    &.hs-fieldtype-textarea {
                        width : 100% !important;
                    }

                    .hs-form-booleancheckbox {
                        label span {
                            color       : #fff;
                            display     : block;
                            font-size   : 13px;
                            line-height : 18px;
                        }
                    }
                    + .hs-dependent-field {
                        width : 50%;

                        @include break(ss-small) {
                            width : 50%;
                        }
                    }
                }

                .hs-dependent-field {
                    display         : flex;
                    justify-content : center;
                    gap             : 16px;
                    width           : 100%;
                    @include break(ss-small) {
                        flex-direction : column;
                        gap            : 0;
                    }

                    .hs-form-field {
                        width : 100%;
                    }
                }

                .legal-consent-container {
                    display : block;

                    .hs-form-field {
                        width : 100%;
                    }
                }

                .inputs-list {
                    .hs-form-booleancheckbox {
                        &:not(:first-child) {
                            margin-bottom : 16px;
                        }
                    }

                    .hs-form-booleancheckbox-display {
                        input[type="checkbox"] {
                            display : none !important;

                            &:checked ~ span::before {
                                background-image : url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M2 0C1.46957 0 0.960859 0.210714 0.585786 0.585786C0.210714 0.960859 0 1.46957 0 2L0 14C0 14.5304 0.210714 15.0391 0.585786 15.4142C0.960859 15.7893 1.46957 16 2 16H14C14.5304 16 15.0391 15.7893 15.4142 15.4142C15.7893 15.0391 16 14.5304 16 14V2C16 1.46957 15.7893 0.960859 15.4142 0.585786C15.0391 0.210714 14.5304 0 14 0L2 0ZM12.03 4.97C12.1689 5.10875 12.2479 5.29644 12.2499 5.49275C12.252 5.68907 12.177 5.87837 12.041 6.02L8.049 11.01C7.98039 11.0839 7.89758 11.1432 7.80553 11.1844C7.71348 11.2255 7.61407 11.2477 7.51325 11.2496C7.41243 11.2514 7.31227 11.233 7.21876 11.1952C7.12524 11.1575 7.0403 11.1013 6.969 11.03L4.324 8.384C4.25031 8.31534 4.19121 8.23254 4.15022 8.14054C4.10923 8.04854 4.08718 7.94923 4.08541 7.84852C4.08363 7.74782 4.10216 7.64779 4.13988 7.5544C4.1776 7.46101 4.23374 7.37618 4.30496 7.30496C4.37618 7.23374 4.46101 7.1776 4.5544 7.13988C4.64779 7.10216 4.74782 7.08363 4.84852 7.08541C4.94923 7.08718 5.04854 7.10923 5.14054 7.15022C5.23254 7.19121 5.31534 7.25031 5.384 7.324L7.478 9.417L10.951 4.992C11.0195 4.91797 11.1022 4.85851 11.1942 4.81717C11.2861 4.77583 11.3855 4.75347 11.4863 4.75141C11.5871 4.74936 11.6873 4.76766 11.7809 4.80522C11.8745 4.84277 11.9596 4.89882 12.031 4.97H12.03Z' fill='%23FFFFFF'/%3E%3C/svg%3E%0A");
                            }
                        }

                        span {
                            padding-inline-start : 24px;
                            margin               : 0;
                            position             : relative;
                            cursor               : pointer;

                            * {
                                font-size   : 13px;
                                line-height : 18px;
                                color       : $white;
                                font-family : $second_font;
                                font-weight : 600;
                            }

                            a {
                                &:hover {
                                    text-decoration : underline;
                                }
                            }

                            &::before {
                                content             : '';
                                display             : block;
                                width               : 16px;
                                height              : 16px;
                                position            : absolute;
                                left                : 0;
                                top                 : 50%;
                                transform           : translateY(-50%);
                                background-image    : url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M14 1C14.2652 1 14.5196 1.10536 14.7071 1.29289C14.8946 1.48043 15 1.73478 15 2V14C15 14.2652 14.8946 14.5196 14.7071 14.7071C14.5196 14.8946 14.2652 15 14 15H2C1.73478 15 1.48043 14.8946 1.29289 14.7071C1.10536 14.5196 1 14.2652 1 14V2C1 1.73478 1.10536 1.48043 1.29289 1.29289C1.48043 1.10536 1.73478 1 2 1H14ZM2 0C1.46957 0 0.960859 0.210714 0.585786 0.585786C0.210714 0.960859 0 1.46957 0 2L0 14C0 14.5304 0.210714 15.0391 0.585786 15.4142C0.960859 15.7893 1.46957 16 2 16H14C14.5304 16 15.0391 15.7893 15.4142 15.4142C15.7893 15.0391 16 14.5304 16 14V2C16 1.46957 15.7893 0.960859 15.4142 0.585786C15.0391 0.210714 14.5304 0 14 0L2 0Z' fill='%23FFFFFF' fill-opacity='1'/%3E%3C/svg%3E%0A");
                                background-position : center;
                                background-repeat   : no-repeat;
                            }
                        }
                    }
                }

                .hs-richtext {
                    * {
                        font-size   : 13px;
                        line-height : 18px;
                        color       : $white;
                        font-weight : 600;
                        font-family : $second_font;
                    }

                    a {
                        font-weight : 600;

                        &:hover {
                            text-decoration : underline;
                        }
                    }
                }

                .submitted-message {
                    text-align     : center;
                    font-size      : 24px;
                    line-height    : 29px;
                    color          : $white;
                    padding-bottom : 30px;
                    padding-top    : 10px;

                    p {
                        color : $white;
                    }
                }

                .hs-submit {
                    margin-top : 32px;

                    .actions {
                        text-align : center;
                    }

                    input[type="submit"] {
                        @extend .white-border-btn;
                        cursor    : pointer;
                        min-width : 115px;
                        @include break(medium) {
                            font-size     : 15px;
                            line-height   : 24px;
                            padding       : 9px 14px;
                            border-radius : 15px;
                        }
                    }
                }
            }
        }
    }
}
