.right-side-image-banner {
    margin-top    : 24px;
    margin-bottom : 72px;

    @include break(medium) {
        margin-bottom : $mobile_margin;
    }

    @include break(x-small) {
        margin-bottom : 24px;
    }

    &.has-navigation {
        margin-top : 24px;
        @include break(medium) {
            margin-top : 16px;
        }
    }

    .breadcrumbs,
    .return-back-link {
        margin-bottom : 24px;
    }

    &__wrapper {
        display               : grid;
        grid-template-columns : 1fr 488px;
        grid-column-gap       : 20px;
        grid-row-gap          : 20px;
        column-gap            : 20px;
        row-gap               : 20px;
        @include break(desktop) {
            grid-template-columns : 1fr 400px;
        }
        @include break(medium850) {
            grid-template-columns : 1fr 334px;
        }
        @include break(ss-small) {
            grid-template-columns : 1fr 250px;
        }
        @include break(s-small) {
            text-align            : center;
            grid-template-columns : 1fr;
        }
    }

    &__content-wrapper {
        padding       : 40px;
        border-radius : 40px;
        min-height    : 458px;
        display       : flex;
        align-items   : center;
        @include break(desktop) {
            padding : 24px;
        }
        @include break(medium) {
            border-radius : 20px;
            min-height    : 346px;
        }
        @include break(small) {
            min-height : auto;
        }

        &.none {
            padding       : 37px 0;
            border-radius : 0;
            @include break(medium) {
                padding : 39px 0;
            }
            @include break(s-small) {
                padding : 0;
            }
        }

        &.blue {
            background-color : $blue;
        }

        &.coral {
            background-color : $coral;
        }

        &.purple {
            background-color : $purple;
        }

        &.light-blue {
            background-color : $light_blue;
        }

        &.apricot {
            border           : 1px solid $apricot;
            background-color : $coral_tint;
        }

        &.malibu {
            background-color : $malibu;
        }
    }

    &__content {
        &.none {
            max-width : 612px;
        }
    }

    &__logo {
        img {
            margin-bottom : 16px;
            @include break(tablet) {
                margin-bottom : 11px;
            }
        }

    }

    &__subtitle {
        font-size     : 40px;
        line-height   : 48px;
        margin-bottom : 16px;
        @include break(tablet) {
            margin-bottom : 11px;
            font-size     : 24px;
            line-height   : 29px;
        }
        @include break(ss-small) {
            font-size   : 18px;
            line-height : 22px;
        }
    }

    &__title {
        font-size     : 60px;
        line-height   : 62px;
        margin-bottom : 16px;
        @include break(tablet) {
            font-size   : 32px;
            line-height : 34px;
        }
        @include break(ss-small) {
            font-size   : 25px;
            line-height : 29px;
        }
    }

    &__text {
        @include break(medium) {
            font-size   : 14px;
            line-height : 20px;
        }
    }

    &__subtitle,
    &__title,
    &__text {
        @extend .styled-text;
    }

    &__button-wrapper {
        margin-top : 24px;
        display: flex;
        gap: 14px;

        @include break(medium) {
            flex-direction: column;
        }

        @include break(s-small) {
            align-items: center;
            text-align: center;
        }
    }

    &__button {
        @extend .styled-btn;
        width: max-content;
    }

    &__media {
        position : relative;

        &.like-logo {
            padding         : 40px 35px;
            display         : flex;
            justify-content : center;
            align-items     : center;
            @include break(desktop) {
                padding : 30px;
            }
            @include break(medium) {
                padding : 0 30px;
            }
        }

        .mask,
        .figure {
            position            : absolute;
            background-repeat   : no-repeat;
            background-position : center;
            z-index             : 10;

            &.bottom-right {
