.team-section {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__container {
        &-3 {
            @include break(desktop) {
                padding-left  : 10px;
                padding-right : 10px;
            }
            @include break(ss-small) {
                padding-left  : 6px;
                padding-right : 6px;
            }
        }

        &-4 {
            padding-left  : 21px;
            padding-right : 21px;
            @include break(medium) {
                padding-left  : 10px;
                padding-right : 10px;
            }
            @include break(ss-small) {
                padding-left  : 6px;
                padding-right : 6px;
            }
        }

        @include break(x-small) {
            &-3,
            &-4 {
                padding-left  : 0;
                padding-right : 0;
            }

        }
    }

    &__wrapper {
        margin-left  : auto;
        margin-right : auto;

        &-4 {
            max-width : 1220px;
        }

        &-3 {
            max-width : 1256px;
        }
    }

    &__title {
        margin-bottom : 88px;
        text-align    : center;
        @include break(medium) {
            margin-bottom : 24px;
            font-size     : 32px;
            line-height   : 24px;
        }
        @include break(x-small) {
            margin-bottom : 31px;
            padding-left  : 16px;
            padding-right : 16px;
            font-size     : 25px;
            line-height   : 29px;
            max-width     : 240px;
            margin-left   : auto;
            margin-right  : auto;
        }
    }

    &__cards {
        display         : flex;
        flex-wrap       : wrap;
        justify-content : center;
        row-gap         : 15px;
        text-align      : center;

        &-3 {
            column-gap : 0;
            @include break(desktop) {
                row-gap : 25px;
            }
        }

        &-4 {
            @include break(medium) {
                row-gap : 25px;
            }
        }

        @include break(x-small) {
            padding-left               : 53px;
            padding-right              : 53px;
            flex-wrap                  : nowrap;
            justify-content            : initial;
            white-space                : nowrap;
            overflow-x                 : auto;
            -webkit-overflow-scrolling : touch;
            -ms-overflow-style         : -ms-autohiding-scrollbar;
            scroll-snap-type           : x mandatory;
            overflow-y                 : hidden;
            &::-webkit-scrollbar {
                display : none;
            }
        }

    }

    &__card {
        @include break(x-small) {
            scroll-snap-align : center;
        }

        &:hover {
            .square-1, .square-2,
            .team-section__card-text,
            .team-section__card-social-wrapper {
                opacity : 1;
            }
        }

        &-3 {
            width   : 33.3333%;
            padding : 0 60px;
            @include break(desktop) {
                padding : 0 30px;
            }
            @include break(ss-small) {
                padding : 0 10px;
            }

            &.js-animate-parent {
                @media screen and (min-width : 481px) {
                    opacity    : 0;
                    transform  : translate3d(0, 60px, 0);
                    transition : opacity .3s, transform .8s cubic-bezier(0.165, 0.84, 0.44, 1);
                    &:nth-child(3n + 1) {
                        transition-delay : .1s;
                    }
                    &:nth-child(3n + 2) {
                        transition-delay : .3s;
                    }
                    &:nth-child(3n + 3) {
                        transition-delay : .5s;
                    }
                }
                @media screen and (min-width : 481px) {
                    &.animate {
                        opacity   : 1;
                        transform : translate3d(0, 0, 0);
                    }
                }
            }
        }

        &-4 {
            width   : 25%;
            padding : 0 19px;
            @include break(medium) {
                width   : 33.3333%;
                padding : 0 30px;
            }
            @include break(ss-small) {
                padding : 0 10px;
            }

            &.js-animate-parent {
                @media screen and (min-width : 481px) {
                    opacity    : 0;
                    transform  : translate3d(0, 60px, 0);
                    transition : opacity .3s, transform .8s cubic-bezier(0.165, 0.84, 0.44, 1);
                    &:nth-child(3n + 1) {
                        transition-delay : .1s;
                    }
                    &:nth-child(3n + 2) {
                        transition-delay : .3s;
                    }
                    &:nth-child(3n + 3) {
                        transition-delay : .5s;
                    }
                }
                @media screen and (min-width : 992px) {
                    &:nth-child(4n + 1) {
                        transition-delay : .1s;
                    }
                    &:nth-child(4n + 2) {
                        transition-delay : .3s;
                    }
                    &:nth-child(4n + 3) {
                        transition-delay : .5s;
                    }
                    &:nth-child(4n + 4) {
                        transition-delay : .7s;
                    }
                }
                @media screen and (min-width : 481px) {
                    &.animate {
                        opacity   : 1;
                        transform : translate3d(0, 0, 0);
                    }
                }
            }

            img {
                max-height : 246px;
            }
        }

        &-3 {
            @media screen and (min-width : 481px) {
                opacity    : 0;
                transform  : translate3d(0, 60px, 0);
                transition : opacity .3s, transform .8s cubic-bezier(0.165, 0.84, 0.44, 1);
                &:nth-child(3n + 1) {
                    transition-delay : .1s;
                }
                &:nth-child(3n + 2) {
                    transition-delay : .3s;
                }
                &:nth-child(3n + 3) {
                    transition-delay : .5s;
                }
            }

            img {
                max-height : 285px;
            }
        }

        @include break(x-small) {
            flex      : none;
            max-width : 100%;
            width     : 288px;
        }

        &-wrapper {

        }

        &-image {
            width         : 100%;
            position      : relative;
            padding       : 1px;
            margin-bottom : 14px;
            @include break(medium) {
                margin-bottom : 10px;
            }
            @include break(x-small) {
                margin-bottom : 14px;
                height        : 247px;
            }

            img {
                display       : block;
                width         : 100%;
                height        : auto;
                position      : relative;
                z-index       : 10;
                border-radius : 30px;
                object-fit    : contain;
                @include break(medium) {
                    border-radius : 20px
                }
                @include break(x-small) {
                    border-radius : 16px;
                    height        : 100%;
                    width         : auto;
                    margin        : 0 auto;
                }
            }
        }

        &-bg-wrapper {

            position : absolute;
            left     : 0;
            bottom   : 0;
            width    : 100%;
            height   : 100%;

            &-3 {
                @media screen and (min-width : 992px) {
                    padding-top : 43px;
                }
            }

            &-4 {
                @media screen and (min-width : 992px) {
                    padding-top : 37px;
                }
            }

            @include break(medium) {
                padding-top : 22px;
            }
            @include break(x-small) {
                padding-top : 38px;
            }
        }

        &-bg {
            border        : 1px solid;
            padding       : 16px 18px;
            border-radius : 30px;
            height        : 100%;
            @include break(medium) {
                border-radius : 20px
            }
            @include break(x-small) {
                border-radius : 17px;
                padding       : 15px 18px;
            }

            .square-1 {
                border        : 1px solid;
                border-radius : 17px;
                padding       : 19px 21px;
                width         : 100%;
                height        : 100%;
                opacity       : 0;
                transition    : opacity .3s linear;
                @include break(medium) {
                    border-radius : 15px
                }
                @include break(x-small) {
                    padding : 19px 21px;
                }
            }

            .square-2 {
                border           : 1px solid;
                border-radius    : 10px;
                width            : 100%;
                height           : 100%;
                opacity          : 0;
                transition       : opacity .4s linear;
                transition-delay : 0.1s;
            }

            &.coral {
                border-color     : $coral;
                background-color : $coral_tint;

                .square-1 {
                    border-color : rgba($color : $coral, $alpha : 0.5);
                }

                .square-2 {
                    border-color : rgba($color : $coral, $alpha : 0.2);
                }
            }

            &.blue {
                border-color     : $blue;
                background-color : $light_blue_tint;

                .square-1 {
                    border-color : rgba($color : $blue, $alpha : 0.5);
                }

                .square-2 {
                    border-color : rgba($color : $blue, $alpha : 0.2);
                }
            }

            &.purple {
                border-color     : $purple;
                background-color : $purple_tint;

                .square-1 {
                    border-color : rgba($color : $purple, $alpha : 0.5);
                }

                .square-2 {
                    border-color : rgba($color : $purple, $alpha : 0.2);
                }
            }

            &.light-blue {
                border-color     : $light_blue;
                background-color : $blue_tint;

                .square-1 {
                    border-color : rgba($color : $light_blue, $alpha : 0.5);
                }

                .square-2 {
                    border-color : rgba($color : $light_blue, $alpha : 0.2);
                }
            }
        }

        &-name {
            font-size   : 22px;
            line-height : 28px;
            @include break(medium) {
                font-size   : 18px;
                line-height : 22px;
            }
            @include break(x-small) {
                font-size   : 22px;
                line-height : 28px;
            }
        }

        &-position {
            color       : #3C455A;
            font-size   : 15px;
            line-height : 22px;
            @include break(medium) {
                font-size   : 12px;
                line-height : 16px;
            }
            @include break(x-small) {
                font-size   : 15px;
                line-height : 20px;
            }
        }

        &-text {
            font-size   : 13px;
            line-height : 18px;
            margin-top  : 4px;
            opacity     : 0;
            transition  : opacity .3s linear;
            @include break(medium) {
                opacity     : 1;
                margin-top  : 3px;
                font-size   : 10px;
                line-height : 15px;
            }
            @include break(x-small) {
                font-size   : 13px;
                line-height : 18px;
                margin-top  : 4px;
                white-space : normal;
                padding     : 0 2px;
            }
        }

        &-social-wrapper {
            margin-top      : 11px;
            display         : flex;
            justify-content : center;
            opacity         : 0;
            transition      : opacity .3s linear;
            @include break(medium) {
                opacity    : 1;
                margin-top : 3px;
            }
            @include break(x-small) {
                margin-top : 11px;
            }
        }

        &-social {
            width  : 31px;
            height : 29px;
            @include break(medium) {
                width  : 21px;
                height : 20px;
            }
            @include break(x-small) {
                width  : 30px;
                height : 29px;
            }

            svg {
                width  : 100%;
                height : 100%;
            }

            path {
                transition : fill .3s linear;
            }

            &:hover {
                path {
                    fill : $blue;
                }
            }
        }
    }

    &__button-wrapper {
        text-align : center;
        margin-top : 30px;
        @include break(medium) {
            margin-top : 51px;
        }
        @include break(x-small) {
            margin-top : 37px;
        }
    }

    &__button {
        @extend .blue-btn;
    }
}