.side-image-content-v2{
    margin-top: $desktop_margin;
    margin-bottom: $desktop_margin;
    @include break(medium){
        margin-top: $mobile_margin;
        margin-bottom: $mobile_margin;
    }
    &__container{
        &.js-animate-parent{
            &.animate{
                .js-animate-element{
                    opacity: 1;
                    transform: translate3d(0, 0, 0);
                } 
            }
        }
        .js-animate-element{
            transition: opacity .4s, transform .8s cubic-bezier(0.165, 0.84, 0.44, 1);
            opacity: 0;
            transform: translate3d(0, 50%, 0);
        }
    }
    &__wrapper{
        display: grid;
        grid-template-columns: 488px 1fr;
        grid-column-gap: 48px;
        grid-row-gap: 20px;
        column-gap: 48px;
        row-gap: 20px;
        align-items: center;
        @include break(desktop){
            grid-template-columns: 400px 1fr;
            grid-column-gap:20px;
            column-gap:20px;
        }
        @include break(medium850){
            grid-template-columns: 334px 1fr;
        }
        @include break(ss-small){
            grid-template-columns: 250px 1fr;
        }
        @include break(s-small){
            grid-template-columns: 1fr;
        }
        &.reverse{
            grid-template-columns: 1fr 488px;
            @include break(desktop){
                grid-template-columns: 1fr 400px;
            }
            @include break(medium850){
                grid-template-columns: 1fr 334px;
            }
            @include break(ss-small){
                grid-template-columns:1fr 250px;
            }
            @include break(s-small){
                grid-template-columns: 1fr;
            }
        }  
    }
    &__media{
        display: flex;
        justify-content: center;
        align-items: center;
        max-height: 372px;
        &.reverse{
            order: 2;
        }
        @include break(s-small){
            min-height: 280px;
        }
    }
    &__image{
        display: block;
        max-width: 100%;
        max-height: 400px;
        height: auto;
        width: 100%;
    }
    &__content-wrapper{
        &.reverse{
            order: 1;
        }
    }
    &__content{

    }
    &__title{
        margin-bottom: 24px;
        @include break(desktop){
            font-size: 22px;
            line-height: 28px;
            margin-bottom: 16px;
        }
        &.small{
            font-size: 22px;
            line-height: 28px;
            margin-bottom: 16px;
        }
    }
    &__text{

    }
    &__button-wrapper{
        margin-top: 24px;
        @include break(tablet){
            margin-top: 16px;
        }
    }
    &__button{
        @extend .blue-btn;
    }
}