.ew-card {
    padding       : 0 10px;
    width         : 33.3333%;
    margin-bottom : 20px;
    @include break(medium) {
        width : 50%;
    }
    @include break(s-small) {
        width   : 100%;
        padding : 0;
    }

    &__wrapper {
        padding        : 15px 15px 11px 15px;
        border-radius  : 16px;
        border         : 1px solid $blue;
        height         : 100%;
        display        : flex;
        flex-direction : column;
        transition     : background-color .3s linear;

        &:hover {
            background-color : $light_blue_tint;
        }
    }

    &__media {
        margin-bottom : 15px;
    }

    &__image {
        width: calc((100% - 10px) / 2);

        &.has-logo {
            background-color : $white;
            border-radius : 8px;
            padding : 8px 15px;
            display: flex;
            align-items: center;

            img {
                border-radius : 0;
                height        : 36px;
                object-fit    : contain;
            }
        }
        img {
            border-radius : 8px;
            display       : block;
            width         : 100%;
            height        : 64px;
            object-fit    : cover;
        }
    }


    &__content-wrapper {
        display         : flex;
        flex-direction  : column;
        height          : 100%;
        flex-grow: 1;
        justify-content: space-between;
    }
    &__info {
        width: calc((100% - 10px) / 2);
    }
    &__info-area {
        padding: 20px 10px;
        border-radius: 10px;
        display : flex;
        gap: 10px;
        background-color: $dark;
        margin-bottom: 16px;
    }

    &__type-wrapper {
        margin-bottom : 16px;
    }

    &__type {
        border        : 1px solid;
        border-radius : 10px;
        padding       : 5px 15px;
        text-align    : center;
        display       : inline-block;
        color         : $dark;
        font-family   : $third_font;
        font-weight   : 600;

        &.event {
            border-color     : $malibu;
            background-color : $blue_tint;
        }

        &.webinar {
            background-color : $purple_tint;
            border-color     : $purple;
        }
    }

    &__title {
        color         : #3C455A;
        font-size     : 22px;
        line-height   : 24px;
        margin-bottom : 8px;
        transition    : color .3s linear;
        flex-grow: 1;

        &:hover {
            color : $blue;
        }
    }

    &__link {
        @extend .inherit;
    }

    &__date {
        font-size    : 13px;
        line-height  : 16px;
        color        : $white;
        position     : relative;
        border-radius: 10px;
        border: 1px solid #3B37E6;
        background: rgba(59, 55, 230, 0.20);
        padding: 9px 0 7px;
        display: flex;
        gap: 4px;
        align-items : center;
        justify-content : center;
        height: 28px;

        svg {
            margin-top: -3px;
        }
    }

    &__tags-wrapper {
        margin-bottom : 8px;
        position      : relative;
    }


    &__tag {
        border        : 1px solid;
        border-radius : 10px;
        padding       : 9px 0 7px;
        text-align    : center;
        display       : flex;
        color         : $white;
        font-family   : $third_font;
        font-weight   : 600;
        font-size: 13px;
        line-height : 16px;
        gap: 4px;
        justify-content: center;
        align-items: center;
        height: 28px;
        white-space: nowrap;

        &.event {
            border-color     : $coral;
            background-color : #FFF6F5;
            background: rgba(255, 115, 105, 0.20);
        }

        &.webinar {
            background-color : rgba($color : $dark, $alpha : 0.1);
            border-color     : $dark;
        }
        svg {
            margin-top : -3px;
        }
    }

    &__webinar {
        &-dates {
            &:hover {
                .ew-card__webinar-dates-list-wrapper {
                    visibility : visible;
                    opacity    : 1;
                }
            }
        }

        &-text {
            font-size   : 16px;
            line-height : 24px;
            color       : $blue;
            font-family : $third_font;
            font-weight : 600;
            cursor      : pointer;
        }

        &-dates-list-wrapper {
            padding-bottom : 8px;
            position       : absolute;
            right          : 0;
            bottom         : 100%;
            visibility     : hidden;
            opacity        : 0;
            transition     : opacity .3s linear;
        }

        &-dates-list {
            background-color : $light_blue_tint;
            box-shadow       : 0px 4px 10px rgba(59, 55, 230, 0.15);
            border-radius    : 12px;
            padding          : 12px 16px;
        }

        &-date {
            display               : grid;
            grid-template-columns : 60px 1fr;
            column-gap            : 8px;
            align-items           : center;

            &:not(:last-child) {
                margin-bottom : 12px;
            }

            &-lang {
                text-align       : center;
                padding          : 5px;
                font-family      : $third_font;
                font-weight      : 600;
                font-size        : 13px;
                line-height      : 16px;
                color            : $dark;
                border           : 1px solid $dark;
                background-color : rgba($color : $dark, $alpha : 0.1);
                border-radius    : 10px;
            }

            &-date {
                font-size   : 15px;
                line-height : 24px;
                color       : #3C455A;
            }
        }
    }

    &__excerpt {
        font-size   : 16px;
        line-height : 24px;
        display: -webkit-box;
        -webkit-box-orient: vertical;
        overflow: hidden;
        text-overflow: ellipsis;
        -webkit-line-clamp: 5;
    }

    &__read-wrapper {
        margin-top: 16px;
    }

    &__read {
        @extend .arrow-btn-right;
        font-family : $third_font;
        font-weight : 600;
    }
}