.case-study-banner {
    background-color : $dark;
    padding-top      : 24px;
    padding-bottom   : 40px;
    margin-bottom    : 64px;
    @include break(medium) {
        padding-top   : 16px;
        margin-bottom : 40px;
    }
    @include break(s-small) {
        padding-bottom : 32px;
        margin-bottom  : 24px;
    }

    .breadcrumbs {
        margin-bottom : 14px;
        @include break(medium) {
            margin-bottom : 24px;
        }

        &__link {
            color   : $white;
            opacity : 0.7;

            &:hover {
                opacity : 1;
            }

            span {
                color       : inherit;
                font-size   : inherit;
                line-height : inherit;
            }
        }

        &__separator {
            path {
                stroke  : $white;
                opacity : 0.7;
            }
        }

        &__current {
            color       : $white;
            opacity     : 1;
            font-size   : 15px;
            line-height : 24px;
        }
    }

    &__wrapper {
        display               : grid;
        grid-template-columns : repeat(2, 1fr);
        grid-column-gap       : 20px;
        column-gap            : 20px;
        min-height            : 480px;
        grid-row-gap          : 20px;
        row-gap               : 20px;
        @include break(tablet) {
            min-height : 288px;
        }
        @include break(s-small) {
            grid-template-columns :1fr;
            min-height            : auto;
        }
    }

    &__content-wrapper {
        padding         : 25px 0;
        align-self      : center;
        display         : flex;
        flex-direction  : column;
        justify-content : space-between;
        height          : 100%;
        @include break(tablet) {
            padding : 12px 0;
        }
        @include break(s-small) {
            padding : 0;
        }
    }

    &__cat-wrapper {
        margin-bottom : 24px;
        @include break(medium) {
            margin-bottom : 16px;
        }
    }

    &__cat {
        display       : inline-block;
        font-size     : 13px;
        line-height   : 16px;
        border-radius : 10px;
        padding       : 5px 15px;
        border        : 1px solid;
        font-family   : $third_font;
        font-weight   : 600;
        color         : $white;
        border-color  : $white;

        &.erp {
            border-color     : $blue;
            background-color : rgba($color : $blue, $alpha : 0.2);
        }

        &.hospitality {
            border-color     : $malibu;
            background-color : rgba($color : $malibu, $alpha : 0.2);
        }

        &.school {
            border-color     : $apricot;
            background-color : rgba($color : $apricot, $alpha : 0.2);
        }

        &.retail {
            border-color     : $purple;
            background-color : rgba($color : $purple, $alpha : 0.2);
        }
    }

    &__title {
        font-size   : 40px;
        line-height : 48px;
        color       : $white;
        @include break(tablet) {
            font-size   : 22px;
            line-height : 28px;
        }
    }

    &__link-wrapper {
        margin-top : 32px;
        display: flex;
        gap: 10px;

        @include break(medium) {
            margin-top : 16px;
            flex-direction: column;
            align-items: flex-start;
        }
    }

    &__link {
        @extend .blue-btn;
        font-size   : 15px;
        line-height : 24px;
        padding     : 10px 30px;
        @at-root {
            a#{&}:hover {
                background-color : $white;
            }
        }
        &:hover {
            background-color : $white;
            color            : $dark;
        }
    }

    .single-banner__bottom {
        margin-top : 24px;
    }

    &__media {
        position      : relative;
        z-index: 1;
        border-radius : 24px;
        border        : 1px solid $purple;
        overflow      : hidden;
    }

    &__media-logo {
        position: absolute;
        z-index: 1;
        right: 10px;
        bottom: 10px;
        display: flex;
        background: rgba(255, 255, 255, .7);
        padding: 10px;
        border-radius: 16px;
        max-width: 200px;

        @include break(tablet) {
            max-width: 150px;
        }

        @include break(medium850) {
            max-width: 135px;
        }

        @include break(ss-small) {
            max-width: 115px;
        }

        @include break(s-small) {
            max-width: 150px;
        }

        @include break(small-375) {
            max-width: 120px;
        }

        @include break(small-330) {
            max-width: 100px;
        }

        img {
            width: 100%;
            height: auto;
        }
    }

    &__play-btn {
        position        : absolute;
        left            : 0;
        top             : 0;
        width           : 100%;
        height          : 100%;
        display         : flex;
        justify-content : center;
        align-items     : center;
        transition      : fill .5s linear;

        svg {
            circle {
                transition : all .4s ease-in-out;
            }
            parth {
                transition : all .5s ease-in-out;
            }

            @include break(medium) {
                width  : 81px;
                height : 93px;
            }
        }

        &:hover {
            svg {
                circle {
                    fill : $blue;
                }

                path {
                    fill : $royal_blue;
                }
            }
        }
    }

    &__image {
        width      : 100%;
        height     : 100%;
        object-fit : cover;
    }

    &__blocks {
        display               : grid;
        grid-column-gap       : 20px;
        grid-row-gap          : 20px;
        column-gap            : 20px;
        row-gap               : 20px;
        grid-template-columns : 26% 17% 26% 26%;
        margin-top            : 56px;
        @include break(desktop) {
            grid-template-columns : repeat(2, 1fr);
            margin-top            : 52px;
        }
        @include break(ss-small) {
            grid-template-columns : 1fr;
        }
        @include break(s-small) {
            margin-top   : 60px;
            grid-row-gap : 16px;
            row-gap      : 16px;
        }
    }

    &__block {
        border          : 1px solid;
        padding         : 15px 23px;
        display         : flex;
        flex-direction  : column;
        justify-content : center;
        @include break(s-small) {
            padding : 11px 23px;
        }

        &.industry {
            border-color     : $blue;
            background-color : rgba($color : $blue, $alpha : 0.2);
            border-radius    : 16px;
        }

        &.website {
            border-color     : $malibu;
            background-color : rgba($color : $malibu, $alpha : 0.2);
            border-radius    : 24px;
        }

        &.country {
            border-color     : $apricot;
            background-color : rgba($color : $apricot, $alpha : 0.2);
            border-radius    : 100px;
        }

        &.partner {
            border-color     : $purple;
            background-color : rgba($color : $purple, $alpha : 0.2);
            border-radius    : 1000px;
            position         : relative;
            padding-right    : 80px;
            @include break(s-small) {
                padding-right : 72px;
            }

            .circle {
                width            : 76px;
                height           : 100%;
                background-color : $purple;
                position         : absolute;
                right            : 0;
                top              : 0;
                border-radius    : 50%;
                @include break(s-small) {
                    width : 68px;
                }
            }
        }

        &-title,
        &-text,
        &-link {
            font-family : $third_font;
            font-weight : 600;
            color       : $white;
        }

        &-title {
            opacity       : 0.8;
            font-size     : 12px;
            line-height   : 16px;
            margin-bottom : 4px;
        }

        &-text {
            font-size   : 16px;
            line-height : 24px;
        }

        &-link {
            &:hover {
                text-decoration : underline;
            }
        }
    }
}
