.lobby-banner {
    &__media-wrapper {
        a {
            svg {
                circle {
                    transition : all .4s ease-in-out;
                }
                parth {
                    transition : all .5s ease-in-out;
                }

                @include break(medium) {
                    width  : 81px;
                    height : 93px;
                }
            }
            &:hover {
                svg {
                    circle {
                        fill : $blue;
                    }
                    path {
                        fill : $royal_blue;
                    }
                }
            }
        }
    }
}