.webinar-dates {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__wrapper {
        display               : grid;
        grid-template-columns : 1fr 590px;
        row-gap               : 32px;
        @include break(desktop) {
            grid-template-columns : 1fr 470px;
        }
        @include break(medium) {
            grid-template-columns : 1fr;
        }
        @include break(s-small) {
            row-gap : 24px;
        }
    }

    &__content {
        align-self    : center;
        padding-right : 40px;
        @include break(desktop) {
            padding-right : 20px;
        }
        @include break(medium) {
            padding : 0;
        }
    }

    &__dates {
        align-self   : center;
        padding-left : 40px;
        position     : relative;
        @include break(desktop) {
            padding-left : 20px;
        }
        @include break(medium) {
            padding : 0;
        }

        &::before {
            content          : '';
            display          : block;
            width            : 1px;
            height           : 100%;
            background-color : rgba(22, 33, 61, 0.5);
            position         : absolute;
            left             : 0;
            top              : 0;
            @include break(medium) {
                display : none;
            }
        }
    }

    &__item {
        display               : grid;
        align-items           : center;
        grid-template-columns : 64px 1fr 120px;
        column-gap            : 12px;

        &:first-of-type {
            margin-top : 32px;
        }

        @include break(s-small) {
            column-gap            : 8px;
            grid-template-columns : 48px 1fr 105px;
        }

        &:not(:last-child) {
            margin-bottom : 16px;
        }

        &-lang {
            text-align    : center;
            padding       : 6px;
            border        : 10px;
            background    : rgba($color : $dark, $alpha : 0.1);
            border        : 1px solid $dark;
            text-align    : center;
            border-radius : 10px;
            font-size     : 13px;
            line-height   : 16px;
            font-family   : $third_font;
            font-weight   : 600;
        }

        &-date {
            margin : 0 !important;
            @include break(s-small) {
                font-size   : 15px !important;
                line-height : 22px !important;
            }
        }

        a.webinar-dates__item-btn {
            @extend .blue-btn;
            display       : block;
            width         : 100%;
            font-size     : 15px;
            line-height   : 24px;
            border-radius : 15px;
            padding       : 10px;
            text-align    : center;
            min-width     : auto;
        }
    }
}