.title-video {
    padding: 64px 0;

    @include break(small) {
        padding: 20px 0;
    }

    &__sectio-wrapper {
        display: grid;
        grid-template-columns: 624px 1fr;
        gap: 48px;

        @include break(desktop) {
            display: flex;
            flex-direction: column;
            gap: 0;
        }
    }

    &__video-perivew {
        position: relative;
        overflow: hidden;
        height: 372px;


        @include break(desktop) {
            margin-bottom: 20px;
        }

        @include break(small) {
            height: 350px;
        }

        @include break(s-small) {
            height: 300px;
        }

        @include break(x-small) {
            height: 213px;
        }

        .image {
            border-radius: 30px;
            max-width: 100%;
            height: 100%;
            width: 100%;
            padding: 1px;
            display: block;
            object-fit: cover;

            @include break(x-small) {
                border-radius: 20px;
            }
        }

        .youtube-icon {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);

            @include break(medium) {
                width: 88px;
                height: 60px;
            }
        }

        .mask,
        .figure {
            position: absolute;
            background-position: center;
            background-repeat: no-repeat;
            display: flex;
            z-index: 10;

            &.top-right {
                right: 0;
                top: 0;
            }

            &.top-left {
                left: 0;
                top: 0;
            }

            &.bottom-left {
                left: 0;
                bottom: 0;
            }
        }

