    &__title-wrapper {
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: flex-start;
    }

    &__button {
        @include break(medium) {
            margin: 0 auto;
        }
    }

    &__title {
        color: $purple;
        margin-bottom: 32px;
        padding-right: 10px;

        @include break(desktop) {
            display: none;
        }

        &.mob {
            display: none;

            @include break(desktop) {
                display: block;
                margin-bottom: 20px;
            }

            @include break(medium) {
                text-align: center;
            }
        }
    }

    @supports(-webkit-mask-image: url(#mask)) or (mask-image: url(#mask)) {
        /* code that requires mask-image here. */
    }
