.billboard-mozaic-section  {
    margin-top    : 50px;
    margin-bottom : $desktop_margin;

    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__wrapper {
        display: grid;
        grid-template-columns: 380px 400px 380px;
        grid-template-rows: 230px 380px 230px;
        gap: 20px;
        padding: 0 80px;

        @include break(large1470) {
            padding: 0;
            max-width: 1200px;
            margin: 0 auto;
        }
        @include break(desktop) {
            grid-template-columns: 300px 300px 300px;
            grid-template-rows: 200px 350px 200px;
            max-width: 950px;
        }
        @include break(medium) {
            display: flex;
            flex-direction: column;
        }
        @include break( s-small) {
            gap: 16px;
        }
    }
    &__item {
        display : flex;
        gap: 24px;
        transition: all 0.3s ease-in-out;

        @include break(medium) {
            padding: 20px 16px;
            margin-bottom: 16px;
        }
        @include break( s-small) {
            margin-bottom: 0;
            flex-direction: column-reverse;
        }

        &-description {
            display : flex;
            flex-direction: column;
            justify-content: center;

            @include break(medium) {
                width : calc(100% - 324px);
            }
            @include break(ss-small) {
                width : calc(100% - 227px);
            }
            @include break( s-small) {
                width: 100%;
            }
        }
        &-content {
            color: $dark;
            font-family: $second_font;
            font-size: 18px;
            font-weight: 400;
            line-height: 28px; /* 155.556% */
        }
        &-title {
            color: $dark;
            font-family: $third_font;
            font-size: 40px;
            font-weight: 600;
            line-height: 48px;
            margin-bottom: 8px;

            @include break(desktop) {
                font-size: 24px;
                line-height: 110%;
            }

            @include break(s-small) {
                font-size: 22px;
            }
        }
        &-image {
            @include break(medium) {
                width : 313px;
            }
            @include break( s-small) {
                width: 100%;
            }
        }
        &.item-1 {
            grid-row-start: 1;
            grid-row-end: 1;
            grid-column-start: 1;
            grid-column-end: 3;
            border: 1px solid $malibu;
            border-radius: 50px;
            padding: 25.253px 32.324px;
            gap: 24px;
            flex-shrink: 0;

            @include break(medium) {
                order: 2;
                border-radius: 16px;
                padding: 20px 16px;
            }
            @include break( s-small) {
                gap: 16px;
            }
        }
        &.item-2 {
            grid-row-start: 2;
            grid-row-end: 4;
            grid-column-start: 1;
            grid-column-end: 2;
            border: 1px solid $purple;
            border-radius:  45.455px 15.152px 45.455px 101.011px;
            gap: 10px;
            flex-shrink: 0;
            flex-direction: column;
            padding: 40px 34px;

            @include break(medium) {
                order: 3;
                border-radius: 16px;
                padding: 20px 16px;
            }


            .billboard-mozaic__media_image {
                border-radius: 45px 45px 45px 80px;
                height: 340px;

                @include break(desktop) {
                    height: 310px;
                }
                @include break(medium) {
                    width : 313px;
                    height: auto;
                    border-radius: 15px;
                }
            }
        }
        &.item-3 {
            grid-row-start: 2;
            grid-row-end: 2;
            grid-column-start: 2;
            grid-column-end: 2;
            border: 1px solid $blue;
            background-color: $royal_blue;
            border-radius: 50px;
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            padding: 40px;

            @include break(medium) {
                order: 1;
                border-radius: 16px;
                padding: 20px 16px;
            }

            .billboard-mozaic-section__item-title {
                color: $blue;

                @include break( s-small) {
                    margin-bottom: 0;
                }
            }
            .billboard-mozaic-section__item-description {
                @include break(medium) {
                    width: auto;
                }
            }

            &:hover {
                background-color: $blue;
                .billboard-mozaic-section__item-content,
                .billboard-mozaic-section__item-title {
                    color: $white;
                }
            }
        }
        &.item-4 {
            grid-row-start: 1;
            grid-row-end: 3;
            grid-column-start: 3;
            grid-column-end: 3;
            border: 1px solid $purple;
            border-radius: 45.455px 101.011px 45.455px 15.152px;
            padding: 32px 32px 34px 32px;
            flex-direction: column-reverse;
            justify-content: flex-end;

            @include break(medium) {
                order: 5;
                border-radius: 16px;
                padding: 20px 16px;
            }

            .billboard-mozaic__media_image {
                height: 300px;
                border-radius: 45px 89px 45px 45px;

                @include break(medium) {
                    width : 313px;
                    height: auto;
                    border-radius: 15px;
                }
            }
        }
        &.item-5 {
            grid-row-start: 3;
            grid-row-end: 3;
            grid-column-start: 2;
            grid-column-end: 4;
            border: 1px solid $malibu;
            border-radius: 50px;
            padding: 25px 32px;

            @include break(medium) {
                border-radius: 16px;
                padding: 20px 16px;
                order: 4;
            }
        }
        &.item-1,
        &.item-5 {
            .billboard-mozaic-section__item-image {
                display: flex;
                align-items: center;
            }
            .billboard-mozaic__media_image {
                width         : 284px;
                object-fit    : contain;
                border-radius : 36px;
                border        : 1px solid $malibu;
                height        : auto;

                @include break(desktop) {
                    width : 264px;
                }
                @include break(medium) {
                    width : 313px;
                    border-radius : 15px;
                }
                @include break(ss-small) {
                    width : 200px;
                }
                @include break( s-small) {
                    width : 100%;
                }
            }
            &:hover {
                background-color : $malibu;

                .billboard-mozaic-section__item-content,
                .billboard-mozaic-section__item-title {
                    color : $white;
                }
            }
            .billboard-mozaic-section__item-description {
                width : calc(100% - 308px);

                @include break( s-small) {
                    width: 100%;
                }
            }
        }
        &.item-2,
        &.item-4 {
            @include break(medium) {
                flex-direction: row;
            }
            @include break( s-small) {
                flex-direction: column-reverse;
            }
            .billboard-mozaic__media_image {
                object-fit: cover;
                border: 1px solid $purple;
                width: 100%;

                @include break(medium) {
                    width : 313px;
                    border-radius : 15px;
                }
                @include break(ss-small) {
                    width : 200px;
                }
                @include break( s-small) {
                    width : 100%;
                }
            }
            &:hover {
                background-color: $purple;

                .billboard-mozaic-section__item-content,
                .billboard-mozaic-section__item-title {
                    color: $white;
                }
            }
            .billboard-mozaic-section__item-description {
                height : calc(100% - 350px);
            }
        }
    }
}