.partners-card{
    padding: 0 10px;
    width: 25%;
    margin-bottom: 20px;

    @include break(tablet){
        width: 33.3333%;
    }

    @include break(medium){
        width: 50%;
    }

    @include break(s-small){
        width: 100%;
        padding: 0;
    }
    &__wrapper{
        padding: 15px 15px 23px 15px;
        border-radius: 16px;
        border: 1px solid $blue;
        height: 100%;
        display: flex;
        transition:background-color .3s linear;
        flex-direction: column;
        align-items: center;
        &:hover{
            background-color: $light_blue_tint;
        }
    }
    &__link{
        display: flex;
        height: 100%;
        flex-direction: column;
        align-items: center;
    }
    &__media{
        margin-bottom: 24px;
        border-radius: 15px;
        display: flex;
        justify-content: center;
        align-items: center;
        position: relative;
        height: 100px;
        min-height: 100px;

        @include break(large1370) {
            height: 140px;
            min-height: 140px;
        }

        @include break(desktop) {
            height: 100px;
            min-height: 100px;
        }

        @include break(tablet) {
            height: 100px;
            min-height: 100px;
        }

        @include break(ss-small) {
            height: 80px;
            min-height: 80px;
        }

        @include break(s-small) {
            height: 120px;
            min-height: 120px;
        }

        @include break(x-small) {
            margin-bottom: 18px;
            height: 100px;
            min-height: 100px;
        }

        img{
            max-width: 100%;
            max-height: 100%;
            height: auto;
            width: auto;
        }
    }
