    &__cat-wrapper{
        text-align: center;
        margin-bottom: 24px;
        display: flex;
        gap: 10px;
        flex-wrap: wrap;
        justify-content: center;
    }
    &__cat{
        border: 1px solid;
        border-radius: 10px;
        padding: 7px 15px 3px;
        text-align: center;
        display: inline-block;
        color: $dark;
        font-family: $third_font;
        font-weight: 600;
        font-size: 13px;
        line-height: 16px;
    }
    &__content-wrapper{
        display: flex;
        flex-direction: column;
        align-items: center;
    }
    &__name{
        font-size: 16px;
        line-height: 16px;
        color: #3C455A;
        font-family: $third_font;
        font-weight: 600;
        position: relative;
        padding-left: 32px;

        &.hide-flag {
            padding-left: 0;
        }
    }
    &__flag{
        width: 24px;
        height: 16px;
        object-fit: contain;
        position: absolute;
        left: 0;
        top: -2px;
    }
}
