.industry-banner-v2 {
    margin-top    : 24px;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-bottom : $mobile_margin;
        margin-top    : 16px;
    }

    .breadcrumbs,
    .return-back-link {
        margin-bottom : 16px;
        @include break(medium) {
            margin-bottom : 24px;
        }
        @include break(ss-small) {
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }
    }
    .breadcrumbs {
        @include break(ss-small) {
            margin-bottom: 8px;
        }
    }

    &__wrapper {
        background-color      : $dark;
        border-radius         : 50px;
        display               : grid;
        gap                   : 0 20px;
        grid-template-columns :1fr 683px;
        @include break(desktop) {
            grid-template-columns :1fr 560px;
        }
        @include break(medium) {
            grid-template-columns :1fr 345px;
            border-radius         : 25px;
        }
        @include break(ss-small) {
            grid-template-columns :1fr 295px;
        }
        @include break(s-small) {
            grid-template-columns :1fr;
        }

        &-image {
            min-height : 554px;
            @include break(desktop) {
                min-height : 400px;
            }
            @include break(medium) {
                min-height : 304px;
            }
        }

        &-frame {
            height   : 554px;
            overflow : hidden;
            @include break(desktop) {
                height : 400px;
            }
            @include break(medium) {
                height : 304px;
            }
            @include break(s-small) {
                height : auto;
            }
        }
    }

    &__content-wrapper {
        display     : flex;
        align-items : center;
        padding     : 64px 0 64px 80px;
        @include break(large1370) {
            padding-left : 40px;
        }
        @include break(desktop) {
            padding : 40px 0 40px 40px;
        }
        @include break(ss-small) {
            padding : 30px 0 30px 30px;
        }
        @include break(s-small) {
            padding : 36px 20px 28px 20px;
        }

        &-frame {
            @include break(s-small) {
                padding : 50px 20px 42px 20px;
            }
        }
    }

    &__content {
        max-width : 548px;
        @include break(medium) {
            max-width : 420px;
        }
    }

    &__subtitle,
    &__title {
        color : $white;
    }

    &__subtitle {
        font-size     : 40px;
        line-height   : 48px;
        margin-bottom : 16px;
        @include break(desktop) {
            margin-bottom : 8px;
            font-size     : 22px;
            line-height   : 28px;
        }
        @include break(medium) {
            font-size   : 15px;
            line-height : 24px;
        }
    }

    &__title {
        font-size   : 60px;
        line-height : 62px;
        @include break(desktop) {
            font-size   : 40px;
            line-height : 48px;
        }
        @include break(medium) {
            font-size   : 22px;
            line-height : 28px;
        }
    }

    &__button-wrapper {
        margin-top : 40px;
        @include break(desktop) {
            margin-top : 32px;
        }
        @include break(s-small) {
            text-align : center;
        }
    }

    &__button {
        @extend .white-btn;
        @at-root {
            a#{&} {
                color : $dark;

                &:hover {
                    color : $white;
                }
            }
        }
    }

    &__media {
        &-image {
            padding         : 60px;
            display         : flex;
            justify-content : center;
            align-items     : center;
            @include break(medium) {
                padding : 32px;
            }
            @include break(s-small) {
                min-height : 247px;
                padding    : 20px 45px;
            }

            img, svg {
                max-width     : 100%;
                max-height    : 480px;
                width         : auto;
                height        : auto;
                object-fit    : contain;
                border-radius : 0;
            }
        }

        &-frame {
            position  : relative;
            isolation : isolate;
            padding   : 94px 119px 94px 14px;
            @include break(desktop) {
                height  : 400px;
                padding : 66px 78px 66px 14px;
            }
            @include break(medium) {
                height  : 304px;
                padding : 57px 61px 57px 0;
            }
            @include break(ss-small) {
                height  : 304px;
                padding : 57px 51px 57px 0;
            }
            @include break(s-small) {
                height  : auto;
                padding : 0 20px 20px;
            }

            .frame {
