.tabs-section {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    overflow      : hidden;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__container {
        @include break(s-small) {
            padding-left  : 0;
            padding-right : 0;
        }
    }

    &__wrapper {

    }

    &__title {
        margin-bottom : 49px;
        max-width     : 550px;
        margin-left   : auto;
        margin-right  : auto;
        text-align    : center;
        @include break(medium) {
            margin-bottom : 30px;
        }
        @include break(s-small) {
            padding-left  : 16px;
            padding-right : 16px;
        }
        @include break(x-small) {
            margin-bottom : 51px;
        }
    }

    &__tabs {

    }

    &__heading {
        display         : flex;
        justify-content : flex-start;
        border-bottom   : 1px solid rgba(22, 33, 61, 0.5);
        padding-bottom  : 8px;
        @include break(s-small) {
            width                      : 100%;
            white-space                : nowrap;
            padding-left               : 16px;
            padding-right              : 16px;
            overflow                   : auto;
            display                    : inline-flex;
            -webkit-overflow-scrolling : touch;
            -ms-overflow-style         : -ms-autohiding-scrollbar;
            border-bottom              : 0;
            position                   : relative;
            padding-bottom             : 12px;
            &::-webkit-scrollbar {
                display : none;
            }
        }
    }

    &__tab-name {
        max-width       : 200px;
        width           : 100%;
        position        : relative;
        text-align      : center;
        font-family     : $second_font;
        font-size       : 13px;
        line-height     : 18px;
        font-weight     : 400;
        cursor          : pointer;
        transition      : color .3s linear;
        display         : flex;
        justify-content : center;
        padding         : 0 20px;
        @include break(medium) {
            padding : 0 10px;
        }
        @include break(small) {
            max-width : 115px;
        }
        @include break(s-small) {
            white-space : normal;
            width       : 120px;
            max-width   : none;
            flex        : none;
            padding     : 0 5px;
            &::after {
                content          : '';
                display          : block;
                width            : 100%;
                height           : 1px;
                position         : absolute;
                left             : 0px;
                bottom           : -9px;
                background-color : rgba(22, 33, 61, 0.5);
            }
        }

        &.blue {
            &.active {
                color : $blue;

                &::before {
                    background-color : $blue;
                }
            }

            &:hover {
                color : $blue;
            }
        }

        &.coral {
            &.active {
                color : $coral;

                &::before {
                    background-color : $coral;
                }
            }

            &:hover {
                color : $coral;
            }
        }

        &.purple {
            &.active {
                color : $purple;

                &::before {
                    background-color : $purple;
                }
            }

            &:hover {
                color : $purple;
            }
        }

        &.light-blue {
            &.active {
                color : $light_blue;

                &::before {
                    background-color : $light_blue;
                }
            }

            &:hover {
                color : $light_blue;
            }
        }

        &::before {
            content          : '';
            display          : block;
            width            : 100%;
            height           : 3px;
            background-color : transparent;
            position         : absolute;
            left             : 0;
            bottom           : -12px;
            transition       : background-color .3s linear;
        }

        &:first-child {
            margin-left : 0;
            @include break(s-small) {
                &::after {
                    width : 100%;
                    left  : 0;
                }
            }

        }
    }

    &__tabs-wrapper {
        margin-top : 11px;
        @include break(s-small) {
            padding-left  : 16px;
            padding-right : 16px;
            margin-top    : 35px;
        }
    }

    &__tab {
        &-item {
            display : none;

            &.active {
                display : block;
            }
        }

        &-wrapper {
            display               : grid;
            grid-column-gap       : 48px;
            grid-row-gap          : 20px;
            gap                   : 20px 48px;
            align-items           : center;
            grid-template-columns : 1fr 488px;
            @include break(desktop) {
                grid-template-columns : 1fr 400px;
                gap                   : 20px;
            }
            @include break(medium850) {
                grid-template-columns : 1fr 334px;
            }
            @include break(s-small) {
                grid-template-columns : 1fr;
            }
        }

        &-content {
            padding : 30px 0;
            @include break(s-small) {
                padding : 0;
            }
        }

        &-content-title {

            margin-bottom : 16px;
            @include break(medium) {
                font-size   : 24px;
                line-height : 26px;
            }
            @include break(s-small) {
                font-size   : 22px;
                line-height : 28px;
            }
        }

        &-content-text {
            @extend .a-tag;

            p, li {
                font-size   : 16px;
                line-height : 24px;
                font-weight : 400;
                // @include break(medium){
                //   font-size: 12px;
                //   line-height: 18px;
                // }
                // @include break(s-small){
                //   font-size: 16px;
                //   line-height: 20px;
                // }
            }

            p {
                &:not(:last-child) {
                    margin-bottom : 22px;
                    @include break(medium) {
                        margin-bottom : 18px;
                    }
                    @include break(s-small) {
                        margin-bottom : 20px;
                    }
                }
            }

            ol {
                list-style : decimal;
            }

            ul {
                list-style : disc;
            }

            ol,
            ul {
                margin-left : 18px;

                &:not(:first-child) {
                    margin-top : 18px;
                }

                &:not(:last-child) {
                    margin-bottom : 18px;
                }
            }

            li {
                font-family : $second_font;
                font-weight : 300;
                padding     : 0;
                list-style  : inherit;

                &:not(:last-child) {
                    margin-bottom : 8px;
                }

                &::before {
                    display : none;
                }
            }

            h2, h3, h4, h5, h6 {
                font-size   : 18px;
                line-height : 28px;

                &:not(:last-child) {
                    margin-bottom : 8px;
                }
            }
        }

        &-media {
            //width: 50%;
            display         : flex;
            justify-content : center;
            align-items     : center;

            a {
                display         : flex;
                justify-content : center;
                align-items     : center;
                padding         : 30px;
                height          : 372px;
                @include break(medium850) {
                    height : 298px;
                }
                @include break(small) {
                    padding: 0;
                }
                @include break(s-small) {
                    min-height : 280px;
                    height     : auto;
                }
            }

            img, svg {
                max-width  : 100%;
                max-height : 312px;
                display    : block;
                width      : auto;
                height     : auto;
            }

            &.round {
                img, svg {
                    border-radius : 50px;
                }
            }
        }
    }
}