.testimonial-block {
    $self: &;
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__content-wrapper {
        -webkit-border-radius             : 50px;
        -webkit-border-bottom-left-radius : 0;
        -moz-border-radius                : 50px;
        -moz-border-radius-bottomleft     : 0;
        border-radius                     : 50px;
        border-bottom-left-radius         : 0;
        position                          : relative;
        isolation                         : isolate;
        border                            : 1px solid $purple;
        @include break(s-small) {
            -webkit-border-radius             : 20px;
            -webkit-border-bottom-left-radius : 0;
            -moz-border-radius                : 20px;
            -moz-border-radius-bottomleft     : 0;
            border-radius                     : 20px;
            border-bottom-left-radius         : 0;
        }

        .figure {
            background-image : url("data:image/svg+xml,%3Csvg width='199' height='114' viewBox='0 0 199 114' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cg clip-path='url(%23clip0_5704_34137)'%3E%3Cpath d='M197.07 0.71196L47.6424 107.866C27.9332 122 0.499999 107.911 0.5 83.6545L0.500009 -130.655C0.50001 -154.911 27.9332 -169 47.6424 -154.866L197.07 -47.712C213.643 -35.8268 213.643 -11.1732 197.07 0.71196Z' fill='%23ECDEFF' stroke='%23A142FF'/%3E%3C/g%3E%3Cdefs%3E%3CclipPath id='clip0_5704_34137'%3E%3Crect width='199' height='114' fill='white'/%3E%3C/clipPath%3E%3C/defs%3E%3C/svg%3E");
            width            : 199px;
            height           : 114px;
            left             : -1px;
            bottom           : -113px;
            position         : absolute;
            z-index          : -1;
            @include break(s-small) {
                background-image : url("data:image/svg+xml,%3Csvg width='122' height='69' viewBox='0 0 122 69' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cg clip-path='url(%23clip0_5706_34139)'%3E%3Cpath d='M127.522 -4.88136L30.7505 64.8665C18.1068 73.9793 0.499999 64.8987 0.5 49.2478L0.500006 -90.2479C0.500007 -105.899 18.1068 -114.979 30.7505 -105.866L127.522 -36.1186C138.159 -28.4522 138.159 -12.5478 127.522 -4.88136Z' fill='%23ECDEFF' stroke='%23A142FF'/%3E%3C/g%3E%3Cdefs%3E%3CclipPath id='clip0_5706_34139'%3E%3Crect width='122' height='69' fill='white'/%3E%3C/clipPath%3E%3C/defs%3E%3C/svg%3E%0A");
                width            : 122px;
                height           : 69px;
                bottom           : -69px;
            }
        }
    }

    &__content {
        padding                           : 39px 79px;
        -webkit-border-radius             : 50px;
        -webkit-border-bottom-left-radius : 0;
        -moz-border-radius                : 50px;
        -moz-border-radius-bottomleft     : 0;
        border-radius                     : 50px;
        border-bottom-left-radius         : 0;
        background-color                  : $purple_tint;
        position                          : relative;
        isolation                         : isolate;
        @include break(medium) {
            padding : 39px;
        }
        @include break(s-small) {
            -webkit-border-radius             : 20px;
            -webkit-border-bottom-left-radius : 0;
            -moz-border-radius                : 20px;
            -moz-border-radius-bottomleft     : 0;
            border-radius                     : 20px;
            border-bottom-left-radius         : 0;
            padding                           : 15px;
        }
    }

    &__text {
        font-size     : 22px;
        line-height   : 32px;
        font-family   : $third_font;
        font-weight   : 600;
        color         : $purple;
        margin-bottom : 16px;
        @include break(s-small) {
            font-size   : 15px;
            line-height : 24px;
        }
    }

    &__from {
        color       : $purple;
        font-size   : 18px;
        line-height : 28px;
        @include break(s-small) {
            font-size   : 15px;
            line-height : 22px;
        }
    }

    &__bottom {
        height                : 80px;
        width                 : calc(100% - 169px);
        margin-left           : auto;
        display               : grid;
        grid-template-columns : 113px 1fr;
        grid-column-gap       : 24px;
        column-gap            : 24px;
        margin-top            : 33px;
        @include break(medium) {
            height                : 48px;
            width                 : calc(100% - 134px);
            margin-top            : 59px;
            grid-template-columns : 68px 1fr;
        }
        @include break(s-small) {
            height                : 32px;
            width                 : calc(100% - 74px);
            margin-top            : 36px;
            grid-template-columns : 45px 1fr;
            grid-column-gap       : 16px;
            column-gap            : 16px;
        }
    }

    &__quote {
        height              : 100%;
        background-image    : url("data:image/svg+xml,%3Csvg width='113' height='80' viewBox='0 0 113 80' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M53.1238 12.9287C53.8254 13.843 53.6009 15.1339 52.6468 15.8331C39.457 25.3802 31.2625 32.7758 28.0914 38.0468H28.7088C39.5693 38.0468 48.9424 47.5938 48.9424 58.2973C48.9424 70.1571 38.0819 79.9999 25.0886 79.9999C10.5799 80.0268 0 69.3234 0 54.2633C0 35.8416 13.6107 17.6887 41.1408 0.369622C42.123 -0.248918 43.442 -0.00688067 44.1155 0.907483L53.1238 12.9556V12.9287ZM88.1469 38.0468C99.0074 38.0468 108.381 47.5938 108.381 58.2973C108.381 70.1571 97.52 79.9999 84.5267 79.9999C70.018 79.9999 59.4662 69.2965 59.4662 54.2364C59.4662 35.8147 73.0769 17.6619 100.607 0.342729C101.589 -0.275811 102.908 -0.0337738 103.582 0.88059L112.59 12.9287C113.292 13.843 113.067 15.1339 112.113 15.8331C98.9232 25.3802 90.7287 32.7758 87.5575 38.0468H88.1749H88.1469Z' fill='%233B37E6'/%3E%3C/svg%3E");
        width               : 100%;
        background-position : center;
        background-repeat   : no-repeat;
        background-size     : contain;
    }

    &__figure {
        height        : 80px;
        border        : 1px solid $apricot;
        border-radius : 1000px;
        @include break(medium) {
            height : 48px;
        }
        @include break(s-small) {
            height : 32px;
        }

        &-bg {
            border-radius    : 1000px;
            background-color : $apricot;
            width            : 60.4%;
            height           : 100%;
            margin-left      : auto;
            @include break(medium) {
                width : 64.5%;
            }
            @include break(s-small) {
                width : 69.53%;
            }
        }
    }
    &__wrapper {
        &.media {
            display: grid;
            grid-template-columns: 350px 1fr;
            grid-column-gap: 20px;

            @include break(medium) {
                grid-template-columns: 200px 1fr;
            }
            @include break(small) {
                grid-template-columns: 1fr;
                grid-row-gap: 20px;
            }
        }
        &.video {
            .testimonial-block__media {
                border-radius: 24px;
                border: 1px solid $purple;


                &::before {
                    content    : '';
                    display    : block;
                    position   : absolute;
                    width      : 100%;
                    height     : 100%;
                    background : linear-gradient(180deg, rgba(217, 217, 217, 0) 1.26%, rgba(217, 217, 217, 0) 34.91%, rgba(59, 55, 230, 0.32) 100%);
                    z-index    : 10;
                }
            }
            .testimonial-block__image {
                object-fit: cover;
                width : 100%;
                height : 100%;
            }
        }
    }
    &__media {
        position : relative;
        overflow: hidden;
        display: flex;
        align-items: center;
    }
    &__image {
        width : 100%;
        height : auto;
    }
    &__play-btn {
        cursor           : pointer;
        position         : absolute;
        left             : 0;
        top              : 0;
        width            : 100%;
        height           : 100%;
        background-color : transparent;
        border           : none !important;
        z-index          : 200;
        display          : flex;
        justify-content  : center;
        align-items      : center;

        * {
            pointer-events : none;
        }

        svg {
            width  : 81px;
            height : 93px;

            circle {
                transition : all .4s ease-in-out;
            }
            parth {
                transition : all .5s ease-in-out;
            }
        }
        &:hover {
            svg {
                circle {
                    fill : $blue;
                }
                path {
                    fill : $royal_blue;
                }
            }
        }
    }

    &.testimonial-slider {
        background: $dark;
        border-radius: 116px 116px 0 0;
        padding: 100px 0;
        margin-bottom: 0;

        @include break(ss-small) {
            border-radius: 20px 20px 0 0;
            padding: 40px 0;
        }

        #{ $self }__title {
            color: $white;
            font-size: 70px;
            line-height: 72px;
            max-width: 794px;
            margin: 0 auto 90px;

            @include break(ss-small) {
                font-size: 30px;
                line-height: 40px;
                margin: 0 auto 24px;
                text-align: center;
            }
            + #{ $self }__sub-title {
                margin: -45px auto 90px;

                @include break(ss-small) {
                    margin: -12px auto 24px;
                }
            }
        }
        #{ $self }__sub-title {
            color: $white;
            font-size: 40px;
            line-height: 48px;
            max-width: 794px;
            margin: 0 auto 90px;

            @include break(ss-small) {
                font-size: 16px;
                line-height: 21px;
                margin: 0 auto 24px;
                text-align: center;
            }
        }
    }
    .testimonial-slider-2 {
        max-width: 880px;

        .swiper-wrapper {
            @include break(ss-small) {
                display: grid;
                grid-template-columns: 1fr 1fr;
                grid-template-rows: 1fr 1fr;
                grid-gap: 16px;
            }
        }

        .swiper-slide {
            border-radius: 25px;
            border: 1px solid rgba(141, 157, 181, 0.60);
            background: rgba(37, 47, 89, 0.70);
            display: flex;
            align-items: center;
            padding: 7px 20px 5px;

            @include break(ss-small) {
                width: 100%!important;
            }

            &:hover {
                border: 1px solid $white;
                background: $white;
                cursor: pointer;

                img {
                    filter: none;
                }
            }

            img {
                width: 100%;
                object-fit: contain;
                height: 34px;
                filter: brightness(0) invert(1);
            }

            &.swiper-slide-thumb-active {
                border: 1px solid $white;
                background: $white;

                img {
                    filter: none;
                }
            }
        }
    }
    .testimonial-slider-1 {
        margin-top: 40px;
        .swiper-slide {
            padding: 0 1px 5px;
        }

        .testimonial-block__content {
            background-color: #322764;

            @include break(s-small) {
                padding-bottom: 34px;
            }
        }
        .testimonial-block__figure-bg {
            background-color: $malibu;
        }
        .testimonial-block__figure {
            border-color: $malibu;
        }
        .testimonial-block__content-wrapper .figure {
            background-image : url("data:image/svg+xml,%3Csvg width='199' height='114' viewBox='0 0 199 114' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cg clip-path='url(%23clip0_5704_34137)'%3E%3Cpath d='M197.07 0.71196L47.6424 107.866C27.9332 122 0.499999 107.911 0.5 83.6545L0.500009 -130.655C0.50001 -154.911 27.9332 -169 47.6424 -154.866L197.07 -47.712C213.643 -35.8268 213.643 -11.1732 197.07 0.71196Z' fill='%23322764' stroke='%23A142FF'/%3E%3C/g%3E%3Cdefs%3E%3CclipPath id='clip0_5704_34137'%3E%3Crect width='199' height='114' fill='white'/%3E%3C/clipPath%3E%3C/defs%3E%3C/svg%3E");

            @include break(s-small) {
                background-image : url("data:image/svg+xml,%3Csvg width='122' height='69' viewBox='0 0 122 69' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cg clip-path='url(%23clip0_5706_34139)'%3E%3Cpath d='M127.522 -4.88136L30.7505 64.8665C18.1068 73.9793 0.499999 64.8987 0.5 49.2478L0.500006 -90.2479C0.500007 -105.899 18.1068 -114.979 30.7505 -105.866L127.522 -36.1186C138.159 -28.4522 138.159 -12.5478 127.522 -4.88136Z' fill='%23322764' stroke='%23A142FF'/%3E%3C/g%3E%3Cdefs%3E%3CclipPath id='clip0_5706_34139'%3E%3Crect width='122' height='69' fill='white'/%3E%3C/clipPath%3E%3C/defs%3E%3C/svg%3E%0A");
                width            : 122px;
                height           : 69px;
                bottom           : -69px;
            }
        }
        .testimonial-block__text {
            p {
                color: $white;
                font-size: 22px;
                font-weight: 600;
                line-height: 32px;
            }
        }
        .testimonial-block__from {
            color: $white;
            padding-inline-end: 260px;
            font-family: $second_font;
            font-weight: 300;
            font-size: 18px;
            position : relative;

            @include break(ss-small) {
                padding: 0 0 50px 0;
            }
        }
        .testimonial-block__stars {
            position : absolute;
            right: 0;
            bottom: -10px;

        }
        .testimonial-block__stars-animations {
            width : 255px;
            height : 40px;
        }
    }

    & +.related-resources {
        margin-top: 0;

        @include break(medium) {
            margin-top: 0;
        }
    }
}