.book-a-demo {
    overflow         : hidden;
    background-color : $blue;
    display          : flex;
    min-height       : 554px;
    padding: 0!important;

    @include break(medium) {
        min-height : 380px;
    }
    @include break(s-small) {
        min-height : auto;
    }
    &.has-form {
        .book-a-demo__title {
            font-size: 70px;
            font-weight: 600;
            line-height: 72px;

            @include break(small) {
                font-size: 30px;
                line-height: 34px;
                padding: 0 44px;
            }
            @include break(small-375) {
                padding: 0 29px;
            }
        }
        .book-a-demo__container {
            padding: 152px 0 97px;

            @include break(medium) {
                padding: 120px 15px 70px;
            }
            @include break(small) {
                padding: 62px 15px 23px;
            }
        }
        .book-a-demo__text {
            @include break(small) {
                font-size: 18px;
                line-height: 110%;
                padding: 0 40px;
            }
        }
        .hbspt-form {
            @include break(small) {
                max-width: 281px;
                margin: 0 auto;
            }

            .hs-richtext {
                a {
                    color : $white!important;
                }
            }
        }
    }

    &__container {
        padding-top    : 140px;
        padding-bottom : 80px;
        position       : relative;
        isolation      : isolate;
        @include break(medium) {
            padding-top    : 106px;
            padding-bottom : 106px;
            padding-left   : 75px;
            padding-right  : 75px;
        }
        @include break(ss-small) {
            padding-top    : 80px;
            padding-bottom : 80px;
        }
        @include break(s-small) {
            padding-top    : 80px;
            padding-bottom : 80px;
            padding-left   : 30px;
            padding-right  : 30px;
