                    left : -25vw;
                }
                @include break(medium) {
                    width  : 197px;
                    height : 197px;
                    bottom : -71px;
                    left   : -130px;
                }
                @include break(ss-small) {
                    width  : 178px;
                    height : 178px;
                    left   : -119px;
                    bottom : -86px;
                }
            }

            &-5 {
                background-color : $dark;
                opacity          : 0.6;
                border-radius    : 150px;
                width            : 606px;
                height           : 292px;
                bottom           : -126px;
                //right: -380px;
                right            : -380px;
                @include break(large1370) {
                    right : -33.389%;
                }
