        .hs-richtext {
            * {
                color: #FFF;
            }

            a {
                text-decoration: underline;

                &:hover {
                    text-decoration: none;
                }
            }
        }
    }

    &__wrapper {
        text-align : center;
    }

    &__title {
        text-align   : center;
        max-width    : 794px;
        width        : 100%;
        margin-left  : auto;
        margin-right : auto;
        color        : $white;
        @include break(medium) {
            max-width   : none;
            font-size   : 40px;
            line-height : 48px;
        }
        @include break(s-small) {
            font-size   : 32px;
            line-height : 34px;
        }

        &-small {
            @media screen and (min-width : 992px) {
                font-size   : 60px;
                line-height : 62px;
                max-width   : 72%;
            }
            @media screen and (min-width : 1199px) {
                font-size   : 60px;
                line-height : 62px;
                max-width   : 66%;
            }
        }
    }
    &__text-container {
        max-width    : 794px;
        width        : 100%;
        margin-left  : auto;
        margin-right : auto;
        position : relative;
    }

    &__text {
        margin-top   : 16px;
        color        : $white;
        font-size    : 25px;
        line-height  : 35px;
        text-align   : center;
        font-weight  : 600;
        @include break(medium) {
            margin-top  : 8px;
            font-size   : 15px;
            line-height : 24px;
        }

        &-small {
            @media screen and (min-width : 992px) {
                max-width : 988px;
            }
        }
    }

    &__button-wrapper {
        margin-top : 48px;
        @include break(medium) {
            margin-top : 32px;
        }
    }

    &__button {
        display             : inline-block;
        padding             : 16px 40px;
        background-color    : $white;
        font-family         : $third_font;
        font-size           : 20px;
        line-height         : 24px;
        color               : $dark;
        text-align          : center;
        border-radius       : 15px;
        transition          : .3s linear;
        transition-property : background-color, color;

        &:hover {
            background-color : $dark;
            color            : $white;
        }
    }

    &__form-wrapper {
        max-width : 814px;
        margin: 72px auto 0;
        position : relative;

        @include break(medium) {
            margin-top: 40px;
        }

        @include break(x-small) {
            margin-top: 16px;
        }
    }
    @extend .hubspot-form;

    .hbspt-form {
        .hs-submit {
            input[type="submit"] {
                background-color: transparent;
                border: 1px solid $white;

                &:hover {
                    border-color: $dark;
                }
            }
        }
    }
    &__animation-arrow {
        position : absolute;
        top : -100px;
        left : -160px;
        animation: move-arrow-demo 3.5s infinite;

        &-he {
            display : none;
        }

        @include break(ss-small) {
            display: none;
            animation: none;
            width: 40px;
            height: 70px;
            left: 25px;
            transform: rotate(336deg);
            top: -17px;
        }
        @include break(small-375) {
            left: 16px;
        }

        svg {
            @include break(ss-small) {
                width: 40px;
                height: 70px;
            }
        }
    }
}
@keyframes move-arrow-demo {
    0% {-webkit-transform: rotate(10deg); opacity: 0;}
    60% { opacity: 1;}
    100% {-webkit-transform: rotate(5deg); opacity: 0;}
}
