.newsletter-block {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__wrapper {
        padding          : 24px 32px;
        background-color : #FBF8FF;
        border           : 1px solid $purple;
        border-radius    : 24px;
        @include break(medium) {
            padding : 32px;
        }
        @include break(s-small) {
            padding    : 24px;
            text-align : center;
        }
    }

    &__block {
        display               : grid;
        grid-template-columns : 1fr 321px;
        column-gap            : 40px;
        max-width             : 944px;
        margin-left           : auto;
        margin-right          : auto;
        @include break(medium) {
            grid-template-columns : 1fr 210px;
            column-gap            : 58px;
        }
        @include break(ss-small) {
            column-gap            : 20px;
            grid-template-columns : 1fr 160px;
        }
        @include break(s-small) {
            grid-template-columns : 1fr;
        }
    }

    &__content {
        align-self : center;
    }

    &__title {
        font-size   : 40px;
        line-height : 48px;
        color       : $purple;
        @include break(medium850) {
            font-size   : 22px;
            line-height : 28px;
        }
    }

    &__text {
        font-size   : 18px;
        line-height : 28px;
        margin-top  : 8px;
        @include break(medium850) {
            font-size   : 15px;
            line-height : 22px;
        }
    }

    &__form {
        margin-top : 32px;
        @include break(medium) {
            margin-top : 16px;
        }
    }
    @extend .hubspot-form;

    .hubspot-form {
        padding: 0;
        background-color: transparent;

        .hbspt-form {
            .input,
            .hs-form-field {
                select,
                input[type="number"],
                input[type="text"],
                input[type="email"],
                input[type="tel"],
                textarea {
                    border-color: $purple;
                }
            }
            .hs-submit {
                text-align: left;
                margin-top: 2px;

                input[type="submit"] {
                    background-color: $purple;
                }
            }
            select {
                option {
                    &:hover {
                        background-color : #fbf8ff;
                    }
                }
            }
        }
    }

    &__media {
        align-self : center;
        @include break(s-small) {
            display : none;
        }
    }

    &__image {
        max-width  : 320px;
        max-height : 264px;
        width      : 100%;
        height     : auto;
        display    : block;
        object-fit : cover;
    }
}