.content-columns-with-icons{
    margin-top: $desktop_margin;
    margin-bottom: $desktop_margin;
    @include break(medium){
        margin-top: $mobile_margin;
        margin-bottom: $mobile_margin;
    }

    &__container{
        padding-left: 0;
        padding-right: 0;
        @include break(desktop){
            padding-left: 28px;
            padding-right: 28px;
        }
        @include break(ss-small){
            padding-left: 16px;
            padding-right: 16px;
        }
    }
    &__wrapper{
        display: flex;
        row-gap: 40px;
        justify-content: center;
        flex-wrap: wrap;
        max-width: 1280px;
        @include break(ss-small){
            row-gap: 24px;
        }
    }
    &__title{
        margin-bottom: 48px;
        font-size: 32px;
        line-height: 48px;
        text-align: center;
        @include break(medium){
            margin-bottom: 24px;
            font-size: 22px;
            line-height: 28px;
        }
    }
    &__card{
        padding: 0 40px;
        width: 33.3333%;
        @include break(desktop){
            padding: 0 12px;
        }
        @include break(medium){
            width: 50%;
        }
        @include break(ss-small){
            width: 100%;
            padding: 0;
        }
        &-heading{
            &.grid{
                display: grid;
                grid-template-columns: 65px 1fr;
                column-gap: 14px;
        
            }
        }
        &-icon{
            display: flex;
            justify-content: center;
            align-items: center;
            width: 56px;
            height: 56px;
            align-self: center;
            img,svg{
                display: block;
                max-width: 100%;
                max-height: 100%;
                width: 100%;
                height: auto;
            }
        }
        &-title{
            align-self: center;
            margin-bottom: 0;
            font-size: 22px;
            line-height: 28px;
        }
        &-text{
            margin-top: 18px;
        }
    }
}