.left-side-monitor-content {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__container {
        &.js-animate-parent {
            &.animate {
                .js-animate-element {
                    opacity   : 1;
                    transform : translate3d(0, 0, 0);
                }
            }
        }

        .js-animate-element {
            transition : opacity .4s, transform .8s cubic-bezier(0.165, 0.84, 0.44, 1);
            opacity    : 0;
            transform  : translate3d(0, 50%, 0);
        }
    }

    &__wrapper {
        display               : grid;
        grid-template-columns : 589px 1fr;
        column-gap            : 20px;
        row-gap               : 36px;
        max-width             : 1200px;
        margin-left           : auto;
        margin-right          : auto;
        @include break(desktop) {
            grid-template-columns : 450px 1fr;
        }
        @include break(medium) {
            grid-template-columns : 312px 1fr;
        }
        @include break(medium850) {
            grid-template-columns : 292px 1fr;
        }
        @include break(ss-small) {
            grid-template-columns : 266px 1fr;
        }
        @include break(s-small) {
            grid-template-columns : 1fr;
        }
    }

    &__main-title {
        text-align    : center;
        margin-bottom : 53px;
        @include break(medium) {
            margin-bottom : 59px;
        }
        @include break(x-small) {
            margin-bottom : 48px;
        }
    }

    &__media {
        align-self : center;
    }

    &__media-wrapper {
        height   : 412px;
        position : relative;
        @include break(medium) {
            height : 260px;
        }
        @include break(s-small) {
            width        : 266px;
            margin-left  : auto;
            margin-right : auto;
        }
        @include break(small-375) {
            width  : 233px;
            height : 230px;
        }

        .figure {
            position      : absolute;
            z-index       : 10;
            border-radius : 46px;
            @include break(medium) {
                border-radius : 29px;
            }

            &-1 {
                width  : 195px;
                height : 334px;
                top    : 0;
                left   : 42px;
                @include break(desktop) {
                    left : -97px;
                }
                @include break(medium) {
                    width  : 123px;
                    height : 211px;
                    left   : -52px;
                }
                @include break(small-375) {
                    width  : 122px;
                    height : 173px;
                    top    : 21px;
                    left   : -36px;
                }

                &.blue {
                    background-color : $blue;
                }

                &.coral {
                    background-color : $coral;
                }

                &.purple {
                    background-color : $purple;
                }

                &.light-blue {
                    background-color : $light_blue;
                }
            }

            &-2 {
                width  : 180px;
                height : 334px;
                border : 1px solid;
                top    : 0;
                left   : 253px;
                @include break(desktop) {
                    left : 114px;
                }
                @include break(medium) {
                    width  : 114px;
                    height : 211px;
                    left   : 82px;
                }
                @include break(small-375) {
                    width  : 93px;
                    height : 173px;
                    top    : 21px;
                    left   : 94px;
                }

                &.blue {
                    border-color : $blue;
                }

                &.coral {
                    border-color : $coral;
                }

                &.purple {
                    border-color : $purple;
                }

                &.light-blue {
                    border-color : $light_blue;
                }
            }
        }

        .monitor-block {
            position : absolute;
            top      : 45px;
            right    : 44px;
            z-index  : 20;
            width    : 422px;
            height   : 259px;
            @include break(medium) {
                top    : 29px;
                right  : 28px;
                width  : 266px;
                height : 163px;
            }
            @include break(ss-small) {
                right : 0;
            }
            @include break(s-small) {
                left      : 50%;
                right     : auto;
                transform : translateX(-50%);
            }
            @include break(small-375) {
                width  : 218px;
                height : 133px;
                top    : 44px;
            }

            .monitor {
                width               : 422px;
                height              : 259px;
                background-image    : url("data:image/svg+xml,%3Csvg width='422' height='259' viewBox='0 0 422 259' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M412.758 0H9.24213C4.13784 0 0 4.14654 0 9.26155V249.176C0 254.291 4.13784 258.437 9.24213 258.437H412.758C417.862 258.437 422 254.291 422 249.176V9.26155C422 4.14654 417.862 0 412.758 0Z' fill='url(%23paint0_linear_4302_51938)'/%3E%3Cpath d='M412.76 1.08594H9.27263C4.75125 1.08594 1.08594 4.75895 1.08594 9.28984V249.176C1.08594 253.706 4.75125 257.379 9.27263 257.379H412.76C417.281 257.379 420.947 253.706 420.947 249.176V9.28984C420.947 4.75895 417.281 1.08594 412.76 1.08594Z' fill='url(%23paint1_linear_4302_51938)'/%3E%3Cdefs%3E%3ClinearGradient id='paint0_linear_4302_51938' x1='8.47194' y1='-8.08956' x2='409.206' y2='262.459' gradientUnits='userSpaceOnUse'%3E%3Cstop stop-color='%23FAFAFA'/%3E%3Cstop offset='0.34' stop-color='%23D0D0D0'/%3E%3Cstop offset='0.67' stop-color='%23EDEDED'/%3E%3Cstop offset='1' stop-color='%23BEBEBE'/%3E%3C/linearGradient%3E%3ClinearGradient id='paint1_linear_4302_51938' x1='211.002' y1='2.08641' x2='211.002' y2='255.893' gradientUnits='userSpaceOnUse'%3E%3Cstop stop-color='%23F0F0F1'/%3E%3Cstop offset='1' stop-color='%23E6E6E6'/%3E%3C/linearGradient%3E%3C/defs%3E%3C/svg%3E%0A");
                background-position : center;
                background-repeat   : no-repeat;
                background-size     : contain;
                padding             : 17px 17px 20px 17px;
                position            : relative;
                z-index             : 30;
                @include break(medium) {
                    width   : 266px;
                    height  : 163px;
                    padding : 10px 10px 12px 10px;
                }
                @include break(small-375) {
                    width   : 218px;
                    height  : 133px;
                    padding : 8px 8px 10px 8px;
                }

                a {
                    display : block;
                    width   : 100%;
                    height  : 100%;
                }

                img, svg {
                    display       : block;
                    width         : 100%;
                    height        : 100%;
                    object-fit    : cover;
                    border-radius : 5px;
                }
                &__animation {
                    height  : 225px;

                    @include break(medium) {
                        height  : 127px;
                    }
                    @include break(x-small) {
                        height  : 117px;
                    }
                }
            }

            .monitor-bottom {
                position   : absolute;
                z-index    : 25;
                left       : 50%;
                transform  : translateX(-50%);
                top        : 100%;
                margin-top : -1px;

                img {
                    @include break(medium) {
                        width  : 273px;
                        height : auto;
                    }
                }
            }
        }
    }

    &__content-wrapper {
        align-self : center;
    }

    &__content {
        // padding-left: 42px;
        // padding-right: 28px;
        @include break(ss-small) {
            padding : 0;
        }
        @include break(s-small) {
            padding-left  : 6px;
            padding-right : 6px;
            text-align    : center;
        }
    }

    &__title {
        font-size   : 40px;
        line-height : 44px;
        font-family : $main_font;

        @include break(medium850) {
            font-size   : 24px;
            line-height : 29px;
        }
        @include break(x-small) {
            max-width    : 255px;
            margin-left  : auto;
            margin-right : auto;
            font-size    : 20px;
            line-height  : 23px;
        }
    }

    &__text {
        margin-top : 26px;
        @include break(medium850) {
            margin-top : 22px;
        }
        @include break(x-small) {
            margin-top : 20px;
        }
        @extend .block-page-content;
    }

    &__button-wrapper {
        margin-top : 26px;
        @include break(medium850) {
            margin-top : 30px;
        }
        @include break(x-small) {
            margin-top : 28px;
        }
    }

    &__button {
        @extend .blue-btn;
    }
}