.huge-title-with-text {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }
    .js-animate-parent {
        &.animate {
            .animation-title,
            .animation-text {
                opacity   : 1;
                transform : translate3d(0, 0, 0);
            }
        }

        .animation-title,
        .animation-text {
            transition : opacity .4s, transform .8s cubic-bezier(0.165, 0.84, 0.44, 1);
            opacity    : 0;
            transform  : translate3d(0, 50%, 0);
        }

        .animation-text {
            transition-delay : 0.5s;
        }
    }

    &__title {
        text-transform      : uppercase;
        text-align          : center;
        font-size           : 208px;
        line-height         : 1;
        color               : $blue_tint;
        -webkit-text-stroke : 1px $light_blue;
        @include break(large1370) {
            font-size : 15vw;
        }
        @include break(x-small) {
            font-size : 91px;
        }
        @include break(small-360) {
            font-size : 18vw;
        }
    }

    &__text {
        max-width    : 750px;
        margin-left  : auto;
        margin-right : auto;
        font-size    : 25px;
        line-height  : 34px;
        position     : relative;
        z-index      : 10;
        text-align   : center;
        @include break(medium) {
            margin-top : 14px;
        }
        @include break(small) {
            font-size   : 14px;
            line-height : 20px;
            max-width   : 566px;
        }
    }
}