.billboard-hero-section {
    margin-top    : 87px;
    margin-bottom : $desktop_margin;

    @include break(medium) {
        margin-top    : 16px;
        margin-bottom : 24px ;
    }
    &__wrapper {
        display: grid;
        grid-template-columns: 1fr 488px;
        grid-column-gap: 54px;
        padding: 0 80px;

        @include break(large1470) {
            padding: 0 15px;
        }
        @include break(desktop) {
            grid-template-columns: 1fr 1fr;
        }
        @include break(medium850) {
            display: block;
        }
        @include break(desktop) {
            padding: 0;
        }
    }
    .container {
        @include break(small) {
            padding: 0 15px;
        }
    }
    &__subtitle {
        color: $dark;
        font-family: $third_font;
        font-size: 26px;
        font-weight: 300;
        line-height: 103%;

        @include break(desktop) {
            text-align: center;
        }
    }
    &__animation-area {
        font-family: $third_font;
        font-size: 60px;
        font-weight: 600;
        line-height: 62px;
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 18px;
        margin: 24px 0;

        @include break(desktop) {
            font-size: 32px;
            line-height: 40px;
            justify-content: center;
            gap : 15px;
        }
        @include break(ss-small) {
            text-align: center;
        }
        @include break(small-375) {
            font-size: 28px;
        }

        .typing-animation {
            color: $blue;
            font-weight: 600;
            min-height: 62px;

            @include break(desktop) {
                min-height: 26px;
            }
        }
    }
    &__animation-text {
        font-size: 60px;
        font-weight: 600;
        color: $dark;
        line-height: 62px;

        @include break(desktop) {
            font-size: 32px;
            line-height: 40px;
        }
    }
    &__badge-area {
        display: grid;
        grid-template-columns: repeat(3, 184px);
        grid-gap: 16px;

        @include break(desktop) {
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
        }
    }
