.hero-w-iframe {
    padding-top: 16px;
    padding-bottom: 120px;

    @include break(x-small) {
        padding-top: 12px;
        padding-bottom: 40px;
        background-color: #FFF !important;
    }

    &__container {
        display: flex;
        justify-content: center;

        .hbspt-form .hs-recaptcha {
            width: 0 !important;
            float: none !important;
            display: none !important;
        }

        .hbspt-form fieldset .hs-dependent-field .hs-form-field.hs_state {
            width: calc((100%* 2) + 16px) !important;
            position: relative;
            left: calc(-100% - 16px);
            margin-top: 16px;
        }
    }

    &__iframe-wrapper {
        overflow: hidden;
        max-width: 1200px;
        width: 100%;
        height: 624px;
        border: 1px solid #3B37E6;
        border-radius: 35px;
        position: relative;
        z-index: 1;

        @include break(x-small) {
            height: 590px;
        }

        &:before {
            position: absolute;
            content: '';
            display: block;
            left: 0;
            top: 0;
            border-radius: 30px;
            width: 100%;
            height: 100%;
            z-index: 1;
            background: linear-gradient(0deg, rgba(22, 33, 61, 0.75) 0%, rgba(22, 33, 61, 0.75) 100%);
        }

        &.active {
            @include break(x-small) {
                height: unset;
                border-radius: unset;
                border: unset;
            }

            &:before {
                display: none;
            }
        }
    }

    &__iframe {
        border-radius: 30px;
        overflow: hidden;
        width: 100%;
        height: 100%;
    }

    .popup-start-now,
    .popup-see-more {
        position: absolute;
        z-index: 3;
        left: 50%;
        top: 50%;
        transform: translate(-50%, -50%);
        padding: 40px 24px;
        border-radius: 20px;
        border: 1px solid #3B37E6;
        background: #16213D;
        width: 634px;

        @include break(x-small) {
            width: calc(100% - 24px);
        }

        &__title,
        &__desc {
            color: #FFF;
            text-align: center;
        }

        &__title {
            font-family: "Axiforma", sans-serif;
            margin-bottom: 8px;

            @include break(x-small) {
                margin-bottom: 16px;
            }
        }

        &__desc {
            font-family: "Open Sans", sans-serif;
            font-size: 15px;
            font-style: normal;
            font-weight: 300;
            line-height: 1.46;
            margin-bottom: 32px;

            @include break(x-small) {
                max-width: 297px;
                margin-left: auto;
                margin-right: auto;
                margin-bottom: 24px;
            }
        }

        &__form-wrap {
            .hbspt-form {
                input[type="text"],
                input[type="email"],
                input[type="tel"],
                select,
                textarea {
                    height: 48px;
                    width: 100% !important;
                    padding: 10px 16px;
                    font-size: 13px;
                    line-height: 16px;
                    color: #16213D;
                    background-color: #fff;
                    border: 1px solid rgba(22, 33, 61, 0.1);
                    border-radius: 10px;
                }

                select {
                    height              : 48px;
                    width               : 100%!important;
                    padding             : 10px 35px 10px 16px;
                    font-size           : 13px;
                    line-height         : 16px;
                    color               : $dark;
                    background-color    : $white;
                    border              : 1px solid rgba(22, 33, 61, 0.1);
                    border-radius       : 10px;
                    -moz-appearance     : none; /* Firefox */
                    -webkit-appearance  : none; /* Safari and Chrome */
                    appearance          : none;
                    background-image    : url("data:image/svg+xml,%3Csvg width='14' height='8' viewBox='0 0 14 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M13 1L7 7L1 0.999999' stroke='%233B37E6'/%3E%3C/svg%3E%0A");
                    background-position : center right 19px;
                    background-repeat   : no-repeat;

                    &.error {
                        border-color : $red;
                    }

                    &::placeholder {
                        color : rgba(22, 33, 61, 0.4);
                    }

                    &.is-placeholder {
                        color : rgba(22, 33, 61, 0.4);
                    }
                }

                label {
                    display: none;
                }

                .form-columns-2 {
                    display: flex;
                    gap: 16px;

                    @include break(ss-small) {
                        flex-direction: column;
                        align-items: center;
                    }

                    .hs-dependent-field {
                        width: 50%;
                    }
                }

                fieldset {
                    width: 100%;
                    max-width: 100%;


                }

                form {
                    display: flex;
                    flex-direction: column;
                    // gap: 16px;

                    fieldset[class*="form-columns-"] {
                        margin-bottom: 16px;
                        gap: 16px;

                        &:last-child {
                            margin-bottom: 0;
                        }
                    }

                    .hs_recaptcha {
                        margin-bottom: 16px;
                    }
                }

                .input {
                    margin-right: 0;
                }

                .hs-richtext {
                    margin-left: auto;
                    margin-right: auto;
                    margin-bottom: 16px;

                    p {
                        color: #FFF;
                        font-family: "Open Sans", sans-serif;
                        font-size: 13px;
                        font-style: normal;
                        font-weight: 600;
                        line-height: 18px;
                        text-align: center;

                        * {
                            color: inherit;
                            font-family: inherit;
                            font-size: inherit;
                            font-style: inherit;
                            font-weight: inherit;
                            line-height: inherit;
                        }

                        a {
                            &:hover {
                                text-decoration: underline;
                            }
                        }
                    }
                }

                .hs_submit {
                    .actions {
                        display: flex;
                        justify-content: center;
                    }
                }
            }

            .hbspt-form .form-columns-2 {
                display: grid;
                grid-template-columns: 1fr 1fr;

                @include break(x-small) {
                    grid-template-columns: 1fr;
                }

                > .hs-dependent-field,
                > .hs-form-field {
                    width: 100%;
                    float: none;
                }
            }
            .hbspt-form .form-columns-3 {
                display: grid;
                grid-template-columns: 1fr 1fr 1fr;

                @include break(x-small) {
                    grid-template-columns: 1fr;
                }

                > .hs-dependent-field,
                > .hs-form-field {
                    width: 100%;
                    float: none;
                }
            }
        }
    }

    .popup-start-now {

    }

    .popup-see-more {
        display: none;

        &.active {
            display: block;
        }

        &__btns {
            display: flex;
            gap: 16px;
            justify-content: center;

            @include break(x-small) {
                flex-direction: column;
                align-items: center;
            }
        }
    }
}
