.case-study-carousel{
    margin-top: $desktop_margin;
    margin-bottom: $desktop_margin;
    overflow: hidden;
    @include break(medium){
        margin-top: $mobile_margin;
        margin-bottom: $mobile_margin;
    }
    &__slider{
        max-width: 1320px;
        margin-left: auto;
        margin-right: auto;
        &.swiper{
            .swiper-slide{
                padding-left: 100px;
                padding-right: 100px;
                height: auto;
                @include break(large1370){
                    padding-left: 50px;
                    padding-right: 50px;
                }
                @include break(desktop){
                    padding-left: 0;
                    padding-right: 0;
                }
                opacity: 0 !important;
                &-active{
                    opacity: 1 !important;
                }
            }
            .swiper-pagination{
                display: none;
                @include break(desktop){
                    display: flex;
                    margin-top: 22px;
                }
                @include break(x-small){
                    margin-top: 21px;
                }
            }
      
        }
    }
    &__slide{
        margin-left: auto;
        margin-right: auto;
        height: 100%;
        display: grid;
        grid-template-columns: 486px 1fr;
        column-gap: 10px;
        padding: 67px 66px 67px 63px;
        background-color: $light_blue_tint;
        border: 1px solid $blue;
        border-radius: 50px;
        @include break(desktop){
            grid-template-columns: 320px 1fr;
        }
        @include break(medium){
            padding: 16px 17px 19px 28px;
            border-radius: 30px;
            column-gap: 7px;
        }
        @include break(ss-small){
            grid-template-columns: 260px 1fr;
      
        }
        @include break(s-small){
            display: flex;
            flex-direction: column-reverse;
            justify-content: space-between;
            padding: 17px 16px 14px 16px;
            border-radius: 20px;
        }
        &-content-wrapper{
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            @include break(s-small){
                height: 100%;
            }
        }
        &-content{
            margin-bottom: 15px;
            @include break(medium){
                margin-bottom: 5px;
                padding-top: 12px;
            }
            @include break(s-small){
                padding-top: 0;
                margin-bottom: 0;

            }
        }
        &-title{
            color: $blue;
            font-size: 40px;
            line-height: 48px;
            @include break(desktop){
                font-size: 24px;
                line-height: 29px;
                max-width: 300px;
            }
            @include break(ss-small){
                font-size: 18px;
                line-height: 22px;
            }
            @include break(s-small){
                max-width: none;
            }
            &:hover{
                color: $dark;
            }
            a{
                @extend .inherit;
                transition:color .3s linear;
            }
        }
        &-logo-wrapper{
            margin-top: 6px;
            @include break(medium){
                margin-top: 13px;
            }
            @include break(s-small){
                margin-top: 7px;
            }
            img,svg{
                max-height: 40px;
                height: auto;
                width: auto;
                display: block;
                @include break(medium){
                    max-height: 28px;
                }
                @include break(s-small){
                    max-height:30px;
                }
            }
        }
        &-excerpt{
            margin-top: 16px;
            max-width: 325px;
            font-family: $second_font;
            font-weight: 300;
            color: #3C455A;
            font-size: 15px;
            line-height: 22px;
            @include break(medium){
                margin-top: 7px;
                font-size: 14px;
                line-height: 21px;
                max-width: 305px;
            }
            @include break(ss-small){
                font-size: 12px;
                line-height: 15px;
            }
            @include break(s-small){
                max-width: none;
                margin-top: 11px;
            }
        }
        &-more{
            margin-top: 11px;
            display: inline-block;
            font-size: 16px;
            line-height: 24px;
            color: $blue;
            padding-right: 24px;
            position: relative;
            transition:color .3s linear;
            @include break(ss-small){
                padding-right: 20px;
            }
            @include break(s-small){
                margin-top: 13px;
            }
            &:hover{
                color: $dark;
                &::after{
                    background-image: url("data:image/svg+xml,%3Csvg width='8' height='11' viewBox='0 0 8 11' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1.5 10L7.5 5.5L1.5 1' stroke='%2316213D' stroke-width='1.3' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E%0A");
                }
            }
            &::after{
                content: '';
                display: block;
                width: 16px;
                height: 16px;
                position: absolute;
                right: 0;
                top: 50%;
                background-image: url("data:image/svg+xml,%3Csvg width='8' height='11' viewBox='0 0 8 11' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1.5 10L7.5 5.5L1.5 1' stroke='%233B37E6' stroke-width='1.3' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E%0A");
                background-position: center;
                background-repeat: no-repeat;
                transition:background-image .3s linear;
                transform: translateY(-50%);
            }
        }
        &-tags{
            display: flex;
            flex-wrap: wrap;
            @include break(s-small){
                margin-top: 22px;
            }
            a{
                transition:background-color .3s linear;
                &:hover{
                    background-color: rgba(22, 33, 61, 0.1);
                }
            }
        }
        &-tag{
            border: 1px solid #3C455A;
            box-shadow: 0px 0px 43.893px rgba(0, 0, 0, 0.04);
            border-radius: 9px;
            padding: 4px 25px;
            font-size: 14px;
            line-height: 22px;
            color: #3C455A;
            margin-top: 10px;
            @include break(desktop){
                font-size: 10px;
                line-height: 16px;
                padding: 3px 16px;
                border-radius: 6px;
                margin-top: 7px;
            }
            @include break(s-small){
                margin-top: 8px;
            }
            &:not(:last-child){
                margin-right: 6px;
            }
        }
        &-image-wrapper{
            position: relative;
            height: 463px;
            overflow: hidden;
            @include break(medium){
                height: 352px;
            }
            @include break(s-small){
                height: auto;
                min-height: 300px;
                margin-bottom: 23px;
            }
            @include break(x-small){
                min-height: 250px;
            }
            @include break(small-375){
                min-height: 185px;
            }
            .mask-element{
                position: absolute;
                z-index: 100;
                background-repeat: no-repeat;
                left: -1px;
                top: 0px;
                background-image:url('data:image/png;base64,');
                background-size: cover;
                width: 260px;
                height: 463px;
                background-position: top left;
                @include break(medium){
                    background-image: url("data:image/svg+xml,%3Csvg width='167' height='352' viewBox='0 0 167 352' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M8.27295 324.589L143.94 15.9518C148.25 6.14745 156.769 0 166.058 0H0V352H22.1811C10.3806 352 2.79551 337.056 8.27926 324.589H8.27295Z' fill='%23F3F6FF'/%3E%3C/svg%3E%0A");
                    width: 167px;
                    height: 353px;
                    top: -1px;
                    left: 0;
                }
                @include break(s-small){
                    background-image: url("data:image/svg+xml,%3Csvg width='309' height='65' viewBox='0 0 309 65' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M292.464 19.9931L22.2371 59.7418C10.5215 61.4665 0 52.475 0 40.7447V65.0005H309.002V0.996094C309.002 10.5145 301.962 18.5964 292.459 19.9931H292.464Z' fill='%23F3F6FF'/%3E%3C/svg%3E%0A");
                    width: calc(100% + 3px);
                    height: calc(100% + 1px);
                    background-position: bottom left;
                    background-size: contain;
                    top: auto;
                    bottom: -1px;
                    left: -2px;
                }
                @include break(small-375){
                    width: calc(100% + 3px);
                    bottom: -1px;
                    left: -1px;
                }
            }
        }
        &-image-link{
            display: block;
            width: 100%;
            height: 100%;
            border-radius: 40px;
            position: relative;
            @include break(medium){
                border-radius: 28px;
            }
            @include break(s-small){
                border-radius: 19px;
            }
        }
        &-image{
            display: block;
            object-fit: cover;
            width: 100%;
            height: 100%;
            border-radius: 40px;
            @include break(medium){
                border-radius: 28px;
            }
            @include break(s-small){
                border-radius: 19px;
            }
        }
    }
}
