.news-card{
    padding: 0 10px;
    width: 33.3333%;
    margin-bottom: $desktop_margin;
    @include break(medium){
        width: 50%;
        margin-bottom: $mobile_margin;
    }
    @include break(s-small){
        width: 100%;
        padding: 0;
    }
    &__wrapper{
        padding: 15px;
        border-radius: 16px;
        border: 1px solid $blue;
        height: 100%;
        display: flex;
        flex-direction: column;
        transition:background-color .3s linear;
    }
    &__media{
        margin-bottom: 16px;
        border-radius: 15px;
        overflow: hidden;
        min-height: 224px;
        height: 224px;
    }
    &__image{
   
        width: 100%;
        min-height: 224px;
        height: 224px;
        &.media{
            display: flex;
            justify-content: center;
            align-items: center;
        }
        img{
            max-width: 100%;
            max-height: 100%;
            height: auto;
            width: auto;
            &.press{
                object-fit: cover;
                height: 100%;
                width: 100%;
            }
        }
    }
    &__content-wrapper{
        display: flex;
        justify-content: space-between;
        flex-direction: column;
        height: 100%;
        @include break(s-small){
            height: auto;
        }
    }
    &__content{

    }
    &__type-date-wrapper{
        margin-bottom: 16px;
        display: flex;
        gap: 8px;
        flex-wrap: wrap;
    }
    &__type,
    &__date{
        border-radius: 10px;
        padding: 5px 15px;
        border: 1px solid;
        font-family: $third_font;
        font-weight: 600;
        font-size: 13px;
        line-height: 16px;
        text-align: center;
    }
    // &__type{
    //   &.media{
    //     border-color: $malibu;
    //     background-color: $blue_tint;
    //   }
    //   &.press{
    //     border-color: $purple;
    //     background-color: $purple_tint;
    //   }
    // }
    &__date{
        background-color: rgba($color: $dark, $alpha: 0.1);
        border-color: $dark;
    }
    &__title{
        font-size: 18px;
        line-height: 28px;
        transition:color .3s linear;
        &:hover{
            color: $blue;
        }
    }
    &__link{
        @extend .inherit;
    }
    &__read-wrapper{
        margin-top: 16px;
    }
    &__read{
        @extend .arrow-btn-right;
        font-family: $third_font;
        font-weight: 600;
    }
}