.single-events-webinars{
    .breadcrumbs{
        margin-top: 24px;
        margin-bottom: 16px;
        @include break(medium){
            margin-top: 16px;
        }
    }
}
.related-ew{
    margin-top: 110px;
    margin-bottom: 40px;
    @include break(medium){
        margin-top: 64px;
        margin-bottom: 24px;
    }
    @include break(s-small){
        margin-top: 40px;
    }
    &__container{
        padding-left: 30px;
        padding-right: 30px;
        @include break(ss-small){
            padding-left: 6px;
            padding-right: 6px;
        }
        @include break(s-small){
            padding-left: 16px;
            padding-right: 16px;
        }
    }
    &__wrapper{
        max-width: 1220px;
    }
    &__title{
        text-align: center;
        @include break(medium){
            font-size: 22px;
            line-height: 28px;
        }
    }
    &__list{
        margin-top: 32px;
        display: flex;
        flex-wrap: wrap;
        @include break(medium){
            margin-top: 16px;
        }
        .ew-card{
            margin-bottom: 0;
            @include break(s-small){
                margin-bottom: 20px;
            }
            &:nth-child(3){
                @include break(medium){
                    display: none;
                }
                @include break(s-small){
                    display: block;
                }
            }
        }
    }
}