.content-slider-sale {
    padding-top: 85px;
    padding-bottom: 116px;
    background: rgba(227, 238, 255, 0.80);

    @include break(large1650) {
        padding-bottom: 100px;
    }

    @include break(large1540) {
        padding-top: 65px;
        padding-bottom: 75px;
    }

    @include break(desktop) {
        padding-top: 45px;
        padding-bottom: 60px;
    }

    @include break(medium) {
        padding-bottom: 40px;
    }

    @include break(small) {
        flex-direction: column;
        padding-top: 0;
        padding-bottom: 30px;
    }

    @include break(x-small) {
        flex-direction: column;
        padding-top: 0;
        padding-bottom: 23px;
    }

    .badge-icon-wrapper {
        position: absolute;
        display: block;
        left: 11px;
        top: -60px;
        z-index: 10000;

        &__icon {
            width: 455px;
            height: 618px;


            @include break(large1750) {
                left: -25px;
            }

            @include break(large1650) {
                left: -85px;
            }

            @include break(large1540) {
                width: 368px;
                height: 500px;
                left: -70px;
            }

            @include break(large1370) {
                width: 322px;
                height: 440px;
                left: -60px;
            }

            @include break(desktop) {
                width: 260px;
                height: 390px;
            }

            @include break(medium850) {
                width: 210px;
                height: 360px;
                left: -35px;
            }

            @include break(small) {
                width: 285px;
                height: 430px;
                left: -45px;
            }

            @include break(ss-small) {
                width: 220px;
                height: 365px;
                left: -25px;
            }

            @include break(s-small) {
                width: 180px;
                height: 315px;
                left: -25px;
            }

            @include break(x-small) {
                width: 160px;
                height: 315px;
                left: -32px;
            }

            @include break(small-375) {
                width: 145px;
                height: 300px;
            }

            @include break(small-330) {
                width: 130px;
                height: 285px;
                left: -25px;
            }
        }

        &__lower-text,
        &__upper-text {
            height: 90px;
            text-align: center;
            left: 50%;
            position: absolute;
            top: 50%;
            transform: translate(-50%, 20%);
            color: #fff;
            font-family: $fourth_font;
            font-size: 34px;
            font-style: normal;
            line-height: 1.2;
            max-width: 190px;

            @include break(large1540) {
                font-size: 30px;
            }

            @include break(large1370) {
                font-size: 26px;
            }

            @include break(desktop) {
                font-size: 22px;
            }

            @include break(medium850) {
                font-size: 18px;
            }

            @include break(small) {
                font-size: 24px;
            }

            @include break(ss-small) {
                font-size: 20px;
                height: 70px;
            }

            @include break(s-small) {
                font-size: 14px;
                height: 60px;
            }

            @include break(x-small) {
                height: 53px;
            }

            @include break(small-375) {
                font-size: 13px;
                height: 46px;
            }

            strong {
                color: #fff;
                font-weight: 700;
                font-size: 66px;

                @include break(large1540) {
                    font-size: 52px;
                }

                @include break(large1370) {
                    font-size: 42px;
                }

                @include break(desktop) {
                    font-size: 40px;
                }

                @include break(medium850) {
                    font-size: 30px;
                }

                @include break(small) {
                    font-size: 44px;
                }

                @include break(ss-small) {
                    font-size: 32px;
                }

                @include break(s-small) {
                    font-size: 25px;
                }
            }
        }

        &__lower-text {
            transform: translate(-50%, 190%);

            @include break(large1540) {
                transform: translate(-50%, 150%);
            }

            @include break(large1370) {
                transform: translate(-50%, 120%);
            }

            @include break(desktop) {
                transform: translate(-50%, 115%);
            }

            @include break(medium850) {
                transform: translate(-50%, 90%);
            }

            @include break(small) {
                transform: translate(-50%, 120%);
            }

            @include break(ss-small) {
                font-size: 32px;
            }

            @include break(s-small) {
                font-size: 15px;
            }
        }

    }

    &__container {}

    &__wrapper {
        display: flex;
        gap: 90px;

        @include break(desktop) {
            gap: 55px;
        }

        @include break(medium850) {
            gap: 30px;
        }

        @include break(small) {
            gap: 20px;
        }

        @include break(ss-small) {
            gap: 15px;
        }

        @include break(x-small) {
            gap: 0px;
        }
    }

    &__left-side,
    &__right-side {
        flex: 1;
        width: 50%;

        @include break(small) {
            width: 100%;
        }
    }

    &__left-side {
        max-width: 655px;

        @include break(small) {
            max-width: 100%;
        }

        .swiper-wrapper {
            width: 100%;
        }

        .swiper-slide {
            width: 100%;
        }
    }

    &__slider {
        position: relative;
        z-index: 1;
        padding-top: 33px;

        @include break(small) {
            padding-top: 15px;
        }

        @include break(ss-small) {
            padding-top: 0;
        }

        &:before,
        &:after {
            position: absolute;
            content: '';
            display: block;
            z-index: 1;
        }

        &:before {
            left: 18px;
            top: 40px;
            width: 268px;
            height: 209px;
            z-index: -1;
            background: url(data:image/svg+xml;base64,) center center no-repeat;
            background-size: contain;

            @include break(desktop) {
                left: 0;
                width: 238px;
            }

            @include break(tablet) {
                width: 205px;
                height: 140px;
            }

            @include break(medium850) {
                width: 169px;
                height: 115px;
            }

            @include break(small) {
                display: none;
            }
        }

        &:after {
            right: 100px;
            top: 0;
            width: 118px;
            height: 58px;
            background: url(data:image/svg+xml;base64,) center center no-repeat;
            background-size: contain;

            @include break(tablet) {
                width: 100px;
                height: 50px;
                right: 65px;
            }

            @include break(medium) {
                width: 85px;
                height: 45px;
            }

            @include break(medium850) {
                width: 67px;
                height: 45px;
                right: 55px;
            }

            @include break(small) {
                display: none;
            }
        }
    }

    &__pagination {
        margin-top: 23px;
        max-width: 630px;

        @include break(tablet) {
            margin-top: 16px;
        }

        @include break(small) {
            max-width: unset;
        }

        @include break(x-small) {
            margin-top: 12px;
        }

        .swiper-pagination-bullet {
            width: 9px;
            height: 9px;
            border: none;
            background: #D9D9D9;

            @include break(x-small) {
                width: 5px;
                height: 5px;
            }

            &-active {
                background: #3A3BDA;
            }
        }
    }

    &__slider-wrapper {}

    &__swiper-slide {}

    &__swiper-image-wrap {
        max-width: 630px;
        width: 100%;

        @include break(small) {
            max-width: 100%;
        }

        @include break(ss-small) {
            height: 350px;
        }

        @include break(s-small) {
            height: 390px;
        }

        @include break(x-small) {
            height: auto;
        }
    }

    &__swiper-image {
        width: 100%;
        height: auto;

        @include break(ss-small) {
            height: 100%;
            object-fit: contain;
        }
    }

    &__right-side {
        padding-top: 45px;

        @include break(large1650) {
            padding-top: 0;
            display: flex;
            flex-direction: column;
            align-items: flex-start;
            justify-content: center;
        }

        @include break(small) {
            align-items: center;
        }

        @include break(s-small) {
            gap: 17px;
        }
    }

    &__title,
    &__subtitle {
        color: #3A3BDA;
    }

    &__title {}

    &__subtitle {
        margin-bottom: 20px;

        @include break(s-small) {
            margin-bottom: 0;
        }

        * {
            color: inherit;
        }
    }

    &__desc {
        margin-bottom: 20px;
        color: $dark;
        font-size: 35px;
        font-weight: 400;
        line-height: 1.23;

        @include break(large1370) {
            font-size: 32px;
        }

        @include break(desktop) {
            font-size: 28px;
        }

        @include break(tablet) {
            font-size: 24px;
        }

        @include break(medium) {
            font-size: 20px;
        }

        @include break(small) {
            max-width: 360px;
            text-align: center;
        }

        @include break(s-small) {
            margin-bottom: 0;
        }

        @include break(x-small) {
            font-size: 18px;
            max-width: 320px;
        }

        * {
            color: inherit;
            font-size: inherit;
            font-weight: inherit;
            line-height: inherit;

        }
    }

    &__btn {
        color: $white;
        font-size: 24px;
        font-style: normal;
        font-weight: 500;
        line-height: 1.27;
    }
}
