.hero-section {
    margin-top    : 40px;
    margin-bottom : $desktop_margin;
    overflow      : hidden;
    @include break(x-small) {
        margin-top    : 8px;
        margin-bottom : $mobile_margin;
    }

    &__wrapper {
        display : flex;
        @include break(ss-small) {
            flex-direction : column;
        }
    }

    &__content-wrapper {
        padding-right : 15px;
        width         : 50.736%;
        @include break(medium) {
            padding-right : 7px;
            width         : 50.874%;
        }
        @include break(ss-small) {
            padding-right  : 0;
            padding-bottom : 8px;
            width          : 100%;
        }
    }

    &__content {
        background-color : $blue;
        border-radius    : 50px;
        display          : flex;
        flex-direction   : column;
        justify-content  : flex-end;
        padding-left     : 90px;
        padding-right    : 90px;
        padding-top      : 70px;
        padding-bottom   : 90px;
        height           : 645px;
        @include break(large1370) {
            height         : 100%;
            max-height     : 645px;
            padding-left   : 60px;
            padding-right  : 60px;
            padding-top    : 50px;
            padding-bottom : 60px;
        }
        @include break(desktop) {
            padding-top    : 35px;
            padding-bottom : 40px;
            padding-right  : 20px;
            padding-left   : 30px;
            border-radius  : 26px;
        }
        @include break(medium) {
            padding-top    : 45px;
            padding-bottom : 50px;
        }
        @include break(medium850) {
            padding-top    : 34px;
            padding-bottom : 38px;
        }
        @include break(ss-small) {
            text-align    : center;
            padding-left  : 30px;
            padding-right : 30px;
        }
        @include break(x-small) {
            padding-top    : 25px;
            padding-bottom : 25px;
            padding-left   : 15px;
            padding-right  : 15px;
        }

        .text1,
        .text2 {
            font-size     : inherit;
            line-height   : inherit;
            font-family   : inherit;
            //font-weight: inherit;
            color         : inherit;
            text-overflow : ellipsis;
            will-change   : transform, opacity;
            transition    : all 0.5s ease-in-out;
            position      : absolute;
            left          : 0;
            top           : 0;
            width         : 100%;
            //height: 100%;
            display       : block;
        }

        .text1 {
            opacity    : 1;
            transform  : translateX(0);
            visibility : visible;
        }

        .text2 {
            opacity    : 0;
            transform  : translateX(100px);
            visibility : hidden;
            // transition-delay: 0.1s;
        }

        &.animate {
            .text1 {

                animation : hideText 0.3s linear both;
            }

            .text2 {

                animation : showText 0.5s ease-in-out both;
            }

        }
    }

    &__subtitle {
        color         : $white;
        font-size     : 26px;
        line-height   : 28px;
        text-overflow : ellipsis;
        font-family   : $main_font;
        margin-bottom : 10px;
        height        : 28px;
        position      : relative;
        @include break(large1370) {
            font-size   : 22px;
            line-height : 24px;
            height      : 24px;
        }
        @include break(desktop) {
            font-size   : 18px;
            line-height : 20px;
            height      : 20px;
        }
        @include break(tablet) {
            font-size   : 16px;
            line-height : 18px;
            height      : 18px;
        }
        @include break(medium) {
            margin-bottom : 5px;
        }
        @include break(small) {
            font-size   : 14px;
            line-height : 18px;
        }
        @include break(ss-small) {
            font-size   : 22px;
            line-height : 24px;
            height      : 24px;
        }
        @include break(x-small) {
            max-width    : 260px;
            height       : auto;
            font-size    : 16px;
            line-height  : 18px;
            margin-left  : auto;
            margin-right : auto;
            width        : 100%;
            height       : 18px;
        }

        span {
            height   : 28px;
            overflow : hidden;
            @include break(large1370) {
                height : 24px;
            }
            @include break(desktop) {
                height : 20px;
            }
            @include break(tablet) {
                height : 18px;
            }
            @include break(ss-small) {
                height : 22px;
            }
            @include break(x-small) {
                height : auto;
            }
        }
    }

    &__title {
        color    : $white;
        height   : 308px;
        position : relative;
        @include break(large1370) {
            font-size   : 66px;
            line-height : 70px;
            height      : 280px;
        }
        @include break(desktop) {
            font-size   : 56px;
            line-height : 62px;
            height      : 248px;
        }
        @include break(tablet) {
            font-size   : 46px;
            line-height : 52px;
            height      : 208px;
        }
        @include break(medium) {
            font-size   : 48px;
            line-height : 58px;
            height      : 232px;
        }
        @include break(medium850) {
            font-size   : 35px;
            line-height : 37px;
            height      : 148px;
            max-width   : 275px;
        }
        @include break(ss-small) {
            font-size    : 48px;
            line-height  : 58px;
            height       : 232px;
            max-width    : 400px;
            margin-left  : auto;
            margin-right : auto;
            width        : 100%;
        }
        @include break(x-small) {
            max-width    : 260px;
            font-size    : 38px;
            line-height  : 40px;
            margin-left  : auto;
            margin-right : auto;
            height       : 160px;
        }

        span {
            height     : 308px;
            overflow   : hidden;
            min-height : 308px;
            @include break(large1370) {
                height     : 280px;
                min-height : 280px;
            }
            @include break(desktop) {
                height     : 248px;
                min-height : 248px;
            }
            @include break(tablet) {
                height     : 208px;
                min-height : 208px;
            }
            @include break(medium) {
                height     : 232px;
                min-height : 232px;
            }
            @include break(medium850) {
                height     : 152px;
                min-height : 152px;
            }
            @include break(ss-small) {
                height     : 232px;
                min-height : 232px;
            }
            @include break(x-small) {
                height     : 160px;
                min-height : 160px;
            }
        }
    }

    &__text {
        font-family   : $second_font;
        font-weight   : 300;
        color         : $white;
        max-width     : 450px;
        margin-bottom : 0 !important;
        overflow      : hidden;
        // display: -webkit-box;
        // -webkit-line-clamp: 2;
        // -webkit-box-orient: vertical;
        @include break(desktop) {
            font-size   : 12px;
            line-height : 18px;
            max-width   : 300px;
        }
        @include break(ss-small) {
            font-size    : 18px;
            line-height  : 24px;
            max-width    : 450px;
            margin-left  : auto;
            margin-right : auto;
        }
        @include break(x-small) {
            margin-top   : 5px;
            max-width    : 260px;
            margin-left  : auto;
            margin-right : auto;
            font-size    : 14px;
            line-height  : 20px;
        }
    }

    &__button-wrapper {
        margin-top : 13px;
    }

    &__button {
        @extend .white-border-btn;
        @include break(medium) {
            font-size     : 14px;
            line-height   : 22px;
            padding       : 6px 19px;
            border-radius : 10px;
        }
        @include break(x-small) {
            padding       : 6px 19px;
            font-size     : 15px;
            line-height   : 24px;
            border-radius : 10px;
        }
    }

    &__animation {
        width           : 49.264%;
        display         : flex;
        justify-content : center;
        align-items     : center;
        @include break(medium) {
            width : 49.13%;
        }
        @include break(ss-small) {
            width      : 100%;
            min-height : 275px;
        }

        svg {
            display : block;
            width   : 100%;
            height  : 100%;
        }
        @include break(s-small) {
            display: none;
        }
    }
}

@keyframes hideText {
    0% {
        opacity    : 1;
        transform  : translateX(0);
        visibility : visible;
    }
    100% {
        transform  : translateX(-200px);
        opacity    : 0;
        visibility : hidden;
    }
}

@keyframes showText {
    0% {
        opacity    : 0;
        transform  : translateX(100px);
        visibility : hidden;
    }
    100% {
        transform  : translateX(0);
        opacity    : 1;
        visibility : visible;
    }
}