.page-template-privacy-policy{
    .page-content{
        p, h2,h3,h4,h5,h6,ul,ol{
            max-width: 1080px;
            padding-left: 40px;
            padding-right: 40px;
            margin-left: auto;
            margin-right: auto;
            scroll-margin-top: 100px;
            @include break(medium){
                max-width: 590px;
            }
            @include break(ss-small){
                padding-left: 16px;
                padding-right: 16px;
            }
        }
        a{
            word-break: break-word;
        }
        .wp-block-table{
            margin-left: auto;
            margin-right: auto;
            max-width: 1080px;
            padding-left: 40px;
            padding-right: 40px;
            @include break(medium){
                max-width: 590px;
            }
            @include break(ss-small){
                padding-left: 16px;
                padding-right: 16px;
                overflow-x: auto;
            }
        }
        table{
            border: 1px solid #000;
            width: 100%;
            border-collapse: collapse;
            tr,td,th{
                border: 1px solid #000;
                border-collapse: collapse;
                line-height   : 24px;
                font-size: 16px;
                font-family: $second_font;
            }
            th,td{
                padding: 10px;
            }
        }
    }
  
    #primary-wrapper{
        margin-bottom: 125px;
        @include break(medium){
            margin-bottom: 110px;
        }
        @include break(x-small){
            margin-bottom: 130px;
        }
    }
}

.wp-block-image {
    img {
        width: 100%;
        height: auto;
        object-fit: contain;
    }
}