.image-block{
    margin-top: $desktop_margin;
    margin-bottom: $desktop_margin;
    @include break(medium){
        margin-top: $mobile_margin;
        margin-bottom: $mobile_margin;
    }
    &__wrapper{
        position: relative;
    }
    .figure,
    .mask{
        position: absolute;
        right: 0;
        top: 0;
        background-position: top right;
        background-repeat: no-repeat;
    }
    .mask{
        z-index: 10;
        background-image: url("data:image/svg+xml,%3Csvg width='342' height='373' viewBox='0 0 342 373' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0.925781 0C7.95413 0 14.6653 2.96375 19.3731 8.15865L335.482 356.333C339.622 360.895 341.926 366.839 341.926 373V0H0.925781Z' fill='white'/%3E%3C/svg%3E%0A");
        width: 342px;
        height: 373px;
        @include break(medium){
            background-image: url('data:image/png;base64,');
            width: 194px;
            height: 213px;
        }
        @include break(x-small){
            background-image: url('data:image/png;base64,');
            width: 142px;
            height: 167px;
        }
    }
    .figure{
        z-index: 20;
        background-image: url("data:image/svg+xml,%3Csvg width='287' height='297' viewBox='0 0 287 297' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M286 21L286 286.168C286 295.172 275.031 299.589 268.791 293.098L4.27478 17.9301C-1.83358 11.5758 2.6698 0.999997 11.484 0.999998L266 1C277.046 1 286 9.95428 286 21Z' fill='%23FFDFD9' stroke='%23FF7369'/%3E%3C/svg%3E%0A");
        width: 287px;
        height: 297px;
        @include break(medium){
            background-image: url("data:image/svg+xml,%3Csvg width='159' height='165' viewBox='0 0 159 165' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M157.859 21.3641L157.859 153.564C157.859 162.569 146.89 166.986 140.65 160.494L3.95462 18.2942C-2.15378 11.9398 2.34961 1.36406 11.1638 1.36406L137.859 1.36406C148.905 1.36406 157.859 10.3184 157.859 21.3641Z' fill='%23FFDFD9' stroke='%23FF7369'/%3E%3C/svg%3E%0A");
            width: 159px;
            height: 165px;
        }
        @include break(x-small){
            background-image: url("data:image/svg+xml,%3Csvg width='105' height='123' viewBox='0 0 105 123' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M104.035 32.335L104.035 112.342C104.035 120.985 93.2088 124.874 87.7092 118.207L3.47376 16.0804C-1.48433 10.0693 2.79144 1 10.5835 1L72.7001 1C90.006 1 104.035 15.0292 104.035 32.335Z' fill='%23FFDFD9' stroke='%23FF7369' stroke-width='1.094'/%3E%3C/svg%3E%0A");
            width: 105px;
            height: 123px;
        }
    }
    &__image{ 
        display: block;
        width: 100%;
        height: auto;
        object-fit: cover;
        border-radius: 25px;
        @include break(medium){
            border-radius: 13px;
        }
        @include break(x-small){
            border-radius: 20px;
        }
    }
    p.image-block__text,
    &__text{
        font-size: 13px;
        line-height: 18px;
        margin-top: 38px;
        @include break(medium){
            font-size: 12px;
            margin-top: 18px;
        }
        @include break(x-small){
            font-size: 14px;
            line-height: 20px;
            margin-top: 12px;
        }
    }
}