.cards-with-icons {
    margin-top: $desktop_margin;
    margin-bottom: $desktop_margin;
    background-color: $light_blue_tint;
    padding-top: 94px;
    position: relative;
    isolation: isolate;

    &::after {
        content: '';
        display: block;
        width: 100%;
        height: 75px;
        position: absolute;
        left: 0;
        bottom: 0;
        background-color: $white;
        z-index: -1;
    }

    @include break(medium) {
        margin-top: 80px;
        margin-bottom: 80px;
        padding-top: 57px;
    }
    @include break(x-small) {
        padding-top: 42px;
        margin-top: $mobile_margin;
        margin-bottom: $mobile_margin;
    }

    &__container {
        padding-left: 8px;
        padding-right: 8px;
        @include break(tablet) {
            padding-left: 33px;
            padding-right: 33px;
        }
        @include break(ss-small) {
            padding-left: 19px;
            padding-right: 19px;
        }
        @include break(x-small) {
            padding-left: 14px;
            padding-right: 14px;
        }
    }

    &__wrapper {
        max-width: 1135px;
        margin-left: auto;
        margin-right: auto;
    }

    &__title {
        text-align: center;
        max-width: 745px;
        margin-left: auto;
        margin-right: auto;
        @include break(medium) {
            max-width: 540px;
        }
        @include break(x-small) {
            max-width: 270px;
        }
    }

    &__cards {
        margin-top: 12px;
        display: flex;
        justify-content: center;
        flex-wrap: wrap;
        @include break(tablet) {
            margin-top: 33px;
        }
        @include break(ss-small) {
            margin-top: 15px;
        }
        &-2 {
            .cards-with-icons__card {
                width: 49.99%;
                max-width: 600px;

                @include break(s-small) {
                    width: 50%;
                }
            }
        }
    }

    &__card {
        width: 33.3333%;
        padding: 0 31px;
        margin-top: 62px;
        max-width: 378px;
        @include break(tablet) {
            padding: 0 7px;
            margin-top: 20px;
        }
        @include break(ss-small) {
            padding: 0 10px;
        }
        @include break(s-small) {
            width: 50%;
        }

        &.animate {
            .cards-with-icons__card-wrapper {
                opacity: 1;
                transform: translate(0, 0);
            }
        }

        &:nth-child(1),
        &:nth-child(3n+4) {
            .js-animate-element {
                transition-delay: 0.2s;
            }
        }

        &:nth-child(2),
        &:nth-child(3n+5) {
            .js-animate-element {
                transition-delay: 0.3s;
            }
        }

        &:nth-child(3),
        &:nth-child(3n+6) {
            .js-animate-element {
                transition-delay: 0.4s;
            }
        }

        @include break(ss-small) {
            &:nth-child(odd) {
                .js-animate-element {
                    transition-delay: 0.2s;
                }
            }
            &:nth-child(even) {
                .js-animate-element {
                    transition-delay: 0.3s;
                }
            }
        }

        &-wrapper {
            border-radius: 19px;
            background-color: $white;
            box-shadow: 0px 3px 15px rgba(59, 55, 230, 0.2);
            text-align: center;
            padding: 38px 17px 21px 17px;
            height: 100%;
            opacity: 0;
            transform: translate(0, 60px);
            transition: opacity .2s, transform .8s cubic-bezier(0.165, 0.84, 0.44, 1);
            @include break(medium) {
                padding: 21px 15px 18px 15px;
                border-radius: 10px;
            }
            @include break(x-small) {
                padding: 22px 12px 25px 12px;
                border-radius: 13px;
            }
        }

        &-icon {
            width: 72px;
            height: 72px;
            margin-left: auto;
            margin-right: auto;
            display: flex;
            justify-content: center;
            align-items: center;
            margin-bottom: 23px;
            @include break(medium) {
                margin-bottom: 15px;
                width: 68px;
                height: 68px;
                padding: 2px;
            }
            @include break(x-small) {
                width: 49px;
                height: 49px;
                padding: 0;
            }

            img, svg {
                max-width: 100%;
                max-height: 100%;
                height: auto;
                width: auto;
                object-fit: contain;
                display: block;
            }
        }

        &-title {
            margin-bottom: 7px;
            @include break(medium) {
                margin-bottom: 1px;
            }
        }

        &-text {

        }
    }
    &__button-wrapper {
        margin-top: 24px;
    }
    &__button {
        @extend .styled-btn;
    }
}
