.contact-lobby {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    .circle {
        width         : 9px;
        height        : 9px;
        border-radius : 50%;
        visibility    : hidden;
        opacity       : 0;
        transition    : opacity .3s linear;
    }

    .js-tab {
        display : none;

        &.active {
            display : block;
        }
    }

    .lobby {
        &-blue {
            border-color     : $blue;
            background-color : $royal_blue;
            color            : $blue;
        }

        &-coral {
            border-color     : $apricot;
            background-color : $coral_tint;
            color            : $apricot;
        }

        &-purple {
            border-color     : $purple;
            background-color : $purple_tint;
            color            : $purple;
        }

        &-light-blue {
            border-color     : $malibu;
            background-color : $blue_tint;
        }

        &-title {
            text-align    : center;
            margin-bottom : 8px;
            font-size     : 40px;
            line-height   : 48px;
            @include break(s-small) {
                font-size   : 22px;
                line-height : 28px;
                padding     : 0;
            }
        }

        &-text {
            font-size   : 18px;
            line-height : 28px;
            text-align  : center;
        }
    }

    &__container {
        padding-left  : 28px;
        padding-right : 28px;
        @include break(ss-small) {
            padding-left  : 4px;
            padding-right : 4px;
        }
        @include break(s-small) {
            padding-left  : 16px;
            padding-right : 16px;
        }
    }

    &__wrapper {
        max-width : 1224px;
    }

    &__title {
        @extend .lobby-title;
        padding : 0 12px;
        @include break(s-small) {
            padding : 0;
        }
    }

    &__text {
        @extend .lobby-text;
        padding : 0 12px;
        @include break(s-small) {
            padding : 0;
        }
    }

    &__tabs {
        margin-top : 40px;
        @include break(s-small) {
            margin-top : 24px;
        }
    }

    &__tabs-heading {
        display         : flex;
        justify-content : center;
        gap             : 24px 0;
        flex-wrap       : wrap;
        @include break(s-small) {
            gap : 16px;
        }
    }

    &__tab-heading-block {
        padding : 0 12px;
        width   : 33.333%;
        @include break(medium) {
            width : 50%;
        }
        @include break(s-small) {
            padding : 0;
            width   : 100%;
        }
    }

    &__tab-button {
        padding        : 24px;
        border-radius  : 15px;
        display        : flex;
        flex-direction : column;
        gap            : 17px;
        border         : 1px solid;
        width          : 100%;
        align-items    : center;
        cursor         : pointer;
        height         : 100%;

        * {
            pointer-events : none;
        }

        &-name {
            font-size   : 15px;
            line-height : 24px;
            font-family : $third_font;
            font-weight : 600;
            text-align  : center;
            color       : inherit;
        }

        &.active {
            .circle {
                opacity    : 1;
                visibility : visible;
            }
        }

        &-radio {
            width           : 21px;
            height          : 21px;
            border-radius   : 50%;
            border          : 1px solid;
            display         : flex;
            justify-content : center;
            align-items     : center;

            &-blue {
                border-color : $blue;

                .circle {
                    background-color : $blue;
                }
            }

            &-coral {
                border-color : $apricot;

                .circle {
                    background-color : $apricot;
                }
            }

            &-purple {
                border-color : $purple;

                .circle {
                    background-color : $purple;
                }
            }
        }
    }

    &__tabs-body {
        padding : 0 12px;
        @include break(s-small) {
            padding : 0;
        }
    }

    &__tab {
        &-form {
            &-container {
                margin-top    : 104px;
                border-radius : 30px;
                border        : 1px solid;
                padding       : 40px;
                @media (min-width : 992px) {
                    grid-column : 2 span;
                }
                @include break(medium) {
                    padding    : 24px;
                    margin-top : 80px;
                }
                @include break(s-small) {
                    margin-top : 48px;
                }

                &-step {
                    margin-top : 32px;
                    @include break(medium) {
                        margin-top : 80px;
                    }
                    @include break(s-small) {
                        margin-top : 64px;
                    }

                    &.step-1 {
                        order : 3;
                        @include break(medium) {
                            order         : 2;
                            margin-top    : 32px;
                            margin-bottom : 32px;
                        }
                        @include break(s-small) {
                            margin-top    : 48px;
                            margin-bottom : 48px;
                        }
                    }

                    &.step-2 {
                        order : 4;
                        @include break(medium) {
                            margin-top : 32px;
                        }
                        @include break(s-small) {
                            margin-top : 48px;
                        }
                    }

                }
            }

            &-title {
                @extend .lobby-title;
            }

            &-text {
                @extend .lobby-text;
            }

            & {
                margin-top   : 32px;
                max-width    : 746px;
                margin-left  : auto;
                margin-right : auto;
            }
        }
    }

    &__options-container {
        margin-top : 56px;
        @include break(medium) {
            margin-top : 80px;
        }
    }

    &__options-title {
        text-align    : center;
        font-size     : 22px;
        line-height   : 28px;
        margin-bottom : 24px;
    }

    &__options {
        display               : grid;
        gap                   : 32px;
        grid-template-columns : repeat(2, 1fr);
        align-items           : flex-start;
        @include break(medium) {
            grid-template-columns : 1fr;
        }
        @include break(s-small) {
            gap : 16px;
        }
    }

    &__option-wrapper {
        border-radius : 15px;
        padding       : 24px;
        border        : 1px solid;

        &-1 {
            order : 1;
        }

        &-2 {
            order : 2;
            @include break(medium) {
                order : 3;
            }
        }

        &:not(.active) {
            cursor : pointer;

            * {
                pointer-events : none;
            }
        }

        &.blue {
            border-color : $blue;
        }

        &.coral {
            border-color : $apricot;
        }

        &.purple {
            border-color : $purple;
        }

        &.active {
            .circle {
                visibility : visible;
                opacity    : 1;
            }
        }
    }

    &__option-button {
        display               : grid;
        gap                   : 17px;
        grid-template-columns : 17px 1fr;
        align-items           : center;
        border                : none;
        background-color      : transparent;
        padding               : 0;

        &.blue {
            border-color : $blue;
            color        : $blue;

            .circle {
                background-color : $blue;
            }
        }

        &.coral {
            border-color : $apricot;
            color        : $apricot;

            .circle {
                background-color : $apricot;
            }
        }

        &.purple {
            border-color : $purple;
            color        : $purple;

            .circle {
                background-color : $purple;
            }
        }

        .button-radio {
            width           : 21px;
            height          : 21px;
            border-radius   : 50%;
            border          : 1px solid;
            border-color    : inherit;
            display         : flex;
            justify-content : center;
            align-items     : center;

            .circle {

            }
        }

        .button-name {
            color       : inherit;
            font-size   : 15px;
            line-height : 24px;
            font-family : $third_font;
            font-weight : 600;
            color       : inherit;
            text-align  : left;
        }
    }

    &__solutions {
        margin-top : 32px;

        &-title {
            font-size     : 22px;
            line-height   : 28px;
            margin-bottom : 16px;
        }

        &-heading {
            display   : flex;
            flex-wrap : wrap;
            gap       : 16px;
        }
    }

    &__solution {
        &-button {
            padding       : 10px 30px;
            border-radius : 15px;
            font-size     : 15px;
            line-height   : 24px;
            font-family   : $third_font;
            font-weight   : 600;
            text-align    : center;
            border        : 1px solid;

            cursor        : pointer;

            &.lobby-blue {
                color : $dark;

                &.active {
                    background-color : $blue;
                    color            : $white;
                }
            }

            &.lobby-coral {
                color : $dark;

                &.active {
                    background-color : $apricot;
                    color            : $white;
                }
            }

            &.lobby-purple {
                color : $dark;

                &.active {
                    background-color : $purple;
                    color            : $white;
                }
            }

            &.lobby-light-blue {
                color : $dark;

                &.active {
                    background-color : $malibu;
                    color            : $white;
                }
            }
        }

        &-tab {
            margin-top : 32px;

            h1, h2, h3, h4, h5 {
                font-size   : 22px;
                line-height : 28px;

                &:not(:last-child) {
                    margin-bottom : 8px;
                }
            }

            P, li {
                &:not(:last-child) {
                    margin-bottom : 8px;
                }
            }

            a {
                font-weight     : 700;
                text-decoration : underline;
                color           : $blue;

                &:hover {
                    text-decoration : none;
                }
            }
        }
    }

    .hbspt-form {
        .submitted-message {
            text-align  : center;
            font-size   : 22px;
            line-height : 28px;
            font-family : $second_font;
            font-weight : 600;
        }

        .hs-form {
            .hs-recaptcha {
                display : none !important;
            }

            fieldset {
                max-width : none;
            }

            .form-columns-3,
            .form-columns-2,
            .form-columns-1 {
                &:not(:last-child) {
                    margin-bottom : 16px;
                }

                .hs-form-field {
                    & > label {
                        display : none !important;
                    }
                }
            }

            .form-columns-3,
            .form-columns-2 {
                display : grid;
                gap     : 16px;
            }

            .form-columns-3 {
                grid-template-columns : repeat(3, 1fr);
                @include break(ss-small) {
                    grid-template-columns : 1fr;
                }
            }

            .form-columns-2 {
                grid-template-columns : repeat(2, 1fr);
                @include break(ss-small) {
                    grid-template-columns : 1fr;
                }
            }

            .hs-error-msgs {
                li {
                    margin-top : 5px;

                    label {
                        font-size   : 13px;
                        line-height : 16px;
                        color       : $red;
                    }
                }
            }

            .hs_error_rollup {
                text-align : center;
            }

            .hs-dependent-field {
                display         : flex;
                gap             : 16px;
                justify-content : center;
                @include break(ss-small) {
                    flex-direction : column;
                }

                .hs-form-field {
                    // width: 50%;
                    // @include break(ss-small){
                    //   width: 100%;
                    // }
                }
            }

            .hs-form-field {
                width : 100%;
                float : none;

                .input {
                    margin : 0;
                    width  : 100%;
                }

                input[type="text"],
                input[type="email"],
                input[type="tel"],
                input[type="number"],
                select,
                textarea {
                    cursor        : pointer;
                    display       : block;
                    width         : 100% !important;
                    border        : 1px solid rgba($color : $dark, $alpha : 0.1);
                    padding       : 0 16px;
                    height        : 48px;
                    border-radius : 10px;
                    font-size     : 13px;
                    line-height   : 16px;

                    &::placeholder {
                        color : rgba(22, 33, 61, 0.4);
                    }

                    &.error {
                        border-color : $red;
                    }
                }

                select {
                    -moz-appearance     : none; /* Firefox */
                    -webkit-appearance  : none; /* Safari and Chrome */
                    appearance          : none;
                    background-image    : url("data:image/svg+xml,%3Csvg width='10' height='6' viewBox='0 0 10 6' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M5 6.00005L0 1.00005L0.7 0.300049L5 4.60005L9.3 0.300049L10 1.00005L5 6.00005Z' fill='%2316213D' fill-opacity='0.4'/%3E%3C/svg%3E");
                    background-position : center right 19px;
                    background-repeat   : no-repeat;
                    padding-right       : 32px;
                    color: rgba(22, 33, 61, 0.4);

                    &.is-placeholder {
                        color: rgba(22, 33, 61, 0.4);

                        &:valid {
                            color: rgba(22, 33, 61, 0.4);
                        }
                    } 

                    &:valid {
                        font-family : $main_font;
                        font-weight : 300;
                        color: $dark;
                    }
                }

                textarea {
                    padding : 16px;
                    height  : 104px;
                    resize  : none;
                }
            }

            .hs-richtext {
                text-align : center;

                p {
                    font-size   : 13px;
                    line-height : 18px;

                    a {
                        font-weight     : 600;
                        text-decoration : underline;
                        font-family     : $second_font;

                        &:hover {
                            text-decoration : none;
                        }
                    }
                }
            }

            .legal-consent-container {
                margin-top : 12px;

                .hs-dependent-field {
                    margin : 0;

                    .hs-fieldtype-booleancheckbox {
                        &.hs-form-field {
                            width  : 100%;
                            margin : 0;
                        }
                    }
                }

                .hs-form-booleancheckbox-display {
                    display         : flex;
                    justify-content : center;

                    input[type="checkbox"] {
                        display : none;

                        &:checked ~ span::before {
                            background-image : url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M2 0C1.46957 0 0.960859 0.210714 0.585786 0.585786C0.210714 0.960859 0 1.46957 0 2L0 14C0 14.5304 0.210714 15.0391 0.585786 15.4142C0.960859 15.7893 1.46957 16 2 16H14C14.5304 16 15.0391 15.7893 15.4142 15.4142C15.7893 15.0391 16 14.5304 16 14V2C16 1.46957 15.7893 0.960859 15.4142 0.585786C15.0391 0.210714 14.5304 0 14 0L2 0ZM12.03 4.97C12.1689 5.10875 12.2479 5.29644 12.2499 5.49275C12.252 5.68907 12.177 5.87837 12.041 6.02L8.049 11.01C7.98039 11.0839 7.89758 11.1432 7.80553 11.1844C7.71348 11.2255 7.61407 11.2477 7.51325 11.2496C7.41243 11.2514 7.31227 11.233 7.21876 11.1952C7.12524 11.1575 7.0403 11.1013 6.969 11.03L4.324 8.384C4.25031 8.31534 4.19121 8.23254 4.15022 8.14054C4.10923 8.04854 4.08718 7.94923 4.08541 7.84852C4.08363 7.74782 4.10216 7.64779 4.13988 7.5544C4.1776 7.46101 4.23374 7.37618 4.30496 7.30496C4.37618 7.23374 4.46101 7.1776 4.5544 7.13988C4.64779 7.10216 4.74782 7.08363 4.84852 7.08541C4.94923 7.08718 5.04854 7.10923 5.14054 7.15022C5.23254 7.19121 5.31534 7.25031 5.384 7.324L7.478 9.417L10.951 4.992C11.0195 4.91797 11.1022 4.85851 11.1942 4.81717C11.2861 4.77583 11.3855 4.75347 11.4863 4.75141C11.5871 4.74936 11.6873 4.76766 11.7809 4.80522C11.8745 4.84277 11.9596 4.89882 12.031 4.97H12.03Z' fill='%233B37E6'/%3E%3C/svg%3E%0A");
                        }
                    }

                    & > span {
                        margin       : 0;
                        padding-left : 24px;
                        position     : relative;
                        cursor       : pointer;

                        &::before {
                            content             : '';
                            display             : block;
                            width               : 16px;
                            height              : 100%;
                            position            : absolute;
                            left                : 0;
                            top                 : 0;
                            background-image    : url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cg clip-path='url(%23clip0_6901_31825)'%3E%3Cpath d='M14 1C14.2652 1 14.5196 1.10536 14.7071 1.29289C14.8946 1.48043 15 1.73478 15 2V14C15 14.2652 14.8946 14.5196 14.7071 14.7071C14.5196 14.8946 14.2652 15 14 15H2C1.73478 15 1.48043 14.8946 1.29289 14.7071C1.10536 14.5196 1 14.2652 1 14V2C1 1.73478 1.10536 1.48043 1.29289 1.29289C1.48043 1.10536 1.73478 1 2 1H14ZM2 0C1.46957 0 0.960859 0.210714 0.585786 0.585786C0.210714 0.960859 0 1.46957 0 2L0 14C0 14.5304 0.210714 15.0391 0.585786 15.4142C0.960859 15.7893 1.46957 16 2 16H14C14.5304 16 15.0391 15.7893 15.4142 15.4142C15.7893 15.0391 16 14.5304 16 14V2C16 1.46957 15.7893 0.960859 15.4142 0.585786C15.0391 0.210714 14.5304 0 14 0L2 0Z' fill='%2316213D' fill-opacity='0.8'/%3E%3C/g%3E%3Cdefs%3E%3CclipPath id='clip0_6901_31825'%3E%3Crect width='16' height='16' fill='white'/%3E%3C/clipPath%3E%3C/defs%3E%3C/svg%3E");
                            background-repeat   : no-repeat;
                            background-position : center;
                        }
                    }

                    p {
                        font-size   : 13px;
                        line-height : 18px;

                        a {
                            font-weight     : 600;
                            text-decoration : underline;

                            &:hover {
                                text-decoration : none;
                            }
                        }
                    }
                }
            }

            .hs-submit {
                margin-top : 24px;

                .actions {
                    display         : grid;
                    justify-content : center;
                    gap             : 16px;

                    input[type="submit"] {
                        @extend .blue-btn;
                        cursor : pointer;
                    }
                }
            }
        }
    }

}
