#primary-wrapper .blog-author {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;

    @include break(medium) {
        margin-top    : 80px;
        margin-bottom : 80px;
    }
    @include break(small) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    @include break(ss-small) {
        border-radius: 20px;
        border: 1px solid $blue;
        background: $royal_blue;
        padding: 32px 16px;
        text-align: center;
        margin-bottom : 24px;
    }

    &__title.h2-title {
        margin-bottom : 32px;
        max-width     : none;
        font-size     : 40px;
        line-height   : 48px;
        @include break(medium) {
            font-size   : 22px;
            line-height : 28px;
        }
        @include break(ss-small) {
            margin-bottom : 24px;
        }
    }

    &__wrapper {
        display         : flex;
        justify-content : center;
        flex-wrap       : wrap;
    }

    &__item {
        width       : 100%;
        align-items : center;
        display     : flex;

        @include break(ss-small) {
            flex-direction : column;
            align-items    : center;
        }

        &-image {
            border-radius : 20px;
            display       : block;
            width         : 100%;
            height        : auto;
            border        : 1px solid $blue;
            margin-bottom : 16px;
            max-width     : 269px;
            //margin-left: auto;
            margin-right  : 40px;

            @include break(ss-small) {
                margin-left  : auto;
                margin-right : auto;
                max-width: 146px;
            }
        }

        &-name {
            font-size     : 22px;
            line-height   : 28px;
            margin-bottom : 4px;
        }

        &-position {
            font-size     : 15px;
            line-height   : 24px;
            font-family   : $main_font;
            margin-top    : 4px;
            margin-bottom : 0;
        }

        &-link {
            display    : block;
            margin-top : 10px;

            @include break(ss-small) {
                margin-top : 24px;
            }

            &:hover {
                svg {
                    transform  : scale(1.2);
                    transition : .2s;
                }
            }

            svg path {
                fill : $dark;
            }
        }

        &-text {
            font-size     : 13px;
            line-height   : 18px;
            margin-top    : 12px;
            margin-bottom : 0;

            @include break(ss-small) {
                margin-top : 24px;
            }
        }
        p {
            &:last-of-type {
                margin-bottom: 0;
            }
        }
    }

    &__description {
        @include break(ss-small) {
            text-align : center;
        }
    }
    &__type {
        border-radius: 10px;
        border: 1px solid $dark;
        padding: 6px 16px;
        color: $dark;
        text-align: center;
        font-family: $third_font;
        font-size: 13px;
        font-weight: 600;
        line-height: 16px;
    }
}
.blog-author-share,
.blog-author-categories {
    display: none;
    border-top: 1px solid $royal_blue;
    margin-top: 32px;
    padding-top: 16px;

    @include break(ss-small) {
        display : block;
    }

    .h2-title { color: $blue; }

    .blog-author-tags {
        display: flex;
        gap: 8px;
        flex-wrap : wrap;
    }
}
.blog-author-share {
    .single-banner__bottom {
        justify-content: flex-start;
    }
    p.single-banner__share-text {
        margin-bottom: 0;
    }
    .single-banner__share {
        svg {
            path {
                fill: $blue;
            }
        }
    }
}
