.industry-banner {
    margin-top    : 28px;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : 27px;
        margin-bottom : $mobile_margin;
    }
    @include break(s-small) {
        margin-top    : 8px;
    }

    &.has-navigation {
        margin-top : 10px;
    }

    &.ew-banner {
        margin-top    : 0;
        margin-bottom : $desktop_margin;
        @include break(medium) {
            margin-bottom : $mobile_margin;
        }
        @include break(s-small) {
            margin-bottom : 32px;
        }
    }

    .breadcrumbs,
    .return-back-link {
        margin-bottom : 10px;
    }

    &__wrapper {
        border-radius         : 50px;
        background-color      : $dark;
        display               : grid;
        grid-template-columns : 1fr 696px;
        min-height                : 554px;
        overflow              : hidden;
        row-gap               : 30px;
        @include break(medium) {
            border-radius : 27px;
        }
        @include break(s-small) {
            border-radius : 26px;
        }
        @include break(desktop) {
            min-height                : 470px;
            grid-template-columns : 1fr 565px;
        }
        @include break(medium) {
            min-height                : 304px;
            grid-template-columns : 1fr 358px;
        }
        @include break(ss-small) {
            grid-template-columns : 1fr 295px;
        }
        @include break(s-small) {
            grid-template-columns : 1fr;
            height                : auto;
            justify-items         : center;
        }
    }

    &__content-wrapper {
        display        : flex;
        align-items    : center;
        padding-left   : 86px;
        padding-top    : 63px;
        padding-bottom : 63px;
        padding-right  : 29px;
        @include break(large1370) {
            padding-left   : 40px;
            padding-top    : 30px;
            padding-bottom : 30px;
        }
        @include break(ss-small) {
            padding-left  : 20px;
            padding-right : 10px;
        }
        @include break(s-small) {
            padding    : 62px 20px 16px 20px;
            text-align : center;
        }

        &-ew {
            flex-direction  : column;
            justify-content : space-between;
            align-items     : normal;
            padding-left    : 80px;
            padding-bottom  : 56px;
            padding-top     : 64px;
            @include break(large1370) {
                padding-left : 40px;
            }
            @include break(medium) {
                padding-bottom : 32px;
                padding-top    : 40px;
            }
            @include break(s-small) {
                padding-top    : 20px;
                padding-bottom : 10px;
                padding-left   : 20px;
                padding-right  : 20px;
                justify-self   : baseline;
                width          : 100%;
                text-align     : initial;
            }
        }
    }

    &__content {
        max-width : 550px;
        @include break(desktop) {
            max-width : 370px;
        }
    }

    &__title {
        font-size     : 60px;
        line-height   : 62px;
        color         : $white;
        margin-bottom : 19px;
        @include break(large1370) {
            font-size   : 50px;
            line-height : 52px;
        }
        @include break(desktop) {
            font-size   : 32px;
            line-height : 34px;

        }
        @include break(medium) {
            margin-bottom : 0px;
        }
        @include break(ss-small) {
            font-size   : 25px;
            line-height : 29px;
            max-width   : 270px;
        }
        @include break(s-small) {
            margin-bottom : 10px;
            margin-left   : auto;
            margin-right  : auto;
            max-width   : none;
        }

        &-ew {
            margin-bottom : 0;
            @include break(medium) {
                font-size   : 22px;
                line-height : 28px;
            }
            @include break(s-small) {
                max-width : none;
                padding   : 0;
            }
        }
    }

    &__text {
        max-width : 490px;
        color     : $white;
    }

    &__button-wrapper {
        margin-top : 38px;
        @include break(medium) {
            margin-top : 22px;
        }
        @include break(s-small) {
            margin-top : 29px;
        }
    }

    &__button {
        @extend .blue-btn;
        @at-root {
            a#{&}:hover {
                background-color : $white;
                color            : $blue;
            }
        }
    }

    &__play-btn {
        cursor           : pointer;
        position         : absolute;
        left             : 0;
        top              : 0;
        width            : 100%;
        height           : 100%;
        background-color : transparent;
        border           : none !important;
        z-index          : 200;
        display          : flex;
        justify-content  : center;
        align-items      : center;
        padding          : 94px 119px 94px 27px;
        @include break(desktop) {
            padding : 69px 86px 69px 20px;
        }
        @include break(medium) {
            padding : 54px 57px 58px 14px;
        }
        @include break(s-small) {
            padding : 0;
            width   : 100%;
        }

        * {
            pointer-events : none;
        }

        svg {
            circle {
                transition : all .4s ease-in-out;
            }
            parth {
                transition : all .5s ease-in-out;
            }

            @include break(medium) {
                width  : 81px;
                height : 93px;
            }
        }
        &:hover {
            svg {
                circle {
                    fill : $blue;
                }
                path {
                    fill : $royal_blue;
                }
            }
        }
    }

    &__media {
        position  : relative;
        padding   : 94px 119px 94px 27px;
        isolation : isolate;
        display: flex;
        align-items: center;

        @include break(desktop) {
            padding : 69px 86px 69px 20px;
        }
        @include break(medium) {
            padding : 54px 57px 58px 14px;
        }
        @include break(s-small) {
            padding : 20px;
            width   : 100%;
        }

        &-ew {
            @include break(medium) {
                padding : 57px 62px 58px 14px;
            }
            @include break(ss-small) {
                padding : 57px 62px 58px 3px;
            }
            @include break(s-small) {
                padding : 0 20px 20px;
            }
        }

