.ew-banner {
    &__type-wrapper {
        margin-bottom : 40px;
        @include break(desktop) {
            margin-bottom : 24px;
        }
    }
    &__tags {
        margin-top: 20px;

        .ew-card__tag {
            padding: 8px 15px 7px;
            height: auto;
            display: inline-block;
        }
    }

    &__type {
        border        : 1px solid;
        border-radius : 10px;
        padding       : 5px 15px;
        text-align    : center;
        display       : inline-block;
        font-family   : $third_font;
        font-weight   : 600;

        &.event {
            border-color     : $malibu;
            color            : $malibu;
            background-color : rgba($color : $malibu, $alpha : 0.2);
        }

        &.webinar {
            border-color     : $purple;
            color            : $purple;
            background-color : rgba($color : $purple, $alpha : 0.2);
        }
    }

    &__date {
        font-size    : 22px;
        line-height  : 28px;
        color        : $white;
        font-family  : $third_font;
        font-weight  : 600;
        padding-left : 32px;
        margin-top   : 32px;
        position     : relative;
        @include break(desktop) {
            margin-top   : 16px;
            font-size    : 15px;
            line-height  : 24px;
            font-weight  : 300;
            font-family  : $main_font;
            padding-left : 24px;
        }

        &::before {
            content             : '';
            display             : block;
