.side-title-content-cta{
    margin-top: $desktop_margin;
    margin-bottom: $desktop_margin;
    overflow: hidden;
    @include break(medium){
        margin-top: $mobile_margin;
        margin-bottom: $mobile_margin;
    }
    @include break(s-small){
        overflow: unset;
    }
    &__container{
        &.js-animate-parent{
            &.animate{
                .js-animate-element{
                    opacity: 1;
                    transform: translate3d(0, 0, 0);
                } 
            }
        }
        .js-animate-element{
            transition: opacity .4s, transform .8s cubic-bezier(0.165, 0.84, 0.44, 1);
            opacity: 0;
            transform: translate3d(0, 50%, 0);
        }
    }
    &__wrapper{
        //max-width: 1062px;
        margin-left: auto;
        margin-right: auto;
        display: grid;
        grid-template-columns: 306px 1fr;
        column-gap: 116px;
        row-gap: 28px;
        align-items: center;
        @include break(medium){
            grid-template-columns: 246px 1fr;
            column-gap: 54px;
        }
        @include break(s-small){
            grid-template-columns: 1fr;
            text-align: center;
        }
    }
    &__title-wrapper{
        position: relative;
        display: flex;
        align-items: center;
        justify-content: center;
        @include break(s-small){
            padding-bottom: 20px;
      
        }
    }
    &__title{
        color: $blue;
        width: 100%;
        @include break(medium){
            font-size: 32px;
            line-height: 34px; 
        }
        @include break(s-small){
            max-width: 300px;
        }
        @include break(x-small){
            font-size: 25px;
            line-height: 29px;
        }
    }
    &__content-wrapper{
        position: relative;
        &::before{
            content: '';
            display: block;
            width: 1px;
            height: 100%;
            border: 1px solid rgba(22, 33, 61, 0.5);
            position: absolute;
            left: -58px;
            top: 0;
            @include break(medium){
                left: -27px;
            }
            @include break(s-small){
                left: 50%;
                transform: translateX(-50%);
                bottom: 0;
                top: -28px;
                width: 53px;
                height: 1px;
            }
        }
        @include break(s-small){
            padding-left: 6px;
            padding-right: 6px;
        }
    }
    &__text{
        font-size: 16px;
        line-height: 24px;
        // @include break(medium){
        //   font-size: 14px;
        //   line-height: 21px;
        // }
        // @include break(x-small){
        //   font-size: 12px;
        //   line-height: 15px;
        // }   
    }
    &__button-wrapper{
        margin-top: 40px;
        @include break(medium){
            margin-top: 30px;
        }
    }
    &__button{
        @extend .blue-btn;
    }
}