.title-grid-columns {
    padding: 48px 0;

    @include break(desktop) {
        padding: 40px 0;
    }

    &__title {
        @include break(desktop) {
            text-align: center;
            margin-bottom: 20px;
        }

        @include break(x-small) {
            font-size: 22px;
        }
    }

    &__section-wrapper {
        display: grid;
        grid-template-columns: repeat(4, 1fr);
        gap: 48px 40px;

        @include break(desktop) {
            display: none;
        }

        &.slider {
            display: none;

            @include break(desktop) {
                display: block;
            }

            .swiper-wrapper {
                margin-bottom: 32px;
            }

            .swiper-pagination {
                position: relative;
                bottom: 0;

                .swiper-pagination-bullet {
                    border: 1px solid $purple;

                    &.swiper-pagination-bullet-active {
                        background-color: $purple;
                    }
                }

            }
        }

    }

    &__item {
        display: flex;
        flex-direction: column;

        @include break(x-small) {
            align-items: center;
            text-align: center;
            padding: 40px 16px;
        }

        &:first-child {
            justify-content: center;
        }

        &.swiper-slide-active {
            border-radius: 20px;
            box-shadow: 0px 3px 15px 0px rgba(59, 55, 230, 0.20);
        }
    }

    &__item-icon {
        width: 72px;
        height: 72px;
        margin-bottom: 16px;
    }

    &__item-title {
        font-size: 18px;
        font-weight: 600;
        line-height: 1.5;
        margin-bottom: 8px;

        @include break(medium) {}
    }

    &__item-text {
        font-size: 15px;
        font-style: normal;
        font-weight: 300;
        line-height: 1.6;

        @include break(medium) {}
    }
}
