.single-post {
    &__wrapper {
        display               : grid;
        grid-template-columns : 1fr 385px;
        column-gap            : 20px;
        margin-bottom         : 80px;
        @include break(desktop) {
            grid-template-columns : 1fr 300px;
        }
        @include break(medium) {
            grid-template-columns : 1fr;
            margin-bottom         : 48px;
        }
    }

    &__content {
        table {
            border          : 1px solid #000;
            width           : 100%;
            border-collapse : collapse;

            tr, td, th {
                border          : 1px solid #000;
                border-collapse : collapse;
                line-height     : 24px;
                font-size       : 16px;
                font-family     : $second_font;
            }

            th, td {
                padding : 10px;
            }
        }

        h2 {
            font-weight : 600;
            font-size   : 40px;
            line-height : 48px;
            @include break(medium) {
                font-size   : 24px;
                line-height : 29px;
            }
            @include break(x-small) {
                font-size   : 20px;
                line-height : 23px;
            }
        }

        h3 {
            font-size   : 37px;
            line-height : 40px;
            @include break(medium) {
                font-size   : 22px;
                line-height : 25px;
            }
            @include break(x-small) {
                font-size   : 18px;
                line-height : 20px;
            }

        }

        h4 {
            font-size   : 34px;
            line-height : 35px;
            @include break(medium) {
                font-size   : 20px;
                line-height : 23px;
            }
            @include break(x-small) {
                font-size   : 16px;
                line-height : 18px;
            }
        }

        h5 {
            font-size   : 27px;
            line-height : 30px;
            @include break(medium) {
                font-size   : 18px;
                line-height : 20px;
            }
            @include break(x-small) {
                font-size   : 16px;
                line-height : 18px;
            }
        }
    }

    .breadcrumbs {
        margin-top    : 16px;
        margin-bottom : 24px;

        @include break(small) {
            margin-bottom : 8px;
        }
    }

    .book-a-demo {
        margin-top : 0;
    }

    .newsletter-block {
        margin-top : 96px;
        @include break(medium) {
            margin-top : 32px;
        }
    }
}