.video-banner{
    margin-top: 32px;
    margin-bottom: $desktop_margin;
    @include break(medium){
        margin-top: 16px;
        margin-bottom: $mobile_margin;
    }

    &.has-navigation{
        margin-top: 20px;
        @include break(s-small){
            margin-top: 16px;
        }
    }
    .breadcrumbs,
    .return-back-link{
        margin-bottom: 10px;
        max-width: 1260px;
        margin-left: auto;
    }
    &__wrapper{
        max-width: 1260px;
        margin-left: auto;
        display: grid;
        grid-template-columns: 1fr 718px;
        column-gap: 3px;
        row-gap: 3px;
        @include break(large1370){
            grid-template-columns: 1fr 600px;
        }
        @include break(desktop){
            grid-template-columns: 1fr 500px;
        }
        @include break(medium){
            grid-template-columns: 1fr 373px;
        }
        @include break(ss-small){
            grid-template-columns: 1fr 300px;
        }
        @include break(s-small){
            grid-template-columns: 1fr;
        }
    }
    &__content-wrapper{
        padding-top: 10px;
        padding-bottom: 71px;
        @include break(large1370){
            padding-bottom: 58px;
        }
        @include break(desktop){
            padding-bottom: 48px;
        }
        @include break(medium){
            padding-bottom: 36px;
            padding-top: 6px;
        }
        @include break(ss-small){
            padding-top: 3px;
            padding-bottom: 28px;
        }
        @include break(s-small){
            padding: 0;
        }
    }
    &__content{
        display: flex;
        align-items: center;
        background-color: $blue;
        border-radius: 30px;
        padding: 30px 55px 30px 65px;
        height: 100%;
        @include break(medium){
            border-radius: 30px;
        }
        @include break(medium850){
            padding: 30px 35px;
        }
        @include break(ss-small){
            padding: 20px;
        }
        @include break(s-small){
            padding: 50px 36px;
            min-height: 268px;
            text-align: center;
            border-radius: 26px;
        }
    }
    &__text{
        color: $white;
        margin: 0  auto;
        font-size: 60px;
        line-height: 62px;
        @include break(desktop){
            font-size: 50px;
            line-height: 52px;
        }
        @include break(tablet){
            font-size: 40px;
            line-height: 42px;
        }
        @include break(medium850){
            font-size: 32px;
            line-height: 34px;
        }
        @include break(s-small){
            font-size: 38px;
            line-height: 40px;
            max-width: 270px;
        }
    }
    &__media{
        height: 612px;
        position: relative;
        overflow: hidden;
        @include break(large1370){
            height: 512px;
        }
        @include break(desktop){
            height: 426px;
        }
        @include break(medium){
            height: 318px;
        }
        @include break(ss-small){
            height: 256px;
        }
        @include break(s-small){
            height: auto;
        }
    }
    &__mask,
    &__video,
    &__image{
        position: absolute;
        left: 0;
        top: 0;
        width: 100%;
        height: 100%;
        display: block;
    }
    &__video,
    &__image{
        object-fit: cover;
        z-index: 10;
    }
    &__video{
        padding: 2px;
        background-color: $white;
    }
    &__mask-image{
        display: none;
        height: 612px;
        position: relative;
        z-index: 20;
        width: 100%;
        @include break(large1370){
            height: 512px;
        }
        @include break(desktop){
            height: 426px;
        }
        @include break(medium){
            height: 318px;
        }
        @include break(ss-small){
            height: 256px;
        }
        @include break(s-small){
            height: auto;
        }
        &-desktop{
            display: block;
            @include break(s-small){
                display: none;
            }
        }
        &-mobile{
            @include break(s-small){
                display: block;
                height: auto;
            }
        }
    
    }
}