.side-image-banner {
    margin-top    : 40px;
    margin-bottom : 32px;
    @include break(medium) {
        margin-top    : 46px;
        margin-bottom : 21px;
    }
    @include break(s-small) {
        margin-top    : 8px;
        margin-bottom : 24px;
    }

    &.has-navigation {
        margin-top : 5px;
    }

    .breadcrumbs,
    .return-back-link {
        margin-bottom : 5px;
    }
    .breadcrumbs {
        @include break(ss-small) {
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }
    }

    &__wrapper {
        display               : grid;
        grid-template-columns : repeat(2, 1fr);
        column-gap            : 16px;
        row-gap               : 15px;
        @include break(medium) {
            column-gap : 20px;
        }
        @include break(s-small) {
            grid-template-columns : 1fr;
            padding-bottom: 15px!important;
        }
    }

    &__content-wrapper {

        border-radius : 50px;
        display       : flex;
        align-items   : center;
        min-height    : 514px;
        padding       : 91px 46px 98px 55px;

        &.blue {
            background-color : $blue;
        }

        &.coral {
            background-color : $coral;
        }

        &.purple {
            background-color : $purple;
        }

        &.light-blue {
            background-color : $light-blue;
        }

        @include break(medium) {
            padding       : 39px 26px 43px 31px;
            border-radius : 20px;
            min-height    : auto;
        }
        @include break(s-small) {
            text-align    : center;
            border-radius : 26px;
            padding       : 48px 36px 53px;
        }
    }

    &__content {
        width : 100%;
    }

    &__subtitle {
        color         : $white;
        margin-bottom : 11px;
        font-size     : 22px;
        line-height   : 28px;
        @include break(medium) {
            margin-bottom : 3px;
            font-size     : 24px;
            line-height   : 29px;
        }
        @include break(s-small) {
            margin-bottom : 20px;
            font-size     : 18px;
            line-height   : 22px;
        }
    }

    &__title {
        font-size     : 60px;
        line-height   : 62px;
        color         : $white;
        margin-bottom : 5px;
        max-width     : 480px;
        @include break(tablet) {
            font-size   : 32px;
            line-height : 34px;
            max-width   : 250px;
        }
        @include break(s-small) {
            margin-bottom : 10px;
            max-width     : 320px;
            margin-left   : auto;
            margin-right  : auto;
        }
        @include break(x-small) {
            font-size   : 25px;
            line-height : 29px;
            max-width : auto;
        }
    }

    &__text {
        color : $white;
        @include break(s-small) {
            max-width    : 310px;
            margin-left  : auto;
            margin-right : auto;
        }
    }

    &__button-wrapper {
        margin-top : 30px;
        @include break(medium) {
            margin-top : 14px;
        }
        @include break(s-small) {
            margin-top : 29px;

        }
    }

    &__button {
        @extend .white-btn;
        @at-root {
            a#{&}:hover {
                background-color : $dark;
            }
        }
        &.blue {
            &:not(:hover) {
                color : $blue;
            }
        }

        &.coral {
            &:not(:hover) {
                color : $coral;
            }
        }

        &.purple {
            &:not(:hover) {
                color : $purple;
            }
        }

        &.light-blue {
            &:not(:hover) {
                color : $light_blue;
            }
        }

        @include break(s-small) {
            padding : 7px 28px;
        }
    }

    &__media {
        position : relative;

        .mask,
        .figure {
            background-position : bottom left;
            background-repeat   : no-repeat;
            position            : absolute;
            left                : 0;
            bottom              : 0;
        }

        .mask {
            background-image : url("data:image/svg+xml,%3Csvg width='280' height='301' viewBox='0 0 280 301' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M243.41 284.673L12.2165 27.1512C5.38846 19.5521 1.15967 10.0456 0 0V301H280C266.034 301 252.728 295.069 243.41 284.683V284.673Z' fill='white'/%3E%3C/svg%3E%0A");
            width            : 280px;
            height           : 301px;
            z-index          : 10;
            @include break(medium) {
                background-image : url("data:image/svg+xml,%3Csvg width='138' height='170' viewBox='0 0 138 170' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath opacity='1' d='M3.5 11.5C3.12219 11 0.5 7.5 0 0V170H138C127.5 169.5 121 160.5 121 160.5C121 160.5 3.87781 12 3.5 11.5Z' fill='white'/%3E%3C/svg%3E%0A");
                width            : 138px;
                height           : 170px;
            }
            @include break(x-small) {
                background-image : url("data:image/svg+xml,%3Csvg width='143' height='154' viewBox='0 0 143 154' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M124.313 145.647L6.23915 13.8913C2.75196 10.0034 0.592259 5.13963 0 0V154H143C135.867 154 129.072 150.965 124.313 145.652V145.647Z' fill='white'/%3E%3C/svg%3E%0A");
                width            : 143px;
                height           : 154px;
            }
        }

        .figure {

            width   : 223px;
            height  : 242px;
            z-index : 20;
            @include break(medium) {
                width  : 110px;
                height : 132px;
            }
            @include break(x-small) {
                width  : 111px;
                height : 120px;
            }

            &.blue {
                background-image : url("data:image/svg+xml,%3Csvg width='223' height='242' viewBox='0 0 223 242' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 194.89L1 14.9999C1 2.61404 16.2373 -3.29016 24.5829 5.86192L218.301 218.3C226.24 227.007 220.063 241 208.28 241L47.1103 241C21.6443 241 1 220.356 1 194.89Z' fill='%23D8E3FF' stroke='%233B37E6'/%3E%3C/svg%3E%0A");
