                }
                @include break(x-small) {
                    background-image : url("data:image/svg+xml,%3Csvg width='111' height='120' viewBox='0 0 111 120' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 95.8565L1 7.52654C1 1.31507 8.63706 -1.65101 12.8295 2.93223L108.571 107.599C112.566 111.966 109.468 119 103.548 119L24.1435 119C11.3617 119 1 108.638 1 95.8565Z' fill='%23D8E3FF' stroke='%233B37E6' stroke-width='0.501916'/%3E%3C/svg%3E%0A");
                }
            }

            &.coral {
                background-image : url("data:image/svg+xml,%3Csvg width='223' height='242' viewBox='0 0 223 242' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 194.89L1 14.9999C1 2.61404 16.2373 -3.29016 24.5829 5.86192L218.301 218.3C226.24 227.007 220.063 241 208.28 241L47.1103 241C21.6443 241 1 220.356 1 194.89Z' fill='%23FFDFD9' stroke='%23FF7369'/%3E%3C/svg%3E%0A");
