.solutions-cards{
    margin-top: $desktop_margin;
    margin-bottom: $desktop_margin;
    overflow: hidden;

    @include break(medium){
        margin-top: 60px;
    }
    @include break(x-small){
        margin-top: $mobile_margin;
        margin-bottom: $mobile_margin;
    }
    &__container{
        border-radius: 116px 116px 0 0;
        background-color: $dark;
        padding-top: 100px;
        padding-bottom: 100px;
        max-width: 100%;
        @include break(medium){
            padding-top: 80px;
            padding-bottom: 80px;
            border-radius: 95px 95px 0 0;
        }
        @include break(ss-small){
            padding-left: 24px;
            padding-right: 24px;
        }
        @include break(x-small){
            border-radius: 35px 35px 0 0;
            padding-top: 40px;
            padding-bottom: 40px;
        }
    }
    &__title{
        max-width: 750px;
        margin-left: auto;
        margin-right: auto;
        margin-bottom: 100px;
        color: $white;
        text-align: center;
        @include break(medium){
            max-width: 500px;
            margin-bottom: 43px;
        }
        @include break(x-small){
            max-width: 325px;
            margin-bottom: 33px;
        }
    }
    &__wrapper{
        max-width: 1295px;
        margin-left: auto;
        margin-right: auto;
        display: grid;
        grid-template-columns: repeat(2, 1fr);   
        grid-column-gap: 19px;
        grid-row-gap: 19px;
        column-gap: 19px;
        row-gap: 19px;
        @include break(desktop){
            grid-column-gap: 20px;
            grid-row-gap: 22px;
            column-gap: 20px;
            row-gap: 22px;
        }
        @include break(s-small){
            grid-template-columns:1fr;
            grid-row-gap: 16px;
            row-gap: 16px;
        }
    }
    &__card{
        background-color: rgba(37, 47, 89, 0.7);
        border: 1px solid rgba(141, 157, 181, 0.6);
        border-radius: 35px;
        padding: 24px;
        transition: .3s linear;
        transition-property: background-color, border-color;
        display: grid;
        grid-template-columns: 290px 1fr;
        column-gap: 15px;
        row-gap: 15px;
        justify-items: flex-end;
        position: relative;
        z-index: 1000;
        @include break(desktop){
            display: flex;
            flex-direction: column-reverse;
            padding: 16px 16px 38px 16px;
            border-radius: 25px;
            row-gap: 0;
      
        }
        @include break(desktop){
            padding-bottom: 28px;
        }
        &:hover{
            background-color: #313E60;
            border-color: rgba(255, 255, 255, 0.6);
        }
        &-content-wrapper{
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            padding-top: 10px;
            padding-bottom: 30px;
            @include break(desktop){
                width: 100%;
                padding-top: 0;
                padding-bottom: 0;
                height: 100%;
                align-items: center;
            }
            @include break(s-small){
                height: auto;
            }
        }
        &-content{
            @include break(desktop){
                text-align: center;
            }
            @include break(x-small){
                max-width: 255px;
            }
        }
        &-animation{
            width: 100px;
            height: 100px;
            display: flex;
            justify-content: flex-start;
            align-items: center;
            margin-bottom: 20px;
            @include break(desktop){
                width: 82px;
                height: 82px;
                margin-left: auto;
                margin-right: auto;
                margin-bottom: 12px;
            }
            @include break(s-small){
                width: 80px;
                height: 80px;
            }
            img, svg{
                max-width: 100%;
                max-height: 100%;
                width: 100%;
                height: auto;
                display: block;
        
            }
        }
        &-title{
            color: $white;
            margin-bottom: 7px;
            @include break(desktop){
                margin-bottom: 1px;
            }
            @include break(medium){
                font-size: 22px;
                line-height: 26px;
            }
            @include break(x-small){
                font-size: 18px;
                line-height: 22px;
                margin-bottom: 4px;
            }
        }
        &-text{
            color: $white;
            @include break(desktop){
                max-width: 350px;
                margin-left: auto;
                margin-right: auto;
            }
            @include break(small){
                font-size: 14px;
                line-height: 21px;
                max-width: 260px;
            }
            @include break(x-small){
                font-size: 12px;
                line-height: 15px;
                max-width: none;
            }
        }
        &-button-wrapper{
            margin-top: 25px;
            @include break(desktop){
                text-align: center;
                margin-top: 26px;
            }
            @include break(x-small){
                margin-top: 23px;
            }
        }
        &-image-wrapper{
            max-width: 252px;
            min-height: 375px;
            height: 100%;
            @include break(desktop){
                width: 100%;
                height: auto;
                min-height: auto;
                max-width: none;
                margin-bottom: 15px;
            }
            @include break(s-small){
                margin-bottom: 14px;
            }
            @include break(small-375){
                height: 150px;
            }
            img,svg{
                width: 100%;
                height: 100%;
                object-fit: cover;
                border-radius: 24px;
                display: block;
                @include break(desktop){
                    height: auto;
                    width: 100%;
                    border-radius: 30px;
                }
                @include break(s-small){
                    border-radius: 29px;
                }
                @include break(small-375){
                    height: 100%;
                }
            }
        }
        &-image{
            max-width: 100%;
            max-height: 100%;
            width: auto;
            height: auto;
            display: block;
            @include break(desktop){
                height: auto;
                width: 100%;
            }
            @include break(small-375){
                height: 100%;
            }
        }
    }
}