.single-resources {
    .breadcrumbs {
        margin-top    : 17px;
        margin-bottom : 7px;
        @include break(medium) {
            margin-top    : 19px;
            margin-bottom : 19px;
        }
        @include break(s-small) {
            margin-top    : 16px;
            margin-bottom : 16px;
        }
    }
    &__container {
        @include break(s-small) {
            display: flex;
            flex-direction: column;
        }
    }

    .gated {
        .breadcrumbs {
            margin-bottom : 9px;
            padding-left  : 80px;
            @include break(large1370) {
                padding-left : 0;
            }
            @include break(medium) {
                margin-bottom : 24px;
            }
        }
    }

    .content-block {
        margin : 0;
    }

    .left-side-monitor-content,
    .right-side-monitor-content,
    .title-with-cta,
    .styled-side-image-content,
    .cards-with-icons,
    .content-with-cta,
    .tabs-section,
    .side-title-content-cta,
    .side-title-content-cta-v2,
    .specific-solutions {
        margin-top    : 80px;
        margin-bottom : 80px;
        @include break(medium) {
            margin-top    : 60px;
            margin-bottom : 60px;
        }
        @include break(x-small) {
            margin-top    : 35px;
            margin-bottom : 35px;
        }
    }

    .page-content {
        &__resources {
            max-width : 1017px;
            @extend .a-tag;

            p {
                &:not(:last-child) {
                    margin-bottom : 22px;
                    @include break(medium) {
                        margin-bottom : 20px;
                    }
                }
            }

            li {
                padding    : 0;
                list-style : inherit;

                &:not(:last-child) {
                    margin-bottom : 8px;
                }

                &::before {
                    display : none;
                }
            }

            ol {
                list-style : decimal;
            }

            ul {
                list-style : disc;
            }

            ol,
            ul {
                margin-left : 18px;

                &:not(:first-child) {
                    margin-top : 18px;
                }

                &:not(:last-child) {
                    margin-bottom : 18px;
                }
            }
        }
    }
    .content-section {
        &:first-of-type {
            @include break(s-small) {
                order: 2
            }
        }
    }
}