.lobby-banner {
    margin-bottom: $desktop_margin;

    @include break(medium) {
        margin-bottom: $mobile_margin;
    }

    @include break(s-small) {
        padding-top: 0;
    }

    &-v2 {
        padding: 0;
    }

    .image-border {
        border-radius: 24px;
        border: 1px solid;

        @include break(medium) {
            border-radius: 12px;
        }

        @include break(ss-small) {
            border: none;
        }
    }

    &__main {
        padding-top: 56px;
        padding-bottom: 56px;

        @include break(medium) {
            padding-top: 43px;
            padding-bottom: 43px;
        }

        @include break(s-small) {
            padding-top: 0;
            padding-bottom: 0;
            background: transparent;
        }

        &.has-navigation {
            padding-top: 24px;

            @include break(medium) {
                padding-top: 16px;
            }
        }

        &.has-button {
            @include break(ss-small) {
                position: relative;
                padding-bottom: 108px;
            }
        }

        &.has-two-button {
            @include break(ss-small) {
                padding-bottom: 152px;
            }
        }

        &.no-frame {
            .lobby-banner__wrapper {
                @include break(medium) {
                    grid-template-columns: 1fr 1fr;
                }

                @include break(ss-small) {
                    display: block;
                }
            }

            .lobby-banner__media,
            .lobby-banner__media.video {
                height: 372px;
            }

            .lobby-banner__frame {
                width: 626px;
                height: 372px;
                top: 0;
                z-index: 1;

                @include break(desktop) {
                    width: 450px;
                    height: 276px;
                }

                @include break(medium) {
                    width: 334px;
                    height: 196px;
                }

                @include break(small) {
                    width: 100%;
                    height: auto;
                }

                &:before {
                    content: '';
                    background-image: url('data:image/png;base64,');
                    width: 202px;
                    height: 214px;
                    position: absolute;
                    top: 0;
                    right: 0;
                    z-index: 1;

                    @include break(medium) {
                        width: 155px;
                        height: 161px;
                        background-size: cover;
                    }
                }

                &:after {
                    content: '';
                    background-image: url("data:image/svg+xml,%3Csvg width='157' height='168' viewBox='0 0 157 168' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0.5 9.57177L0.500002 136.665C0.500002 153.695 14.3053 167.5 31.335 167.5L146.95 167.5C154.549 167.5 158.509 158.455 153.355 152.872L15.6209 3.65978C10.2391 -2.17047 0.5 1.63734 0.5 9.57177Z' fill='%23ECDEFF' stroke='%23A142FF'/%3E%3C/svg%3E");
                    width: 157px;
                    height: 168px;
                    position: absolute;
                    top: 0;
                    right: 0;
                    z-index: 1;
                    background-repeat: no-repeat;
                    background-position: 100% 0;
                    transform: scale(-1);

                    @include break(medium) {
                        width: 117px;
                        height: 125px;
                        background-size: cover;
                    }
                }
            }

            .lobby-banner__image-wrapper {
                padding: 0;
            }

            .lobby-banner__play-btn {
                padding: 0;
                left: 50%;
                top: 50%;
                transform: translate(-50%, -50%);
            }

            .lobby-banner__subtitle {
                color: $blue;
                font-size: 60px;
                font-weight: 600;
                line-height: 62px;
                text-align: left;

                @include break(medium) {
                    font-size: 30px;
                    line-height: 127%;
                }

                @include break(small) {
                    margin-bottom: 12px;
                }
            }

            .lobby-banner__button-left {
                background: $white;
                color: $blue;
                border: 1px solid $blue;

                &:hover {
                    background: $blue;
                    color: $white;
                    border-color: $blue;
                }
            }

            .lobby-banner__text,
            .lobby-banner__content {
                @include break(small) {
                    max-width: none;
                }
            }

            .lobby-banner__text {
                text-align: left;
            }
        }

        .breadcrumbs,
        .return-back-link {
            margin-bottom: 0;
            padding-left: 80px;

            @include break(large1370) {
                padding-left: 0;
            }

            @include break(medium) {
                margin-bottom: 24px;
            }

            @include break(ss-small) {
                margin-bottom: 16px;
            }
        }

        &.blue {
            background-color: $light_blue_tint;

            @include break(ss-small) {
                background-color: transparent;
            }

            .lobby-banner__subtitle:not(.subtitle) {
                color: $blue;
            }

