    &__wrapper {
        display: grid;
        grid-template-columns: 1fr 626px;
        column-gap: 20px;
        padding-left: 80px;
        padding-right: 30px;

        @include break(large1370) {
            padding-left: 0;
            padding-right: 0;
        }

        @include break(desktop) {
            grid-template-columns: 1fr 450px;
            column-gap: 40px;
        }

        @include break(medium) {
            grid-template-columns: 1fr 334px;
            column-gap: 40px;
        }

        @include break(small) {
            column-gap: 20px;
            gap: 30px;
            grid-template-columns: 1fr;
        }

        @include break(s-small) {
            display: block;
        }
    }

    &__content-wrapper {
        display: flex;
        align-items: center;

        @include break(ss-small) {
            margin-bottom: 8px;
        }

        &-v2 {
            @include break(s-small) {
                margin-bottom: 8px;
            }
        }
    }

