            line-height: 56px;
            margin-bottom: 17px;
        }

        @include break(medium) {
            font-size: 32px;
            line-height: 34px !important;
        }

        @include break(ss-small) {
            font-size: 25px !important;
            line-height: 29px;
            max-width: 270px;
        }

        @include break(s-small) {
            max-width: none;
            margin-bottom: 10px;
        }

        &.title {
            margin-bottom: 16px;

            @include break(s-small) {
                font-size: 32px !important;
                line-height: 40px;
                margin-bottom: 10px;
            }
        }
    }

    &__subtitle-bottom {
        font-family: $third_font;
        font-weight: 600;
        margin-bottom: 16px;
        font-size: 22px;
        line-height: 28px;

        @include break(medium) {
            font-size: 15px;
            line-height: 22px;
            font-family: $second_font;
        }

        @include break(s-small) {
            margin-bottom: 10px;
        }
    }

    &__text {
        max-width: 395px;
        font-family: $second_font;

        @include break(medium) {
            max-width: 300px;
        }

        @include break(s-small) {
            margin-left: auto;
            margin-right: auto;
            font-size: 14px;
            line-height: 20px;
            max-width: none;
            margin-top: 24px;
        }

        &-editor {
            margin-top: 0;
        }

        &-editor,
        &-gated {
            max-width: none;

            a {
                color: $blue;

                &:hover {
                    text-decoration: underline;
                }
            }

            p {
                &:not(:last-child) {
                    margin-bottom: 28px;
                    padding-bottom: 0;

                    @include break(medium) {
                        margin-bottom: 22px;
                    }
                }
            }

            p,
            li {
                font-weight: 400;
                font-size: 16px;
                line-height: 24px;
            }

            li {
                padding: 0;
                list-style: inherit;

                &:not(:last-child) {
                    margin-bottom: 8px;
                }

                &::before {
                    display: none;
                }
            }

            ol {
                list-style: decimal;
            }

            ul {
                list-style: disc;
            }

            ol,
            ul {
                margin-left: 18px;

                &:not(:last-child) {
                    margin-bottom: 18px;
                }
            }

            h2,
            h3,
            h4,
            h5,
            h6 {
                font-size: 22px;
                line-height: 28px;

                &:not(:last-child) {
                    margin-bottom: 8px;
                }

                @include break(desktop) {
                    font-size: 18px;
                }
            }
        }
    }

    &__buttons-wrapper {
        margin-top: 36px;
        display: flex;
        gap: 15px;

        @include break(medium) {
            margin-top: 28px;
        }

        @include break(ss-small) {
            position: absolute;
            bottom: 32px;
            left: 50%;
            transform: translateX(-50%);
        }

        @include break(s-small) {
            justify-content: center;
            gap: 16px;
            flex-direction: column;
            width: max-content;
        }

        &.button-wrapper {
            margin-top: 24px;

            @include break(medium) {
                margin-top: 10px;
            }

            @include break(s-small) {
                margin-top: 24px;
            }
        }

        &.webinar {
            @include break(ss-small) {
                position: relative;
                bottom: 0;
                left: 0;
                transform: none;
                width: 100%;
                margin-bottom: 24px;
            }
        }
    }

    &__button {
        @extend .blue-btn;

        &.button {
            @extend .styled-btn;
        }
    }

    &__button-left {
        @extend .blue-btn;
    }

    &__button-right {
        @extend .blue-border-btn;
    }

    &__media {
        position: relative;
        height: 524px;
        align-self: center;

        @include break(desktop) {
            height: 377px;
        }

        @include break(medium) {
            height: 280px;
        }

        @include break(ss-small) {
            height: auto;
            margin-left: auto;
            margin-right: auto;
        }

        &.video {
            @include break(ss-small) {
                height: auto;
                width: 100%;
                background: $royal_blue;
                border: 1px solid $blue;
                border-radius: 30px;
            }

            .lobby-banner__frame {
                @include break(ss-small) {
                    background: none;
                }
            }

            .lobby-banner__image-wrapper {
                @include break(ss-small) {
                    padding: 15px;
                }
            }

            .lobby-banner__iframe {
                @include break(ss-small) {
                    background-image: none;

                    &:before {
                        display: none;
                    }
                }
            }
        }

        .webinar-dates__dates {
            border-radius: 20px;
            border: 1px solid $blue;
            background: $gret_blue;
            padding: 32px;
            display: flex;
            flex-direction: column;
            justify-content: center;
            height: 100%;

            &:before {
                content: none;
            }

            .h2-title {
                text-align: center;
            }
        }

        &.webinar {

            @include break(small) {
                height: auto;
                width: 100%;
            }

            .webinar-dates__dates {
                @include break(small) {
                    padding: 18px;
                }
            }

            .webinar-dates__item {
                @include break(small) {
                    grid-template-columns: 63px 1fr 105px;
                }
            }
        }

        + .lobby-banner__buttons-wrapper {
            margin-top: 20px;
        }
    }

    &__video-title {
        display: none;
        color: $dark;
        font-family: $third_font;
        font-size: 15px;
        font-weight: 600;
        line-height: 116%;
        border: 1px solid $blue;
        border-top: none;
        background: $royal_blue;
        border-radius: 0 0 28px 28px;
        max-width: 234px;
        padding: 5px 18px 16px 18px;
        margin: -1px auto 0;
        position: relative;
        z-index: 5;
        text-align: center;

        @include break(ss-small) {
            display: block;
        }
    }


    &__iframe {
        position: absolute;
        left: 0;
        top: 0;
        width: 100%;
        height: 100%;
        z-index: -1;

        @include break(ss-small) {
            background-image: url('data:image/png;base64,');
            top: 0;
            z-index: 1;
            background-repeat: no-repeat;
            background-position: 100% 0;

            &:before {
                content: '';
                background-image: url("data:image/svg+xml,%3Csvg width='109' height='137' viewBox='0 0 109 137' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0.5 6.74101L0.500001 115.553C0.500001 127.122 9.87807 136.5 21.4465 136.5L102.134 136.5C106.959 136.5 109.68 130.957 106.729 127.14L10.9026 3.1888C7.51511 -1.19293 0.5 1.20254 0.5 6.74101Z' fill='%23ECDEFF' stroke='%23A142FF'/%3E%3C/svg%3E");
                width: 109px;
                height: 137px;
                position: absolute;
                top: 0;
                right: 0;
                transform: scale(-1);
            }
        }

        &.active {
            z-index: 500;
        }
    }

    &__frame {
        width: 626px;
        height: 524px;
        background-size: contain;
        background-position: center;
        background-repeat: no-repeat;

        @include break(desktop) {
            width: 450px;
            height: 377px;
        }

        @include break(medium) {
            width: 334px;
            height: 280px;
        }

        @include break(ss-small) {
            width: auto;
            height: auto;
        }
    }

    &__media-wrapper {
        position: absolute;
        left: 0;
        top: 0;
        width: 100%;
        height: 100%;

        @include break(ss-small) {
            position: relative;
        }

        iframe {
            display: block;
            object-fit: cover;
            width: 100%;
            height: 100%;
        }
    }

    &__play-btn {
        cursor: pointer;
        position: absolute;
        left: 0;
        top: 0;
        width: 100%;
        height: 100%;
        background-color: transparent;
        border: none !important;
        z-index: 200;
        display: flex;
        justify-content: center;
        align-items: center;
        padding: 118px 82px 81px 99px;

        @include break(desktop) {
            padding: 83px 58px 58px 71px;
        }

        @include break(medium) {
            padding: 65px 46px 44px 56px;
        }

        @include break(ss-small) {
            padding: 47px 33px 33px 40px;
        }

        @include break(s-small) {
            padding: 67px 48px 46px 57px;
        }

        @include break(x-small) {
            padding: 56px 41px 40px 49px;
        }

        @include break(small-360) {
            padding: 50px 36px 35px 42px;
        }

        * {
            pointer-events: none;
        }

        svg {
            circle {
                transition: all .4s ease-in-out;
            }

            parth {
                transition: all .5s ease-in-out;
            }

            @include break(medium) {
                width: 81px;
                height: 93px;
            }
        }

        &:hover {
            svg {
                circle {
                    fill: $blue;
                }

                path {
                    fill: $royal_blue;
                }
            }
        }
    }

    &__image-wrapper {
        position: absolute;
        left: 0;
        top: 0;
        width: 100%;
        height: 100%;
        padding: 118px 82px 81px 99px;

        @include break(desktop) {
            padding: 83px 58px 58px 71px;
        }

        @include break(medium) {
            padding: 65px 46px 44px 56px;
        }

        @include break(ss-small) {
            padding: 0;
            position: relative;
        }


        img,
        svg {
            border-radius: 24px;
            border: 1px solid;

            @include break(medium) {
                border-radius: 12px;
            }
        }
    }

    .gradient {
        width: 100%;
        height: 100%;
        border-radius: 24px;
        position: relative;
        overflow: hidden;

        @include break(medium) {
            border-radius: 12px;
        }

        &::before {
            content: '';
            display: block;
            position: absolute;
            width: 100%;
            height: 100%;
            background: linear-gradient(180deg, rgba(217, 217, 217, 0) 1.26%, rgba(217, 217, 217, 0) 34.91%, rgba(59, 55, 230, 0.32) 100%);
            z-index: 10;

            @include break(ss-small) {
                display: none;
            }
        }
    }

    &__image {
        left: 0;
        top: 0;
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
        z-index: 9;
    }

    .utm-form-check {
        .form-columns-1 {
            display: inline-block;
            float: left;
            width: 285px;

            @include break(small) {
                width: calc((100% - 16px) / 2);
            }

            @include break(ss-small) {
                width: 100%;
            }

            &:nth-child(2) {
                margin-right: 16px;
            }

            &:nth-child(5),
            &:nth-child(6),
            &:nth-child(7),
            &:nth-child(8),
            &:nth-child(9),
            &:nth-child(4) {
                clear: both;
                width: 100%;
            }

            .hs-form-field {
                width: 100%;
            }
        }

        .form-columns-0 {
            clear: both;
            width: 100%;
        }
    }

    &__event-description {
        line-height: 24px;
        font-size: 16px;
        font-weight: 400;
        margin: 0 0 20px;
    }

    &__form-wrapper {
        padding: 40px 24px;
        border-radius: 20px;
        border: 1px solid #3B37E6;
        background: #16213D;

        .hbspt-form {
            height: 100%;
        }

        form {
            height: max-content;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            align-items: center;
            gap: 0;

            fieldset {
                margin-bottom: 16px;
            }
        }

        select,
        input[type="text"],
        input[type="email"] {
            height: 48px;
            width: 100% !important;
            padding: 10px 16px;
            font-size: 13px;
            line-height: 16px;
            color: #16213D;
            background-color: #fff;
            border: 1px solid rgba(22, 33, 61, 0.1);
            border-radius: 10px;
        }

        .hs-richtext p, a {
            text-align: center;
            color: #FFF;
            font-family: "Open Sans", sans-serif;
            font-size: 13px;
            font-style: normal;
            font-weight: 600;
            line-height: 18px;
            text-align: center;
        }

        input[type="submit"] {
            border: 1px solid #fff;
            padding: 9px 29px;
            background-color: transparent;
            display: inline-block;
            color: #fff;
            font-size: 15px;
            line-height: 24px;
            border-radius: 15px;
            text-align: center;
            transition: .3s linear;
            transition-property: background-color, color;
            text-decoration: none;
        }

        .hs-submit {
            .actions {
                display: flex;
                justify-content: center;
            }
        }

        .hs_recaptcha {
            display: none;
        }

        .form-columns-2 {
            width: 100%;
            display: flex;

            .hs-form-field {
                @include break(x-small) {
                    width: 50% !important;
                }
            }

            .hs-form-field {
                width: 50%;
                float: left;
                min-width: 50%;
            }

            .hs-dependent-field .hs-form-field.hs_state {
                left: -100%;
                position: relative;
                width: calc(200% - 8px) !important;
            }

            .hs-dependent-field .hs-form-field.hs_state .input {
                margin-right: 0;
            }

            .hs-dependent-field .hs-form-field.hs_state label {
                height: 0;
            }
        }
    }

    &__form-title,
    &__form-desc {
        color: #FFF;
        text-align: center;
    }

    &__form-title {
        font-family: "Axiforma", sans-serif;
        margin-bottom: 8px;

        @include break(x-small) {
            margin-bottom: 16px;
        }
    }

    &__form-desc {
        font-family: "Open Sans", sans-serif;
        font-size: 15px;
        font-style: normal;
        font-weight: 300;
        line-height: 1.46;
        margin-bottom: 32px;

        @include break(x-small) {
            max-width: 297px;
            margin-left: auto;
            margin-right: auto;
            margin-bottom: 24px;
        }
    }
    @extend .hubspot-form;
}
