.content-title-icon{
    margin-top: 56px;
    margin-bottom: 56px;
    @include break(medium){
        margin-top: 32px;
        margin-bottom: 32px;
    }
    @include break(s-small){
        margin-top: 24px;
        margin-bottom: 24px;
    }
    &__wrapper{
        max-width: 997px;
    }
    &__heading{
        display: grid;
        grid-template-columns: 40px 1fr;
        grid-column-gap: 14px;
        column-gap: 14px;
        margin-bottom: 18px;
        align-items: center;
    }
    &__icon-wrapper{
        display: flex;
        justify-content: center;
        align-items: center;
    }
    &__icon{
        display: block;
        max-width: 100%;
        max-height: 100%;
        width: auto;
        height: auto;
    }
    &__title{
        font-size: 22px;
        line-height: 28px;
        color: $blue;
    }
    &__text{
        @extend .a-tag;
        p,h2,h3,h4,h5,h6{
            &:not(:last-child){
                margin-bottom: 18px;
            }
        }
        h2,h3,h4,h5,h6{
            font-size: 18px;
            line-height: 28px;
        }
        ol{
            list-style: decimal;
        }
        ul{
            list-style: disc;
        }
        ol,
        ul{
            margin-left: 18px;
            &:not(:last-child){
                margin-bottom: 18px;
            }
        }
        li{
            list-style: inherit;
            &:not(:last-child){
                margin-bottom: 8px;
            }
        }
        p, li{
            font-family: $second_font;
            font-weight: 400;
            font-size: 16px;
            line-height: 24px;
        }
    }
}