.single-case-studies{
    .page-content{
        &__case-studies{
            @extend .a-tag;
            p{
                &:not(:last-child){
                    margin-bottom: 8px;
                }
            }
            li{
                padding: 0;
                font-family: $second_font;
                font-weight: 400;
                list-style: inherit;
                &:not(:last-child){
                    margin-bottom: 8px;
                }
                &::before{
                    display: none;
                }
            }
            ol{
                list-style: decimal;
            }
            ul{
                list-style: disc;
            }
            ol,
            ul{
                margin-left: 18px;
                &:not(:first-child){
                    margin-top: 18px;
                }
                &:not(:last-child){
                    margin-bottom: 18px;
                }
            }
            h2,h3,h4,h5,h6{
                font-size: 22px;
                line-height: 28px;
                &:not(:last-child){
                    margin-bottom: 8px;
                }
                @include break(desktop){
                    font-size: 18px;
                }
            }
        }
    }
}
.related-case-studies{
    margin-top: 100px;
    margin-bottom: 40px;

    @include break(medium){
        margin-top: 80px;
    }
    @include break(s-small){
        margin-top: 48px;
        margin-bottom: 24px;
    }
    &__container{
        padding-left: 30px;
        padding-right: 30px;
        @include break(ss-small){
            padding-left: 6px;
            padding-right: 6px;
        }
    }
    &__wrapper{
        max-width: 1220px;
    }
    &__title{
        text-align: center;
        @include break(medium){
            font-size: 40px;
            line-height: 48px;
        }
        @include break(s-small){
            font-size: 22px;
            line-height: 28px;
        }
    }
    &__list{
        margin-top: 40px;
        display: flex;
        flex-wrap: wrap;
        @include break(medium){
            margin-top: 24px;
        }
        .case-study-card{
            margin-bottom: 0;
            @include break(s-small){
                &:not(:last-child){
                    margin-bottom: 20px;
                }
            }
            &:nth-child(3){
                @include break(medium){
                    display: none;
                }
                @include break(s-small){
                    display: block;
                }
            }
        }
    }
}