.benefits-section{
    padding-top: 88px;
    padding-bottom: 225px;
    background-color: $dark;
    overflow: hidden;
    margin-top: -1px;
    @include break(medium){
        padding-top: 40px;
        padding-bottom: 98px;
    }
    @media screen and (max-width:767px){
        overflow: visible;
        z-index: 10;
        position: relative;
    }
    @include break(x-small){
        padding-top: 45px;
        padding-bottom: 20px;
    }
    &__title-wrapper{
        padding: 0 30px;
        margin-bottom: 28px;
        display: flex;
        justify-content: center;
        align-items: center;
        height: 130px;
        border-radius: 21px;
        background: rgba(217, 217, 217, 0.1);
        border: 1px solid rgba(255, 255, 255, 0.2);
        @include break(medium){
            height: 116px;
            margin-bottom: 15px;
        }
        @include break(x-small){
            margin-bottom: 32px;
            padding: 0;
            background-color: transparent;
            border: none;
            height: auto;
        }
    }
    &__title{
        text-align: center;
        color: $white;
        @include break(medium){
            font-size: 32px;
            line-height: 34px;
        }
        @include break(x-small){
            font-size: 25px;
            line-height: 29px;
            max-width: 270px;
        }
    }
    .js-animate-parent{
        .animate-object{
            transition:background-color .3s, opacity .2s, transform 0.6s cubic-bezier(0.165, 0.84, 0.44, 1);
            opacity: 0;
            &-title{
                transform: translate3d(0, -100%, 0);
                @media screen and (max-width:767px) {
                    opacity: 1;
                    transform: translate3d(0, 0, 0);
                }
            }
            &-1,
            &-2,
            &-4,
            &-5,
            &-7{
                transform: translate3d(-100%, 0, 0);
                @media screen and (max-width:767px) {
                    opacity: 1;
                    transform: translate3d(0, 0, 0);
                }
            }
            &-3{
                transform: translate3d(0, -100%, 0);
                @media screen and (max-width:767px) {
                    opacity: 1;
                    transform: translate3d(0, 0, 0);
                }
            }
            &-6{
                transform: translate3d(0, 100%, 0);
                @media screen and (max-width:767px) {
                    opacity: 1;
                    transform: translate3d(0, 0, 0);
                }
            }
            &-8{
                transform: translate3d(100%, 0, 0);
                @media screen and (max-width:767px) {
                    opacity: 1;
                    transform: translate3d(0, 0, 0);
                }
            }
        }
        &.animate{
            .animate-object{
                opacity: 1;
                transform: translate3d(0, 0, 0);
            }
        }
    }
    @media screen and (max-width:767px){
        .js-animate-parent{
            .animate-object.js-animate-object{
                transition: opacity .2s, transform 0.6s cubic-bezier(0.165, 0.84, 0.44, 1);
                opacity: 0;
                transform: translate3d(0, 50%, 0);
                &.animate{
                    opacity: 1;
                    transform: translate3d(0, 0, 0);
                }
            }
        }
    }  
    .js-animate-count{
        @media screen and (max-width:767px){
            display: none;
        }
        &.mobile{
            display: none;
            @media screen and (max-width:767px){
                display: inline-block;
            }
        }
    }
    &__wrapper{
        @media screen and (max-width:1280px) {
            max-width: 1000px;
        }
        @media screen and (max-width:1080px) {
            max-width: 900px;
        }
        @include break(medium){
            max-width: 770px;
        }
        @include break(medium850){
            max-width: 688px;
        }
        @media screen and (max-width:767px) {
            max-width: 550px;
        }
        svg{
            &.desktop{
                @media screen and (max-width:1080px) {
                    display: none;
                }
            }
            &.tablet{
                display: none;
                @media screen and (max-width:1080px){
                    display: block;
                }
                @media screen and (max-width:767px){
                    display: none;
                }
            }
            &.mobile{
                display: none;
                @media screen and (max-width:767px){
                    display: block;
                }
            }
        }
    }
    &__objects{
        height: 867px;
        position: relative;
        @media screen and (max-width:1280px) {
            height: 722px;
        }
        @media screen and (max-width:1080px) {
