.faq-section {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : 40px$mobile_margin;
    }

    &__wrapper {
        max-width    : 1200px;
        margin-left  : auto;
        margin-right : auto;
    }

    &__title {
        text-align    : center;
        margin-bottom : 37px;
        @include break(medium) {
            margin-bottom : 42px;
        }
        @include break(x-small) {
            font-size     : 25px;
            line-height   : 29px;
            margin-bottom : 23px;
        }
    }

    &__questions {

    }

    &__item {
        border              : 1px solid rgba(22, 33, 61, 0.6);
        border-radius       : 23px;
        padding             : 32px;
        transition          : .3s linear;
        transition-property : border-color, background-color;
        @include break(s-small) {
            padding : 24px;
        }

        &:not(:last-child) {
            margin-bottom : 20px;
        }

        &:hover,
        &.active {
            border-color     : $blue;
            background-color : $light_blue_tint;

            .faq-section__item-question {
                color : $blue;
            }

            .faq-section__item-btn span {
                background-color : $blue;
            }
        }

        &.active {
            .faq-section__item-question {
                font-weight : 600;
            }

            .faq-section__item-answer-wrapper {
                max-height : 5000px;
            }
        }

        &.active {
            .faq-section__item-question {
                //font-weight: 600;
            }

            .faq-section__item-btn span:last-child {
                transform : rotate(90deg);
            }
        }

        &-question-wrapper {
            position : relative;
        }

        &-question {
            font-size     : 18px;
            line-height   : 24px;
            padding-right : 36px;
            transition    : color .3s linear;
            cursor        : pointer;
            @include break(x-small) {
                padding-right : 50px;
                font-size     : 16px;
                line-height   : 20px;
            }
        }

        &-btn {
            position         : absolute;
            right            : 0;
            top              : 50%;
            transform        : translateY(-50%);
            width            : 17px;
            height           : 17px;
            cursor           : pointer;
            background-color : transparent;
            border           : none;
            padding          : 0;
            pointer-events   : none;

            span {
                position         : absolute;
                background-color : $dark;
                transition       : background-color, transform .3s linear;

                &:first-child {
                    width  : 100%;
                    height : 1px;
                    top    : 8px;
                    left   : 0;
                }

                &:last-child {
                    width  : 1px;
                    height : 100%;
                    top    : 0;
                    left   : 8px;
                }
            }
        }

        &-answer-wrapper {
            padding-right : 40px;
            max-height    : 0;
            overflow      : hidden;
            transition    : max-height .3s linear;
            @include break(x-small) {
                padding-right : 8px;
            }
        }

        &-answer {
            padding-top : 20px;
            @extend .a-tag;

            p {
                &:not(:last-child) {
                    margin-bottom : 16px;
                }
            }

            p, li {
                font-size   : 16px;
                line-height : 24px;
            }

            ol {
                list-style : decimal;
            }

            ul {
                list-style : disc;
            }

            ol,
            ul {
                margin-left : 18px;

                &:not(:first-child) {
                    margin-top : 16px;
                }

                &:not(:last-child) {
                    margin-bottom : 16px;
                }
            }

            li {
                padding     : 0;
                font-family : $second_font;
                font-weight : 300;
                list-style  : inherit;

                &:not(:last-child) {
                    margin-bottom : 8px;
                }

                &::before {
                    display : none;
                }
            }

            h2, h3, h4, h5, h6 {
                font-size   : 22px;
                line-height : 28px;

                &:not(:last-child) {
                    margin-bottom : 8px;
                }

                @include break(desktop) {
                    font-size : 18px;
                }
            }
        }
    }

}