.case-studies-featured{
    margin-top: $desktop_margin;
    margin-bottom: $desktop_margin;
    @include break(medium){
        margin-top: $mobile_margin;
        margin-bottom: $mobile_margin;
    }
    &__title{
        text-align: center;
        margin-bottom: 24px;
        @include break(medium){
            font-size: 22px;
            line-height: 28px;
            margin-bottom: 16px;
        } 
        @include break(s-small){
            margin-bottom: 24px;
        }
    }
    &__post{
        border-radius: 50px;
        border: 1px solid $blue;
        background-color: $light_blue_tint;
        padding: 39px 71px;
        display: grid;
        grid-template-columns: 45.455% 50%;
        grid-column-gap: 48px;
        grid-row-gap: 24px;
        column-gap: 48px;
        row-gap: 24px;
        @include break(desktop){
            padding: 39px;
            grid-column-gap: 24px;
            column-gap: 24px;
        }
        @include break(tablet){
            padding: 23px;
            border-radius: 32px;
        }
        @include break(medium850){
            grid-template-columns: 47.5% 48.75%;
        }
        @include break(ss-small){
            padding: 15px;
            border-radius: 16px;
        }
        @include break(s-small){
            grid-template-columns:1fr;
        }
        &-media{
      
        }
        &-image-link{
            position: relative;
            display: block;
            border-radius: 30px;
            height: 100%;
            .mask,
            .figure{
                position: absolute;
                left: 0;
                top: 0;background-position: top left;
                background-repeat: no-repeat;
            }
            .mask{
                background-image: url("data:image/svg+xml,%3Csvg width='146' height='158' viewBox='0 0 146 158' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0 158C-3.49938e-07 149.994 2.78887 142.456 7.52835 137.649L141.101 2.20799C142.514 0.774346 144.233 -1.05943e-06 146 -1.13665e-06L-6.9064e-06 5.24521e-06L0 158Z' fill='%23F3F6FF'/%3E%3C/svg%3E");
                width: 147px;
                height: 156px;
            }
            .figure{
                background-image: url("data:image/svg+xml,%3Csvg width='105' height='105' viewBox='0 0 105 105' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M30 -7.34351e-06L97.1005 -1.4774e-06C103.337 -9.32203e-07 106.46 7.54 102.05 11.9498L11.9497 102.05C7.53998 106.46 -9.03399e-06 103.337 -8.4888e-06 97.1005L-2.62268e-06 30C-1.17422e-06 13.4314 13.4315 -8.79198e-06 30 -7.34351e-06Z' fill='%233B37E6'/%3E%3C/svg%3E");
                width: 105px;
                height: 105px;
            }
        }
        &-image{
            display: block;
            border-radius: 20px;
            width: 100%;
            height: 100%;
        }
        &-logo-wrapper{
            position: absolute;
            left: 8px;
            bottom: 8px;
            z-index: 10;
            padding: 8px 16px;
            width: 136px;
            height: 48px;
            border-radius: 8px;
            background-color: $white;
            display: flex;
            justify-content: center;
            align-items: center;
        }
        &-logo{
            display: block;
            max-width: 100%;
            max-height: 100%;
            width: auto;
            height: auto;
        }
        &-content-wrapper{
            display: flex;
            justify-content: space-between;
            flex-direction: column;
            height: 100%;
        }
        &-content{
  
        }
        &-cat-wrapper{
            margin-bottom: 32px;
            @include break(tablet){
                margin-bottom: 16px;
            }
        }
        &-cat{
            display: inline-block;
            font-size: 13px;
            line-height: 16px;
            border-radius: 10px;
            padding: 5px 15px;
            border: 1px solid;
            font-family: $third_font;
            font-weight: 600;
            color: $dark;
            border-color: $dark;
            &.erp{
                border-color: $blue;
                background-color: $royal_blue;
            }
            &.hospitality{
                border-color: $malibu;
                background-color: $blue_tint;
            }
            &.school{
                border-color: $apricot;
                background-color: $coral_tint;
            }
            &.retail{
                border-color: $purple;
                background-color: $purple_tint;
            }
        }
        &-title{
            font-size: 32px;
            line-height: 40px;
            color: $blue;
            margin-bottom: 12px;
            transition: color .3s linear;
            @include break(tablet){
                font-size: 22px;
                line-height: 28px;
            }
            &:hover{
                color: $dark;
            }
            a{
                @extend .inherit;
            }
        }
        &-excerpt{
            font-size: 16px;
            line-height: 24px;
        }
        &-read-wrapper{
            margin-top: 16px;
        }
        &-read{
            @extend .arrow-btn-right;
            font-family: $third_font;
            font-weight: 600;
        }
    }
}