.moving-text{
    margin-top: $desktop_margin;
    margin-bottom: $desktop_margin;
    overflow: hidden;
    @include break(medium){
        margin-top: $mobile_margin;
        margin-bottom: $mobile_margin;
    }

    &__container{
        position: relative;
        @include break(ss-small){
            padding-top: 27px;
            padding-bottom: 27px;
        }
    } 
    &__line{
        overflow: hidden;
        max-width: 100vw;
        width: 100%;
        height: 70px;
        margin: 0 auto;
        position: relative;
        display: flex;
        @include break(medium){
            height: 54px;
            &:not(:last-child){
                margin-bottom: 13px;
            }
        }
        @include break(ss-small){
            height: 32px;
        }
        &.reverse{
            .moving-text__block{
                animation: moving-line 70s linear infinite reverse;
            }
        }
        &:not(.reverse){
            .moving-text__block{
                animation: moving-line 50s linear infinite normal; 
            }
        }
        &-7, &-8, &-9{
            display: none;
            @include break(ss-small){
                display: flex;
            }
        }
    }
    &__block{
        display: flex;
        position: relative;
    
        justify-content: center;
        img,svg{
            display: block;
            width: auto;
            margin: 0;
            height: 70px;
            @include break(medium){
                height: 54px;
            }
            @include break(ss-small){
                height: 32px;
            }
        }
    }
    &__content{
        position: absolute;
        left: 50%;
        top: 50%;
        transform: translate(-50%,-50%);
        z-index: 100;
        max-width: 735px;
        width: 100%;
        min-height: 159px;
        //background: linear-gradient(90deg, rgba(255, 255, 255, 0) 3.54%, #FFFFFF 12.11%, #FFFFFF 89.79%, rgba(255, 255, 255, 0) 99.5%);
        display: flex;
        justify-content: center;
        align-items: center;
        padding: 10px;
        padding-bottom: 10px;
        &::before{
            content: '';
            display: block;
            width: 100%;
            height: 100%;
            position: absolute;
            z-index: -1;
            left: 0;
            top: 0;
            background-color: $white;
            filter: blur(8px);
        }
        @include break(medium){
            min-height: 124px;
            max-width: 560px;
        }
        @include break(ss-small){
            padding-left: 0;
            padding-right: 0;
            max-width: 305px;
            min-height: 134px;
        }
    }
    &__text{
        text-align: center;
        font-size: 75px;
        line-height: 77px;
        @include break(medium){
            font-size: 58px;
            line-height: 60px;
        }
        @include break(ss-small){
            font-size: 38px;
            line-height: 39px;
        }
    }
}
@-webkit-keyframes moving-line {
    0% {
        transform: translateX(0%);
    }
    100% {
        transform: translateX(-100%);
    }
}
@keyframes moving-line {
    0% {
        transform: translateX(0%);
    }
    100% {
        transform: translateX(-100%);
    }
}