.mobile-menu-overlay {
    position            : fixed;
    z-index             : 9050;
    background          : rgba(0, 0, 0, 0.5);
    width               : 100%;
    height              : 100%;
    top                 : 0;
    left                : 0;
    visibility          : hidden;
    opacity             : 0;
    transition          : .3s linear;
    transition-property : opacity, visibility;

    &.show {
        visibility : visible;
        opacity    : 1;
    }
}

.mobile-menu {
    position                       : fixed;
    z-index                        : 9100;
    right                          : 0;
    top                            : 0;
    height                         : 100%;
    width                          : 376px;
    padding-top                    : 109px;
    background-color               : $white;
    -webkit-border-top-left-radius : 30px;
    -moz-border-radius-topleft     : 30px;
    border-top-left-radius         : 30px;
    transform                      : translateX(100%);
    opacity                        : 0;
    transition                     : .5s cubic-bezier(0.4, 0, 0.2, 1);
    transition-property            : opacity, transform;

    &.show {
        transform        : translateX(0);
        transition-delay : 0.2s;
        opacity          : 1;
    }

    @include break(x-small) {
        width                          : 90%;
        padding-top                    : 90px;
        max-width                      : 325px;
        -webkit-border-top-left-radius : 22px;
        -moz-border-radius-topleft     : 22px;
        border-top-left-radius         : 22px;
    }

    &__container {
        padding-left   : 34px;
        padding-right  : 26px;
        overflow       : auto;
        height         : 100%;
        padding-bottom : 40px;
        @include break(ss-small) {
            padding-left  : 36px;
            padding-right : 40px;
        }
    }

    &__nav {

    }

    &__menu {

        & > .menu-item {
            padding-top    : 15px;
            padding-bottom : 15px;

            &.menu-item-has-children {
                &.active {
                    & > a {
                        color : $blue;

                        .sub-menu-toggle {
                            background-image : url("data:image/svg+xml,%3Csvg width='14' height='9' viewBox='0 0 14 9' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M13 1L7 7L1 1' stroke='%233B37E6' stroke-width='1.5'/%3E%3C/svg%3E%0A");
                            transform        : rotate(-180deg);
                        }
                    }

                }

                & > .nav__link,
                & > a {
                    position   : relative;
                    transition : color .3s linear;
                }

                .sub-menu-toggle {
                    display             : block;
                    width               : 14px;
                    height              : 13px;
                    position            : absolute;
                    right               : 0;
                    top                 : 6px;
                    background-image    : url("data:image/svg+xml,%3Csvg width='14' height='9' viewBox='0 0 14 9' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M13 1.5L7 7.5L1 1.5' stroke='%2316213D' stroke-width='1.5'/%3E%3C/svg%3E%0A");
                    background-position : center;
                    background-repeat   : no-repeat;
                    transition          : transform .3s linear;
                    z-index : -1;
                }

                & > .sub-menu {
                    max-height : 0;
                    overflow   : hidden;
                    transition : max-height .3s linear;

                    & > li {
                        &.current-menu-item {
                            & > .nav__link,
                            & > a {
                                color : $blue;
                            }
                        }

                        &:first-child {
                            padding-top : 13px;
                        }

                        &:not(:last-child) {
                            & > .nav__link,
                            & > a {
                                border-bottom  : 1px solid $gret_blue;
                                padding-bottom : 11px;
                            }
                        }

                        & > .nav__link,
                        & > a {
                            display     : block;
                            font-size   : 14px;
                            line-height : 22px;
                            padding-top : 11px;

                        }
                    }
                }

                &.mega-menu {
                    &.active {
                        padding-bottom : 8px;
                    }

                    & > .sub-menu {
                        & > .menu-item {
                            padding-bottom : 4px;

                            &:first-child {
                                padding-top : 9px;
                            }

                            & > .nav__link,
                            & > a {
                                padding        : 9px 17px;
                                display        : flex;
                                align-items    : center;
                                font-size      : 14px;
                                line-height    : 18px;
                                letter-spacing : -0.03em;
                                font-family    : $third_font;
                                font-weight    : 600;
                                border-bottom  : none;
                                height         : 54px;
                                border-radius  : 10px;
                            }

                            & > .fixed-menu-wrapper {
                                position                       : fixed;
                                width                          : 100%;
                                height                         : 100%;
                                right                          : 0;
                                top                            : 0;
                                -webkit-border-top-left-radius : 30px;
                                -moz-border-radius-topleft     : 30px;
                                border-top-left-radius         : 30px;
                                transform                      : translateX(100%);
                                transition                     : transform .5s cubic-bezier(0.4, 0, 0.2, 1);
                                z-index                        : 9300;
                                padding-top                    : 86px;
                                @include break(ss-small) {
                                    padding-top : 60px;
                                }

                                &.show {
                                    transform : translateX(0);
                                }

                                @include break(x-small) {
                                    -webkit-border-top-left-radius : 22px;
                                    -moz-border-radius-topleft     : 22px;
                                    border-top-left-radius         : 22px;
                                }

                                .return-back {
                                    position         : absolute;
                                    top              : 33px;
                                    left             : 20px;
                                    font-size        : 16px;
                                    line-height      : 25px;
                                    color            : $dark;
                                    border           : none;
                                    background-color : transparent;
                                    padding          : 0 0 0 15px !important;
                                    @include break(ss-small) {
                                        top : 21px;
                                    }

                                    &::before {
                                        content             : '';
                                        display             : block;
                                        background-image    : url("data:image/svg+xml,%3Csvg width='9' height='14' viewBox='0 0 9 14' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M8 13L2 7L8 0.999999' stroke='%2316213D' stroke-width='1.5'/%3E%3C/svg%3E%0A");
                                        background-position : center;
                                        background-repeat   : no-repeat;
                                        width               : 9px;
                                        height              : 14px;
                                        position            : absolute;
                                        left                : 0;
                                        top                 : 3px;
                                    }
                                }

                                & > .sub-menu {
                                    padding-top    : 24px;
                                    padding-bottom : 50px;
                                    overflow       : auto;
                                    height         : 100%;
                                    padding-left   : 40px;
                                    padding-right  : 35px;
                                    @include break(ss-small) {
                                        padding-top : 50px;
                                    }

                                    & > .menu-item {
                                        margin-bottom : 22px;

                                        & > a {
                                            font-size      : 12px;
                                            line-height    : 19px;
                                            color          : rgba($color : $dark, $alpha : 0.6);
                                            display        : block;
                                            padding-bottom : 7px;
                                            border-bottom  : 1px solid rgba(192, 198, 214, 0.5);
                                        }

                                        & > .sub-menu {
                                            margin-top : 4px;

                                            & > .menu-item {
                                                padding-top    : 11px;
                                                padding-bottom : 11px;

                                                &:not(:last-child) {
                                                    border-bottom : 1px solid $gret_blue;
                                                }

                                                &.menu-item-has-children {
                                                    &.active {
                                                        .nav__link {
                                                            .sub-menu-toggle {
                                                                background-image : url("data:image/svg+xml,%3Csvg width='14' height='9' viewBox='0 0 14 9' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M13 1L7 7L1 1' stroke='%233B37E6' stroke-width='1.5'/%3E%3C/svg%3E%0A");
                                                                transform        : rotate(-180deg);
                                                            }
                                                        }
                                                    }

                                                    .nav__link {
                                                        position           : relative;
                                                        padding-inline-end : 18px;
                                                    }

                                                    .sub-menu {
                                                        //padding-inline-start: 10px;

                                                        max-height : 0;
                                                        overflow   : hidden;
                                                        transition : max-height .3s linear;

                                                        .menu-item {
                                                            padding-top    : 10px;
                                                            padding-bottom : 10px;

                                                            &:first-of-type {
                                                                padding-top : 20px;
                                                            }

                                                            .nav__link,
                                                            a {
                                                                font-size   : 13px;
                                                                line-height : 18px;
                                                            }
                                                        }
                                                    }
                                                }
                                            }

                                            .nav__link,
                                            a {
                                                font-size   : 14px;
                                                line-height : 22px;
                                                color       : $black;
                                                display     : block;
                                            }
                                        }
                                    }
                                }

                                .menu-item-parent-link {
                                    display       : block;
                                    margin-bottom : 20px;
                                    font-family   : $third_font;
                                    font-weight   : 600;
                                    font-size     : 16px;
                                    line-height   : 20px;
                                }
                            }

                            &.style-blue {
                                & > span.nav__link,
                                & > a {
                                    background-color : #F3F7FF;
                                    color            : $blue;
                                }

                                & > .fixed-menu-wrapper {
                                    background-color : #F3F7FF;

                                    & > .sub-menu > .menu-item > .sub-menu .current-menu-item > a,
                                    & > .sub-menu > .menu-item > .sub-menu span.nav__link,
                                    .menu-item-parent-link {
                                        color : $blue;
                                    }

                                }
                            }

                            &.style-coral {
                                & > span.nav__link,
                                & > a {
                                    background-color : #FFF5F3;
                                    color            : $coral;
                                }

                                & > .fixed-menu-wrapper {
                                    background-color : #FFF5F3;

                                    & > .sub-menu > .menu-item > .sub-menu .current-menu-item > a,
                                    & > .sub-menu > .menu-item > .sub-menu span.nav__link,
                                    .menu-item-parent-link {
                                        color : $coral;
                                    }
                                }
                            }

                            &.style-purple {
                                & > span.nav__link,
                                & > a {
                                    background-color : #F9F5FF;
                                    color            : $purple;
                                }

                                & > .fixed-menu-wrapper {
                                    background-color : #F9F5FF;

                                    & > .sub-menu > .menu-item > .sub-menu .current-menu-item > a,
                                    & > .sub-menu > .menu-item > .sub-menu span.nav__link,
                                    .menu-item-parent-link {
                                        color : $purple;
                                    }
                                }
                            }

                            &.style-light-blue {
                                & > span.nav__link,
                                & > a {
                                    background-color : #F3FDFF;
                                    color            : $light_blue;
                                }

                                & > .fixed-menu-wrapper {
                                    background-color : #F3FDFF;

                                    & > .sub-menu > .menu-item > .sub-menu .current-menu-item > a,
                                    & > .sub-menu > .menu-item > .sub-menu span.nav__link,
                                    .menu-item-parent-link {
                                        color : $light_blue;
                                    }
                                }
                            }
                        }
                    }

                }
            }

            & > .nav__link,
            & > a {
                font-size     : 16px;
                line-height   : 25px;
                display       : block;
                padding-right : 18px;
            }
        }
    }

    &__lang {
        margin-top : 15px;

        &-current {
            display     : flex;
            align-items : center;
            font-size   : 15px;
            line-height : 24px;
            transition  : color .3s linear;
            cursor      : pointer;

            * {
                pointer-events : none;
            }

            svg {
                margin-top : -3px;
                min-width  : 20px;
            }

            path {
                transition : fill .3s linear;
            }

            &.active {
                .mobile-menu__lang-code {
                    color : $blue;

                    &::after {
                        transform        : rotate(-180deg);
                        background-image : url("data:image/svg+xml,%3Csvg width='14' height='9' viewBox='0 0 14 9' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M13 1L7 7L1 1' stroke='%233B37E6' stroke-width='1.5'/%3E%3C/svg%3E%0A");
                    }
                }

                path {
                    fill : $blue;
                }
            }
        }

        &-code {
            padding-left   : 6px;
            text-transform : capitalize;
            width          : 100%;
            position       : relative;
            padding-right  : 18px;

            &::after {
                content             : '';
                display             : block;
                width               : 14px;
                height              : 13px;
                position            : absolute;
                right               : 0;
                top                 : 6px;
                background-image    : url("data:image/svg+xml,%3Csvg width='14' height='9' viewBox='0 0 14 9' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M13 1.5L7 7.5L1 1.5' stroke='%2316213D' stroke-width='1.5'/%3E%3C/svg%3E%0A");
                background-position : center;
                background-repeat   : no-repeat;
                transition          : transform .3s linear;
            }
        }

        .wpml-ls {
            max-height : 0;
            overflow   : hidden;
            transition : max-height .3s linear;
            margin-top : 13px;
            display    : block;

            ul {
                padding : 0;
                margin  : 0;
            }

            .wpml-ls-item {
                width       : 100%;
                padding-top : 11px;

                &:not(:last-child) {
                    border-bottom  : 1px solid $gret_blue;
                    padding-bottom : 11px;
                }

                & > a {
                    display     : block;
                    width       : 100%;
                    font-size   : 14px;
                    line-height : 22px;
                    padding     : 0;
                }
            }
        }
    }

    &__button {
        font-size        : 15px;
        line-height      : 24px;
        text-align       : center;
        color            : $white;
        background-color : $blue;
        padding          : 8px 17px;
        display          : inline-block;
        min-width        : 125px;
        max-width        : 200px;
        border-radius    : 15px;
        position         : absolute;
        left             : 27px;
        top              : 27px;
        @include break(ss-small) {
            top  : 26px;
            left : 30px;
        }
    }
}