.side-title-content-cta-v3 {
    $self: &;
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    overflow      : hidden;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
        overflow      : unset;
    }
    @include break(x-small) {
        margin-top    : 50px;
        margin-bottom : 50px;
    }
    .js-animate-parent {
        &.animate {
            .js-animate-element::before,
            .animation-title,
            .animation-content {
                opacity   : 1;
                transform : translate3d(0, 0, 0);
            }
        }

        .js-animate-element::before,
        .animation-title,
        .animation-content {
            transition : opacity .4s, transform .8s cubic-bezier(0.165, 0.84, 0.44, 1);
            opacity    : 0;

        }

        .js-animate-element::before,
        .animation-title {
            transform : translate3d(-50%, 0, 0);
            @include break(medium) {
                transform : translate3d(0, 50%, 0);
            }
        }

        .animation-content {
            transform : translate3d(50%, 0, 0);
            @include break(medium) {
                transform : translate3d(0, 50%, 0);
            }
        }
    }

    &__wrapper {
        display               : grid;
        grid-template-columns : 285px 1fr;
        gap                   : 16px 80px;
        align-items           : center;
        position              : relative;

        &.big {
            grid-template-columns : 444px 1fr;

            &::before {
                left : 484px;
            }
        }

        &.medium {
            grid-template-columns : 305px 1fr;

            &::before {
                left : 345px;
            }
        }

        @include break(medium) {
            &,
            &.medium,
            &.big {
                grid-template-columns : 1fr;
            }

        }

        &::before {
            content          : '';
            display          : block;
            width            : 1px;
            height           : 100%;
            position         : absolute;
            left             : 325px;
            top              : 0;
            background-color : rgba($color : $dark, $alpha : 0.5);
            @include break(medium) {
                display : none;
            }
        }
    }

    &__title {
        @extend .styled-text;
        font-size   : 40px;
        line-height : 48px;
        @include break(medium) {
            font-size   : 32px;
            line-height : 40px;
        }
    }

    &__text {
        @extend .a-tag;

        p, li {
            font-size   : 16px;
            line-height : 24px;
        }

        p {
            &:not(:last-child) {
                margin-bottom : 16px;
            }
        }

        ol {
            list-style  : decimal;
            margin-left : 18px;
        }

        ol,
        ul {
            &:not(:first-child) {
                margin-top : 8px;
            }

            &:not(:last-child) {
                margin-bottom : 32px;
            }
        }

        li {
            padding      : 0;
            font-weight  : 400;
            list-style   : inherit;
            padding-left : 28px;
            position     : relative;

            &::before {
                content          : '';
                display          : block;
                position         : absolute;
                left             : 12px;
                top              : 9px;
                background-color : $dark;
                width            : 3px;
                height           : 3px;
                border-radius    : 50%;
            }
        }

        &.styled {
            li {
                padding-left : 32px;
                color        : $black;

                &:not(:last-child) {
                    margin-bottom : 16px;
                }

                &::before {
                    content          : '';
                    display          : block;
                    position         : absolute;
                    left             : 0;
                    top              : 0;
                    background-color : transparent;
                    border-radius    : 0;
                    background-image : url("data:image/svg+xml,%3Csvg width='25' height='24' viewBox='0 0 25 24' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cg clip-path='url(%23clip0_5243_39384)'%3E%3Cpath d='M13.8886 1.27238L23.4197 10.8035C24.0211 11.4049 24.0211 12.38 23.4197 12.9814L13.8886 22.5125C13.2872 23.1139 12.3121 23.1139 11.7106 22.5125L2.17954 12.9814C1.57812 12.38 1.57812 11.4049 2.17954 10.8035L11.7106 1.27238C12.3121 0.670959 13.2872 0.670959 13.8886 1.27238Z' fill='%23ECDEFF' stroke='%23A142FF' stroke-width='0.285714'/%3E%3C/g%3E%3Cdefs%3E%3CclipPath id='clip0_5243_39384'%3E%3Crect width='24' height='24' fill='white' transform='translate(0.906769)'/%3E%3C/clipPath%3E%3C/defs%3E%3C/svg%3E");
                    width            : 25px;
                    height           : 24px;
                }
            }
        }

        h2, h3, h4, h5, h6 {
            font-size   : 22px;
            line-height : 28px;
            @include break(medium) {
                font-size   : 15px;
                line-height : 24px;
            }

            &:not(:last-child) {
                margin-bottom : 16px;
                @include break(medium) {
                    margin-bottom : 8px;
                }
            }
        }
    }

    &__button-wrapper {
        margin-top : 32px;
    }

    &__button {
        @extend .styled-btn;
    }
    &.responsive-column {
        #{ $self }__wrapper {
            display: flex;
            align-items: center;

            @include break(medium){
                flex-direction: column;
            }

            &:before {
                display: none;
            }
        }
        .js-animate-parent {
            &.animate {
                .side-title-content-cta-v3__content-wrapper:before {
                    opacity   : 1;
                    transform : translate3d(0, 0, 0);
                }
            }
        }
        #{ $self }__content-wrapper {
            position: relative;

            &:before {
                content: '';
                display: block;
                width: 1px;
                height: 100%;
                border: 1px solid rgba(22, 33, 61, 0.5);
                position: absolute;
                left: -37px;
                opacity    : 0;

                @include break(medium){
                    display: none;
                }
            }
        }
    }
}