    &__frame{
        position: absolute;
        z-index: 15;
        filter: drop-shadow(14.9835px 14.9835px 25.9714px rgba(22, 33, 61, 0.2));
        overflow: hidden;
        transition: opacity .2s, transform .8s cubic-bezier(0.165, 0.84, 0.44, 1);
        svg,img{
            display: block;
            width: 100%;
            height: 100%;
            object-fit: cover;
        }
        &-frame{
            position: relative;
            z-index: 11;
        }
        &-frame-image{
            position: absolute;
            width: 100%;
            height: 100%;
            top: 0;
            left: 0;
            z-index: 10;
      
        }
        &.frame-1,
        &.frame-3{
            border: 5px solid $white;
            border-radius: 20px;
            @include break(medium){
                border-width: 4px;
                border-radius: 16px;
            }
            @include break(ss-small){
                border-radius: 8px;
                border-width: 2px;
            }
            svg{
                margin-left: -1px;
                margin-top: -1px;
                width: calc(100% + 2px) !important;
                height: calc(100% + 2px) !important;
            }
            svg,img{
                border-radius: inherit;
            }
        }
        &.frame-1{
            right: 69px;
            width: 504px;
            height: 288px;
            top: -131px;
            opacity: 0;
            transform: translate3d(0, -100%, 0);
            @include break(desktop){
                right: auto;
                left: -41px;
            }
            @include break(medium){
                width: 419px;
                height: 240px;
                top: -98px;
                left: -35px;
                filter: drop-shadow(12.4542px 12.4542px 21.5872px rgba(22, 33, 61, 0.2));
            }
            @include break(ss-small){
                width: 224px;
                height: 128px;
                left: -21px;
                top: -50px;
                filter: drop-shadow(6.65934px 6.65934px 11.5429px rgba(22, 33, 61, 0.2));
            }
            @include break(small-360){
                left: -40px;
            }
        }
        &.frame-2{
            width: 171px;
            height: 333px;
            left: 199px;
            top: 61px;
            opacity: 0;
            transform: translate3d(-100%, 0, 0);
            @include break(large1370){
                left: 159px;
            }
            @include break(desktop){
                transform: translate3d(0, 100%, 0);
                left: auto;
                right: 43px;
                bottom: -120px;
                top: auto;
                width: 193px;
                height: 377px;
                filter: drop-shadow(16.982px 16.982px 29.4354px rgba(22, 33, 61, 0.2));
            }
            @include break(ss-small){
                width: 100px;
                height: 195px;
                right: 21px;
                bottom: -89px;
                filter: drop-shadow(8.79501px 8.79501px 15.2447px rgba(22, 33, 61, 0.2));
            }
            @include break(small-360){
                right: 10px;
            }
            .screens-frames__frame-frame-image{
                padding: 7px 8px 7px 8px;
                @include break(ss-small){
                    padding: 5px 3px 4px 3px;
                }
            }
        }
        &.frame-3{ 
            width: 495px;
            height: 282px;
            left: 115px;
            bottom: 95px;
            opacity: 0;
            transform: translate3d(0, 100%, 0);
            @include break(desktop){
                left: -84px;
                bottom: 130px;
                transform: translate3d(-100%, 0, 0);
            }
            @include break(medium){
                width: 404px;
                height: 230px;
                bottom: 162px;
                left: -69px;
                filter: drop-shadow(12.2297px 12.2297px 21.1981px rgba(22, 33, 61, 0.2));
            }
            @include break(ss-small){
                width: 236px;
                height: 135px;
                left: -23px;
                bottom: 61px;
                filter: drop-shadow(7.18085px 7.18085px 12.4468px rgba(22, 33, 61, 0.2));
            }
            @include break(small-360){
                left: -60px;
            }
        }
        &.frame-4{
            width: 227px;
            height: 475px;
            right: 61px;
            bottom: 255px;
            opacity: 0;
            transform: translate3d(100%, 0, 0);
            @include break(desktop){
                right: 50px;
                top: -157px;
                bottom: auto;
            }
            @include break(medium){
                width: 175px;
                height: 369px;
                right: 53px;
