                filter: drop-shadow(6.44972px 6.44972px 11.1795px rgba(22, 33, 61, 0.2));
            }
            @include break(small-360){
                right: 15px;
            }
            .screens-frames__frame-frame-image{
                padding: 54px 19px 63px 17px;
                @include break(medium){
                    padding: 39px 13px 49px 10px;
                }
                @include break(ss-small){
                    padding: 22px 8px 26px 7px;
                }
            }
        }
    }
    &__container{
        position: relative;
        padding-top: 289px;
        padding-bottom: 441px;
        @media screen and (max-width: 1440px) {
            overflow: hidden;
        }
        @include break(desktop){
            padding-top: 397px;
            padding-bottom: 441px;
        }
        @include break(ss-small){
            padding-top: 249px;
            padding-bottom: 231px;
        }
    }
    &__counter{
        position: absolute;
        z-index: 20;
        display: flex;
        justify-content: center;
        align-items: center;
        padding: 15px;
        &.purple{
            width: 204px;
            height: 148px;
            border-radius: 16px;
            border: 1px solid $purple;
            background-color: $purple_tint;
            @include break(medium){
                width: 200px;
                height: 133px;
            }
            @include break(ss-small){
                width: 109px;
                height: 77px;
                border-radius: 9px;
            }
            .screens-frames__counter-count,
            .screens-frames__counter-text{
                color: $purple;
            }
        }
        &.light-blue{
            width: 196px;
            height: 148px;
            border-radius: 16px;
            border: 1px solid $light_blue;
            background-color: $blue_tint;
            @include break(medium){
                width: 200px;
                height: 132px;
                border-radius: 15px;
            }
            @include break(ss-small){
                width: 109px;
                height: 77px;
                border-radius: 8px;
            }
            .screens-frames__counter-count,
            .screens-frames__counter-text{
                color: $light_blue;
            }
        }
        &.coral{
            width: 204px;
            height: 190px;
            border-radius: 98px;
            border: 1px solid $coral;
            background-color: $coral_tint;
            @include break(medium){
                width: 166px;
                height: 152px;
                border-radius: 91px;
            }
            @include break(ss-small){
                width: 97px;
                height: 91px;
                border-radius: 53px;
            }
            .screens-frames__counter-count,
            .screens-frames__counter-text{
                color: $coral;
            }
        }
        &.position-1{
            top: 61px;
            right: 601px;
            @include break(desktop){
                right: auto;
                left: 50%;
                margin-left: -102px;
                top: 171px;
            }
            @include break(medium){
                top: 191px;
                margin-left: -100px;
            }
            @include break(ss-small){
                top: 129px;
                margin-left: -69px;
            }
        }
        &.position-2{
            bottom: 403px;
            left: 125px;
            @include break(desktop){
                left: auto;
                right: 40px;
                bottom: 288px;
            }
            @include break(ss-small){
                left: auto;
                right: 21px;
                bottom: 121px;
            }
            @include break(small-360){
                right: 10px;
            }
        }
        &.position-3{
            bottom: 138px;
            right: 321px;
            @include break(desktop){
                left: 50%;
                margin-left: -76px;
                bottom: -35px;
            }
            @include break(ss-small){
                left: 50%;
                margin-left: -62px;
                bottom: -68px;
            }
        }
        &-count{
            text-align: center;
            font-family: $third_font;
            font-weight: 600;
            font-size: 53px;
            line-height: 55px;
            display: flex;
            justify-content: center;
            @include break(medium){
                font-size: 40px;
                line-height: 42px;
            }
            @include break(ss-small){
                font-size: 26px;
                line-height: 28px;
            }
            span{
                font-family: inherit;
                font-size: inherit;
                line-height: inherit;
                font-weight: 600;
                color: inherit;
            }
        }
        &-text{
            margin-top: 1px;
            text-align: center;
            font-size: 20px;
            line-height: 1;
            @include break(medium){
                font-size: 18px;
            }
            @include break(ss-small){
                font-size: 10px;
            }
        }
    }
    &__wrapper{
        max-width: 590px;
        margin-left: auto;
        margin-right: auto;
        @include break(medium){
            max-width: 650px;
        }
        @include break(ss-small){
            max-width: 320px;
        }
    }
    &__title{
        text-align: center;
        @include break(medium){
