.benefits-v2 {
    padding-top: 28px;
    padding-bottom: 164px;
    position: relative;
    z-index: 1;
    overflow: hidden;

    @include break(large1650) {
        padding-bottom: 155px;
    }

    @include break(large1280) {
        padding-bottom: 130px;
    }

    @include break(tablet) {
        padding-bottom: 110px;
    }

    @include break(medium850) {
        padding-bottom: 90px;
    }

    @include break(ss-small) {
        padding-top: 50px;
    }

    @include break(s-small) {
        padding-top: 77px;
        padding-bottom: 181px;
    }

    @include break(x-small) {
        padding-bottom: 181px;
    }

    &:before,
    &:after {
        position: absolute;
        content: '';
        display: block;
        left: 0;
        top: 0;
        width: 100%;
        height: 100%;
        z-index: 1;
    }

    &:before {
        right: -21px;
        top: 52px;
        width: 306px;
        height: 287px;
        background: url(data:image/svg+xml;base64,) center center no-repeat;
        background-size: contain;

        @include break(large1750) {
            width: 215px;
        }

        @include break(large1440) {
            width: 175px;
        }

        @include break(desktop) {
            width: 145px;
            height: 140px;
        }

        @include break(medium) {
            width: 115px;
            height: 110px;
            right: -5px;
        }

        @include break(medium850) {
            top: 25px;
        }

        @include break(ss-small) {
            width: 115px;
            height: 74px;
            top: 5px;
            right: -22px;
        }
    }

    &:after {
        left: -10px;
        top: auto;
        bottom: 0;
        width: 462px;
        height: 254px;
        background: url(data:image/svg+xml;base64,) center center no-repeat;
        background-size: contain;

        @include break(large1750) {
            width: 380px;
            height: 200px;
        }

        @include break(large1650) {
            width: 295px;
            height: 160px;
        }

        @include break(large1280) {
            width: 230px;
            height: 120px;
        }

        @include break(tablet) {
            width: 190px;
            height: 95px;
        }

        @include break(s-small) {
            width: 350px;
            height: 190px;
        }

        @include break(x-small) {
            width: 372px;
            height: 210px;
            background: url(data:image/svg+xml;base64,) center center no-repeat;
            background-size: contain;
        }

        @include break(x-small) {
            width: 320px;
            height: 180px;
        }
    }

    &__container {
    }

    &__wrapper {
        display: flex;
        flex-direction: column;
        align-items: center;
    }

    &__title,
    &__desc {
        text-align: center;
        max-width: 1300px;
        width: 100%;

        @include break(large1750) {
            max-width: 1200px;
        }

        @include break(large1470) {
            max-width: 890px;
        }

        @include break(desktop) {
            max-width: 700px;
        }

        @include break(medium) {
            max-width: 600px;
        }

        @include break(medium850) {
            max-width: 500px;
        }

        @include break(ss-small) {
            max-width: 450px;
        }

        @include break(x-small) {
            max-width: 296px;
        }
    }

    &__title {
        margin-bottom: 8px;
        color: #3B37E6;

        @include break(x-small) {
            margin-bottom: 0;
            max-width: 250px;
        }
    }

    &__desc {
        margin-bottom: 81px;
        color: #000;
        text-align: center;
        font-size: 22px;
        font-weight: 400;
        line-height: 1.44;

        @include break(large1470) {
            font-size: 16px;
        }

        @include break(desktop) {
            margin-bottom: 60px;
        }

        @include break(medium) {
            margin-bottom: 45px;
        }

        @include break(small) {
            margin-bottom: 35px;
        }

        @include break(ss-small) {
            margin-bottom: 25px;
        }

        @include break(x-small) {
            font-size: 16px;
            margin-bottom: 13px;
        }
    }

    &__cards {
        max-width: 1050px;
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 44px 144px;
        justify-content: center;

        @include break(large1370) {
            gap: 44px 80px;
            max-width: 950px;
        }

        @include break(tablet) {
            gap: 30px 50px;
            max-width: 940px;
        }

        @include break(medium850) {
            grid-template-columns: repeat(2, 1fr);
            gap: 30px 85px;
        }

        @include break(s-small) {
            gap: 30px 35px;
        }

        @include break(x-small) {
            grid-template-columns: repeat(1, 1fr);
            gap: 13px;
        }
    }

    &__card {

        @include break(x-small) {
            max-width: 255px;
            margin-left: auto;
            margin-right: auto;
        }
    }

    &__card-wrapper {
        display: flex;
        flex-direction: column;
        gap: 16px;
    }

    &__card-icon {
    }

    &__card-iimg {
    }

    &__card-icon,
    &__card-title,
    &__card-text {
        text-align: center;
    }

    &__card-title {
        color: #3A3BDA;
    }

    &__card-text {
        color: #16213D;
        font-weight: 400;
        line-height: 1.27;
    }
}
