.square-images {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__title {
        text-align    : center;
        margin-bottom : 40px;
        @include break(medium) {
            margin-bottom : 29px;
        }
        @include break(x-small) {
            margin-bottom : 18px;
        }
    }
    &__wrapper {
        position: relative;
        &.animate {
            @media screen and (min-width : 571px) {
                .square-blocks__item.animation-item {
                    opacity   : 1;
                    transform : translate(0, 0);
                }
            }
        }
    }
    &.slider-view {
        .container {
            @include break(ss-small) {
                padding-left: 0;
                padding-right: 0;
            }
        }
        .section-wrapper {
            @include break(ss-small) {
                border-radius: 0;
                padding: 32px 16px;
            }
        }
    }
    .section-wrapper {
        border-radius: 40px;
        padding: 64px 64px 32px 64px;

        &.blue {
            background-color : rgba(59, 55, 230, 0.1);
        }

        &.purple {
            background-color: rgba(248, 243, 255, 0.80);
        }
        &.light-blue {
            background-color: rgba(85, 187, 249, 0.1);
        }
        &.apricot {
            background-color: rgba(255, 115, 105, 0.1);
        }
    }

    .square-blocks {
        display               : grid;
        grid-template-columns : repeat(4, 1fr);
        row-gap               : 30px;
        column-gap            : 20px;
        position              : relative;


        @include break(desktop) {
            row-gap    : 25px;
            column-gap : 14px;
        }
        @include break(tablet) {
            grid-template-columns : repeat(3, 1fr);
        }

        @include break(ss-small) {
            grid-template-columns : repeat(2, 1fr);
        }
        @include break(s-small) {
            grid-template-columns : 1fr;
            row-gap               : 34px;
        }

        &__item {
            border-radius: 35px;
            border: 1px solid $purple;
            padding: 24px;
            display: flex;
            justify-content: space-between;
            flex-direction: column;

            &.blue {
                border-color : $blue;
                background-color : $light_blue_tint;
            }

            &.purple {
                border-color : $purple;
                background-color: $purple_tint;
            }
            &.light-blue {
                background-color : #c0e5fc;
                border-color : $light_blue;
            }
            &.apricot {
                border: 1px solid $apricot;
                background-color: $coral_tint;
            }

            @media screen and (min-width : 571px) {
                &:not(.swiper-slide) {
                    opacity      : 0;
                    transition   : opacity .2s cubic-bezier(0.165, 0.84, 0.44, 1);
                    width        : auto !important;
                    margin-left  : 0 !important;
                    margin-right : 0 !important;

                    &.animation-item {
                        transform  : translate(0, 60px);
                        transition : opacity .2s, transform .8s cubic-bezier(0.165, 0.84, 0.44, 1);
                    }
                    @for $i from 1 through 3 {
                        &:nth-child(#{$i}) {
                            transition-delay : #{$i * 0.2}s;
                        }
                    }
                }
                &.hide {
                    display : none;
                }
                &.show {
                    opacity : 1;
                }
            }
        }
        &__item-top {
            flex: 1;
            display: flex;
            flex-direction: column;
        }
        &__banner {
            position: relative;

            &-link {
                display: block;
                position: absolute;
                width: 100%;
                height: 100%;

                &:hover {
                    .square-blocks__play-btn {
                        circle {
                            fill : $blue;
                        }
                        path {
                            fill : $royal_blue;
                        }
                    }
                }
            }
        }
        &__image {
            img {
                width: 100%;
                height : 163px;
                object-fit: cover;
                border-radius: 24px;

                @include break(s-small) {
                    height : 183px;
                }
            }
        }
        &__title {
            color: $dark;
            font-size: 22px;
            font-weight: 600;
            line-height: 28px;
            text-align: center;
        }
        &__title-area {
            margin: 20px 0 0;
            height: calc(100% - 163px);
            display: flex;
            align-items: center;
            justify-content: center;
            flex-direction: column;

            @include break(s-small) {
                height: calc(100% - 183px);
            }
        }
        &__button {
            @extend .styled-btn;
        }
        &__button-wrapper {
            text-align: center;
            margin-top: 16px;

            &.js-load-industries {
                margin-top: 60px;

                @include break(medium) {
                    margin-top: 40px;
                }
            }
        }
        &__play-btn {
            position : absolute;
            top : 50%;
            left : 50%;
            transform : translate(-50%, -50%);
            width : 90px;
            height : 90px;

            circle {
                transition : all .4s ease-in-out;
            }
            path {
                transition : all .5s ease-in-out;
            }

            &:hover {
                circle {
                    fill : $blue;
                }
                path {
                    fill : $royal_blue;
                }
            }
        }
    }
    .js-industries-slider-rounded {
        .swiper-slide {
            opacity : 0.6;

            &.swiper-slide-visible {
                opacity : 1;
            }
        }
    }
    .swiper-button-prev,
    .swiper-button-next {
        width         : 59px;
        height        : 59px;
        border        : 1px solid $blue;
        border-radius : 50%;
        margin-top    : 0;
        top           : 50%;
        transform     : translateY(-50%);
        //opacity: 0.3;
        transition    : opacity .3s linear;

        &.blue {
            border-color : $blue;

            svg {
                path {
                    fill: $blue
                }
            }
        }

        &.purple {
            border-color : $purple;

            svg {
                path {
                    fill: $purple
                }
            }
        }
        &.light-blue {
            border-color : $light_blue;

            svg {
                path {
                    fill: $light_blue
                }
            }
        }
        &.apricot {

            svg {
                path {
                    fill: $apricot
                }
            }
            border-color: $apricot;
        }

        svg {
            width  : 26px;
            height : 21px;

            @include break(large1370) {
                width  : 17px;
                height : 15px;
            }
        }

        @include break(large1370) {
            width  : 40px;
            height : 40px;
        }
        @include break(desktop) {
            display : none;
        }

        &:hover {
            opacity : 0.5;
        }

        &::after {
            display : none;
        }
    }

    .swiper-button-prev {
        left  : 0;
        right : unset;
    }

    .swiper-button-next {
        right : 0;
        left  : unset;
    }
    .swiper-wrapper {
        align-items: stretch;
        margin-bottom: 43px;
    }
    &.dash-bullets {
        .swiper-pagination {
            .swiper-pagination-bullet {
                width: 36px;
                height: 10px;
                border-radius: 10px;
            }
        }
    }
    .swiper-pagination {
        &.blue {
            .swiper-pagination-bullet {
                border-color : $blue;

                &:hover,
                &.swiper-pagination-bullet-active {
                    background-color : $blue;
                }
            }
        }

        &.purple {
            .swiper-pagination-bullet {
                border-color : $purple;

                &:hover,
                &.swiper-pagination-bullet-active {
                    background-color : $purple;
                }
            }
        }
        &.light-blue {
            .swiper-pagination-bullet {
                border-color : $light_blue;

                &:hover,
                &.swiper-pagination-bullet-active {
                    background-color : $light_blue;
                }
            }
        }
        &.apricot {
            .swiper-pagination-bullet {
                border-color: $apricot;

                &:hover,
                &.swiper-pagination-bullet-active {
                    background-color : $apricot;
                }
            }
        }
    }
}