.side-image-content {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__container {
        &.js-animate-parent {
            &.animate {
                .js-animate-element {
                    opacity   : 1;
                    transform : translate3d(0, 0, 0);
                }
            }
        }

        .js-animate-element {
            transition : opacity .4s, transform .8s cubic-bezier(0.165, 0.84, 0.44, 1);
            opacity    : 0;
            transform  : translate3d(0, 50%, 0);
        }
    }

    &__wrapper {
        max-width             : 1200px;
        margin-left           : auto;
        margin-right          : auto;
        display               : grid;
        grid-template-columns : 1fr 590px;
        column-gap            : 20px;
        row-gap               : 20px;
        @include break(desktop) {
            grid-template-columns :1fr 450px;
        }
        @include break(medium) {
            grid-template-columns :1fr 350px;
        }
        @include break(small) {
            grid-template-columns :1fr 295px;
        }
        @include break(s-small) {
            grid-template-columns :1fr;
            gap: 27px;
        }

        &.reverse {
            grid-template-columns :590px 1fr;
            @include break(desktop) {
                grid-template-columns :450px 1fr;
            }
            @include break(medium) {
                grid-template-columns :350px 1fr;
            }
            @include break(small) {
                grid-template-columns :295px 1fr;
            }
            @include break(s-small) {
                grid-template-columns :1fr;
            }
        }

        &-resources {
            grid-template-columns : 1fr 484px;
            column-gap            : 45px;
            @include break(medium) {
                grid-template-columns :1fr 400px;
            }
            @include break(medium850) {
                grid-template-columns :1fr 311px;
            }
            @include break(ss-small) {
                grid-template-columns :1fr 250px;
            }
            @include break(s-small) {
                grid-template-columns :1fr;
            }

            &.reverse {
                grid-template-columns :484px 1fr;
                @include break(medium) {
                    grid-template-columns :400px 1fr;
                }
                @include break(medium850) {
                    grid-template-columns :311px 1fr;
                }
                @include break(ss-small) {
                    grid-template-columns :250px 1fr;
                }
                @include break(s-small) {
                    grid-template-columns :1fr;
                }
            }
        }
    }

    &__content-wrapper {
        align-self : center;

        &-resources {
            align-self : auto;
        }

        @include break(s-small) {
            order : 2;
        }

        &.reverse {
            order : 2;

            .side-image-content__content {
                @include break(medium) {
                    // padding-left: 40px;
                    // padding-right: 0;
                    // @include break(ss-small){
                    //   padding-left: 0;
                    //   padding: 0;
                    // }
                    @include break(s-small) {
                        // padding-left: 6px;
                        // padding-right: 6px;
                        text-align : center;
                    }
                }
            }

            .side-image-content__content-resources {
                padding : 0;
            }
        }
    }

    &__content {
        @include break(s-small) {
            text-align : center;
        }

        &-resources {
            padding   : 0;
            max-width : 590px;

            &.reverse {
                margin-left  : auto;
                padding-left : 0;
            }

            .side-image-content__text,
            .side-image-content__title {
                max-width : none;
                @include break(x-small) {
                    text-align : initial;
                }
            }
        }
    }

    &__title.h2-title {
        font-size     : 40px;
        line-height   : 44px;
        font-family   : $main_font;
        margin-bottom : 26px;
        @include break(medium) {
            font-size     : 24px;
            line-height   : 29px;
            max-width     : 340px;
            margin-bottom : 22px;
        }
        @include break(s-small) {
            margin-left   : auto;
            margin-right  : auto;
            margin-bottom : 20px;

        }
        @include break(x-small) {
            // max-width: 235px;
            max-width   : none;
            font-family : $main_font;
            font-weight : 300;
            font-size   : 20px;
            line-height : 23px;
        }
    }

    &__text {
        @extend .a-tag;

        p {
            &:not(:last-child) {
                margin-bottom : 28px;
                @include break(medium) {
                    margin-bottom : 20px;
                }
            }
        }

        p, li {
            font-size   : 16px;
            line-height : 24px;
        }

        ol {
            list-style : decimal;
        }

        ul {
            list-style : disc;
        }

        ol,
        ul {
            margin-left : 18px;

            &:not(:first-child) {
                margin-top : 18px;
            }

            &:not(:last-child) {
                margin-bottom : 18px;
            }
        }

        li {
            font-family : $second_font;
            font-weight : 400;
            font-size   : 16px;
            line-height : 24px;
            padding     : 0;
            list-style  : inherit;

            &:not(:last-child) {
                margin-bottom : 8px;
            }

            &::before {
                display : none;
            }

            line-height : 20px;
        }

        h2, h3, h4, h5, h6 {
            font-size   : 22px;
            line-height : 28px;

            &:not(:last-child) {
                margin-bottom : 8px;
            }

            @include break(desktop) {
                font-size : 18px;
            }
        }

        &-resources {
            p, li {
                line-height : 24px;
                font-size   : 16px;
            }

            li {
                list-style : inherit;
            }

            p {
                &:not(:last-child) {
                    margin-bottom : 22px;
                    @include break(medium) {
                        margin-bottom : 20px;
                    }
                }
            }

            h2, h3, h4, h5, h6 {
                font-size   : 18px;
                line-height : 28px;

                &:not(:last-child) {
                    margin-bottom : 8px;
                }

                @include break(desktop) {
                    font-size   : 15px;
                    line-height : 20px;
                }
            }
        }
    }

    &__button-wrapper {
        margin-top : 26px;
        @include break(medium850) {
            margin-top : 32px;
        }
        @include break(x-small) {
            margin-top : 28px;
        }
    }

    &__button {
        @extend .blue-btn;
    }

    &__media {
        align-self      : center;
        display         : flex;
        justify-content : flex-end;
        align-items     : center;

        &-resources {
            align-self  : auto;
            align-items : flex-start;
        }

        @include break(s-small) {
            order : 1;
        }

        &.reverse {
            order           : 1;
            justify-content : flex-start;
        }
    }

    &__media-wrapper {
        // padding: 40px 35px;
        // height: 412px;
        padding         : 0;
        width           : 100%;
        display         : flex;
        align-items     : center;
        justify-content : flex-end;
        max-width       : 486px;

        &.reverse {
            justify-content : flex-start;
            @include break(s-small) {
                justify-content : center;
            }
        }

        @include break(medium) {
            padding : 0;
            height  : auto;
        }
        @include break(s-small) {
            //padding: 22px 21px;
            max-width       : 400px;
            margin-left     : auto;
            margin-right    : auto;
            justify-content : center;
        }

        a {
            display : block;
        }

        img, svg {
            max-width  : 100%;
            max-height : 400px;
            width      : auto;
            height     : auto;
            object-fit : contain;
            display    : block;
        }

        &-resources {
            padding   : 0;
            height    : auto;
            position  : relative;
            max-width : none;

            img, svg {
                display       : block;
                width         : 100%;
                height        : auto;
                border-radius : 20px;
                @include break(medium) {
                    border-radius : 12px;
                }
                @include break(x-small) {
                    border-radius : 15px;
                }
            }

            &.bottom {
                .mask,
                .figure {
                    background-position : bottom left;
                    left                : 0;
                    bottom              : 0;
                }
            }

            &.top {
                .mask,
                .figure {
                    background-position : top left;
                    top                 : 0;
                    left                : 0;
                }
            }
        }

        &.mask {
            //padding: 35px 55px 24px 50px;
            position : relative;

            a {
                width  : 100%;
                height : 100%;
            }

            @include break(desktop) {
