                height : 230px;
            }

            img {
                object-fit    : cover;
                width         : 100%;
                height        : 100%;
                border-radius : 20px;
                display       : block;
                @include break(medium) {
                    border-radius : 12px;
                }
                @include break(x-small) {
                    border-radius : 15px;
                }
            }
        }

