.side-content-banner{
    padding-top: 64px;
    padding-bottom: 64px;
    background-color: #F8FBFF;
    margin-bottom:  $desktop_margin;
    @include break(medium){
        padding-top: 30px;
        padding-bottom: 24px;
        margin-bottom: $mobile_margin;
    }
    @include break(s-small){
        padding-bottom: 40px;
    }
    &.has-navigation{
        padding-top: 24px;
        @include break(medium){
            padding-top: 16px;
        }
    }
    .breadcrumbs,
    .return-back-link{
        margin-bottom: 32px;
        @include break(medium){
            margin-bottom: 24px;
        }
    }
    .section-wrapper{
        max-width: 1280px;
        padding-left: 40px;
        @include break(large1370){
            padding-left: 0;
            max-width: 1200px;
        }
    }
    &__container{
        @include break(medium850){
            padding-right: 30px;
        }
        @include break(ss-small){
            padding-right: 16px;
        }
    }
    &__wrapper{
        display: grid;
        grid-template-columns: 1fr 520px;
        column-gap: 26px;
        row-gap: 24px;
        @include break(desktop){
            column-gap: 20px;
            grid-template-columns: 1fr 400px;
        }
        @include break(medium850){
            grid-template-columns: 1fr 345px;
        }
        @include break(ss-small){
            grid-template-columns: repeat(2, 1fr)
        }
        @include break(s-small){
            grid-template-columns: 1fr;
        }
    }
    &__content-wrapper{
        align-self:center;
        @include break(s-small){
            text-align: center;
        }
    }
    &__subtitle{
        color: $blue;
        margin-bottom: 16px;
        @include break(tablet){
            font-size: 24px;
            line-height: 29px;
            margin-bottom: 11px;
        }
        @include break(x-small){
            font-size: 18px;
            line-height: 22px;
            margin-bottom: 16px;
        }
    }
    &__title{
        margin-bottom: 16px;
        @include break(s-small){
            margin-top: 16px;
        }
        @include break(x-small){
            font-size: 32px;
            line-height: 34px;
            margin-left: auto;
            margin-right: auto;
            margin-bottom: 10px;
        }
    }
    &__subtitle-bottom{
        margin-top: 16px;
        margin-bottom: 16px;
        font-size: 22px;
        line-height: 28px;
        font-family: $third_font;
        font-weight: 600;
        @include break(medium){
            font-size: 15px;
            line-height: 24px;
            font-family: $main_font;
            font-weight: 300;
        }
        @include break(s-small){
            margin-top: 10px;
            margin-bottom: 10px;
        }
    }
    &__text{
        margin-top: 10px;
        max-width: 688px;
        @include break(medium){
            font-size: 15px;
            line-height: 22px;
        }
        p{
            &:not(:last-child){
                margin-bottom: 8px;
                @include break(medium){
                    margin-bottom: 16px;
                }
                @include break(s-small){
                    margin-bottom: 10px;
                }
            }
        }
        p, li{
            font-size: 16px;
            line-height: 24px;
        }
        li{
            padding: 0;
            font-family: $second_font;
            font-weight: 300;
            list-style: inherit;
            &:not(:last-child){
                margin-bottom: 4px;
            }
            &::before{
                display: none;
            }
        }
        ol{
            list-style: decimal;
        }
        ul{
            list-style: disc;
        }
        ol,
        ul{
            margin-left: 18px;
            &:not(:first-child){
                margin-top: 10px;
            }
            &:not(:last-child){
                margin-bottom: 10px;
            }
        }
        h2,h3,h4,h5,h6{
            font-size: 18px;
            line-height: 28px;
            &:not(:last-child){
                margin-bottom: 8px;
                @include break(medium){
                    margin-bottom: 16px;
                }
                @include break(s-small){
                    margin-bottom: 10px;
                }
            }
            @include break(medium){
                font-size: 15px;
            }
        }
    }
    &__media{
        align-self:center;
        display: flex;
        justify-content: flex-end;
        img, svg{
            display: block;
            height: auto;
            width: 100%;
            max-width: 100%;
            max-height: 100%;
        }
    }
}