.case-study-section{
    margin-top: $desktop_margin;
    margin-bottom:  $desktop_margin;
    @include break(medium){
        margin-top: $mobile_margin;
        margin-bottom: $mobile_margin;
    }
    &__title{
        text-align: center;
        margin-bottom: 32px;
        @include break(medium){
            font-size: 22px;
            line-height: 28px;
        }
    }
    &__media{
        border-radius: 47px;
        border: 1px solid $blue;
        background-color: $light_blue_tint;
        padding: 31px;
        @include break(medium){
            border-radius: 20px;
        }
        @include break(s-small){
            padding: 15px;
        }
    }
    &__media-wrapper{
        position: relative;
        border-radius: 38px;
        overflow: hidden;
        @include break(medium){
            border-radius: 10px;
        }
    }
    &__image-wrapper{
        @include break(medium){
            height: 400px;
        }
        @include break(s-small){
            height: auto;
        }
    }
    &__image{
        display: block;
        width: 100%;
        height: auto;
        object-fit: cover;
        @include break(medium){
            height: 100%;
        }
        @include break(s-small){
            height: auto;
        }
    }
    &__iframe-wrapper,
    &__play-btn{
        position: absolute;
        left: 0;
        top: 0;
        width: 100%;
        height: 100%;
    }
    &__iframe-wrapper{
        z-index:-1;
        &.active{
            z-index: 20;
        }
        iframe{
            width: 100%;
            height: 100%;
            object-fit: cover;
        }
    }
    &__play-btn{
        cursor: pointer;
        background-color: rgba($color: #252F59, $alpha: 0.6);
        border: none;
        display: flex;
        justify-content: center;
        align-items: center;
        z-index: 10;
        &:hover{
            path{
                opacity: 0.7;
            }
        }
        svg{
            pointer-events: none;
            width: 118px;
            height: 120px;
            @include break(s-small){
                width: 71px;
                height: 72px;
            }
            path{
                opacity: 0.5;
                transition: opacity 0.3s linear;
            }
        }
    }
}