.see-in-action-v1 {
    .container {
        display: grid;
        grid-template-columns: 1fr 626px;

        @include break(large1370) {
            grid-template-columns: 1fr 1fr;
        }
        @include break(tablet) {
            grid-template-columns: 1fr;
            height: auto;
        }
        @include break(small) {
            padding: 0;
        }
    }
    &__wrapper {
        padding: 52px 96px 82px 0;
        position: relative;


        @include break(tablet) {
            padding: 52px 0 77px;
        }
        @include break(ss-small) {
            background: $light_blue_tint;
            display: none;
        }
        @include break(small) {
            padding: 0 16px 77px;
        }
    }
    &__content-wrapper {
        height: 100%;
        display: flex;
        flex-direction: column;
        justify-content: space-between;
    }
    &__animation-arrow {
        position: absolute;
        top: 45px;
        right: -50px;
        animation: move-arrow 3.5s infinite;

        svg {
            @include break(tablet) {
                width: 100%;
            }
        }
        @include break(tablet) {
            width: 110px;
            right: auto;
            left: 86px;
            top: auto;
            bottom: -56px;
        }
        &.dark {
            path {
                fill: $coral;
            }
        }
        &.blue {
            path {
                fill: $light_blue;
            }
        }
    }
    &__popup-link-container {
        position: relative;
    }
    &__link {
        position: absolute;
        top: 0;
        left: 0;
        width : 100%;
        height : 100%;
        z-index : 999;
    }
    &__title {
        font-size: 40px;
        line-height: 48px;
        color : $blue;
        margin: 82px 0 16px;

        @include break(tablet) {
            font-size: 32px;
            line-height: 40px;
            margin: 32px 0 16px;
        }
        @include break(ss-small) {
            text-align: center;
        }
    }
    &__subtitle {
        font-size: 22px;
        color : $dark;
        font-weight: 600;
        line-height: 28px;

        @include break(tablet) {
            font-size: 15px;
            line-height: 22px;
            font-family: $second_font;
        }
        @include break(ss-small) {
            text-align: center;
        }
    }
    &__content {
        margin-top: 16px;
        p {
            padding-bottom : 24px;
        }

        ul {
            padding-bottom : 24px;

            li {
                margin-bottom : 20px;
                font-family   : $second_font;
                line-height   : 24px;
                font-size     : 15px;
                display       : flex;
                gap           : 8px;
                align-items   : center;

                &:before {
                    content             : "";
                    width               : 24px;
                    min-width           : 24px;
                    height              : 24px;
                    background-repeat   : no-repeat;
                    background-position : center;
                    display             : inline-block;
                    vertical-align      : sub;
                }

                &:last-child {
                    margin-bottom: 0;
                }

                &:nth-child(3n + 1) {
                    &:before {
                        background-image : url("data:image/svg+xml;base64,");
                    }
                }

                &:nth-child(3n + 2) {
                    &:before {
                        background-image : url("data:image/svg+xml,%3Csvg width='24' height='24' viewBox='0 0 24 24' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cg clip-path='url(%23clip0_1129_1652)'%3E%3Cpath d='M7.91357 4.66776C10.1112 2.47008 13.6744 2.47009 15.872 4.66776L19.1175 7.91323C21.3152 10.1109 21.3152 13.674 19.1175 15.8717L15.872 19.1172C13.6744 21.3149 10.1112 21.3149 7.91357 19.1172L4.6681 15.8717C2.47042 13.674 2.47042 10.1109 4.6681 7.91323L7.91357 4.66776Z' fill='%23ECDEFF' stroke='%23A142FF'/%3E%3C/g%3E%3Cdefs%3E%3CclipPath id='clip0_1129_1652'%3E%3Crect width='24' height='24' fill='white'/%3E%3C/clipPath%3E%3C/defs%3E%3C/svg%3E%0A");
                    }
                }

                &:nth-child(3n + 3) {
                    &:before {
                        background-image : url("data:image/svg+xml,%3Csvg width='24' height='24' viewBox='0 0 24 24' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cg id='Frame 38486'%3E%3Cpath id='Polygon 3' d='M9.18937 2.88144C10.9305 1.87618 13.0757 1.87618 14.8169 2.88143L18.595 5.06272C20.3361 6.06797 21.4087 7.92576 21.4087 9.93627V14.2988C21.4087 16.3094 20.3361 18.1671 18.595 19.1724L14.8169 21.3537C13.0757 22.3589 10.9305 22.3589 9.18937 21.3537L5.41128 19.1724C3.67012 18.1671 2.59753 16.3094 2.59753 14.2988V9.93628C2.59753 7.92576 3.67012 6.06797 5.41127 5.06272L9.18937 2.88144Z' fill='%23D7F7FF' stroke='%235ED0F9'/%3E%3C/g%3E%3C/svg%3E%0A");
                    }
                }
            }
        }
        img {
            @include break(small) {
                width : 100%;
                height : auto;
            }
        }
    }
    &__download-area {
        margin: 20px 0;

        &-image {
            border-radius: 20px;
            width : 100%;
            height: auto;

            @include break(tablet) {
                border-radius: 12px;
            }
        }
    }
    &__media {
        overflow: hidden;
        border-radius: 16px;
        position: relative;
        margin-top: 56px;

        +.see-in-action-v1__content {
            margin-top: 30px;
        }
        @include break(small) {
            margin-top: 36px;
        }
    }
    &__image-wrapper {
        position: relative;
        isolation: isolate;

        &.video-preview {
            &::before{
                content: '';
                display: block;
                position: absolute;
                width: 100%;
                height: 100%;
                z-index: 10;
                background-color: rgba($color: #252F59, $alpha: 0.6);
                mix-blend-mode: multiply;
            }
        }
    }
    &__play-btn {
        position        : absolute;
        left            : 0;
        top             : 0;
        width           : 100%;
        height          : 100%;
        display         : flex;
        justify-content : center;
        align-items     : center;
        transition      : fill .5s linear;
        z-index : 5;

        svg {
            circle {
                transition : all .4s ease-in-out;
            }
            parth {
                transition : all .5s ease-in-out;
            }

            @include break(medium) {
                width  : 81px;
                height : 93px;
            }
        }
        &:hover {
            svg {

                circle {
                    fill : $blue;
                }

                path {
                    fill : $royal_blue;
                }
            }
        }
    }
    &__form {
        &-wrapper {
            padding: 135px 112px 52px;
            background-repeat: no-repeat;
            background-position: center;
            background-size: cover;
            justify-content: center;

            @include break(large1370) {
                padding: 52px 80px;
            }
            @include break(tablet) {
                padding: 52px 40px;
                justify-content: flex-start;
            }
            @include break(small) {
                padding: 56px 15px;
            }

            &.dark{
                background: $dark;
            }
            &.purple{
                background: $purple;
            }
            &.light-blue{
                background: $light_blue;
            }
            &.blue{
                background: $blue;
            }
        }
        &-title {
            color: $white;
            text-align: center;
            font-size: 22px;
            font-weight: 600;
            line-height: 28px;
            max-width: 386px;

            @include break(large1370) {
                max-width: none;
            }
        }
    }
    &__copyright-block {
        margin-top: 167px;

        @include break(tablet) {
            display: none;
        }
    }
    &__copyright {
        color: $dark;
        font-size: 11px;
        font-weight: 300;
        font-family: $third_font;
    }
    &__button {
        @extend .blue-btn;
    }

    .hbspt-form {
        margin-top: 32px;

        .hs-recaptcha {
            display : none !important;
        }

        .submitted-message {
            font-size   : 18px;
            line-height : 28px;
            padding     : 10px 0 20px;
            color       : $blue;
        }

        fieldset {
            display    : grid;
            column-gap : 16px;
            max-width  : 100% !important;

            &.form-columns-3 {
                grid-template-columns : repeat(3, 1fr);
                @include break(x-small) {
                    grid-template-columns : 1fr;
                }
            }

            &.form-columns-2 {
                grid-template-columns : repeat(2, 1fr);
                @include break(x-small) {
                    grid-template-columns : 1fr;
                }
            }

            &.form-columns-1 {
                .legal-consent-container {
                    .field.hs-form-field {
                        margin-bottom : 0;
                    }
                }
            }

            &.form-columns-0 {
                margin-bottom : 16px;
            }

        }


        .hs-form-field {
            margin-bottom : 16px;
        }

        .hs-dependent-field {
            .hs-form-field {
                &:not(:first-child) {
                    margin-top : 16px;
                }
            }
        }

        .hs-form-field {
            width : 100% !important;
            float : none !important;

            & > label {
                display : none !important;
            }

            &.hs-fieldtype-file {
                margin-bottom : 0;

                & > label {
                    display : block !important;

                    span {
                        position     : relative;
                        font-size    : 15px;
                        line-height  : 24px;
                        color        : $blue;
                        padding-left : 26px;
                        cursor       : pointer;

                        &::before {
                            content             : '';
                            display             : block;
                            background-image    : url("data:image/svg+xml,%3Csvg width='22' height='22' viewBox='0 0 22 22' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M7.5625 12.375L8.53187 13.3444L10.3125 11.5706V19.9375H11.6875V11.5706L13.4681 13.3444L14.4375 12.375L11 8.9375L7.5625 12.375Z' fill='%233B37E6'/%3E%3Cpath d='M16.1563 15.125H15.8125V13.75H16.1563C16.9768 13.7828 17.7767 13.4884 18.3801 12.9314C18.9835 12.3744 19.341 11.6005 19.3738 10.78C19.4066 9.9595 19.1121 9.15955 18.5551 8.55615C17.9982 7.95275 17.2243 7.59533 16.4038 7.56251H15.8125L15.7438 6.99876C15.5912 5.84132 15.0232 4.77878 14.1454 4.00909C13.2676 3.23939 12.14 2.81501 10.9725 2.81501C9.80508 2.81501 8.67743 3.23939 7.79965 4.00909C6.92187 4.77878 6.3538 5.84132 6.20128 6.99876L6.18753 7.56251H5.59628C4.77576 7.59533 4.00189 7.95275 3.44491 8.55615C2.88793 9.15955 2.59345 9.9595 2.62627 10.78C2.6591 11.6005 3.01652 12.3744 3.61992 12.9314C4.22332 13.4884 5.02326 13.7828 5.84378 13.75H6.18753V15.125H5.84378C4.7413 15.118 3.68033 14.7037 2.86483 13.9618C2.04933 13.2199 1.53687 12.2027 1.42599 11.1058C1.31511 10.0089 1.61362 8.90972 2.26414 8.0196C2.91465 7.12948 3.87126 6.51124 4.95002 6.28376C5.24682 4.89949 6.00935 3.65887 7.11037 2.76889C8.21138 1.87892 9.5843 1.39343 11 1.39343C12.4158 1.39343 13.7887 1.87892 14.8897 2.76889C15.9907 3.65887 16.7532 4.89949 17.05 6.28376C18.1288 6.51124 19.0854 7.12948 19.7359 8.0196C20.3864 8.90972 20.6849 10.0089 20.5741 11.1058C20.4632 12.2027 19.9507 13.2199 19.1352 13.9618C18.3197 14.7037 17.2587 15.118 16.1563 15.125Z' fill='%233B37E6'/%3E%3C/svg%3E");
                            width               : 22px;
                            height              : 22px;
                            background-position : center;
                            background-repeat   : no-repeat;
                            position            : absolute;
                            left                : 0;
                        }
                    }
                }

                input[type="file"] {
                    cursor       : pointer;
                    padding-left : 26px;

                    &::-webkit-file-upload-button,
                    &::file-selector-button {
                        display : none;
                    }
                }
            }

            .hs-error-msgs {
                margin-top : 5px;
            }

            input[type="text"],
            input[type="email"],
            input[type="tel"],
            textarea {
                height           : 48px;
                width            : 100% !important;
                padding          : 10px 16px;
                font-size        : 13px;
                line-height      : 16px;
                color            : $dark;
                background-color : $white;
                border           : 1px solid rgba(22, 33, 61, 0.1);
                border-radius    : 10px;

                &.error {
                    border-color : $red;
                }

                &::placeholder {
                    color : rgba(22, 33, 61, 0.4);
                }
            }

            textarea {
                height: 100px;
            }

            select {
                height              : 48px;
                width               : 100%!important;
                padding             : 10px 35px 10px 16px;
                font-size           : 13px;
                line-height         : 16px;
                color               : $dark;
                background-color    : $white;
                border              : 1px solid rgba(22, 33, 61, 0.1);
                border-radius       : 10px;
                -moz-appearance     : none; /* Firefox */
                -webkit-appearance  : none; /* Safari and Chrome */
                appearance          : none;
                background-image    : url("data:image/svg+xml,%3Csvg width='14' height='8' viewBox='0 0 14 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M13 1L7 7L1 0.999999' stroke='%2316213D'/%3E%3C/svg%3E%0A");
                background-position : center right 19px;
                background-repeat   : no-repeat;

                &.error {
                    border-color : $red;
                }

                &::placeholder {
                    color : rgba(22, 33, 61, 0.4);
                }

                &.is-placeholder {
                    color : rgba(22, 33, 61, 0.4);
                }
            }
        }

        .input {
            margin-left  : 0 !important;
            margin-right : 0 !important;
        }

        .inputs-list {
            .hs-form-booleancheckbox {
                &:not(:first-child) {
                    margin-bottom : 16px;
                }
            }

            .hs-form-booleancheckbox-display {
                input[type="checkbox"] {
                    display : none !important;

                    &:checked ~ span::before {
                        background-image : url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M2 0C1.46957 0 0.960859 0.210714 0.585786 0.585786C0.210714 0.960859 0 1.46957 0 2L0 14C0 14.5304 0.210714 15.0391 0.585786 15.4142C0.960859 15.7893 1.46957 16 2 16H14C14.5304 16 15.0391 15.7893 15.4142 15.4142C15.7893 15.0391 16 14.5304 16 14V2C16 1.46957 15.7893 0.960859 15.4142 0.585786C15.0391 0.210714 14.5304 0 14 0L2 0ZM12.03 4.97C12.1689 5.10875 12.2479 5.29644 12.2499 5.49275C12.252 5.68907 12.177 5.87837 12.041 6.02L8.049 11.01C7.98039 11.0839 7.89758 11.1432 7.80553 11.1844C7.71348 11.2255 7.61407 11.2477 7.51325 11.2496C7.41243 11.2514 7.31227 11.233 7.21876 11.1952C7.12524 11.1575 7.0403 11.1013 6.969 11.03L4.324 8.384C4.25031 8.31534 4.19121 8.23254 4.15022 8.14054C4.10923 8.04854 4.08718 7.94923 4.08541 7.84852C4.08363 7.74782 4.10216 7.64779 4.13988 7.5544C4.1776 7.46101 4.23374 7.37618 4.30496 7.30496C4.37618 7.23374 4.46101 7.1776 4.5544 7.13988C4.64779 7.10216 4.74782 7.08363 4.84852 7.08541C4.94923 7.08718 5.04854 7.10923 5.14054 7.15022C5.23254 7.19121 5.31534 7.25031 5.384 7.324L7.478 9.417L10.951 4.992C11.0195 4.91797 11.1022 4.85851 11.1942 4.81717C11.2861 4.77583 11.3855 4.75347 11.4863 4.75141C11.5871 4.74936 11.6873 4.76766 11.7809 4.80522C11.8745 4.84277 11.9596 4.89882 12.031 4.97H12.03Z' fill='%23ffffff'/%3E%3C/svg%3E%0A");
                    }
                }

                span {
                    padding-left : 24px;
                    margin       : 0;
                    position     : relative;
                    cursor       : pointer;
                    color : $white;
                    font-size: 13px;
                    line-height : 18px;

                    * {
                        font-size   : 13px;
                        line-height : 18px;
                    }

                    a {
                        font-weight : 600;

                        &:hover {
                            text-decoration : underline;
                        }
                    }

                    &::before {
                        content             : '';
                        display             : block;
                        width               : 16px;
                        height              : 16px;
                        position            : absolute;
                        left                : 0;
                        top                 : -3px;
                        background-image    : url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M14 1C14.2652 1 14.5196 1.10536 14.7071 1.29289C14.8946 1.48043 15 1.73478 15 2V14C15 14.2652 14.8946 14.5196 14.7071 14.7071C14.5196 14.8946 14.2652 15 14 15H2C1.73478 15 1.48043 14.8946 1.29289 14.7071C1.10536 14.5196 1 14.2652 1 14V2C1 1.73478 1.10536 1.48043 1.29289 1.29289C1.48043 1.10536 1.73478 1 2 1H14ZM2 0C1.46957 0 0.960859 0.210714 0.585786 0.585786C0.210714 0.960859 0 1.46957 0 2L0 14C0 14.5304 0.210714 15.0391 0.585786 15.4142C0.960859 15.7893 1.46957 16 2 16H14C14.5304 16 15.0391 15.7893 15.4142 15.4142C15.7893 15.0391 16 14.5304 16 14V2C16 1.46957 15.7893 0.960859 15.4142 0.585786C15.0391 0.210714 14.5304 0 14 0L2 0Z' fill='%23ffffff' fill-opacity='1'/%3E%3C/svg%3E%0A");
                        background-position : center;
                        background-repeat   : no-repeat;
                    }
                }
            }
        }

        .hs-richtext {
            * {
                font-size   : 13px;
                line-height : 18px;
                color : $white;
            }

            a {
                font-weight : 600;
                text-decoration : underline;
                &:hover {
                    text-decoration : none;
                }
            }
        }

        .hs-submit {
            margin-top : 24px;
            text-align : center;

            .actions {
                @include break(medium) {
                    text-align : center;
                }
            }
            input:is([type="submit"]),
            input[type="submit"] {
                @extend .white-border-btn;
                cursor : pointer;
                padding: 9px 29px;
                @include break(medium) {
                    font-size     : 15px;
                    line-height   : 24px;
                    padding       : 10px 15px;
                    border-radius : 15px;
                }
            }
        }

        .hs_error_rollup {
            .hs-error-msgs {
                .hs-main-font-element {
                    text-align  : center;
                    font-size   : 16px;
                    line-height : 24px;
                }
            }
        }

        .hs-error-msgs {
            .hs-main-font-element,
            .hs-error-msg {
                color       : $red;
                font-size   : 12px;
                line-height : 14px;
            }
        }
    }

    &__button-wrapper {
        margin-top: 16px;
        display: flex;
        gap: 15px;
        justify-content: center;
    }
    &__button {
        @extend .styled-btn;

        &.blue {
            border-color: $blue;
            background-color: $royal_blue;
            color: $blue;
        }
        &.apricot {
            border-color: $apricot;
            background-color: $coral_tint;
            color: $apricot;
        }
        &.purple {
            border-color: $purple;
            background-color: $purple_tint;
            color: $purple;
        }
        &.light-blue {
            border-color: $malibu;
            background-color: $blue_tint;
        }
    }
}

@keyframes move-arrow {
    0% {-webkit-transform: rotate(-5deg); opacity: 0;}
    60% { opacity: 1;}
    100% {-webkit-transform: rotate(10deg); opacity: 0;}
}

#demo {
    .section-wrapper.see-in-action-v1__wrapper {
        @include break(ss-small) {
            //display: none
        }
    }
}
