.specific-solutions {
    margin-top       : $desktop_margin;
    margin-bottom    : $desktop_margin;
    padding-top      : 100px;
    padding-bottom   : 100px;
    background-color : $dark;
    @include break(medium) {
        margin-top     : $mobile_margin;
        margin-bottom  : $mobile_margin;
        padding-top    : 50px;
        padding-bottom : 50px;
    }

    &__container {
        text-align    : center;
        padding-left  : 33px;
        padding-right : 33px;
        @include break(ss-small) {
            padding-left  : 10px;
            padding-right : 10px;
        }
    }

    &__wrapper {
        max-width : 1144px;
        margin    : 0 auto;
    }

    &__content {
        @include break(x-small) {
            padding-left  : 22px;
            padding-right : 22px;
        }
    }

    &__title {
        max-width : 590px;
        margin    : 0 auto;
        color     : $white;
        @include break(medium) {
            max-width : 310px;
        }
    }

    &__text {
        max-width    : 895px;
        margin-top   : 20px;
        margin-left  : auto;
        margin-right : auto;
        color        : $white;
        @include break(medium) {
            max-width : 555px;
        }
        @include break(x-small) {
            margin-top : 24px;
        }
    }

    &__grid {
        margin-top      : 57px;
        display         : flex;
        flex-wrap       : wrap;
        justify-content : flex-start;
        width           : 100%;
        @include break(medium) {
            margin-top : 51px;
        }

        &-item {
            box-sizing    : border-box;
            height        : 94px;
            margin-bottom : 15px;
            padding-left  : 7px;
            padding-right : 7px;
            width         : 100%;
            @include break(medium) {
                height        : 58px;
                margin-bottom : 9px;
                padding-left  : 4px;
                padding-right : 4px;
            }
            @include break(ss-small) {
                flex          : 1 0 auto;
                width         : auto;
                padding-left  : 6px;
                padding-right : 6px;
                margin-bottom : 12px;
                height        : 68px;
            }

            &.small {
                max-width : 12.5%;
                //flex: 0 0 143px;
                //max-width: 143px;
                // @media screen and (max-width:1224px) {
                //   max-width: 143px;
                //   flex: 1 0 auto;
                // }
                @include break(ss-small) {
                    max-width : 100%;
                    min-width : 40%;
                }
            }

            &.medium {
                max-width : 25%;
                //flex: 0 0 286px;
                // max-width: 286px;
                // @media screen and (max-width:1224px) {
                //   max-width: 286px;
                //   flex: 1 0 auto;
                // }
                @include break(ss-small) {
                    max-width : 100%;
                    min-width : 40%;
                }
            }

            &.large {
                max-width : 50%;
                //flex: 0 0 572px;
                // max-width: 572px;
                // @media screen and (max-width:1224px) {
                //   max-width: 572px;
                //   flex: 1 0 auto;
                // }
                @include break(ss-small) {
                    max-width : 100%;
                    min-width : 60%;
                }
            }

            &.empty_element {
                flex  : 1 1 auto;
                width : auto;
            }
        }

        &-block {
            color           : $white;
            justify-content : center;
            align-items     : center;
            text-align      : center;
            padding-left    : 20px;
            padding-right   : 20px;
            padding-top     : 5px;
            padding-bottom  : 5px;
            font-family     : $third_font;
            font-weight     : 600;
            font-size       : 22px;
            line-height     : 28px;
            border          : 1px solid;
            transition      : background-color .3s linear;
            border-radius   : 16px;
            width           : 100%;
            height          : 100%;
            display         : flex;
            @media screen and (max-width : 1224px) {
                padding-left  : 10px;
                padding-right : 10px;
            }
            @include break(medium) {
                font-size     : 14px;
                line-height   : 20px;
                border-radius : 10px;
            }
            @include break(ss-small) {
                line-height   : 15px;
                border-radius : 16px;
            }

            &.rounded {
                border-radius : 60px;
                @include break(medium) {
                    border-radius : 36px;
                }
                @include break(ss-small) {
                    border-radius : 50px;
                }
            }

            &.blue {
                background-color : #0E2260;
                border-color     : $blue;

                &:hover {
                    background-color : $blue;
                }
            }

            &.purple {
                background-color : rgba($color : $purple, $alpha : 0.2);
                border-color     : $purple;

                &:hover {
                    background-color : $purple;
                }
            }

            &.coral {
                background-color : rgba($color : $coral, $alpha : 0.2);
                border-color     : $coral;

                &:hover {
                    background-color : $coral;
                }
            }

            &.light-blue {
                background-color : rgba($color : $light_blue, $alpha : 0.2);
                border-color     : $light_blue;

                &:hover {
                    background-color : $light_blue;
                }
            }
        }
    }
}