.title-body-cta {
    padding-top: 64px;
    padding-bottom: 32px;

    @include break(large1370) {
        padding-top: 50px;
    }

    @include break(medium) {
        padding-top: 35px;
        padding-bottom: 25px;
    }

    @include break(x-small) {
        padding-top: 16px;
        padding-bottom: 12px;
        background-color: #FFF !important;
    }

    &__container {
        display: flex;
        justify-content: center;
    }

    &__wrapper {
        max-width: 1100px;
        display: flex;
        flex-direction: column;
        gap: 16px;

        @include break(medium) {
            gap: 10px;
        }
    }

    &__colored-title,
    &__title,
    &__text {
        text-align: center;
    }

    &__colored-title {
        color: #3B37E6;
        font-family : "Axiforma", sans-serif;
        font-size: 40px;
        font-style: normal;
        font-weight: 600;
        line-height: 1.2;

        @include break(medium) {
            font-size: 22px;
            margin-bottom : 6px;
        }
    }

    &__title {

    }

    &__text {
        text-align: center;
        max-width: 628px;
        margin-left: auto;
        margin-right: auto;
        font-family: "Open Sans", sans-serif;
        font-size: 18px;
        font-style: normal;
        font-weight: 400;
        line-height: 1.57;

        @include break(large1370) {
            font-size: 16px;
            max-width: 555px;
        }

        @include break(medium) {
            font-size: 15px;
            font-style: normal;
            font-weight: 300;
            line-height: 1.46;
            max-width: 495px;
        }
    }
}