.single-resources-banner {
    margin-top    : 7px;
    margin-bottom : 48px;
    @include break(medium) {
        margin-top    : 19px;
        margin-bottom : 36px;
    }
    @include break(s-small) {
        margin-top    : 0;
        margin-bottom : 0;
    }

    .js-single-banner-slider {
        .swiper-pagination {
            bottom : -16px;
        }
    }

    &__wrapper {
        display               : grid;
        grid-template-columns : 1fr 493px;
        column-gap            : 15px;
        row-gap               : 16px;
        @include break(desktop) {
            grid-template-columns : 1fr 400px;
        }
        @include break(medium850) {
            grid-template-columns : 1fr 279px;
        }
        @include break(ss-small) {
            grid-template-columns : 1fr 230px;
        }
        @include break(s-small) {
            grid-template-columns : 1fr;
            padding-bottom: 15px!important;
        }
    }

    &__content-wrapper {
        display          : flex;
        align-items      : flex-start;
        flex-direction   : column;
        justify-content  : center;
        padding          : 60px 51px;
        border-radius    : 50px;
        background-color : $dark;
        height           : 463px;
        position         : relative;

        @include break(medium) {
            border-radius   : 26px;
            padding         : 55px 24px;
            height          : 316px;
            justify-content : flex-start;
        }
        @include break(s-small) {
            height      : auto!important;
            padding     : 32px 18px 32px;
            text-align  : center;
            align-items : center;
            display: flex!important;
            justify-content : center;
        }
    }

    &__content {
        margin-top : -14px;
        @include break(s-small) {
            margin-top : 0;
        }
    }

    &__media-cat-wrapper {
        margin-bottom : 14px;
    }

    &__media-cat {
        padding       : 3px 15px;
        border-radius : 10px;
        display       : inline-block;
        font-size     : 13px;
        line-height   : 20px;
        @include break(medium) {
            padding       : 2px 11px;
            font-size     : 10px;
            line-height   : 16px;
            border-radius : 7px;
        }
    }

    &__title {
        font-size   : 40px;
        line-height : 48px;
        color       : $white;
        @include break(medium) {
            font-size   : 25px;
            line-height : 29px;
        }
    }

    &__button-wrapper {
        //margin-top: 30px;
        @include break(medium) {
            //margin-top: 14px;
        }
        @include break(s-small) {
            //margin-top: 29px;
        }
    }

    &__bottom {
        position        : absolute;
        left            : 51px;
        bottom          : 33px;
        width           : calc(100% - 102px);
        display         : flex;
        align-items     : center;
        justify-content : space-between;
        flex-wrap       : wrap;
        gap             : 32px;
        @include break(medium) {
            left   : 24px;
            bottom : 21px;
            width  : calc(100% - 48px);
        }
        @include break(s-small) {
            position       : initial;
            flex-direction : column;
            margin     : 32px auto 0;
        }
    }

    &__share {
        display     : flex;
        align-items : center;
        @include break(medium) {
        }
        @include break(s-small) {
        }
    }

    p.single-resources-banner__share-text,
    &__share-text {
        font-size     : 15px;
        line-height   : 24px;
        color         : $light_blue_tint;
        font-family   : $main_font;
        padding-right : 10px;
        margin-bottom : 0 !important;
    }

    &__share-wrapper {
        display     : flex;
        align-items : center;

        &:hover {
            .single-resources-banner__share-item {
                opacity : 0.5;

                &:hover {
                    transform : scale(1.3);
                    opacity   : 1;
                }
            }
        }
    }

    &__share-item {
        width               : 23px;
        height              : 23px;
        transition          : .3s linear;
        transition-property : transform opacity;

        &:not(:last-child) {
            margin-inline-end : 12px;
        }
    }

    &__media {
        position : relative;
    }

    &__image {
        position      : absolute;
        display       : block;
        width         : 100%;
        height        : 100%;
        top           : 0;
        left          : 0;
        border-radius : 50px;
        object-fit    : cover;
        @include break(medium) {
            border-radius : 26px;
        }
        @include break(s-small) {
            position : initial;
        }
    }

    +.side-image-content-general {
        @include break(s-small) {
            margin-top: 16px;
        }
    }
}