#wpadminbar {
    @media screen and (max-width : 600px) {
        margin-top: -46px;
    }
}

html {
    scroll-behavior: smooth;
}

body {
    width: 100%;
    position: relative;
    background: #ffffff;
    font-family: $main_font;
    font-weight: 300;

    @include break(large1470) {}

    @include break(desktop) {}

    @include break(medium850) {}

    &.overflow {
        overflow: hidden;

        .demo-sticky {
            visibility: hidden;
        }
    }

    &.filter-is-opened {
        position: relative;
        z-index: 1;
        overflow: hidden;
        height: 100vh;

        &:before {
            position: fixed;
            content: '';
            display: block;
            left: 0;
            top: 0;
            width: 100vw;
            height: 100vh;
            z-index: 10000;
            background: rgba(46, 46, 46, 0.40);
            transition: all .5s ease-out;
        }

        .all-partners-w-sidebar {
            &__filter-wrapper {
                transform: translateX(0);
            }
        }
    }

    #wrapper {
        padding-top: 86px;

        &.without-header {
            padding-top: 0;
        }

        @include break(ss-small) {
            padding-top: 50px;
        }
    }

    &.admin-bar {
        .site-header {
            // margin-top : 32px;
            // @media screen and (max-width : 782px) {
            // 	margin-top : 46px;
            // }

            &.sticky {
                @media screen and (max-width : 600px) {
                    margin-top: 0 !important;
                }

            }
        }

        .mobile-menu {
            margin-top: 32px;

            @media screen and (max-width : 782px) {
                margin-top: 46px;
            }

        }

        &.scroll {
            .mobile-menu {
                @media screen and (max-width : 600px) {
                    margin-top: 0 !important;
                }
            }
        }
    }

    * {
        font-family: $main_font;
        font-weight: 300;
        color: $dark;
        outline: none !important;
        box-sizing: border-box !important;
    }

    &.no-header {
        #wrapper {
            padding-top: 0 !important;
        }
    }

    &.static-header {
        .site-header {
            position: relative;
        }
    }

    &.static-header {
        #wrapper {
            padding-top: 0;
        }
    }

    &.sticky-badge {
        .badge-icon-wrapper {
            position: fixed;
        }
    }
}

