.swiper {
    &.swiper-fade {
        .swiper-slide {
            opacity: 0 !important;

            &-active {
                opacity: 1 !important;
            }
        }
    }

    .swiper-pagination {
        justify-content: center;
        position: relative;
        bottom: auto;
        justify-content: center;

        &-bullet {
            opacity: 1;
            width: 12px;
            height: 12px;
            border: 1px solid $blue;
            background-color: transparent;
            margin: 0 6px !important;
            transition: background-color .3s linear;

            @include break(medium) {
                width: 7px;
                height: 7px;
                margin: 0 3px !important;
            }

            @include break(ss-small) {
                width: 11px;
                height: 11px;
            }

            &:hover,
            &-active {
                background-color: $blue;
            }
        }

        &.apricot {
            .swiper-pagination-bullet {
                border-color: $apricot;

                &:hover {
                    background-color: $apricot;
                }

                &.swiper-pagination-bullet-active {
                    background-color: $apricot;
                }
            }

        }

        &.purple {
            .swiper-pagination-bullet {
                border-color: $purple;

                &:hover {
                    background-color: $purple;
                }

                &.swiper-pagination-bullet-active {
                    background-color: $purple;
                }
            }

        }

        &.light-blue {
            .swiper-pagination-bullet {
                border-color: $malibu;

                &:hover {
                    background-color: $malibu;
                }

                &.swiper-pagination-bullet-active {
                    background-color: $malibu;
                }
            }

        }
    }

    .swiper-button-prev,
    .swiper-button-next {
        width: 59px;
        height: 59px;
        border: 1px solid $blue;
        border-radius: 50%;
        margin-top: 0;
        top: 50%;
        transform: translateY(-50%);
        //opacity: 0.3;
        transition: opacity .3s linear;

        svg {
            width: 25px;
            height: 21px;

            @include break(large1370) {
                width: 17px;
                height: 15px;
            }
        }

        @include break(large1370) {
            width: 40px;
            height: 40px;
        }

        @include break(desktop) {
            display: none;
        }

        &:hover {
            opacity: 0.5;
        }

        &::after {
            display: none;
        }

        &.apricot {
            border: 1px solid $apricot;

            svg {
                path {
                    fill: $apricot;
                }
            }
        }

        &.purple {
            border: 1px solid $purple;

            svg {
                path {
                    fill: $purple;
                }
            }
        }

        &.light-blue {
            border: 1px solid $malibu;

            svg {
                path {
                    fill: $malibu;
                }
            }
        }
    }

    .swiper-button-prev {
        left: 0;
        right: unset;
    }

    .swiper-button-next {
        right: 0;
        left: unset;
    }
}

.dash-bullets {
