    align-items: center;
    margin-top: 18px;
    gap: 10px;

    @include break(s-small) {
        margin-top: 6px;
    }

    .prev,
    .next {
        font-size: 0;
        position: relative;
        z-index: 1;
        width: 28px;
        height: 28px;

        &:after {
            position: absolute;
            content: '';
            display: block;
            left: 0;
            top: 0;
            width: 100%;
            height: 100%;
            z-index: 1;
            background: url(data:image/svg+xml;base64,) center center no-repeat;
            background-size: contain;
        }
    }

    .prev {
        &:after {
            transform: rotate(-180deg);
        }
    }

    &__page {
        display: flex;
        justify-content: center;
        align-items: center;
        padding: 2px;
        width: 33px;
        height: 33px;
        color: $dark;
        text-align: center;
        font-family: "Axiforma", sans-serif;
        font-size: 15px;
        font-style: normal;
        font-weight: 400;
        letter-spacing: 0.1px;
        border-radius: 50%;
        overflow: hidden;
        transition: all .5s ease-out;

        &:hover {
            background-color: $blue;
            color: $white;
        }
    }


    &__current-page {
        pointer-events: none;
        background-color: $blue;
        color: $white;
    }

    &__page-dots {
        pointer-events: none;
        width: 33px;
        height: 33px;
        display: flex;
        align-items: center;
        justify-content: center;
    }
}

