.content-section {
    margin-top    : 56px;
    margin-bottom : 56px;
    @include break(medium) {
        margin-top    : 32px;
        margin-bottom : 32px;
    }
    @include break(s-small) {
        margin-top    : 24px;
        margin-bottom : 24px;
    }

    &__text {
        max-width : 997px;

        &.center {
            margin-left  : auto;
            margin-right : auto;
        }
    }
}