.site-header {
    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.07);
    background-color: $white;
    position: fixed;
    left: 0;
    top: 0;
    width: 100%;
    max-width: 100vw;
    transition: .3s linear;
    z-index: 9000;

    &.hide-header {
        .site-header__container {
            justify-content: center;
        }
    }

    &__inner {
        position: relative;
    }

    &__container {
        height: 88px;
        display: flex;
        align-items: center;
        justify-content: space-between;

        @include break(ss-small) {
            height: 50px;
            padding-top: 14px;
            padding-bottom: 14px;
        }
    }

    &__logo {
        display: flex;
        align-items: center;
        max-height: 40px;

        @include break(tablet) {
            width: 125px;
        }

        @include break(ss-small) {
            width: 85px;
        }

        img,
        svg {
            display: block;
            width: 100%;
            height: auto;
        }
    }

    &__side {
        display: flex;
        align-items: center;
    }

    &__nav {
        @include break(tablet) {
            display: none;
        }
    }

    &__menu {
        display: flex;
        align-items: center;

        .nav__link {
            cursor: pointer;
        }

        a {
            transition: color .3s linear;
        }

        &>.menu-item {
            &:not(:last-child) {
                margin-right: 36px;

                @include break(desktop) {
                    margin-right: 20px;
                }
            }

            &.menu-item-has-children {

                &>.nav__link,
                &>a {
                    padding-right: 20px;
                    position: relative;

                    &::after {
                        content: '';
                        display: block;
                        width: 11px;
                        height: 12px;
                        background-image: url("data:image/svg+xml,%3Csvg width='11' height='7' viewBox='0 0 11 7' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1L5.5 6L10 1' stroke='%2316213D' stroke-width='1.3' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E");
                        background-position: center;
                        background-repeat: no-repeat;
                        position: absolute;
                        right: 0;
                        top: 6px;
                        transition: 0.3s linear;
                        transition-property: transform, background-image;
                    }
                }

                &>.sub-menu-wrapper {
                    position: absolute;
                    visibility: hidden;
                    opacity: 0;
                    top: 59%;
                    left: 50%;
                    transform: translateX(-50%);
                    transition: 0.3s linear;
                    transition-property: opacity, visibility;
                    padding-top: 32px;
                }

                &:not(.mega-menu) .sub-menu {
                    padding: 10px 13px;

                    .menu-item {
                        padding-top: 6px;
                        padding-bottom: 6px;
                        position: relative;

                        &.current-menu-item {
                            .nav__link {
                                color: $blue;
                            }
                        }

                        &:hover {
                            a {
                                color: $blue;
                            }
                        }
                    }

                    .nav__link,
                    a {
                        display: block;
                        margin-left: auto;
                        margin-right: auto;
                        width: auto;
                        //max-width    : 160px;
                        // white-space: nowrap;
                        text-align: center;
                        font-size: 12px;
                        line-height: 18px;
                        transition: color 0.3s linear;
                    }
                }
            }

            &:hover {

                &>.nav__link,
                &>a {
                    color: $blue;

                    span {
                        color: $blue;
                    }

                    &::after {
                        background-image: url("data:image/svg+xml,%3Csvg width='11' height='7' viewBox='0 0 11 7' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1L5.5 6L10 1' stroke='%233B37E6' stroke-width='1.3' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E");
                        transform: rotate(-180deg);
                    }
                }

                &>.sub-menu-wrapper {
                    visibility: visible;
                    opacity: 1;
                    left: 0 !important;
                }
            }

            &>.nav__link,
            &>a {
                display: block;
                font-size: 15px;
                line-height: 24px;
            }

            &.parts-menu,
            &.mega-menu {
                &>.sub-menu-wrapper {
                    transform: translateX(0);
                    left: -150%;
                    width: 100%;
                    border-radius: 0 0 40px 40px;
                    //height: calc(100vh - 86px);
                    //overflow: auto;

                    &:after {
                        content: '';
                        display: block;
                        background-color: $white;
                        width: 100%;
                        height: calc(100% - 35px);
                        top: 35px;
                        left: 0;
                        position: absolute;
                        z-index: 1;
                        border-radius: 0 0 40px 40px;
                        box-shadow: 0 6px 28.6px 0 rgba(8, 7, 67, 0.11);
                    }

                    &:before {
                        content: '';
                        border-radius: 0 0 40px 40px;
                        background-color: #e3eeff;
                        display: block;
                        width: 100%;
                        left: 0;
                        bottom: 0;
                        height: calc(100% - 128px);
                        position: absolute;
                        z-index: 2;
                    }

                    &.erp {
                        &:before {
                            background-color: #e3eeff;
                        }
                    }

                    &.retail-management {
                        &:before {
                            background-color: #f9f5ff;
                        }
                    }

                    &.hospitality-management {
                        &:before {
                            background-color: #f3fdff;
                        }
                    }

                    &.school-management {
                        &:before {
                            background-color: #fff5f3;
                        }
                    }

                    &>.sub-menu {
                        position: relative;
                        isolation: isolate;
                        padding: 67px 40px 16px 40px;
                        max-width: 1440px;
                        margin: 0 auto;
                        z-index: 3;


                        &>.menu-item {
                            &:not(:last-child) {
                                padding-bottom: 6px;
                            }

                            &.menu-item-has-children:hover {
                                &>.sub-menu-wrapper {
                                    visibility: visible;
                                    opacity: 1;
                                }
                            }

                            &>.nav__link,
                            &>a {
                                display: flex;
                                justify-content: center;
                                align-items: center;
                                width: 100%;
                                height: 66px;
                                border-radius: 10px;
                                padding: 15px 95px;
                                text-align: center;

                                position: relative;
                                z-index: 10;
                                isolation: isolate;

                                span {
                                    font-size: 18px;
                                    line-height: 20px;
                                    letter-spacing: -0.03em;
                                    font-family: $third_font;
                                }
                            }

                            &.active {
                                &>.sub-menu-wrapper {
                                    opacity: 1;
                                    visibility: visible;
                                }
                            }

                            &>.sub-menu-wrapper {
                                visibility: hidden;
                                opacity: 0;
                                transition: 0.5s cubic-bezier(0, 0, 0.2, 1);
                                transition-property: visibility, opacity, transform;

                                &>.sub-menu {
                                    border-radius: 10px;
                                    height: 100%;
                                    display: grid;
                                    grid-template-columns: 1fr 1fr;
                                    column-gap: 64px;
                                    width: 100%;
                                    position: relative;

                                    &:before {
                                        content: '';
                                        position: absolute;
                                        background-color: $royal_blue;
                                        top: 50px;
                                        left: 50%;
                                        display: block;
                                        width: 1px;
                                        height: calc(100% - 64px);
                                    }

                                    &>.menu-item {
                                        &>a {
                                            padding-bottom: 6px;
                                            display: block;
                                            transition: color 0.3s linear;
                                            font-size: 14px;
                                            line-height: 16px;
                                            font-family: $third_font;
                                            font-weight: 600;
                                            color: $dark;

                                            span {
                                                line-height: 18px;
                                                font-size: 16px;
                                                font-weight: 600;
                                            }

                                            &[href^="#"] {
                                                pointer-events: none;
                                            }
                                        }

                                        &>.sub-menu-wrapper {
                                            padding-top: 10px;
                                        }

                                        .sub-menu {

                                            span.nav__link,
                                            a {
                                                font-size: 12px;
                                                line-height: 20px;
                                                color: #3C455A;
                                                transition: color 0.3s linear;
                                            }

                                            &>.menu-item-has-children {
                                                position: relative;


                                                .arrow {
                                                    display: block;
                                                    padding: 9px 7px;
                                                    background-image: url("data:image/svg+xml,%3Csvg width='8' height='5' viewBox='0 0 11 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1L5.5 6L10 1' stroke='%2316213D' stroke-width='1.3' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E");
                                                    background-position: center;
                                                    background-repeat: no-repeat;
                                                    position: absolute;
                                                    right: 12px;
                                                    top: 12px;
                                                    transition: 0.3s linear;
                                                    transition-property: transform, background-image;
                                                    cursor: pointer;
                                                }

                                                &.active {
                                                    .arrow {
                                                        transform: rotate(180deg);
                                                    }
                                                }

                                                .sub-menu {
                                                    padding-inline-start: 10px;
                                                    transition: max-height .3s linear;

                                                    a {
                                                        display: block;
                                                    }
                                                }
                                            }
                                        }

                                        &.two-columns {
                                            .sub-menu {
                                                display: inline-grid;
                                                grid-template-columns: repeat(2, auto);
                                                grid-template-rows: repeat(16, auto);
                                                grid-auto-flow: column;
                                            }
                                        }
                                    }

                                    .columns-menu {
                                        .sub-menu {
                                            display: grid;
                                            grid-template-columns: 1fr 1fr;
                                            grid-column-gap: 16px;
                                            grid-row-gap: 8px;
                                        }

                                        &.products {
                                            .sub-menu {
                                                grid-template-rows: 6fr;

                                                .sub-menu {
                                                    display: block;

                                                    .sub-menu {
                                                        .menu-item {
                                                            margin-bottom: 0 !important;
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }

                                    .one-column {
                                        .sub-menu {
                                            width: 50%;
                                            display: flex;
                                            flex-direction: column;
                                            gap: 8px;
                                        }
                                    }
                                }
                            }

