        }

        .item-content-area-button {
            margin-top: 16px;

            .btn {
                @extend .blue-btn;
                border-radius: 10px;
            }
        }

        &.erp {
            .banner {
                border-color: $blue;
                background-color: #bfd6fa;
            }

            .banner-description {
                color: $blue;
            }
        }

        &.hospitality-management {
            .banner {
                border-color: $light_blue;
                background-color: #e2f8fd;

                .btn {
                    background-color: $light_blue;
                }
            }

            .banner-description {
                color: $light_blue;
            }
        }

        &.retail-management {
            .banner {
                border-color: $purple;
                background-color: $purple_tint;

                .btn {
                    background-color: $purple;
                }
            }

            .banner-description {
                color: $purple;
            }
        }

        &.school-management {
            .banner {
                border-color: $apricot;

                .btn {
                    background-color: $apricot;
                }
            }

            .banner-description {
