    .tab-pane.active {
        display: block;
    }

    &.nl {
        .tab-header {
            width: calc((100% - 98px) / 2);

            &.hospitality-management {
                left: calc(50% + 10px);
            }
        }
    }

    &__actions {
        display: flex;
        align-items: center;
        margin-inline-start: 33px;

        .site-header__lang {
            margin-left: 10px;
        }
    }

    &__search {
        display: flex;
        flex-direction: row-reverse;
        align-items: center;

        &-icon {
            position: relative;
            z-index: 1;
            display: flex;
            cursor: pointer;

            svg {
                width: 32px;
                height: 32px;

                &.close {
                    display: none;
                }
            }

            &.active {
                svg {
                    &.open {
                        display: none;
                    }

                    &.close {
                        display: flex;
                    }
                }
            }
        }

        &-form {
            visibility: hidden;
            width: 0;
            opacity: 0;
            position: relative;
            right: -34px;
            transition: .2s;

            &.active {
                visibility: visible;
                opacity: 1;
                width: 300px;
            }

            .searchform {
                input {
                    padding: 6px;
                }

                [type=submit] {
                    right: 30px;
                    padding: 1px;
                    background: none;

                    svg path {
                        stroke: #000;
                    }
                }
            }
        }

        @include break(medium) {
            position: absolute;
            right: 75px;
            max-width: calc(100% - 50px);
        }

        @include break(ss-small) {
            right: 50px;
        }
    }

    &__lang {
        position: relative;
        margin-left: 33px;
        cursor: pointer;

        @include break(tablet) {
            display: none;
        }

        &:hover {
            .site-header__lang-code {
                color: $blue;
            }

            path {
                fill: $blue;
            }

            .wpml-ls {
                visibility: visible;
                opacity: 1;
            }
        }

        &-current {
            display: flex;
            align-items: center;
            font-size: 15px;
            line-height: 24px;
            transition: color .3s linear;

            path {
                transition: fill .3s linear;
            }
        }

        &-code {
            padding-left: 6px;
            text-transform: capitalize;
        }

        .wpml-ls {
            position: absolute;
            visibility: hidden;
            opacity: 0;
            display: block;
            top: 100%;
            left: 0;
            transition: 0.3s linear;
            transition-property: opacity, visibility;
            padding-top: 20px;

            ul {
                box-shadow: 0px 4px 24px rgba(0, 0, 0, 0.07);
                border-radius: 10px;
                background-color: $white;
                padding: 10px 13px;
                min-width: 102px;

                .wpml-ls-item {
                    padding-top: 6px;
                    padding-bottom: 6px;
                    position: relative;

                    &:not(:last-child) {
                        &::after {
                            content: '';
                            display: block;
                            width: 75px;
                            height: 1px;
                            position: absolute;
                            left: 50%;
                            bottom: 0;
                            transform: translateX(-50%);
                            background-color: $gret_blue;
                        }
                    }

                    &:hover {
                        a span {
                            color: $blue;
                        }
                    }
                }

                a {
                    padding: 0;
                    display: block;
                    margin-left: auto;
                    margin-right: auto;
                    white-space: nowrap;
                    text-align: center;
                    font-size: 12px;
                    line-height: 18px;
                    transition: color 0.3s linear;
                    border: none;

                    span {
                        display: block;
                    }
                }
            }
        }
    }

    &__button-wrapper {
        margin-left: 28px;

        @include break(desktop) {
            margin-left: 20px;
        }

        @include break(tablet) {
            display: none;
        }
    }

    &__button {
        display: inline-block;
        border: 1px solid $blue;
        padding: 7px 16px;
        font-size: 15px;
        line-height: 24px;
        color: $blue;
        background-color: $white;
        border-radius: 15px;
        transition: 0.3s linear;
        transition-property: color, background-color;

        &:hover {
            background-color: $blue;
            color: $white;
        }
    }

    &__mobile-menu-btn {
        display: none;
        padding: 0;
        border: none;
        width: 27px;
        height: 16px;
        background-color: transparent;
        position: relative;
        z-index: 9150;
        right: 0;
        -webkit-transition: .5s ease-in-out;
        -moz-transition: .5s ease-in-out;
        -o-transition: .5s ease-in-out;
        transition: .5s ease-in-out;
        cursor: pointer;

        @include break(tablet) {
            display: block;
        }

        &.open {
            transform: translate(18px, 0);

            @include break(ss-small) {
                transform: translate(-20px, 22px);
            }

            span:nth-child(1) {
                top: 8px;
                width: 0%;
                left: 50%;
            }

            span:nth-child(2) {
                -webkit-transform: rotate(45deg);
                -moz-transform: rotate(45deg);
                -o-transform: rotate(45deg);
                transform: rotate(45deg);
            }

            span:nth-child(3) {
                -webkit-transform: rotate(-45deg);
                -moz-transform: rotate(-45deg);
                -o-transform: rotate(-45deg);
                transform: rotate(-45deg);
            }

            span:nth-child(4) {
                top: 8px;
                width: 0%;
                left: 50%;
            }
        }

        span {
            pointer-events: none;
            display: block;
            position: absolute;
            height: 2px;
            width: 100%;
            background: $dark;
            border-radius: 10px;
            opacity: 1;
            left: 0;
            -webkit-transform: rotate(0deg);
            -moz-transform: rotate(0deg);
            -o-transform: rotate(0deg);
            transform: rotate(0deg);
            -webkit-transition: .25s ease-in-out;
            -moz-transition: .25s ease-in-out;
            -o-transition: .25s ease-in-out;
            transition: .25s ease-in-out;

            &:nth-child(1) {
                top: 0px;
            }

            &:nth-child(2),
            &:nth-child(3) {
                top: 7px;
            }

            &:nth-child(4) {
                top: 14px;
            }
        }
    }
}
