.search {
    &-wrapper {
        display: grid;
        grid-template-columns: 385px 1fr;
        column-gap: 50px;
        padding-top: 50px;
        margin-bottom: 80px;
    }

    &-sidebar {
        &__search-bar {
            margin-bottom: 40px;
            .blue-btn {
                background-color: #16213d;
            }
        }

        &__toggle {
            margin-bottom: 40px;
            &-btn {
                display: none;
            }
        }

        &__count {
            padding: 10px 20px;
        }
        &__order {
            padding: 10px 0 50px;
            label {
                margin-right: 5px;
                color: #9d9d9d;
                cursor: pointer;
            }
            input {
                display: none;
                &:checked {
                    & + span {
                        border-bottom: 1px solid #000;
                        color: #000;
                    }
                }
            }
            span {
                padding: 5px 10px;
                color: #9d9d9d;
                transition: .2s;
                &:hover {
                    color: #000;
                }
            }
        }

        &__active-filters {
            display: flex;
            flex-wrap: wrap;
            align-items: center;
            margin-bottom: 40px;
            .active-filters__count {
                margin-inline-end: 16px;
            }
            .active-filters__item {
                border: 1px solid;
                border-radius: 10px;
                padding: 5px 15px;
                font-size: 13px;
                line-height: 16px;
                margin-inline-end: 8px;
                margin-bottom: 4px;
                margin-top: 4px;
                text-align: center;
                border-color: #bae9fd;
                background-color: #d7f7ff;
                cursor: pointer;
                transition: .2s;
                .close {
                    margin-left: 8px;
                }

                &:hover {
                    border-color: #000;
                }
            }
        }

        &__wrapper {
            border: 1px solid $blue;
            background-color: $light_blue_tint;
            border-radius: 25px;
            transition: .3s linear;
            transition-property: max-height, background-color;
            padding: 3px 20px 28px;
        }

        &-heading{
            padding-top: 36px;
            padding-bottom: 20px;
            padding-inline-start: 0;
            font-size: 18px;
            font-weight: 600;
            line-height: 24px;
            position: relative;
            cursor: pointer;
            @include break(small){
                font-size: 12px;
                line-height: 18px;
            }
        }

        &-list {
            & + .search-sidebar-list{
                margin-top: 13px;
            }
        }

        &-item{
            display: block;
            label{
                display: block;
            }
            &:not(:last-child){
                margin-bottom: 13px;
            }
            input {
                &:disabled {
                    & + span {
                        color: #ccc;
                        b {
                            color: #ccc;
                        }
                    }
                }
            }
        }
        &-checkbox{
            display: none;
            &:checked ~ .search-sidebar-name::before{
                background-image: url("data:image/svg+xml,%3Csvg width='15' height='15' viewBox='0 0 13 13' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Crect x='0.25' y='0.25' width='12.5' height='12.5' rx='1.75' stroke='%233B37E6' stroke-width='0.5'/%3E%3Cpath d='M10.1854 4.68541L5.81412 9.05671L3.49586 6.73852' stroke='%233B37E6' stroke-width='1.40047' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
            }
        }
        &-name{
            display: block;
            font-size: 15px;
            line-height: 18px;
            padding-inline-start: 21px;
            position: relative;
            cursor: pointer;
            &::before{
                content: '';
                display: block;
                background-image: url("data:image/svg+xml,%3Csvg width='15' height='15' viewBox='0 0 13 13' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Crect x='0.25' y='0.25' width='12.5' height='12.5' rx='1.75' stroke='%2316213D' stroke-width='0.5'/%3E%3C/svg%3E");
                width: 16px;
                height: 16px;
                background-position: center;
                background-repeat: no-repeat;
                position: absolute;
                left: 0;
                top: 0;
            }

            b {
                font-weight: 400;
                color: #3a36e6;
            }
        }

        &__overlay {
            display: none;
        }
    }

    &-content {
        &__item {
            padding-bottom: 32px;
            a {
                transition: .2s;
                &:hover {
                    color: $black;
                    h3 {
                        color: $blue;
                    }
                }
            }
            &-title {
                font-size: 18px;
                line-height : 24px;
                padding-bottom: 10px;
                pointer-events: none;
            }

            &-tags {
                display: flex;
                flex-wrap: wrap;
                margin-bottom: 8px;
                .tag-item {
                    border: 1px solid;
                    border-radius: 10px;
                    padding: 5px 15px;
                    font-size: 13px;
                    line-height: 16px;
                    margin-right: 8px;
                    margin-bottom: 8px;
                    text-align: center;
                    border-color: #bae9fd;
                    background-color: #d7f7ff;
                    transition: .2s;
                }
            }
            &-text {
                padding-bottom: 10px;
            }
            &-url {
                color: #9d9d9d;
                font-weight: 400;
                line-height: 24px;
                font-size: 12px;
            }
        }
    }

    @include break(medium){
        &-wrapper {
            grid-template-columns: 1fr;
        }

        &-sidebar {
            position: fixed;
            left: -100%;
            top: 0;
            transition: .3s;
            z-index: 9100;
            height: 100%;

            &.active {
                left: 0;
            }

            &__toggle {
                display: flex;
                align-items: center;

                &-btn {
                    display: flex;
                    padding: 10px;
                    border-radius: 10px;
                    background-color: $dark;
                    border: none;
                    svg {
                        pointer-events: none;
                        path {
                            fill: #fff;
                        }
                    }
                }
            }

            &__overlay {
                position: fixed;
                left: 0;
                top: 0;
                width: 100%;
                height: 100%;
                background: rgba(0,0,0,0.5);
                opacity: 0;
                visibility: hidden;
                z-index: 9050;
                display: flex;
                &.active {
                    opacity: 1;
                    visibility: visible;
                }
            }

            &__wrapper {
                overflow: auto;
                height: 100%;
                border-top-left-radius: 0;
                border-bottom-left-radius: 0;
                padding-bottom: 80px;
            }

            &__search-bar {
                display: none;
            }
        }

        &-content {
            &__item {
                &-url {
                    line-height: 16px;
                    font-size: 12px;
                }
            }
        }
    }

}

.searchform {
    .input-wrapper {
        position: relative;
        max-width : 600px;
        input {
            width: 100%;
        }
    }

    input {
        border: 1px solid #3B37E6;
        border-radius: 50px;
        padding: 10px;
    }
    [type=submit] {
        border-radius: 50px;
        position: absolute;
        right: 0;
        top: 0;
        cursor: pointer;
        padding: 5px;
        line-height: 0;
        min-width: unset;
    }
}

.navigation.pagination {
    .screen-reader-text {
        display:none;
    }

    .nav-links {
        display: flex;
        align-items: flex-end;
        .page-numbers {
            padding: 5px 10px;
            line-height: 15px;
            &.current {
                font-weight: 600;
            }
        }
        .next,
        .prev {
            border: 1px solid #3B37E6;
            border-radius: 50%;
            margin-top: 0;
            padding: 5px;
            line-height: 10px;
        }
    }


}

.search-results {
    .side-content-banner {
        margin-bottom: 0;
        padding-top: 36px;
        padding-bottom: 36px;
        //&__subtitle {
        //	font-size: 50px;
        //	line-height: 60px;
        //	padding-left: 20px;
        //	padding-bottom: 16px;
        //}

        &__content {
            #searchform {
                input {
                    font-size: 24px;
                    padding: 16px;
                }
                [type=submit] {
                    padding: 16px;
                    svg {
                        width: 40px;
                        height: 40px;
                    }
                }
            }
        }

        &__wrapper {
            grid-template-columns: 1fr 450px;

            @include break(small){
                display: block;
            }

        }

        &__media {
            &.js-json-animation {
                max-width: 75%;
                min-height: 375px;
                //@include break(medium){
                //	min-height: 375px;
                //}
                @include break(small){
                    min-height: 325px;
                }
            }
        }

        @include break(medium){
            &__content {
                #searchform {
                    input {
                        font-size: 14px;
                        padding: 5px 10px;
                    }
                    [type=submit] {
                        padding: 7px;
                        svg {
                            width: 20px;
                            height: 20px;
                        }
                    }
                }
            }
        }
    }
}
