html {
    position   : relative;
    min-height : 100%;

    &.popup-opened {
        overflow : hidden;

        @include break(small) {
            height : 100vh;
        }
    }
}


.my_overlay {
    position   : fixed;
    z-index    : 1;
    left       : 0;
    top        : 0;
    width      : 100%;
    height     : 100%;
    background : #16213D;
    opacity    : 0.8;
    cursor     : pointer;
    display    : block;
}

.popup {
    top        : 0;
    left       : 0;
    width      : 100%;
    height     : 100%;
    position   : fixed;
    z-index    : 99999;
    display    : none;
    overflow-x : hidden;
    overflow-y : scroll;

    .popup-wrapper-inner {
        width      : 642px;
        padding    : 25px 50px 50px;
        margin     : 70px auto 50px;
        position   : relative;
        z-index    : 2;
        background : #EEEEF2;
        //box-shadow: 0px 0px 60px #2C3549;
    }

    @include break(small) {
        .popup-wrapper-inner {
            margin-top : 40px;
            width      : 90% !important;
            padding    : 45px 20px;

            @include break(x-small) {
                width   : calc(100% - 20px) !important;
                padding : 70px 20px;
            }
        }
    }

    button.popup-close {
        text-indent     : -9999px;
        background-color: transparent;
        background-size : 32px auto;
        border          : none;
        width           : 40px;
        height          : 40px;
        position        : absolute;
        top             : -40px;
        right           : -40px;
        padding         : 0;
        z-index         : 10;
        opacity         : 0.9;
        cursor          : pointer;

        &:hover {
            opacity : 1;
        }
    }
}