.case-study-carousel-review {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    overflow      : hidden;

    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__title {
        margin-bottom : 36px;
        text-align    : center;
        @include break(x-small) {
            font-size   : 25px;
            line-height : 29px;
        }
    }

    &__slider {
        margin-left  : auto;
        margin-right : auto;
        padding-bottom: 80px;

        @include break(small) {
            padding-bottom: 38px;
        }

        &.swiper {
            .swiper-slide {
                padding-left  : 80px;
                padding-right : 80px;
                height        : auto;

                @include break(large1370) {
                    padding-left  : 0;
                    padding-right : 0;
                }
                opacity       : 0 !important;

                &-active {
                    opacity : 1 !important;

                    .testimonial-block__figure-bg {
                        animation: slideIn 2s ease-in-out forwards;
                    }
                }
            }

            .swiper-button-prev, .swiper-button-next {
                margin-top : -60px;
                @include break(large1370) {
                    margin-top : -40px;
                }
            }

            .swiper-pagination {
                bottom: -38px;

                &-bullet {
                    width  : 11px;
                    height : 11px;
                }

                @include break(desktop) {
                    display    : flex;
                    margin-top : 23px;
                }
                @include break(x-small) {
                    margin-top : 0;
                    bottom: -30px;
                }
            }
        }
    }

    &__slide {
        &-content {
            display: flex;
            gap : 20px;

            @include break(medium) {
                gap : 30px;
            }
            @include break(small) {
                flex-wrap: wrap;
                gap : 20px;
            }
        }
        &-media {
            width : 487px;

            @include break(medium) {
                border-radius : 28px;
                width : 380px;
            }
            @include break(small) {
                width: 100%;
                border-radius : 14px;
            }
        }
        &-review {
            width : calc(100% - 507px);

            @include break(medium) {
                width : calc(100% - 410px);
            }
            @include break(small) {
                width: 100%;
            }
        }

        &-media-wrapper {
            overflow      : hidden;
            position      : relative;
        }

        &-image-wrapper {
            position  : relative;
            isolation : isolate;

            /*&::before {
				content          : '';
				display          : block;
				position         : absolute;
				width            : 100%;
				height           : 100%;
				z-index          : 10;
				background-color : rgba($color : #252F59, $alpha : 0.6);
				mix-blend-mode   : multiply;
			}*/
        }

        &-image {
            display    : block;
            width      : 100%;
            object-fit : cover;
            height : 322px;
            border-radius : 38px;
            @include break(medium) {
                height : 400px;
                border-radius : 23px;
            }
            @include break(small) {
                height : 345px;
                border-radius : 14px;
            }
            @include break(ss-small) {
                height : 222px;
                border-radius : 14px;
            }
        }

        &-iframe-wrapper {
            position : absolute;
            width    : 100%;
            height   : 100%;
            left     : 0;
            top      : 0;
            z-index  : 150;

            &.active {
                z-index : 200;
            }

            iframe {
                width  : 100%;
                height : 100%;
            }
        }

        &-video-wrapper {
            position : absolute;
            width    : 100%;
            height   : 100%;
            z-index  : 155;
            left     : 0;
            top      : 0;
        }

        &-play-btn {
            padding          : 0;
            background-color : transparent;
            border           : none;
            display          : flex;
            justify-content  : center;
            align-items      : center;
            cursor           : pointer;
            position         : absolute;
            left             : 0;
            top              : 0;
            width            : 100%;
            height           : 100%;
            z-index: 180;

            * {
                pointer-events : none;
            }

            &:hover {
                svg {
                    circle {
                        fill : $blue;
                    }

                    path {
                        fill : $royal_blue;
                    }
                }
            }

            svg {
                width            : 122px;
                height           : 122px;
                circle {
                    transition : all .4s ease-in-out;
                }
                parth {
                    transition : all .5s ease-in-out;
                }

                @include break(small) {
                    width  : 90px;
                    height : 90px;
                }
            }
        }
    }
    &__logo-wrapper {
        border-radius: 16px;
        border: 0.829px solid $blue;
        background: $white;
        position: absolute;
        left: 16px;
        bottom: 16px;
        padding: 10px 30px;

        @include break(small) {
            padding: 8px 22px;
            max-width: 137px;
        }
        img,svg {
            max-height: 40px;
            height: auto;
            width: auto;
            display: block;
            @include break(medium){
                max-height: 28px;
            }
            @include break(s-small){
                max-height:30px;
            }
        }
    }
    &__slide-logo {
        width : 100%;
    }
    &__label {
        border-radius: 10px;
        border: 1px solid $blue;
        background-color: $gret_blue;
        padding : 7px 16px 5px;
        color: $dark;
        text-align: center;
        font-family: $third_font;
        font-size: 13px;
        font-weight: 600;
        line-height: 16px;
        position : absolute;
        top: 15px;
        left: 22px;
        z-index : 2;
    }
    .figure {
        width: 111px;
        height: 65px;
        left: -1px;
        bottom: -62px;
        background-size: contain;
        background-repeat: no-repeat;
    }
    .testimonial-block {
        &__content {
            padding : 41px 53px 20px;

            @include break(small) {
                padding : 15px 16px 18px;
            }
        }
        &__text {
            height: 130px;

            @include break(small) {
                height: auto;
            }

            p {
                font-size: 22px;
                line-height: 32px;
                font-family: $third_font;
                font-weight: 600;
                color: $purple;

                @include break(small) {
                    font-size: 15px!important;
                    line-height: 24px!important;
                }
            }
        }
        &__from {
            font-weight : 300;
            height: 56px;
            margin-top: 14px;

            @include break(small) {
                height: auto;
            }
        }

        &__quote {
            height              : 46px;
            background-image    : url("data:image/svg+xml,%3Csvg width='113' height='80' viewBox='0 0 113 80' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M53.1238 12.9287C53.8254 13.843 53.6009 15.1339 52.6468 15.8331C39.457 25.3802 31.2625 32.7758 28.0914 38.0468H28.7088C39.5693 38.0468 48.9424 47.5938 48.9424 58.2973C48.9424 70.1571 38.0819 79.9999 25.0886 79.9999C10.5799 80.0268 0 69.3234 0 54.2633C0 35.8416 13.6107 17.6887 41.1408 0.369622C42.123 -0.248918 43.442 -0.00688067 44.1155 0.907483L53.1238 12.9556V12.9287ZM88.1469 38.0468C99.0074 38.0468 108.381 47.5938 108.381 58.2973C108.381 70.1571 97.52 79.9999 84.5267 79.9999C70.018 79.9999 59.4662 69.2965 59.4662 54.2364C59.4662 35.8147 73.0769 17.6619 100.607 0.342729C101.589 -0.275811 102.908 -0.0337738 103.582 0.88059L112.59 12.9287C113.292 13.843 113.067 15.1339 112.113 15.8331C98.9232 25.3802 90.7287 32.7758 87.5575 38.0468H88.1749H88.1469Z' fill='%23A142FF'/%3E%3C/svg%3E");
            width               : 64px;
            background-position : center;
            background-repeat   : no-repeat;
            background-size     : contain;

            @include break(small) {
                height: 44px;
            }
        }

        &__bottom {
            height: 47px;
            width: calc(100% - 84px);
            grid-template-columns: 64px 1fr 167px;
            grid-column-gap: 15px;
            margin-top: 14px;

            @include break(ss-small) {
                grid-template-columns: 64px 1fr;
            }
        }
        &__figure {
            height : 47px;
            position : relative;
            overflow: hidden;


            @include break(ss-small) {
                display: none;
            }
        }
        &__figure-bg {
            position: absolute;
            top: 0;
            right: 100%;
            height: 100%;
        }
        &__button {
            @extend .styled-btn;
            width : 100%;
        }
    }
    .swiper {
        .swiper-button-prev,
        .swiper-button-next {
            display: none;
        }
    }
    .show-arrows {
        .swiper {
            .swiper-button-prev,
            .swiper-button-next {
                display: flex;

                @include break(desktop) {
                    display: none;
                }

                &.apricot {
                    border: 1px solid $apricot;

                    svg {
                        path {
                            fill: $apricot;
                        }
                    }
                }
                &.purple {
                    border: 1px solid $purple;

                    svg {
                        path {
                            fill: $purple;
                        }
                    }
                }
                &.light-blue {
                    border: 1px solid $malibu;

                    svg {
                        path {
                            fill: $malibu;
                        }
                    }
                }
            }
        }
    }
}

@keyframes slideIn {
    0% {
        right: 100%;
    }
    100% {
        right: 0;
    }
}
