.logo-slider {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    overflow      : hidden;
    min-height    : 68px;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }
    @include break(small) {
        min-height : 39px;
    }

    &__wrapper {
        overflow  : hidden;
        max-width : 100vw;
        width     : 100%;
        margin    : 0 auto;
        position  : relative;
        display   : flex;

        &:hover {
            .logo-slider__block {
                animation-play-state : paused;
            }

        }
    }

    &__block {
        display         : flex;
        position        : relative;
        animation       : marquee 55s linear infinite;
        justify-content : space-around;
        animation-delay : 2s;
    }

    &__logo {
        width           : 177px;
        height          : 68px;
        display         : flex;
        justify-content : center;
        align-items     : center;
        padding         : 8px 15px;
        @include break(small) {
            width   : 103px;
            height  : 39px;
            padding : 5px 13px;
        }

        &:hover {
            img, svg {
                filter : grayscale(0);
            }
        }

        picture {
            display         : block;
            max-height      : 100%;
            max-width       : 100%;
            width           : 177px;
            height          : 68px;
            display         : flex;
            align-items     : center;
            justify-content : center;

            img {
                object-fit : contain;
                width      : auto;
                @include break(small) {
                    height : 28px !important;
                }
            }
        }

        img, svg {
            width      : auto;
            height     : auto;
            display    : block;
            max-width  : 100%;
            max-height : 100%;
            filter     : grayscale(100%);
            transition : .3s linear;
        }
    }

    @keyframes marquee {
        0% {
            transform : translateX(0%);
        }
        100% {
            transform : translateX(-100%);
        }
    }
}