.left-side-icon-text-columns {
    margin    : $desktop_margin 0;

    @include break(medium) {
        margin    : 80px 0;
    }
    @include break(small) {
        margin    : $mobile_margin 0;
    }

    &__title {
        text-align    : center;
        font-size     : 40px;
        line-height   : 48px;
        margin-bottom : 48px;
        @include break(medium) {
            font-size   : 22px;
            line-height : 28px;
        }
        @include break(s-small) {
            margin-bottom : 24px;
        }
    }

    &__columns {
        &-2 {
            display   : flex;
            gap       : 40px 24px;
            flex-wrap : wrap;
            @media screen and (min-width : 992px) {
                display               : grid;
                grid-template-columns : repeat(2, 1fr);
                gap                   : 48px 64px;
            }
        }

        &-3 {
            display               : grid;
            grid-template-columns : repeat(auto-fill, minmax(290px, 1fr));
            gap                   : 40px 64px;
            @include break(desktop) {
                gap : 40px 24px;
            }
            @include break(s-small) {
                gap : 24px;
            }
        }
    }

    &__card {
        &-2 {
            @include break(medium) {
                flex : 1 0 300px;
            }
            @include break(small) {
                flex : 1 0 260px;
            }
        }

        &.grid {
            display               : grid;
            grid-template-columns : 56px 1fr;
            gap                   : 0 14px;
            @include break(s-small) {
                grid-template-columns : 40px 1fr;
            }
        }

        &-icon {
            width           : 56px;
            height          : 56px;
            display         : flex;
            justify-content : center;
            align-items     : center;
            @include break(s-small) {
                width  : 40px;
                height : 40px;
            }

            img, svg {
                max-height : 100%;
                max-width  : 100%;
                display    : block;
                width      : 100%;
                height     : auto;
            }
        }

        &-text {
            display     : flex;
            align-items : center;
            min-height  : 56px;
            @include break(s-small) {
                min-height : 40px;
            }
        }
        &-title {
            font-size     : 22px;
            line-height   : 28px;
            margin-bottom : 8px;
            @extend .styled-text;
        }
    }
    &__button {
        @extend .styled-btn;
    }
}
