.all-partners-w-sidebar {
    padding-top: 40px;
    padding-bottom: 60px;

    @include break(medium) {
        padding-top: 24px;
        padding-bottom: 20px;
    }

    &__container {
    }

    &__wrapper {
    }

    &__title {
        text-align: center;
        margin-bottom: 40px;

        @include break(tablet) {
            max-width: 680px;
            margin-left: auto;
            margin-right: auto;
        }

        @include break(medium) {
            margin-bottom: 30px;
            max-width: 365px;
        }

        @include break(s-small) {
            margin-bottom: 24px;
        }
    }

    &__block,
    &__filter-heading-results {
        display: flex;
        gap: 40px;

        @include break(tablet) {
            gap: 15px;
        }

        @include break(medium) {
            gap: 0;
        }
    }

    &__block {
        @include break(medium) {
            flex-direction: column;
        }
    }

    &__filter-heading-results {
        align-items: self-start;

        @include break(medium) {
            flex-direction: column-reverse;
            gap: 16px;
        }
    }

    &__filter-heading-results {
        margin-bottom: 40px;

        @include break(s-small) {
            margin-bottom: 42px;
        }
    }

    &__filter-applied-wrap {
        display: flex;
        gap: 30px;
        padding-left: 8px;

        @include break(medium) {
            padding-left: 0;
        }

        @include break(x-small) {
            flex-direction: column;
            gap: 12px;
        }
    }

    &__filter-applied,
    &__post-results {
        color: $dark;
        font-family: "Axiforma", sans-serif;
        font-size: 15px;
        font-style: normal;
        font-weight: 400;
        line-height: 1.86;
        white-space: nowrap;

        * {
            color: inherit;
            font-family: inherit;
            font-size: inherit;
            font-style: inherit;
            font-weight: inherit;
            line-height: inherit;
        }
    }

    &__filter-icon {
        position: relative;
        z-index: 1;
        width: 44px;
        height: 44px;
        cursor: pointer;
        display: none;

        @include break(medium) {
            display: flex;
        }

        &:before {
            position: absolute;
            content: '';
            display: block;
            left: 0;
            top: 0;
            width: 100%;
            height: 100%;
            z-index: 1;
            background: url(data:image/svg+xml;base64,) center center no-repeat;
            background-size: contain;
        }
    }

    &__filter-applied-list {
        display: flex;
        gap: 16px 12px;
        align-items: center;
        flex-wrap: wrap;
    }

    &__filter-applied-item {
        display: flex;
        gap: 12px;
        align-items: center;
        padding: 5px 15px;
        border-radius: 10px;
        border: 1px solid $malibu;
        background: $blue_tint;
        color: $dark;
        text-align: center;
        font-family: "Axiforma", sans-serif;
        font-size: 13px;
        font-style: normal;
        font-weight: 600;
        line-height: 1.23;
        width: max-content;
    }

    &__filter-applied-item-btn {
        appearance: none;
        outline: none;
        width: 10px;
        height: 10px;
        position: relative;
        z-index: 1;
        background: transparent;
        border: none;
        cursor: pointer;

        &:after {
            position: absolute;
            content: '';
            display: block;
            left: 0;
            top: 0;
            width: 100%;
            height: 100%;
            z-index: 1;
            background: url(data:image/svg+xml;base64,) center center no-repeat;
            background-size: contain;
        }
    }

    &__sidebar {
        flex: 1 0;
        max-width: 264px;
        min-width: 264px;
        width: 100%;
        display: flex;
        flex-direction: column;
        gap: 20px;

        &.desktop {
            @include break(medium) {
                width: 0 !important;
                flex: 0;
            }
        }
    }

    &__post-results-wrap {
        padding-left: 20px;
        padding-right: 20px;

        @include break(tablet) {
            padding-left: 8px;
            padding-right: 8px;
        }

        @include break(medium) {
            flex-direction: row;
            align-items: center;
            gap: 20px;
            display: flex;
            padding-left: 0;
            padding-right: 0;
        }
    }

    &__list {
    }

    &__sidebar-article-wrap,
    &__filter-wrapper {
        padding: 16px;
        border-radius: 16px;
        background: #D7F7FF;
    }

    &__sidebar-article-wrap {
        display: flex;
        flex-direction: column;

        @include break(medium) {
            display: none;
        }
    }

    &__filter-close-btn {
        position: absolute;
        z-index: 1;
        width: 18px;
        height: 18px;
        top: 18px;
        right: 18px;
        left: auto;
        cursor: pointer;
        display: none;

        @include break(medium) {
            display: flex;
        }

        &:before {
            position: absolute;
            content: '';
            display: block;
            left: 0;
            top: 0;
            width: 100%;
            height: 100%;
            z-index: 1;
            background: url(data:image/svg+xml;base64,) center center no-repeat;
            background-size: contain;
        }
    }

    &__filter-wrapper {
        padding: 40px 22px;

        @include break(medium) {
            display: block;
            position: fixed;
            top: 0;
            left: 0;
            z-index: 10000;
            height: 100vh;
            max-width: 265px;
            transform: translateX(-100%);
            transition: transform .5s ease-out;
            border-radius: 0 16px 16px 0;
            overflow-y: scroll;
        }
    }

    &__filter-label {
        width: 100%;
        display: flex;
        align-items: flex-start;
        position: relative;
        z-index: 1;
        padding-left: 24px;
        cursor: pointer;

        &:before,
        &:after {
            position: absolute;
            content: '';
            display: block;
            z-index: 1;
            left: 0;
            top: 4px;
            width: 16px;
            height: 16px;
        }

        &:before {
            background: url(data:image/svg+xml;base64,) center center no-repeat;
            background-size: contain;
        }

        &:after {
            background: url(data:image/svg+xml;base64,) center center no-repeat;
            background-size: contain;
            display: none;
        }
    }

    &__sidebar-article-btn {
        @extend .styled-btn;
        width: 100%;
    }

    &__sidebar-article-img-wrap {
        width: 100%;
        height: 120px;
        margin-bottom: 16px;
    }

    &__sidebar-article-img {
        object-fit: cover;
        object-position: center center;
        border-radius: 15px;
        overflow: hidden;
    }

    &__sidebar-article-title {
        margin-bottom: 8px;
    }

    &__sidebar-article-desc {
        font-size: 15px;
        font-weight: 300;
        line-height: 1.48;
        margin-bottom: 16px;
    }

    &__filter-list {
        display: flex;
        flex-direction: column;
        gap: 18px;

        input[type="checkbox"] {
            display: none;

            &:checked {
                & + .all-partners-w-sidebar {
                    &__filter-label {
                        &:before {
                            display: none;
                        }

                        &:after {
                            display: block;
                        }
                    }
                }
            }
        }
    }

    &__filter-heading,
    &__filter-name {
        color: $dark;
        font-family: "Axiforma", sans-serif;
        font-style: normal;
    }

    &__filter-heading {
        font-size: 20px;
        font-weight: 500;
        line-height: 1.4;
        margin-bottom: 24px;
    }

    &__filter-name,
    &__filter-post-count {
        pointer-events: none;
    }

    &__filter-name {
        font-size: 15px;
        font-weight: 400;
        line-height: 1.86;

        * {
            font-size   : inherit;
            font-weight : inherit;
            line-height : inherit;
        }
    }

    &__filter-post-count {
        color: $blue;
        display: inline-flex;
        padding-left: 5px;
    }

    &__list {
        flex: 1;
    }

    &__list-wrapper {
        display: flex;
        flex-wrap: wrap;

        @include break(medium) {
            position: relative;
            left: -10px;
            width: calc(100% + 20px);
        }

        @include break(s-small) {
            left: 0;
            width: 100%;
        }

        &.loading {
            background: rgba(0,0,0,0.7) url(data:image/svg+xml;base64,) center 10% no-repeat;
        }

        .partners-card {
            @include break(large1370) {
                width: 33.33%;
            }

            @include break(s-small) {
                width: 100%;
            }

            &:nth-child(2n + 1) {

                @include break(x-small) {
                    padding-right: 0;
                }
            }

            &:nth-child(2n + 2) {

                @include break(x-small) {
                    padding-left: 0;
                }
            }

            &__media {
                height: 100px;
                min-height: 100px;

                @include break(large1370) {
                    height: 140px;
                    min-height: 140px;
                }

                @include break(desktop) {
                    height: 100px;
                    min-height: 100px;
                }

                @include break(tablet) {
                    height: 100px;
                    min-height: 100px;
                }

                @include break(ss-small) {
                    height: 80px;
                    min-height: 80px;
                }

                @include break(s-small) {
                    height: 120px;
                    min-height: 120px;
                }

                @include break(x-small) {
                    margin-bottom: 18px;
                    height: 100px;
                    min-height: 100px;
                }

                picture {
                    width: 100%;
                    height: 100%;
                    display: flex;
                    align-items: center;
                }
            }

            &__wrapper {
                @include break(x-small) {
                    padding: 12px 12px 24px 12px;
                }
            }

            &__cat-wrapper {
                margin-bottom: 0;
            }

            &__name {
                display: none;

                @include break(x-small) {
                    font-size: 13px;
                    font-weight: 600;
                    line-height: 1.23;
                }
            }
        }
    }
}
