.case-study-card {
    padding       : 0 10px;
    width         : 33.3333%;
    margin-bottom : 20px;
    @include break(medium) {
        width : 50%;
    }
    @include break(s-small) {
        width : 100%;
    }

    &__wrapper {
        padding        : 15px;
        border-radius  : 16px;
        border         : 1px solid $blue;
        height         : 100%;
        display        : flex;
        flex-direction : column;
        transition     : background-color .3s linear;

        &:hover {
            background-color : $light_blue_tint;
        }
    }

    &__media {
        margin-bottom : 16px;
        position      : relative;
    }

    &__image {
        &:hover {
            svg {
                circle {
                    fill : $blue;
                }
                path {
                    fill : $royal_blue;
                }
            }
        }
    }

    &__img {
        border-radius : 4px;
        display       : block;
        width         : 100%;
        height        : 224px;
        object-fit    : cover;
    }

    &__logo-wrapper {
        position         : absolute;
        left             : 8px;
        bottom           : 8px;
        z-index          : 10;
        padding          : 8px 16px;
        width            : 136px;
        height           : 48px;
        border-radius    : 8px;
        background-color : $white;
        display          : flex;
        justify-content  : center;
        align-items      : center;
    }

    &__logo {
        display    : block;
        max-width  : 100%;
        max-height : 100%;
        width      : auto;
        height     : auto;
    }

    &__content-wrapper {
        display         : flex;
        justify-content : space-between;
        flex-direction  : column;
        height          : 100%;
    }

    &__content {

    }

    &__cat-wrapper {
        margin-bottom : 16px;
    }

    &__cat {
        display       : inline-block;
        font-size     : 13px;
        line-height   : 16px;
        border-radius : 10px;
        padding       : 5px 15px;
        border        : 1px solid;
        font-family   : $third_font;
        font-weight   : 600;
        color         : $dark;
        border-color  : $dark;

        &.erp {
            border-color     : $blue;
            background-color : $royal_blue;
        }

        &.hospitality {
            border-color     : $malibu;
            background-color : $blue_tint;
        }

        &.school {
            border-color     : $apricot;
            background-color : $coral_tint;
        }

        &.retail {
            border-color     : $purple;
            background-color : $purple_tint;
        }
    }

    &__title {
        color         : #3C455A;
        font-size     : 22px;
        line-height   : 24px;
        margin-bottom : 8px;
        transition    : color .3s linear;

        &:hover {
            color : $blue;
        }
    }

    &__link {
        @extend .inherit;
        display            : -webkit-box;
        -webkit-line-clamp : 3;
        -webkit-box-orient : vertical;
        overflow           : hidden;
    }

    &__excerpt {
        font-size   : 16px;
        line-height : 24px;
    }

    &__read-wrapper {
        margin-top : 16px;
    }

    &__read {
        @extend .arrow-btn-right;
        font-family : $third_font;
        font-weight : 600;
    }
}