.blog-card {
    padding       : 0 10px;
    width         : 33.3333%;
    margin-bottom : 20px;
    @include break(medium) {
        width : 50%;
    }
    @include break(s-small) {
        width   : 100%;
        padding : 0;
    }

    &__wrapper {
        padding        : 15px;
        border-radius  : 16px;
        border         : 1px solid $blue;
        height         : 100%;
        display        : flex;
        flex-direction : column;
        transition     : background-color .3s linear;
        // &:hover{
        //   background-color: $light_blue_tint;
        // }
    }

    &__media {
        margin-bottom : 16px;
        border-radius : 15px;
        overflow      : hidden;
        min-height    : 224px;
        height        : 224px;
    }

    &__image {
        width      : 100%;
        min-height : 224px;
        height     : 224px;

        &.media {
            display         : flex;
            justify-content : center;
            align-items     : center;
        }

        img {
            object-fit : cover;
            height     : 100%;
            width      : 100%;
            //max-width: 100%;
            //max-height: 100%;
            //height: auto;
            //width: auto;
            &.press {
                object-fit : cover;
                height     : 100%;
                width      : 100%;
            }
        }
    }

    &__content-wrapper {
        display         : flex;
        justify-content : space-between;
        flex-direction  : column;
        height          : 100%;
        @include break(s-small) {
            height : auto;
        }
    }

    &__content {

    }

    &__type-date-wrapper {
        margin-bottom : 16px;
        display       : flex;
        gap           : 8px;
        flex-wrap     : wrap;
        align-items   : center;
    }

    &__type,
    &__date {
        border-radius : 10px;
        padding       : 5px 15px;
        border        : 1px solid;
        font-family   : $third_font;
        font-weight   : 600;
        font-size     : 13px;
        line-height   : 16px;
        text-align    : center;
    }

    &__date {
        display : none;
    }

    &__new {
        border-radius    : 0 0 28px 28px;
        padding          : 35px 15px 5px;
        color            : $apricot;
        border           : 1px solid $apricot;
        background-color : $coral_tint;
        margin-top       : -30px;
        z-index          : -1;
    }

    &__author {
        margin-bottom : 16px;
        display       : flex;
        gap           : 8px;
        align-items   : center;
        position      : relative;

        img {
            border-radius : 50%;
            width         : 50px;
            height        : 50px;
            margin-right  : 5px;
            border        : 1px solid $blue;
        }

        &-link {
            opacity    : 0;
            visibility : hidden;
            position   : absolute;
            left       : 13px;
            top        : 12px;
            transition : .2s;
        }

        &:hover {
            .blog-card__author-link {
                opacity    : 1;
                visibility : visible;
            }
        }
        &-position {
            font-size: 12px;
            margin-top: 3px;
        }
    }

    // &__type{
    //   &.media{
    //     border-color: $malibu;
    //     background-color: $blue_tint;
    //   }
    //   &.press{
    //     border-color: $purple;
    //     background-color: $purple_tint;
    //   }
    // }
    &__date {

    }

    &__title {
        font-size      : 18px;
        line-height    : 28px;
        transition     : color .3s linear;
        padding-bottom : 16px;

        &:hover {
            color : $blue;
        }
    }

    &__link {
        @extend .inherit;
    }

    &__read-wrapper {
        margin-top : 16px;
    }

    &__read {
        @extend .arrow-btn-right;
        font-family : $third_font;
        font-weight : 600;
    }
}