.resources-card {
    border          : 1px solid rgba($color : $blue, $alpha : 0.5);
    border-radius   : 30px;
    padding         : 19px 19px 22px 19px;
    display         : flex;
    flex-direction  : column;
    justify-content : space-between;
    transition      : background-color .3s linear;
    @include break(medium) {
        padding       : 13px 14px 14px 14px;
        border-radius : 15px;
    }
    @include break(x-small) {
        border-radius : 28px;
        padding       : 17px;
    }

    &:hover {
        background-color : $light_blue_tint;
    }

    &__play-btn {
        position : absolute;
        top : 50%;
        left : 50%;
        transform : translate(-50%, -50%);
        width : 90px;
        height : 90px;

        circle {
            transition : all .4s ease-in-out;
        }
        parth {
            transition : all .5s ease-in-out;
        }
    }

    &__image {
        display       : block;
        border-radius : 15px;
        overflow      : hidden;
        margin-bottom : 14px;
        position      : relative;
        z-index       : 1;

        @include break(medium) {
            border-radius : 7px;
            margin-bottom : 19px;
        }
        @include break(x-small) {
            border-radius : 14px;
            margin-bottom : 11px;
        }

        img {
            display        : block;
            width          : 100%;
            height         : 100%;
            object-fit     : cover;
            transition     : transform .3s linear;
            pointer-events : none;
        }

        &:hover {
            svg {
                circle {
                    fill : $blue;
                }
                path {
                    fill : $royal_blue;
                }
            }
        }
    }

    &__media-cat-wrapper {
        margin-bottom : 14px;
        @include break(medium) {
            margin-bottom : 12px;
        }
        @include break(x-small) {
            margin-bottom : 9px;
        }
    }

    &__media-cat {
        text-align    : center;
        display       : inline-block;
        padding       : 3px 15px;
        border        : 1px solid;
        font-size     : 13px;
        line-height   : 20px;
        border-radius : 10px;

        &.case-study {
            border-color     : $malibu;
            background-color : $blue_tint;
        }

        &.webinar-live {
            border-radius    : 0 0 28px 28px;
            padding          : 35px 15px 5px;
            color            : $apricot;
            border-color     : $apricot;
            background-color : $coral_tint;
            margin-top       : -30px;
            margin-right     : 8px;
        }

        @include break(medium) {
            font-size   : 12px;
            line-height : 19px;
        }
        @include break(x-small) {
            border-radius : 7px;
            padding       : 2px 11px;
            font-size     : 10px;
            line-height   : 16px;
        }
    }

    &__title {
        max-width  : 295px;
        color      : #3C455A;
        transition : color .3s linear;
        @include break(x-small) {
            max-width : none;
        }

        &:hover {
            color : $blue;
        }

        a {
            @extend .inherit;
            text-decoration : none;
            transition      : color .3s linear;
        }
    }

    &__excerpt {
        font-size   : 15px;
        line-height : 22px;
        margin-top  : 8px;
        @include break(medium) {
            margin-top  : 4px;
            font-size   : 12px;
            line-height : 18px;
        }
        @include break(x-small) {
            margin-top  : 0;
            font-size   : 15px;
            line-height : 22px;
        }
    }

    &__link-wrapper {
        margin-top : 15px;
        @include break(medium) {
            margin-top : 0;
        }
        @include break(x-small) {
            margin-top : 35px;
        }

        &.resource {
            margin-top : 7px;
            @include break(x-small) {
                margin-top : 15px;
            }
        }
    }

    &__link {
        @extend .arrow-btn-right;
    }
}