.careers-card {
    width         : 33.3333%;
    padding       : 0 10px;
    margin-bottom : 20px;
    @include break(medium) {
        width : 50%;
    }
    @include break(ss-small) {
        width         : 100%;
        padding-left  : 0;
        padding-right : 0;
    }

    &__wrapper {
        border          : 1px solid $blue;
        border-radius   : 16px;
        padding         : 16px;
        display         : flex;
        flex-direction  : column;
        justify-content : space-between;
        height          : 100%;
    }

    &__tags {
        display       : flex;
        flex-wrap     : wrap;
        margin-bottom : 8px;
    }

    &__tag {
        border        : 1px solid;
        border-radius : 10px;
        padding       : 5px 15px;
        font-size     : 13px;
        line-height   : 16px;
        margin-bottom : 8px;
        text-align    : center;

        &:not(:last-child) {
            margin-right : 8px;
        }
    }

    &__title {
        font-size   : 22px;
        line-height : 28px;
        color       : #3C455A;
        transition  : color .3s linear;

        a {
            @extend .inherit;
        }

        &:hover {
            color : $blue;
        }
    }

    &__excerpt {
        font-size   : 16px;
        line-height : 24px;
        margin-top  : 8px;
        display: -webkit-box;
        -webkit-box-orient: vertical;
        -webkit-line-clamp: 8;
        overflow: hidden;
    }

    &__link-wrapper {
        margin-top : 16px;
    }

    &__link {
        @extend .arrow-btn-right;
        font-size     : 16px;
        line-height   : 24px;
        padding-right : 24px;

        &::after {
            width            : 16px;
            height           : 16px;
            background-image : url("data:image/svg+xml,%3Csvg width='8' height='11' viewBox='0 0 8 11' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1.5 10L7.5 5.5L1.5 1' stroke='%233B37E6' stroke-width='1.3' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E%0A");
        }
    }
}