.cta-btn {
    margin-top    : 25px;
    margin-bottom : 25px;
    @include break(medium) {
        margin-top    : 15px;
        margin-bottom : 15px;
    }
    @include break(x-small) {
        margin-top    : 30px;
        margin-bottom : 30px;
        text-align    : center;
    }

    a.cta-btn__button {
        @extend .blue-btn;
        text-decoration : none !important;
        @extend .styled-btn;
    }
    &__wrapper {
        &.left {
            text-align : left;
        }
        &.right {
            text-align : right;
        }
        &.center {
            text-align : center;
        }
    }
}