.side-title-content-cta-v2{
    margin-top: $desktop_margin;
    margin-bottom: $desktop_margin;
    overflow: hidden;
    @include break(medium){
        margin-top: $mobile_margin;
        margin-bottom: $mobile_margin;
        overflow: unset;
    }
    @include break(s-small){
        margin-top: 50px;
        margin-bottom: 50px;
    }
    .js-animate-parent{
        &.animate{
            .animation-title,
            .animation-content{
                opacity: 1;
                transform: translate3d(0, 0, 0);
            }
        }
        .animation-title,
        .animation-content{
            transition: opacity .4s, transform .8s cubic-bezier(0.165, 0.84, 0.44, 1);
            opacity: 0;
      
        }
        .animation-title{
            transform: translate3d(-50%, 0, 0);
            @include break(s-small){
                transform: translate3d(0, 50%, 0);
            }
        }
        .animation-content{
            transform: translate3d(50%, 0, 0);
            @include break(s-small){
                transform: translate3d(0, 50%, 0);
                transition-delay: 0.5s;
            }
        }
    }
    &__wrapper{
        display: flex;
        justify-content: space-between;
        @include break(s-small){
            flex-direction: column;
            text-align: center;
        }
    }
    &__title-wrapper{
        max-width: 620px;
        padding-right: 10px;
        width: 51.67%;
        @include break(medium){
            width: 48.84%;
            padding-right: 16px;
        }
        @include break(s-small){
            padding: 0;
            width: 100%;
        }
    }
    &__content-wrapper{
        width: 48.3%;
        max-width: 580px;
        position: relative;
        padding-left: 64px;
        display: flex;
        align-items: center;
        @include break(medium){
            width: 51.16%;
            padding-left: 44px;
        }
        @include break(s-small){
            padding-left: 10px;
            padding-right: 10px;
            align-items: flex-start;
            width: 100%;
     
        }
        &::before{
            content: '';
            display: block;
            width: 1px;
            height: calc(100% - 37px);
            position: absolute;
            left: 0;
            top: 50%;
            transform: translateY(-50%);
            background-color: $purple_tint;
            @include break(medium){
                height: calc(100% - 25px);
            }
            @include break(s-small){
                display: none;
            }
        }
    }
    &__title{
        font-size: 70px;
        line-height: 84px;
        color: $purple_tint;
        -webkit-text-stroke: 1px $purple;
        @include break(medium){
            font-size: 40px;
            line-height: 48px;
        }
        @include break(s-small){
            font-size: 42px;
            line-height: 50px;
            margin-bottom: 11px;
        }
    }
    &__content{
        max-width: 458px;
        @include break(s-small){
            max-width: none;
        }
    }
    &__text{
        @include break(s-small){
            font-size: 15px;
            line-height: 22px;
        }
    }

    &__button-wrapper{
        margin-top: 20px;
        @include break(medium){
            margin-top: 15px;
        }
    }
    &__button{
        @extend .blue-btn;
    }
}