.featured-resources {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    overflow      : hidden;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__title {
        text-align    : center;
        margin-bottom : 38px;
        @include break(medium) {
            margin-bottom : 23px;
        }
        @include break(x-small) {
            margin-bottom : 25px;
        }
    }

    &__slider {
        &.swiper {
            .swiper-slide {
                padding : 0 101px;
                height  : auto;
                @include break(large1370) {
                    padding : 0 80px;
                }
                @include break(desktop) {
                    padding : 0;
                }
            }

            .swiper-button-prev, .swiper-button-next {
                width  : 59px;
                height : 59px;

                svg {
                    width  : 25px;
                    height : 21px;
                }
            }

            .swiper-pagination {
                margin-top : 23px;

                @include break(x-small) {
                    margin-top : 28px;
                }

                &-bullet {
                    width  : 11px;
                    height : 11px;
                    margin : 0 7px !important;
                }
            }
        }
    }

    &__slide {
        display               : grid;
        height                : 100%;
        grid-template-columns : 1fr 396px;
        column-gap            : 33px;
        row-gap               : 10px;
        border-radius         : 50px;
        border                : 1px solid $blue;
        background-color      : $light_blue_tint;
        padding               : 50px 41px 50px 45px;

        &.reverse {
            .featured-resources__slide-media { order: 1; }
        }
        @include break(desktop) {
            grid-template-columns : 1fr 500px;
        }
        @include break(tablet) {
            grid-template-columns : 1fr 396px;
        }
        @include break(medium) {

        }
        @include break(medium850) {
            grid-template-columns : 1fr 333px;
            column-gap            : 39px;
            padding               : 25px 45px 25px 25px;
            border-radius         : 22px;
        }
        @media screen and (max-width : 767px) {
            grid-template-columns : 1fr 260px;
            column-gap            : 20px;
        }
        @include break(s-small) {
            grid-template-columns : 1fr;
            padding               : 18px 16px 30px 16px;
            border-radius         : 28px;
        }

        &.blue {
            border-color : $blue;
            background-color : $light_blue_tint;
        }

        &.purple {
            border-color : $purple;
            background-color: rgba(248, 243, 255, 0.80);

            .h2-title {
