                    height           : 97px;
                }
            }

            .figure {
                z-index          : 20;
                background-image : url("data:image/svg+xml,%3Csvg width='104' height='107' viewBox='0 0 104 107' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M29.9971 0.121086L96.9136 0.121092C103.103 0.121093 106.247 7.5639 101.932 12.0011L12.0156 104.468C7.63501 108.973 -0.00284738 105.872 -0.00284683 99.5884L-0.00284076 30.1211C-0.00283931 13.5525 13.4286 0.121085 29.9971 0.121086Z' fill='%233B37E6'/%3E%3C/svg%3E%0A");
                width            : 104px;
                height           : 107px;
                @include break(medium) {
                    background-image : url("data:image/svg+xml,%3Csvg width='54' height='56' viewBox='0 0 54 56' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M16.1234 0.937496L50.3207 0.937499C53.4836 0.9375 55.0904 4.74111 52.8853 7.00873L6.93405 54.2636C4.69535 56.5658 0.792075 54.9809 0.792075 51.7697L0.792079 16.2688C0.792079 7.80156 7.65616 0.937496 16.1234 0.937496Z' fill='%233B37E6'/%3E%3C/svg%3E");
