                }
                @include break(x-small) {
                    background-image : url("data:image/svg+xml,%3Csvg width='66' height='68' viewBox='0 0 66 68' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M18.9998 -4.6225e-06L61.3802 -9.17487e-07C65.3 -5.74803e-07 67.2913 4.71378 64.5585 7.52403L7.61147 66.0867C4.83707 68.9398 -0.000234737 66.9756 -0.000234389 62.996L-0.000230543 19C-0.000229626 8.50658 8.50636 -5.53986e-06 18.9998 -4.6225e-06Z' fill='%233B37E6'/%3E%3C/svg%3E%0A");
                    width            : 66px;
                    height           : 68px;
                }
            }
        }

        &-image {
            display       : block;
            width         : 100%;
            height        : 100%;
            object-fit    : cover;
            border-radius : 32px;
            @include break(tablet) {
                border-radius : 15px;
            }
            @include break(s-small) {
                border-radius : 20px;
            }
        }

        &-content-wrapper {
            display         : flex;
            flex-direction  : column;
            justify-content : space-between;
        }

        &-content {
            @include break(medium850) {
                max-width : 310px;
            }
            @include break(s-small) {
                max-width     : none;
                text-align: center;
            }
        }

        &-media-cat {
            text-align    : center;
            display       : inline-block;
            padding       : 3px 15px;
            border        : 1px solid;
            font-size     : 13px;
            line-height   : 20px;
            border-radius : 10px;
            @include break(medium) {
                font-size   : 12px;
                line-height : 19px;
            }
            @include break(x-small) {
                border-radius : 6px;
                padding       : 2px 8px;
                font-size     : 8px;
                line-height   : 12px;
            }
        }

        &-title {
            margin-top : 18px;
            color      : $blue;
            transition : color .3s linear;
            @include break(medium) {
                margin-top : 16px;
            }
            @include break(s-small) {
                min-height : 87px;
                margin-top : 11px;
            }
            @include break(x-small) {
                min-height : 66px;
                text-align: center;
            }

            &:hover {
                color : $dark;
            }

            a {
                @extend .inherit;
            }
        }

        &-content-bottom {
            margin-top : 10px;
            @include break(medium) {
                margin-top : 16px;
            }
            @include break(s-small) {
                margin-top : 22px;
            }
        }

        &-link {
            @extend .arrow-btn-right;
        }
    }
    &__media-wrapper {
        position: relative;
    }
    &__play-btn {
        cursor           : pointer;
        position         : absolute;
        left             : 0;
        top              : 0;
        width            : 100%;
        height           : 100%;
        background-color : transparent;
        border           : none !important;
        z-index          : 200;
        display          : flex;
        justify-content  : center;
        align-items      : center;

        * {
            pointer-events : none;
        }

        svg {
            circle {
                transition : all .4s ease-in-out;
            }
            parth {
                transition : all .5s ease-in-out;
            }

            @include break(medium) {
                width  : 81px;
                height : 93px;
            }
        }
        &:hover {
            svg {
                circle {
                    fill : $blue;
                }
                path {
                    fill : $royal_blue;
                }
            }
        }
    }
    .hide-arrows {
        .swiper-button-next,
        .swiper-button-prev {
            display : none;
        }
        .featured-resources__slider.swiper .swiper-slide {
            padding: 0;
        }
        .featured-resources__slide {
            grid-template-columns : 1fr 510px;

            @include break(desktop) {
                grid-template-columns : 1fr 450px;
            }
            @include break(medium) {
                padding               : 16px 16px 16px 34px;
                grid-template-columns : 1fr 317px;
                column-gap            : 40px;
            }
            @include break(ss-small) {
                grid-template-columns : 1fr 250px;
                padding               : 16px;
            }
            @include break(s-small) {
                grid-template-columns : 1fr;
                padding               : 17px 16px 33px 16px;
            }
        }
    }
}