.hyper-link-buttons{
    margin-top: 32px;
    margin-bottom: 80px;
    @include break(s-small){
        margin-bottom: 35px;
    }
    &__title{
        margin-bottom: 12px;
        font-size: 15px;
        line-height: 24px;
        font-weight: 600;
        font-family: $third_font;
        @include break(s-small){
            text-align: center;
        }
    }
    &__list{
        display: flex;
        gap: 16px;
        flex-wrap: wrap;
        @include break(s-small){
            flex-direction: column;
            align-items: center;
        }
    }
    &__button{
        padding: 9px 29px;
        border: 1px solid;
        text-align: center;
        font-size: 15px;
        line-height: 24px;
        border-radius: 15px;
        transition: .3s linear;
        transition-property: background-color, color;
        &.blue,
        &.purple,
        &.coral,
        &.light-blue{
            &:hover{
                color: $white;
            }
        }
        &.blue{
            border-color: $blue;
            background-color: $royal_blue;
            &:hover{
                background-color: $blue;
            }
        }
        &.purple{
            border-color: $purple;
            background-color: $purple_tint;
            &:hover{
                background-color: $purple;
            }
        }
        &.coral{
            border-color: $apricot;
            background-color: $coral_tint;
            &:hover{
                background-color: $apricot;
            }
        }
        &.light-blue{
            border-color: $malibu;
            background-color: $blue_tint;
            &:hover{
                background-color: $malibu;
            }
        }
    }
}