.text-content-with-icon-columns {
    margin     : $desktop_margin 0;
    text-align : center;

    @include break(medium) {
        margin : $mobile_margin 0;
    }


    &__container {
        padding-left  : 0;
        padding-right : 0;
        @include break(tablet) {
            padding-left  : 28px;
            padding-right : 28px;
        }
        @include break(ss-small) {
            padding-left  : 4px;
            padding-right : 4px;
        }
        @include break(s-small) {
            padding-left  : 16px;
            padding-right : 16px;
        }

        &-v2 {
            padding-left  : 24px;
            padding-right : 24px;
            @include break(s-small) {
                padding-left  : 16px;
                padding-right : 16px;
            }
        }
    }

    &__wrapper {
        max-width : 1280px;

        &-v2 {
            max-width : 1232px;
        }
    }

    &__text,
    &__subtitle {
        max-width    : 1152px;
        margin-left  : auto;
        margin-right : auto;
    }

    &__title,
    &__text,
    &__subtitle {
        padding : 0 40px;
        @include break(tablet) {
            padding : 0 12px;
        }
        @include break(s-small) {
            padding : 0;
        }
    }

    &__title {
        font-size     : 40px;
        line-height   : 48px;
        margin-bottom : 16px;
        max-width     : 1015px;
        margin-left   : auto;
        margin-right  : auto;
        @include break(medium) {
            font-size   : 22px;
            line-height : 28px;
        }
    }

    &__text {
        font-size   : 16px;
        line-height : 24px;

        &-v2 {
            margin-bottom : 24px;
            &:last-of-type,
            &:first-of-type {
                &:last-of-type {
                    margin-bottom : 0;
                }
            }
        }
    }

    &__subtitle {
        font-size   : 22px;
        line-height : 28px;
        margin-top  : 48px;
        @include break(medium) {
            margin-top : 32px;
        }
    }

    &__columns {
        margin-top      : 40px;
        display         : flex;
        justify-content : center;
        flex-wrap       : wrap;
        gap             : 40px 0;
        @include break(tablet) {
            gap : 24px 0;
        }
        @include break(s-small) {
            margin-top : 24px;
        }

        &-v2 {
            margin-top : 0;
            gap        : 32px 0;
            @include break(s-small) {
                gap : 24px 0;
            }
        }
    }

    &__card {
        display        : flex;
        flex-direction : column;
        gap            : 14px;
        align-items    : center;
        width          : 33.3333%;
        padding        : 0 40px;

        &-v2 {
            gap     : 0;
            padding : 0 16px;
            @include break(medium) {
                width : 50%;
            }
            @include break(s-small) {
                padding : 0;
            }
        }

        &.two-columns {
            @media screen and (min-width : 1031px) {
                max-width : 554px;
                width     : 50%;
                padding   : 0 60px;
            }
        }

        @include break(tablet) {
            padding : 0 12px;
        }
        @include break(medium850) {
            width : 50%;
        }
        @include break(s-small) {
            width   : 100%;
            padding : 0;
        }

        &-icon {
            width           : 56px;
            height          : 56px;
            display         : flex;
            justify-content : center;
            align-items     : center;

            &-v2 {
                margin-bottom : 24px;
            }

            img, svg {
                width   : 100%;
                height  : auto;
                display : block;
            }
        }

        &-title {
            margin-bottom : 8px;
            font-size     : 22px;
            line-height   : 28px;
        }

        &-text {
            font-size   : 16px;
            line-height : 24px;
            font-weight : 400;

        }
    }
}