.title-with-cta {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;

    @include break(medium) {
        margin-top    : 80px;
        margin-bottom : 80px;
    }
    @include break(small) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__wrapper {
        text-align       : center;
        border           : 1px solid $malibu;
        background-color : $blue_tint;
        padding-top      : 48px;
        padding-bottom   : 48px;
        padding-left     : 30px;
        padding-right    : 30px;
        border-radius    : 40px;
        @extend .styled-container;
        @include break(medium) {
            border-radius : 20px;
        }
        @include break(x-small) {
            padding-top   : 40px;
            border-radius : 40px;
        }
    }

    &__title {
        max-width    : 80%;
        margin-left  : auto;
        margin-right : auto;
        @include break(medium) {
            font-size   : 40px;
            line-height : 48px;
            max-width   : 100%;
        }
        @include break(s-small) {
            max-width   : 100%;
            font-size   : 22px;
            line-height : 28px;
        }
    }

    &__button-wrapper {
        margin-top : 24px;
    }

    &__button {
        @extend .blue-btn;
        @extend .styled-btn;
    }
}