.site-footer {
    background-color   : $dark;
    padding-top        : 45px;
    padding-bottom     : 35px;
    content-visibility : auto;
    @include break(tablet) {
        padding-top    : 25px;
        padding-bottom : 20px;
    }
    @include break(ss-small) {
        padding-top    : 35px;
        padding-bottom : 75px;
    }

    &__container {
        padding-left : 50px;
        @include break(large1370) {
            padding-left : 40px;
        }
        @include break(tablet) {
            padding-left  : 25px;
            padding-right : 30px;
        }
        @include break(ss-small) {
            padding-left  : 16px;
            padding-right : 16px;
        }
    }

    &__wrapper {
        display         : flex;
        justify-content : space-between;
        margin-bottom   : 45px;
        @include break(tablet) {
            margin-bottom : 15px;
        }
        @include break(ss-small) {
            margin-bottom  : 35px;
            flex-direction : column;
        }
    }

    &__side {
        display         : flex;
        justify-content : space-between;
        width           : 100%;
        max-width       : 1125px;
        padding-left    : 50px;
        @include break(tablet) {
            padding-left : 40px;
        }
        @include break(ss-small) {
            padding-left : 0;
        }
    }

    &__logo-wrapper {
        width     : 141px;
        min-width : 120px;
        @include break(ss-small) {
            display         : flex;
            align-items     : center;
            justify-content : space-between;
            width           : 100%;
            margin-bottom   : 60px;
        }
    }

    &__mobile-socials {
        display    : none;
        margin-top : 20px;
        @include break(tablet) {
            display : block;
        }
        @include break(ss-small) {
            margin-top : 0;
        }
    }

    &__logo {
        display : block;

        img, svg {
            display : block;
            width   : 100%;
            height  : auto;
            @include break(tablet) {
                max-width : 80px;
            }
            @include break(ss-small) {
                max-width : 141px;
            }
        }
    }

    &__nav {
        width     : 100%;
        max-width : 830px
    }

    &__menu {
        display         : flex;
        justify-content : space-between;
        @include break(x-small) {
            flex-direction : column;
        }

        & > .menu-item {
            @include break(tablet) {
                min-width : 105px;
            }
            @include break(x-small) {
                padding-top    : 14px;
                padding-bottom : 14px;
                border-bottom  : 1px solid $white;
            }

            &:not(:last-child) {
                padding-right : 20px;
                @include break(tablet) {
                    padding-right : 10px;
                }
                @include break(x-small) {
                    padding-right : 0;;
                }
            }

            & > a[href^="#"] {
                pointer-events : none;
                @include break(x-small) {
                    pointer-events : all;
                }
            }

            & > .nav__link,
            & > a {
                font-family    : $third_font;
                font-weight    : 600;
                color          : $white;
                text-transform : capitalize;
            }

            &.menu-item-has-children {
                a {
                    @include break(x-small) {
                        display       : block;
                        position      : relative;
                        padding-right : 15px;
                    }
                }

                &.active {
                    .sub-menu-toggle::after {
                        transform : rotate(90deg);
                    }
                }

                .sub-menu-toggle {
                    display  : none;
                    width    : 100%;
                    height   : 21px;
                    position : absolute;
                    right    : 0;
                    top      : 0px;
                    z-index  : 1000;

                    &::before,
                    &::after {
                        content          : '';
                        display          : block;
                        background-color : $white;
                        pointer-events   : none;
                        position         : absolute;
                    }

                    &::before {
                        width  : 9px;
                        height : 1px;
                        top    : 10px;
                        right  : 0;
                    }

                    &::after {
                        width      : 1px;
                        height     : 9px;
                        top        : 6px;
                        right      : 4px;
                        transition : transform 0.3s linear;
                    }

                    @include break(x-small) {
                        display : block;
                    }
                }
            }
        }

        .nav__link,
        a {
            font-size   : 13px;
            line-height : 20px;
            display     : inline-block;
            @include break(tablet) {
                font-size   : 10px;
                line-height : 16px;
            }
            @include break(x-small) {
                font-size   : 13px;
                line-height : 21px;
            }
        }

        .sub-menu {
            margin-top : 22px;
            max-height : none;
            @include break(tablet) {
                margin-top : 12px;
            }
            @include break(x-small) {
                margin-top : 0;
                max-height : 0;
                overflow   : hidden;
                transition : max-height .3s linear;
            }

            .menu-item {
                @include break(x-small) {
                    padding-top    : 7px;
                    padding-bottom : 7px;
                }
                // &:first-child{
                //   padding-top: 14px;
                // }
                &:last-child {
                    padding-bottom : 0;
                }

                &:not(:last-child) {
                    margin-bottom : 18px;
                    @include break(tablet) {
                        margin-bottom : 8px;
                    }
                    @include break(x-small) {
                        margin-bottom : 0;
                    }
                }
            }

            .nav__link,
            a {
                color      : #98A3BE;
                transition : color .3s linear;
                @include break(x-small) {
                    line-height : 20px;
                }

                &:hover {
                    color : $white;
                }
            }

            .nav__link {
                color : $white;
            }
        }
    }

    &__socials {
        margin-left : 30px;
        @include break(tablet) {
            display : none;
        }
    }

    &__bottom {
        display         : flex;
        align-items     : flex-end;
        justify-content : space-between;
        position        : relative;
    }

    &__partners {
        width     : 141px;
        min-width : 120px;
        @include break(tablet) {
            width : 120px;
        }
        @include break(ss-small) {
            position  : absolute;
            right     : 0;
            top       : 0;
            min-width : auto;
            width     : 63px;
        }

        &-wrapper {
            display   : block;
            max-width : 63px;
            @include break(tablet) {
                max-width : 50px;
            }
            @include break(ss-small) {
                max-width : 63px;
                width     : 63px;
            }

            img, svg {
                display    : block;
                width      : 100%;
                height     : auto;
                transition : transform .3s linear;

                &:hover {
                    transform : scale(1.1);
                }
            }
        }
    }

    &__bottom-side {
        display         : flex;
        align-items     : center;
        justify-content : space-between;
        width           : 100%;
        max-width       : 1125px;
        padding-left    : 50px;
        @include break(tablet) {
            padding-left : 40px;
        }
        @include break(ss-small) {
            padding-left   : 0;
            flex-direction : column;
            align-items    : flex-start;
        }
    }

    &__bottom-nav {
        @include break(ss-small) {
            margin-bottom : 95px;
            padding-right : 90px;
        }
    }

    &__bottom-menu {
        display     : flex;
        align-items : center;
        @include break(ss-small) {
            flex-direction : column;
            align-items    : flex-start;
        }

        .sub-menu {
            display : none;
        }

        .menu-item {
            &:not(:last-child) {
                margin-right : 55px;
                @include break(tablet) {
                    margin-right : 35px;
                }
                @include break(ss-small) {
                    margin-right  : 0;
                    margin-bottom : 25px;
                }
            }
        }

        .nav__link,
        a {
            display     : block;
            font-size   : 11px;
            line-height : 17px;
            color       : $white;
            transition  : color .3s linear;
            @include break(tablet) {
                font-size   : 9px;
                line-height : 14px;
            }
            @include break(ss-small) {
                font-size   : 11px;
                line-height : 17px;
            }

            &:hover {
                color : #98A3BE;
            }
        }
    }

    &__copyright-block {
        @include break(tablet) {
            margin-left : 20px;
        }
        @include break(ss-small) {
            text-align  : center;
            width       : 100%;
            margin-left : 0;
        }
    }

    &__copyright {
        font-size   : 11px;
        line-height : 17px;
        color       : $white;
        margin      : 0;
        @include break(tablet) {
            font-size   : 9px;
            line-height : 14px;
        }
        @include break(ss-small) {
            font-size   : 11px;
            line-height : 17px;
        }
    }
}