.three-columns-table {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : 90px;
        margin-bottom : 90px;
    }
    @include break(s-small) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__title {
        margin-bottom : 32px;
        text-align    : center;
        @include break(medium) {
            font-size   : 24px;
            line-height : 26px;
        }
    }

    &__content {
        @include break(small) {
            overflow-x: auto;
        }

        table {
            border-collapse : separate !important;
            height          : auto !important;
            width           : 100%;
            overflow        : hidden;
            border          : 1px solid rgba($color : $purple, $alpha : 0.2);
            border-radius   : 8px;
            table-layout    : fixed;

            thead > tr:not(:last-child) > th,
            thead > tr:not(:last-child) > td,
            tbody > tr:not(:last-child) > th,
            tbody > tr:not(:last-child) > td,
            tfoot > tr:not(:last-child) > th,
            tfoot > tr:not(:last-child) > td,
            tr:not(:last-child) > td,
            tr:not(:last-child) > th,
            thead:not(:last-child),
            tbody:not(:last-child),
            tfoot:not(:last-child) {
                border-bottom : 1px solid rgba($color : $purple, $alpha : 0.2);
            }
            @include break(small) {
                min-width: max-content;
            }

            tr {
                height : auto !important;

                &:first-child {
                    td {
                        font-family      : $third_font;
                        font-weight      : 600;
                        height           : 40px !important;
                        padding          : 8px 24px;
                        color            : rgba(22, 33, 61, 0.6);
                        background-color : #F9F5FF;
                        font-size        : 12px;

                        &:not(:first-child) {
                            text-align : center;
                        }

                        @include break(s-small) {
                            padding : 8px 12px;
                        }
                    }
                }

                td {
                    height         : 90px !important;
                    vertical-align : middle;
                    padding        : 12px 24px;
                    font-size      : 15px;
                    line-height    : 22px;
                    font-family    : $third_font;
                    font-weight    : 400;
                    width          : 33.3333%;

                    &:not(:last-child) {
                        border-right : 1px solid rgba($color : $purple, $alpha : 0.2);
                    }

                    &:first-child {
                        font-weight      : 600;
                        background-color : #F9F5FF;
                    }

                    img {
                        display : block;
                        margin  : 0 auto;
                    }

                    @include break(s-small) {
                        padding : 12px 16px;
                        width   : 26% !important;
                        height: auto;
                        &:first-child {
                            width : 25% !important;
                        }
                    }
                }
            }
        }

        @include break(medium) {
            &.mobile {
                //overflow-x: auto!important;
                table {
                    //min-width: 900px;
                    tr {
                        display        : flex;
                        flex-direction : column;

                        &:first-child {
                            display : none;
                        }

                        td {
                            display     : flex;
                            align-items : center;
                            width       : 100% !important;
                            height: auto!important;

                            &:not(:first-child) {
                                &:before {
                                    content     : attr(data-title) ": ";
                                    font-weight : 600;
                                    min-width   : 25%;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}