.cards-with-icons-v2 {
    padding-top    : 56px;
    padding-bottom : 56px;
    margin-top     : $desktop_margin;
    margin-bottom  : $desktop_margin;
    position       : relative;
    isolation      : isolate;
    @include break(medium) {
        margin-top     : $mobile_margin;
        margin-bottom  : $mobile_margin;
        padding-top    : 40px;
        padding-bottom : 40px;
    }

    &::before {
        content  : '';
        display  : block;
        position : absolute;
        left     : 0;
        bottom   : 0;
        z-index  : -1;
        width    : 100%;
    }

    &.white-bottom {
        padding-bottom : 40px;

        &::before {
            height           : 128px;
            background-color : $white;
            @include break(medium) {
                height : 244px;
            }
        }
    }

    &.white-gap {
        padding-bottom : 48px;
        @include break(medium) {
            padding-bottom : 40px;
        }

        &::before {
            height           : 48px;
            background-color : $white;
        }
    }

    &__container {
        padding-left  : 8px;
        padding-right : 8px;
        position      : relative;
        z-index       : 10;
        @include break(tablet) {
            padding-left  : 28px;
            padding-right : 28px;
        }
        @include break(ss-small) {
            padding-left  : 6px;
            padding-right : 6px;
        }
        @include break(s-small) {
            padding-left  : 16px;
            padding-right : 16px;
        }
    }

    &__wrapper {
        max-width    : 1134px;
        margin-left  : auto;
        margin-right : auto;
    }

    &__title,
    &__text {
        text-align : center;
    }

    &__title {
        margin-bottom : 8px;
        @extend .section-title;
    }

    &__text {
        p {
            @extend .section-text;
            color : #343434;
        }
    }

    &__cards {
        margin-top      : 56px;
        display         : flex;
        justify-content : center;
        flex-wrap       : wrap;
        gap             : 62px 0;
        @include break(desktop) {
            gap : 24px 0;
        }
        @include break(medium) {
            margin-top : 24px;
        }
    }
    &__button-area {
        margin-top: 16px;
    }
    &__button {
        @extend .styled-btn;
    }

    &__card {
        width   : 33.3333%;
        padding : 0 31px;
        @include break(desktop) {
            padding : 0 12px;
        }
        @include break(medium) {
            width : 50%;
        }
        @include break(s-small) {
            width   : 100%;
            padding : 0;
        }

        &.animate {
            .js-animate-element {
                opacity   : 1;
                transform : translate(0, 0);
            }
        }

        &:nth-child(1),
        &:nth-child(3n+4) {
            .js-animate-element {
                transition-delay : 0.2s;
            }
        }

        &:nth-child(2),
        &:nth-child(3n+5) {
            .js-animate-element {
                transition-delay : 0.3s;
            }
        }

        &:nth-child(3),
        &:nth-child(3n+6) {
            .js-animate-element {
                transition-delay : 0.4s;
            }
        }

        @include break(medium) {
            &:nth-child(odd) {
                .js-animate-element {
                    transition-delay : 0.2s;
                }
            }
            &:nth-child(even) {
                .js-animate-element {
                    transition-delay : 0.3s;
                }
            }
        }
        @include break(s-small) {
            & {
                .js-animate-element {
                    transition-delay : 0;
                }
            }
        }

        &-wrapper {
            transform        : translate(0, 60px);
            transition       : opacity .2s, transform .8s cubic-bezier(0.165, 0.84, 0.44, 1);
            opacity          : 0;
            display          : flex;
            flex-direction   : column;
            align-items      : center;
            padding          : 40px 16px;
            gap              : 24px;
            box-shadow       : 0px 3px 15px rgba(59, 55, 230, 0.2);
            border-radius    : 20px;
            background-color : $white;
            text-align       : center;
            height           : 100%;
        }

        &-icon {
            width           : 72px;
            height          : 72px;
            display         : flex;
            justify-content : center;
            align-items     : center;

            img, svg {
                max-width  : 100%;
                max-height : 100%;
                width      : auto;
                height     : auto;
                display    : block;
            }
        }

        &-title {
            font-size     : 22px;
            line-height   : 28px;
            margin-bottom : 8px;
        }

        &-text {
            font-size   : 16px;
            line-height : 24px;
            font-family : $main_font;
        }
    }
    &__animation {
        width : 250px;
        margin: 0 auto;
    }

    &__bottom-wrapper {
        background-color : $white;
        padding-left     : 40px;
        padding-right    : 40px;
        padding-top      : 48px;
        position         : relative;
        @include break(medium) {
            padding-top : 24px;
        }
        @include break(ss-small) {
            padding-left  : 16px;
            padding-right : 16px;
        }

        &::before {
            content    : '';
            display    : block;
            background : $white;
            position   : absolute;
            left       : 0;
            bottom     : 100%;
            height     : 85px;
            width      : 100%;
            @include break(medium) {
                height : 100px;
            }
        }
    }

    &__bottom-text {
        max-width    : 832px;
        margin-left  : auto;
        margin-right : auto;
    }
}