.all-partners {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__container {
        padding-left  : 30px;
        padding-right : 30px;
        @include break(ss-small) {
            padding-left  : 6px;
            padding-right : 6px;
        }
        @include break(s-small) {
            padding-left  : 16px;
            padding-right : 16px;
        }
    }

    &__wrapper {
        max-width : 1220px;
    }

    &__title {
        text-align    : center;
        margin-bottom : 40px;
        @include break(medium) {
            margin-bottom : 24px;
            font-size     : 22px;
            line-height   : 28px;
        }
    }

    &__filters {
        display         : flex;
        justify-content : center;
        margin-bottom   : 40px;
        @include break(medium) {
            margin-bottom : 24px;
        }
        @include break(x-small) {
            flex-direction : column;
            align-items    : center;
        }

        .content-filter {
            @include break(x-small) {
                &:not(:first-child) {
                    margin-top : 16px;
                }
            }

        }
    }

    &__list {

    }

    &__list-wrapper {
        display         : flex;
        flex-wrap       : wrap;
        justify-content: flex-start;
    }
}

body {
    .partners-card {
        &__cat-categories {
            display: none;
        }
    }

    .all-partners-w-sidebar {
        &__block {
            .partners-card {
                &__cat-categories {
                    display: flex;
                }

                &__cat-solutions {
                    display: none;
                }
            }
        }
    }
}
