.billboard-checkbox-section {
    background-color: $light_blue_tint;
    position: relative;
    margin-top    : $desktop_margin;
    margin-bottom : 50px;
    padding: 40px 0 0;

    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }
    @include break(medium850) {
        background : linear-gradient(0deg, #F3F6FF 0%, #F3F6FF 100%), #FFF;
    }

    &:after {
        content: '';
        background-color: $white;
        height: 87px;
        position: absolute;
        bottom: 0;
        left: 0;
        width : 100%;
        z-index: 1;

        @include break(medium850) {
            height: 244px;
        }
        @include break(ss-small) {
            display: none;
        }
    }
    &__wrapper {
        display: grid;
        grid-template-columns: 400px 1fr;
        grid-column-gap: 60px;
        position: relative;
        z-index: 5;
        padding: 0 80px;

        @include break(large1470) {
            padding: 0;
        }
        @include break(desktop){
            grid-column-gap: 40px;
        }
        @include break(medium850) {
            display: flex;
            flex-direction: column-reverse;
        }
    }
    &__title {
        color: $blue;
        font-family: $third_font;
        font-size: 40px;
        font-weight: 600;
        line-height: 48px;
        margin: 56px 0 24px;

        @include break(desktop){
            margin: 0 0 24px;
        }
        @include break(small) {
            font-size: 22px;
            margin-bottom: 12px;
        }
    }
    &__content {
        padding-bottom: 87px;

        @include break(small) {
            padding-bottom: 20px;
        }
    }
    &__list {
        max-width: 660px;

        &-item {
            margin-bottom: 24px;
            display: flex;
            align-items: flex-start;
            gap: 11px;
        }
        &-content {
            color: $dark;
            font-family: $second_font;
            font-size: 18px;
            font-weight: 400;
            line-height: 157%;
        }
        &-mark {
            border-radius: 7px;
            border: 1px solid $blue;
            background: $royal_blue;
            display: flex;
            width: 26px;
            height: 26px;
            padding: 4px;
            align-items: center;
            gap: 10px;
            flex-shrink: 0;
            margin-top: 2px;
        }
    }
    &__media {
        display: grid;
        grid-template-columns: 1fr 1fr;
        grid-template-rows: repeat(4, 158px);
        grid-gap: 16px;

        @include break(medium850) {
            max-width: 400px;
            margin: 0 auto;
        }
        @include break(ss-small) {
            display: none;
        }

        &-item {

            svg {
                @include break(super-small) {
                    width : 100%;
                }
            }
            &:nth-child(1) {
                grid-row-start: 1;
                grid-row-end: 1;
                grid-column-start: 1;
                grid-column-end: 1;
            }
            &:nth-child(2) {
                grid-row-start: 1;
                grid-row-end: 3;
                grid-column-start: 2;
                grid-column-end: 2;
            }
            &:nth-child(3) {
                grid-row-start: 2;
                grid-row-end: 4;
                grid-column-start: 1;
                grid-column-end: 1;
            }
            &:nth-child(4) {
                grid-row-start: 3;
                grid-row-end: 5;
                grid-column-start: 2;
                grid-column-end: 2;
            }
            &:nth-child(5) {
                grid-row-start: 4;
                grid-row-end: 4;
                grid-column-start: 1;
                grid-column-end: 1;
            }
            &.image {
                border-radius: 40px;
                overflow: hidden;
            }
        }
    }
}