.case-study-video-carousel {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    overflow      : hidden;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__title {
        margin-bottom : 30px;
        text-align    : center;
        @include break(x-small) {
            font-size   : 25px;
            line-height : 29px;
        }
    }

    &__slider {
        max-width    : 1320px;
        margin-left  : auto;
        margin-right : auto;

        &.swiper {
            .swiper-slide {
                padding-left  : 100px;
                padding-right : 100px;
                height        : auto;
                @include break(large1370) {
                    padding-left  : 50px;
                    padding-right : 50px;
                }
                @include break(desktop) {
                    padding-left  : 0;
                    padding-right : 0;
                }
                opacity       : 0 !important;

                &-active {
                    opacity : 1 !important;
                }
            }

            .swiper-button-prev, .swiper-button-next {
                margin-top : -60px;
                @include break(large1370) {
                    margin-top : -40px;
                }
            }

            .swiper-pagination {
                display : none;

                &-bullet {
                    width  : 11px;
                    height : 11px;
                }

                @include break(desktop) {
                    display    : flex;
                    margin-top : 23px;
                }
                @include break(x-small) {
                    margin-top : 38px;
                }
            }
        }
    }

    &__slide {
        &-media {
            background-color                  : $light_blue_tint;
            border                            : 1px solid $blue;
            -webkit-border-radius             : 47px;
            -webkit-border-bottom-left-radius : 0;
            -moz-border-radius                : 47px;
            -moz-border-radius-bottomleft     : 0;
            border-radius                     : 47px;
            border-bottom-left-radius         : 0;
            padding                           : 31px;
            @include break(medium) {
                padding                           : 20px 22px 25px 22px;
                -webkit-border-radius             : 28px;
                -webkit-border-bottom-left-radius : 0;
                -moz-border-radius                : 28px;
                -moz-border-radius-bottomleft     : 0;
                border-radius                     : 28px;
                border-bottom-left-radius         : 0;
            }
            @include break(ss-small) {
                border-radius : 27px;
                padding       : 17px 14px 28px 14px;
            }
        }

        &-media-wrapper {
            overflow      : hidden;
            border-radius : 38px;
            position      : relative;
            @include break(medium) {
                border-radius : 23px;
            }
            @include break(ss-small) {
                border-radius : 11px;
            }
        }

        &-image-wrapper {
            position  : relative;
            isolation : isolate;

            /*&::before {
				content          : '';
				display          : block;
				position         : absolute;
				width            : 100%;
				height           : 100%;
				z-index          : 10;
				background-color : rgba($color : #252F59, $alpha : 0.6);
				mix-blend-mode   : multiply;
			}*/
        }

        &-image {
            display    : block;
            width      : 100%;
            height     : 562px;
            object-fit : cover;
            @include break(medium) {
                height : 400px;
            }
            @include break(small) {
                height : 335px;
            }
            @include break(x-small) {
                height : 175px;
            }
        }

        &-iframe-wrapper {
            position : absolute;
            width    : 100%;
            height   : 100%;
            z-index  : 100;
            left     : 0;
            top      : 0;
            z-index  : 150;

            &.active {
                z-index : 200;
            }

            iframe {
                width  : 100%;
                height : 100%;
            }
        }

        &-video-wrapper {
            position : absolute;
            width    : 100%;
            height   : 100%;
            z-index  : 100;
            left     : 0;
            top      : 0;
            z-index  : 170;
        }

        &-play-btn {
            padding          : 0;
            background-color : transparent;
            border           : none;
            width            : 100%;
            height           : 100%;
            display          : flex;
            justify-content  : center;
            align-items      : center;
            cursor           : pointer;
            position         : absolute;
            left             : 0;
            top              : 0;
            width            : 100%;
            height           : 100%;

            * {
                pointer-events : none;
            }

            &:hover {
                svg {
                    circle {
                        fill : $blue;
                    }

                    path {
                        fill : $royal_blue;
                    }
                }
            }

            svg {
                circle {
                    transition : all .4s ease-in-out;
                }
                parth {
                    transition : all .5s ease-in-out;
                }

                @include break(small) {
                    width  : 71px;
                    height : 71px;
                }
                @include break(x-small) {
                    width  : 36px;
                    height : 36px;
                }
            }
        }

        &-bottom {
            display     : flex;
            height      : 100px;
            align-items : center;
            @include break(medium) {
                height : 60px;
            }
            @include break(ss-small) {
                height          : auto;
                flex-direction  : column;
                justify-content : flex-start;
                align-items     : center;
                padding-left    : 25px;
                padding-right   : 25px;
            }
        }

        &-button-wrapper {
            background-color                   : $light_blue_tint;
            border                             : 1px solid $blue;
            background-color                   : $light_blue_tint;
            border                             : 1px solid $blue;
            border-top                         : 0;
            height                             : 101px;
            margin-top                         : -1px;
            -webkit-border-bottom-right-radius : 47px;
            -webkit-border-bottom-left-radius  : 47px;
            -moz-border-radius-bottomright     : 47px;
            -moz-border-radius-bottomleft      : 47px;
            border-bottom-right-radius         : 47px;
            border-bottom-left-radius          : 47px;
            min-width                          : 390px;
            padding-left                       : 32px;
            padding-right                      : 32px;
            position                           : relative;
            @include break(medium) {
                -webkit-border-bottom-right-radius : 28px;
                -webkit-border-bottom-left-radius  : 28px;
                -moz-border-radius-bottomright     : 28px;
                -moz-border-radius-bottomleft      : 28px;
                border-bottom-right-radius         : 28px;
                border-bottom-left-radius          : 28px;
                height                             : 61px;
                padding-left                       : 22px;
                padding-right                      : 22px;
                min-width                          : 240px;
            }
            @include break(ss-small) {
                width                              : 180px;
                min-width                          : none;
                height                             : 41px;
                -webkit-border-bottom-right-radius : 27px;
                -webkit-border-bottom-left-radius  : 27px;
                -moz-border-radius-bottomright     : 27px;
                -moz-border-radius-bottomleft      : 27px;
                border-bottom-right-radius         : 27px;
                border-bottom-left-radius          : 27px;
                padding-left                       : 30px;
                padding-right                      : 30px;
            }
            @include break(x-small) {
                width : 180px;
            }

            &::after {
                content             : '';
                display             : block;
                width               : 35px;
                height              : 35px;
