.return-back-link{
    &__btn{
        color: $dark;
        padding-left: 18px;
        font-size: 15px;
        line-height: 24px;
        transition:color .3s linear;
        position: relative;
        display: inline-block;
        &:hover{
            color: $blue;
            &::before{
                background-image: url("data:image/svg+xml,%3Csvg width='7' height='11' viewBox='0 0 7 11' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M6 1L1 5.5L6 10' stroke='%233B37E6' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E");
            }
        }
        &::before{
            content: '';
            display: block;
            position: absolute;
            background-image: url("data:image/svg+xml,%3Csvg width='7' height='11' viewBox='0 0 7 11' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M6 1L1 5.5L6 10' stroke='%2316213D' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E");
            width: 7px;
            height: 11px;
            left: 2px;
            top: 50%;
            margin-top: -2px;
            transition:background-image .3s linear;
            transform: translateY(-50%);
        }
    }
}