.content-image {
    padding: 92px 0 75px;

    @include break(medium) {
        padding: 40px 0;
    }

    &.blue {
        border-color     : $blue;
        background-color : $light_blue_tint;

        .content-image__uptitle {
            color: $purple;
        }
    }
    &.purple {
        border-color : $purple;
        background-color: rgba(248, 243, 255, 0.80);

        .content-image__uptitle {
            color: $purple;
        }
    }
    &.light-blue {
        background-color : rgba($color : $light_blue, $alpha : 0.082);
        border-color : $light_blue;

        .content-image__uptitle {
            color: $malibu;
        }
    }

    &.apricot {
        border: 1px solid $apricot;
        background-color: $coral_tint;

        .content-image__uptitle {
            color: $apricot;
        }
    }

    &__content {
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: flex-start;
    }

    &__section-wrapper {
        display: flex;
        gap: 90px;

        @include break(medium) {
            flex-direction: column-reverse;
            align-items: center;
            gap: 30px;
        }

        &.columns-2 {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 16px;

            @include break(small) {
                grid-template-columns: 1fr;
                gap: 16px;
            }
        }
        &.columns-1 {
            display: grid;
            grid-template-columns: 1fr;
            gap: 20px;

            @include break(small) {
                grid-template-columns: 1fr;
                gap: 20px;
            }
        }
    }


    &__img {
        max-width: 510px;
        width: 100%;

        img {
            padding: 1px;
            max-width: 100%;
            @include break(medium) {
                max-width: 100%;
            }
        }
    }

    &__content {
        @include break(medium) {
            text-align: center;
        }
    }

    &__uptitle {
        margin-bottom: 16px;
        line-height: 1.2;
        @include break(x-small) {
            font-size: 22px !important;
        }
    }

    &__title {
        margin-bottom: 16px;
        line-height: 1.2;
        @include break(x-small) {
            font-size: 32px;
        }

        &.line_height1_4 {
            line-height: 1.4;
        }
    }

    &__description {
        font-size: 18px;
        margin-bottom: 24px;

        @include break(x-small) {
            font-size: 15px;
        }

        p {
            font-size: inherit;
        }
    }

    &__button {
        @extend .blue-btn;
    }
}
