.single-careers{
    .breadcrumbs{
        margin-top: 24px;
        margin-bottom: 32px;
        @include break(medium){
            margin-top: 24px;
            margin-bottom: 24px;
        }
        @include break(x-small){
            margin-top: 16px;
        }
    }
    &__wrapper{
        display: grid;
        grid-template-columns: 1fr 385px;
        column-gap: 20px;
        margin-bottom: 80px;
        @include break(desktop){
            grid-template-columns: 1fr 300px;
        }
        @include break(medium){
            grid-template-columns: 1fr;
            margin-bottom: 48px;
        }
    }
    &__heading{
        margin-bottom: 32px;
        @include break(medium){
            margin-bottom: 40px;
        }
    }
    &__tags{
        margin-top: 12px;
        display: flex;
        flex-wrap: wrap;
        @include break(medium){
            margin-top: 16px;
        }
    }
    &__tag{
        border: 1px solid;
        border-radius: 10px;
        padding: 5px 15px;
        font-size: 13px;
        line-height: 16px;
        font-family: $third_font;
        font-weight: 600;
        margin-bottom: 8px;
        &:not(:last-child){
            margin-right: 16px;
        }
    }
    &__title{
        font-size: 40px;
        line-height: 48px;
        margin-bottom: 2px;
        @include break(medium){
            font-size: 22px;
            line-height: 28px;
        }
    }
    &__excerpt{
        @include break(medium){
            font-size: 15px;
            line-height: 22px;
        }
    }
    &__aside{
        @include break(medium){
            margin-top: 20px;
        }
    }
    &__apply-form{
        // position: sticky;
        // top: 140px;
        &-wrapper{
            border-radius: 16px;
            padding: 31px 23px;
            background: $gret_blue;
            border: 1px solid $blue;
        }
        &-title{
            font-family: $third_font;
            font-weight: 600;
            font-size: 22px;
            line-height: 28px;
        }
        &-text{
            font-size: 15px;
            line-height: 22px;
            margin-top: 4px;
        }
        &-container{
            margin-top: 24px;
        }
    }
    &__share{
        transition:opacity .3s linear;
        margin: 0 6px;
        display: block;
        height: 24px;
        width: 24px;
        &:hover{
            opacity: 0.7;
        }
        &-wrapper{
            display: flex;
            align-items: center;
            &.desktop{
                margin-top: 12px;
                @include break(medium){
                    display: none;
                }
            }
            &.mobile{
                margin-top: 16px;
                display: none;
                @include break(medium){
                    display: flex;
                }
            }
        }
        &-text{
            font-size: 15px;
            line-height: 24px;
            color: #3C455A;
            margin-right: 6px;
        }
        &-block{
            display: flex;
            align-items: center;
        }
    }
    .book-a-demo{
        margin-top: 0;
    }
    .hbspt-form{
        .hs-recaptcha{
            display: none !important;
        }
        .submitted-message{
            font-size: 18px;
            line-height: 28px;
            padding: 10px 0 20px;
            color: $blue;
        }
        fieldset{
            display: grid;
            column-gap: 16px;
            max-width: 100% !important;
            &.form-columns-3{
                @include break(medium){
                    grid-template-columns: repeat(3, 1fr);
                }
                @include break(ss-small){
                    grid-template-columns: 1fr;
                }  
            }
            &.form-columns-2{
                @include break(medium){
                    grid-template-columns: repeat(2, 1fr);
                }
                @include break(ss-small){
                    grid-template-columns: 1fr;
                }       
            }
            & > .hs-form-field{
                margin-bottom: 16px;
            }
            .hs-dependent-field{
                .hs-form-field{
                    &:not(:first-child){
                        margin-top: 16px;
                    }
                }
            }
            .hs-form-field{
                width: 100% !important;
                float: none !important;
     
                & > label{
                    display: none !important;
                }
                &.hs-fieldtype-file{
         
                    & > label{
                        display: block !important;
                        span{
                            position: relative;
                            font-size: 15px;
                            line-height: 24px;
                            color: $blue;
                            padding-left: 26px;
                            cursor: pointer;
                            &::before{
                                content: '';
                                display: block;
                                background-image: url("data:image/svg+xml,%3Csvg width='22' height='22' viewBox='0 0 22 22' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M7.5625 12.375L8.53187 13.3444L10.3125 11.5706V19.9375H11.6875V11.5706L13.4681 13.3444L14.4375 12.375L11 8.9375L7.5625 12.375Z' fill='%233B37E6'/%3E%3Cpath d='M16.1563 15.125H15.8125V13.75H16.1563C16.9768 13.7828 17.7767 13.4884 18.3801 12.9314C18.9835 12.3744 19.341 11.6005 19.3738 10.78C19.4066 9.9595 19.1121 9.15955 18.5551 8.55615C17.9982 7.95275 17.2243 7.59533 16.4038 7.56251H15.8125L15.7438 6.99876C15.5912 5.84132 15.0232 4.77878 14.1454 4.00909C13.2676 3.23939 12.14 2.81501 10.9725 2.81501C9.80508 2.81501 8.67743 3.23939 7.79965 4.00909C6.92187 4.77878 6.3538 5.84132 6.20128 6.99876L6.18753 7.56251H5.59628C4.77576 7.59533 4.00189 7.95275 3.44491 8.55615C2.88793 9.15955 2.59345 9.9595 2.62627 10.78C2.6591 11.6005 3.01652 12.3744 3.61992 12.9314C4.22332 13.4884 5.02326 13.7828 5.84378 13.75H6.18753V15.125H5.84378C4.7413 15.118 3.68033 14.7037 2.86483 13.9618C2.04933 13.2199 1.53687 12.2027 1.42599 11.1058C1.31511 10.0089 1.61362 8.90972 2.26414 8.0196C2.91465 7.12948 3.87126 6.51124 4.95002 6.28376C5.24682 4.89949 6.00935 3.65887 7.11037 2.76889C8.21138 1.87892 9.5843 1.39343 11 1.39343C12.4158 1.39343 13.7887 1.87892 14.8897 2.76889C15.9907 3.65887 16.7532 4.89949 17.05 6.28376C18.1288 6.51124 19.0854 7.12948 19.7359 8.0196C20.3864 8.90972 20.6849 10.0089 20.5741 11.1058C20.4632 12.2027 19.9507 13.2199 19.1352 13.9618C18.3197 14.7037 17.2587 15.118 16.1563 15.125Z' fill='%233B37E6'/%3E%3C/svg%3E");
                                width: 22px;
                                height: 22px;
                                background-position: center;
                                background-repeat: no-repeat;
                                position: absolute;
                                left: 0;
                            }
                        }
                    }
                    input[type="file"]{
                        cursor: pointer;
                        padding-left: 26px;
                        &::-webkit-file-upload-button,
                        &::file-selector-button{
                            display: none;
                        }
                    }
                }
                .hs-error-msgs{
                    margin-top: 5px;
                }
                input[type="text"],
                input[type="email"],
                input[type="tel"]{
                    height: 48px;
                    width: 100% !important;
                    padding: 10px 16px;
                    font-size: 13px;
                    line-height: 16px;
                    color: $dark;
                    background-color: $white;
                    border: 1px solid rgba(22, 33, 61, 0.1);
                    border-radius: 10px;
                    &.error{
                        border-color: $red;
                    }
                    &::placeholder{
                        color: rgba(22, 33, 61, 0.4);
                    }
                }
                select{
                    height: 48px;
                    width: 100%;
                    padding: 10px 35px 10px 16px;
                    font-size: 13px;
                    line-height: 16px;
                    color: $dark;
                    background-color: $white;
                    border: 1px solid rgba(22, 33, 61, 0.1);
                    border-radius: 10px;
                    -moz-appearance:none; /* Firefox */
                    -webkit-appearance:none; /* Safari and Chrome */
                    appearance:none;
                    background-image: url("data:image/svg+xml,%3Csvg width='14' height='8' viewBox='0 0 14 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M13 1L7 7L1 0.999999' stroke='%233B37E6'/%3E%3C/svg%3E%0A");
                    background-position:center right 19px;
                    background-repeat: no-repeat;
                    // &:active,
                    // &:focus{
                    //   background-image: url("data:image/svg+xml,%3Csvg width='14' height='8' viewBox='0 0 14 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 7L7 1L13 7' stroke='%233B37E6'/%3E%3C/svg%3E");
                    // }
                    &.error{
                        border-color: $red;
                    }
                    &::placeholder{
                        color: rgba(22, 33, 61, 0.4);
                    }
                }
            }
            .input{
                margin-left: 0 !important;
                margin-right: 0 !important;
            }
            &.form-columns-1{
                //margin-bottom: 16px;
                .legal-consent-container{
                    .field.hs-form-field{
                        margin-bottom: 0;
                    }
                }
            }
            &.form-columns-0{
                margin-bottom: 16px;
            }
            .hs-dependent-field{
                margin-bottom: 16px;
            }
            .inputs-list{
                .hs-form-booleancheckbox{
                    &:not(:first-child){
                        margin-bottom: 16px;
                    }
                }
                .hs-form-booleancheckbox-display{
                    input[type="checkbox"]{
                        display: none !important;
                        &:checked ~ span::before{
                            background-image: url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M2 0C1.46957 0 0.960859 0.210714 0.585786 0.585786C0.210714 0.960859 0 1.46957 0 2L0 14C0 14.5304 0.210714 15.0391 0.585786 15.4142C0.960859 15.7893 1.46957 16 2 16H14C14.5304 16 15.0391 15.7893 15.4142 15.4142C15.7893 15.0391 16 14.5304 16 14V2C16 1.46957 15.7893 0.960859 15.4142 0.585786C15.0391 0.210714 14.5304 0 14 0L2 0ZM12.03 4.97C12.1689 5.10875 12.2479 5.29644 12.2499 5.49275C12.252 5.68907 12.177 5.87837 12.041 6.02L8.049 11.01C7.98039 11.0839 7.89758 11.1432 7.80553 11.1844C7.71348 11.2255 7.61407 11.2477 7.51325 11.2496C7.41243 11.2514 7.31227 11.233 7.21876 11.1952C7.12524 11.1575 7.0403 11.1013 6.969 11.03L4.324 8.384C4.25031 8.31534 4.19121 8.23254 4.15022 8.14054C4.10923 8.04854 4.08718 7.94923 4.08541 7.84852C4.08363 7.74782 4.10216 7.64779 4.13988 7.5544C4.1776 7.46101 4.23374 7.37618 4.30496 7.30496C4.37618 7.23374 4.46101 7.1776 4.5544 7.13988C4.64779 7.10216 4.74782 7.08363 4.84852 7.08541C4.94923 7.08718 5.04854 7.10923 5.14054 7.15022C5.23254 7.19121 5.31534 7.25031 5.384 7.324L7.478 9.417L10.951 4.992C11.0195 4.91797 11.1022 4.85851 11.1942 4.81717C11.2861 4.77583 11.3855 4.75347 11.4863 4.75141C11.5871 4.74936 11.6873 4.76766 11.7809 4.80522C11.8745 4.84277 11.9596 4.89882 12.031 4.97H12.03Z' fill='%233B37E6'/%3E%3C/svg%3E%0A");
                        }
                    }
                    span{
                        padding-left: 24px;
                        margin: 0;
                        position: relative;
                        cursor: pointer;
                        *{
                            font-size: 13px;
                            line-height: 18px;
                        }
                        a{
                            font-weight: 600;
                            &:hover{
                                text-decoration: underline;
                            }
                        }
                        &::before{
                            content: '';
                            display: block;
                            width: 16px;
                            height: 16px;
                            position: absolute;
                            left: 0;
                            top: 50%;
                            transform: translateY(-50%);
                            background-image: url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M14 1C14.2652 1 14.5196 1.10536 14.7071 1.29289C14.8946 1.48043 15 1.73478 15 2V14C15 14.2652 14.8946 14.5196 14.7071 14.7071C14.5196 14.8946 14.2652 15 14 15H2C1.73478 15 1.48043 14.8946 1.29289 14.7071C1.10536 14.5196 1 14.2652 1 14V2C1 1.73478 1.10536 1.48043 1.29289 1.29289C1.48043 1.10536 1.73478 1 2 1H14ZM2 0C1.46957 0 0.960859 0.210714 0.585786 0.585786C0.210714 0.960859 0 1.46957 0 2L0 14C0 14.5304 0.210714 15.0391 0.585786 15.4142C0.960859 15.7893 1.46957 16 2 16H14C14.5304 16 15.0391 15.7893 15.4142 15.4142C15.7893 15.0391 16 14.5304 16 14V2C16 1.46957 15.7893 0.960859 15.4142 0.585786C15.0391 0.210714 14.5304 0 14 0L2 0Z' fill='%233B37E6' fill-opacity='1'/%3E%3C/svg%3E%0A");
                            background-position: center;
                            background-repeat: no-repeat;
                        }
                    }
                }
            }
            .hs-richtext{
                *{
                    font-size: 13px;
                    line-height: 18px;
                }
                a{
                    font-weight: 600;
                    &:hover{
                        text-decoration: underline;
                    }
                }
            }
        }
        .hs-submit{
            margin-top: 24px;
            .actions{
                @include break(medium){
                    text-align: center;
                }
            }
            input[type="submit"]{
                @extend .blue-btn;
                cursor: pointer;
                @include break(medium){
                    font-size: 15px;
                    line-height: 24px;
                    padding: 10px 15px;
                    width: 100%;
                    max-width: 340px;
                    border-radius: 15px;          
                }
                @include break(ss-small){
                    max-width: none;
                }
            }
        }
        .hs_error_rollup{
            .hs-error-msgs{
                .hs-main-font-element{
                    text-align: center;
                    font-size: 16px;
                    line-height: 24px;
                }
            }
        }
        .hs-error-msgs{
            .hs-main-font-element,
            .hs-error-msg{
                color: $red;
                font-size: 12px;
                line-height: 14px;
            }
        }
    }
}
.related-careers{
    &__container{
        padding-left: 30px;
        padding-right: 30px;
        @include break(ss-small){
            padding-left: 16px;
            padding-right: 16px;
        }
    }
    &__wrapper{
        max-width: 1220px;
        margin-left: auto;
        margin-right: auto;
        margin-bottom: 40px;
        @include break(medium){
            margin-bottom: 24px;
        }
    }
    &__title{
        font-size: 40px;
        line-height: 48px;
        margin-bottom: 32px;
        text-align: center;
        @include break(medium){
            font-size: 22px;
            line-height: 28px;
            margin-bottom: 16px;
        }
        @include break(x-small){
            margin-bottom: 24px;
        }
    }
    &__list{
        display: flex;
        justify-content: center;
        flex-wrap: wrap;
        // &-1, &-2{
        //   .careers-card{
        //     width: 50%;
        //     @include break(ss-small){
        //       width: 100%;
        //     }
        //   }
        // }
    }
    .careers-card{
        margin-bottom: 0;
        @include break(ss-small){
            &:not(:last-child){
                margin-bottom: 20px;
            }
        }
        &:nth-child(3){
            @include break(medium){
                display: none;
            }
            @include break(ss-small){
                display: block;
            }
        }
    }
}
.apply-now-btn{
    z-index: 1000;
    width: calc(100% - 80px);
    position: fixed;
    left: 50%;
    transform: translateX(-50%);
    bottom: 16px;
    color: $white;
    border: none;
    background-color: $blue;
    border-radius: 15px;
    padding: 10px 30px;
    font-size: 15px;
    line-height: 24px;
    display: none;
    visibility: hidden;
    opacity: 0;
    transition: .3s linear;
    transition-property: opacity, visibility;
    @include break(ss-small){
        display: block;
    }
    &.active{
        visibility: visible;
        opacity: 1;
    }
}