.all-faqs {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top : 80px;
    }
    @include break(s-small) {
        margin-bottom : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__title {
        text-align    : center;
        margin-bottom : 24px;
        @include break(medium) {
            font-size   : 22px;
            line-height : 28px;
        }
    }

    &__filters {
        display         : flex;
        justify-content : center;
        margin-bottom   : 32px;
        @include break(s-small) {
            flex-direction : column;
            align-items    : center;
            gap            : 20px;
        }
    }

    .load-more-wrapper {
        margin-top : 20px;
    }

}