.primary-wrapper {
    .hero-form {
        &:last-of-type {
            margin-bottom: 0;
        }
        &:first-child {
            margin-top: 0;
        }
    }
}

.hero-form {
    margin-top: $desktop_margin;
    margin-bottom : 23px;
    @include break(medium) {
        margin-bottom : 20px;
    }
    @include break(s-small) {
        margin-top: $mobile_margin;
        margin-bottom : 0;
    }

    .image-border {
        border-radius : 24px;
        border        : 1px solid;
        @include break(medium) {
            border-radius : 12px;
        }
        @include break(s-small) {
            border: none;
            border-radius : 15px;
        }
    }
    .mask,
    .figure{
        @include break(s-small) {
            position: absolute;
            background-position: center;
            background-repeat: no-repeat;
            display: flex;
            z-index: 10;
            right: 0;
            top: 0;
        }
    }
    .mask{
        top: -1px;
        width: 140px;
        height: 174px;
        @include break(s-small) {
            background-image: url('data:image/png;base64,');
            top: 0;
        }
    }
    .figure {
        transform: scale(-1);
        @include break(s-small) {
            background-image : url("data:image/svg+xml,%3Csvg width='109' height='137' viewBox='0 0 109 137' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0.5 6.74101L0.500001 115.553C0.500001 127.122 9.87807 136.5 21.4465 136.5L102.134 136.5C106.959 136.5 109.68 130.957 106.729 127.14L10.9026 3.1888C7.51511 -1.19293 0.5 1.20254 0.5 6.74101Z' fill='%23ECDEFF' stroke='%23A142FF'/%3E%3C/svg%3E");
            width: 109px;
            height: 137px;
        }
    }

