                }
            }
        }

        .hs-richtext {
            * {
                font-size   : 13px;
                line-height : 18px;
            }
            span {
                color : $black!important;
            }
            a {
                font-weight : 600;
                text-decoration : underline;
                &:hover {
                    text-decoration : none;
                }
            }
        }

        .hs-submit {
            margin-top : 12px;

            .actions {
                @include break(medium) {
                    text-align : center;
                }
            }
            input:is([type="submit"]),
            input[type="submit"] {
                @extend .blue-btn;
                cursor : pointer;
                padding: 9px 29px;
                @include break(medium) {
                    font-size     : 15px;
                    line-height   : 24px;
                    padding       : 10px 15px;
                    border-radius : 15px;
                }
                @include break(small) {
                    width : 100%;
                }
            }
        }

        .hs_error_rollup {
            .hs-error-msgs {
                .hs-main-font-element {
                    text-align  : center;
                    font-size   : 16px;
                    line-height : 24px;
                    padding-bottom: 0;
                }
            }
        }

        .hs-error-msgs {
            .hs-main-font-element,
            .hs-error-msg {
                color       : $red;
                font-size   : 12px;
                line-height : 14px;
            }
        }
    }

    &__button-wrapper {
        text-align: center;
    }
    &__play-btn {
        cursor           : pointer;
        position         : absolute;
        left             : 0;
        top              : 0;
        width            : 100%;
        height           : 100%;
        background-color : transparent;
        border           : none !important;
        z-index          : 200;
        display          : flex;
        justify-content  : center;
        align-items      : center;
        padding          : 118px 147px 81px 99px;
        @include break(desktop) {
            padding : 83px 58px 58px 71px;
        }
        @include break(medium) {
            padding : 65px 46px 44px 56px;
        }
        @include break(ss-small) {
            padding : 47px 33px 33px 40px;
        }
        @include break(s-small) {
            padding : 67px 48px 46px 57px;
        }
        @include break(x-small) {
            padding : 56px 41px 40px 49px;
        }
        @include break(small-360) {
            padding : 50px 36px 35px 42px;
        }

        * {
            pointer-events : none;
        }

        svg {
            circle {
                transition : all .4s ease-in-out;
            }
            parth {
                transition : all .5s ease-in-out;
            }

            @include break(medium) {
                width  : 81px;
                height : 93px;
            }
        }
        &:hover {
            svg {
                circle {
                    fill : $blue;
                }
                path {
                    fill : $royal_blue;
                }
            }
        }
    }
}