        &.active {
            display : block;
        }
    }

    &__load-more {
        font-size        : 16px;
        line-height      : 18px;
        color            : $blue;
        padding          : 0 0 10px 0;
        position         : relative;
        background-color : transparent;
        border           : none;
        cursor           : pointer;
        transition       : color .3s linear;
        @include break(medium) {
            font-size      : 14px;
            line-height    : 17px;
            padding-bottom : 0;
            padding-right  : 15px;
        }
        @include break(s-small) {
            font-size      : 14px;
            line-height    : 22px;
            padding-bottom : 0;
            padding-right  : 0;
        }

        &:hover {
            color : $dark;

            &::before {
                bottom           : -8px;
                background-image : url("data:image/svg+xml,%3Csvg width='11' height='8' viewBox='0 0 11 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1.85742L5.5 6.85742L10 1.85742' stroke='%2316213D' stroke-width='1.3' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E%0A");
                @include break(medium) {
                    bottom : -6px;
                }
            }
        }

        &::before {
            content             : '';
            display             : block;
            background-image    : url("data:image/svg+xml,%3Csvg width='11' height='8' viewBox='0 0 11 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1.85742L5.5 6.85742L10 1.85742' stroke='%233B37E6' stroke-width='1.3' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E%0A");
            background-repeat   : no-repeat;
            background-position : center;
            width               : 11px;
            height              : 8px;
            position            : absolute;
            left                : 50%;
            transform           : translateX(-50%);
            bottom              : 0;
            transition          : background-image, bottom .3s linear;
            @include break(medium) {
                bottom    : auto;
                right     : 0;
                top       : 50%;
                left      : auto;
                transform : translateY(-50%);
            }
            @include break(s-small) {
                bottom    : -6px;
                right     : auto;
                top       : auto;
                left      : 50%;
                transform : translateX(-50%);
            }
        }
    }
