@mixin adaptive-size($level) {
    font-size: calc(var(--adaptive_size_#{$level}_desktop_1200) * 1px);

    @media screen and (max-width: 1200px) {
        font-size: calc(var(--adaptive_size_#{$level}_desktop_1200) * 1px);
    }

    @media screen and (max-width: 1024px) {
        font-size: calc(var(--adaptive_size_#{$level}_tablet_1024) * 1px);
    }

    @media screen and (max-width: 768px) {
        font-size: calc(var(--adaptive_size_#{$level}_mobile_768) * 1px);
    }

    @media screen and (max-width: 470px) {
        font-size: calc(var(--adaptive_size_#{$level}_mobile_470) * 1px);
        line-height: if($level ==1, 1.12, if($level ==2, 1.16, if($level ==3, 1.2, if($level ==4, 1.11, null))));
    }
}

@for $i from 1 through 5 {
    .adaptive-size-#{$i} {
        @include adaptive-size($i);
    }
}
