.cards-with-logo {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;

    &.zero-top-margin {
        margin-top : 0;
    }

    &.styled-bg {
        position    : relative;
        padding-top : 119px;
        isolation   : isolate;

        @include break(medium) {
            padding-top : 70px;
        }
        @include break(ss-small) {
            padding-top : 50px;
        }

        &::after {
            content          : '';
            display          : block;
            width            : 100%;
            height           : 143px;
            background-color : $white;
            position         : absolute;
            left             : 0;
            bottom           : 0;
            z-index          : -1;
            @include break(medium) {
                height : 71px;
            }
            @include break(ss-small) {
                height : 100px;
            }
        }
    }

    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__container {
        @include break(ss-small) {
            padding-left  : 0;
            padding-right : 0;
        }
    }

    &__wrapper {
        max-width    : 1200px;
        margin-left  : auto;
        margin-right : auto;
    }

    &__title {
        text-align : center;
        @include break(ss-small) {
            margin-left   : auto;
            margin-right  : auto;
            padding-left  : 16px;
            padding-right : 16px;
            max-width     : 360px;
        }
        @include break(x-small) {
            max-width : 280px;

        }
    }

    &__text {
        text-align   : center;
        max-width    : 680px;
        margin-left  : auto;
        margin-right : auto;
        margin-top   : 20px;
        @include break(medium) {
            margin-top    : 24px;
            max-width     : 580px;
            margin-bottom : 47px;
        }
        @include break(ss-small) {
            padding-left  : 16px;
            padding-right : 16px;
        }
        @include break(x-small) {
            margin-top    : 20px;
            margin-bottom : 20px;
            font-size     : 14px;
            line-height   : 20px;
        }
    }

    &__slider {
        margin-top : 55px;
        @include break(medium) {
            margin-top : 40px;
        }
        @include break(ss-small) {
            margin-top : 25px;
        }
        @include break(x-small) {
            margin-top : 10px;
        }

        &.animate {
            @media screen and (min-width : 571px) {
                .cards-with-logo__card.animation-item {
                    opacity   : 1;
                    transform : translate(0, 0);
                }
            }
        }

        &.swiper {
            overflow : visible;
            @include break(ss-small) {
                overflow : hidden;
                padding  : 15px 30px;
            }

            .swiper-pagination {
                display    : none;
                margin-top : 35px;

                @include break(s-small) {
                    display : flex;
                }
            }
        }
    }

    &__block {
        @media screen and (min-width : 571px) {
            display               : grid;
            grid-template-columns : repeat(3, 1fr);

            column-gap            : 20px;
            row-gap               : 20px;
            grid-column-gap       : 20px;
            grid-row-gap          : 20px;
        }
        @include break(medium) {
            column-gap      : 11px;
            row-gap         : 11px;
            grid-column-gap : 11px;
            grid-row-gap    : 11px;
        }
        @include break(s-small) {
            column-gap      : 0;
            row-gap         : 0;
            grid-column-gap : 0;
            grid-row-gap    : 0;
        }
    }

    &__card {
        display    : flex;
        height     : 100%;
        min-height : 285px;
        @media screen and (min-width : 571px) {
            opacity      : 0;
            width        : auto !important;
            margin-left  : 0 !important;
            margin-right : 0 !important;
            transition   : opacity .2s cubic-bezier(0.165, 0.84, 0.44, 1);
            &.hide {
                display : none;
            }
            &.show {
                opacity : 1;
            }
            &.animation-item {
                transform  : translate(0, 60px);
                transition : opacity .2s, transform .8s cubic-bezier(0.165, 0.84, 0.44, 1);
            }
            @for $i from 1 through 3 {
                &:nth-child(#{$i}) {
                    transition-delay : #{$i * 0.2}s;
                }
            }
        }
        @include break(medium) {
            min-height : auto;
        }
        @include break(ss-small) {
            max-width : 100%;
            height    : auto;
        }

        &-container {
            display          : flex;
            flex-direction   : column;
            justify-content  : space-between;
            height           : 100%;
            width            : 100%;
            border-radius    : 19px;
            background-color : $white;
            padding          : 20px 40px 30px 30px;
            box-shadow       : 0px 3px 15px rgba(59, 55, 230, 0.2);
            transition       : box-shadow .3s linear;
            @include break(medium) {
                padding       : 11px 20px 11px 18px;
                border-radius : 10px;
                box-shadow    : 0px 1.70625px 8.53125px rgba(59, 55, 230, 0.2);
            }
            @include break(ss-small) {
                height        : auto;
                padding       : 11px 40px 20px 32px;
                border-radius : 15px;
                box-shadow    : 0px 2.42338px 12.1169px rgba(59, 55, 230, 0.2);
            }
            @media screen and (min-width : 992px) {
                &:hover {
                    box-shadow : 0px 3px 15px rgba(59, 55, 230, 0.34);

                    .cards-with-logo__card-more {
                        color : $dark;

                        &::after {
                            background-image : url("data:image/svg+xml,%3Csvg width='8' height='11' viewBox='0 0 8 11' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1.5 10L7.5 5.5L1.5 1' stroke='%2316213D' stroke-width='1.3' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E%0A");
                            @include break(medium) {
                                background-image : url("data:image/svg+xml,%3Csvg width='6' height='8' viewBox='0 0 6 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1.56207 7.33093L5.61912 4.28815L1.56207 1.24536' stroke='%2316213D' stroke-width='0.879026' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E%0A");
                            }
                            @include break(ss-small) {
                                background-image : url("data:image/svg+xml,%3Csvg width='8' height='12' viewBox='0 0 8 12' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1.14062 10.5932L7.26399 6.00072L1.14062 1.4082' stroke='%2316213D' stroke-width='1.32673' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E%0A");
                            }
                        }
                    }
                }
            }
        }

        &-image {
            display         : flex;
            align-items     : center;
            justify-content : flex-start;
            width           : 170px;
            height          : 130px;
            @include break(medium) {
                width  : 96px;
                height : 74px;
            }
            @include break(x-small) {
                width  : 78px;
                height : 46px;
            }

            picture, img, svg {
                display    : block;
                max-width  : 100%;
                max-height : 100%;
                width      : auto;
                height     : 100%;
                object-fit : contain;
            }

            & > img, & > svg {
                height : auto;
            }
        }

        &-text {
            margin-top : 5px;
            @include break(x-small) {
                margin-top : 1px;

            }
        }

        &-more-wrapper {
            margin-top : 10px;
            @include break(medium) {
                margin-top : 15px;
            }
        }

        &-more {
            display       : inline-block;
            font-size     : 16px;
            line-height   : 24px;
            color         : $blue;
            padding-right : 24px;
            position      : relative;
            transition    : color .3s linear;
            @include break(medium) {
                padding-right : 16px;
            }
            @include break(ss-small) {
                padding-right : 20px;
            }

            &::after {
                content             : '';
                display             : block;
                width               : 16px;
                height              : 16px;
                position            : absolute;
                right               : 0;
                top                 : 50%;
                background-image    : url("data:image/svg+xml,%3Csvg width='8' height='11' viewBox='0 0 8 11' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1.5 10L7.5 5.5L1.5 1' stroke='%233B37E6' stroke-width='1.3' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E%0A");
                background-position : center;
                background-repeat   : no-repeat;
                transition          : background-image .3s linear;
                transform           : translateY(-50%);
                @include break(medium) {
                    background-image : url("data:image/svg+xml,%3Csvg width='6' height='8' viewBox='0 0 6 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1.56207 7.33093L5.61912 4.28815L1.56207 1.24536' stroke='%233B37E6' stroke-width='0.879026' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E%0A");
                    width            : 11px;
                    height           : 11px;
                }
                @include break(ss-small) {
                    background-image : url("data:image/svg+xml,%3Csvg width='8' height='12' viewBox='0 0 8 12' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1.14062 10.5932L7.26399 6.00072L1.14062 1.4082' stroke='%233B37E6' stroke-width='1.32673' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E%0A");
                    width            : 20px;
                }
            }
        }
    }

    &__button-wrapper {
        margin-top : 60px;
        text-align : center;
        @include break(medium) {
            margin-top : 35px;
        }
        @include break(s-small) {
            display : none;
        }
    }

    &__button {
        color            : $blue;
        font-size        : 16px;
        line-height      : 24px;
        padding          : 0 0 12px 0;
        border           : none;
        background-color : transparent;
        position         : relative;
        cursor           : pointer;
        transition       : color .3s linear;

        &:hover {
            color : $dark;

            &::after {
                transform        : translateY(6px);
                background-image : url("data:image/svg+xml,%3Csvg width='11' height='7' viewBox='0 0 11 7' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1L5.5 6L10 1' stroke='%2316213D' stroke-width='1.3' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E%0A");
            }
        }

        &::after {
            content             : '';
            display             : block;
            width               : 100%;
            height              : 8px;
            background-image    : url("data:image/svg+xml,%3Csvg width='11' height='7' viewBox='0 0 11 7' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1L5.5 6L10 1' stroke='%233B37E6' stroke-width='1.3' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E%0A");
            background-position : center;
            background-repeat   : no-repeat;
            position            : absolute;
            left                : 0;
            bottom              : 0;
            transition          : background-image, transform .3s linear;
        }
    }
}