.contact-info{
    margin-top: $desktop_margin;
    margin-bottom: $desktop_margin;
    @include break(medium){
        margin-bottom: $mobile_margin;
        margin-top: $mobile_margin;
    }
    &__container{
        padding-left: 28px;
        padding-right: 28px;
        @include break(ss-small){
            padding-left: 4px;
            padding-right: 4px;
        }
        @include break(s-small){
            padding-left: 16px;
            padding-right: 16px;
        }
    }
    &__wrapper{
        max-width: 1224px;
    }
    &__title{
        text-align: center;
        margin-bottom: 8px; 
        padding: 0 12px;
        @include break(medium){
            font-size: 40px;
            line-height: 48px;
        }
        @include break(s-small){
            font-size: 22px;
            line-height: 28px;
            padding: 0;
        }
    }
    &__text{
        font-size: 18px;
        line-height: 28px;
        text-align: center;
        padding: 0 12px;
        @include break(s-small){
            padding: 0;
        }
    }
    &__list{
        display: flex;
        justify-content: center;
        gap: 24px 0;
        flex-wrap: wrap;
        margin-top: 32px;
        @include break(s-small){
            gap: 16px;
            margin-top: 24px;
        }
    }
    &__address{
        padding: 0 12px;
        width: 33.333%;
        @include break(medium){
            width: 50%;
        }
        @include break(s-small){
            padding: 0;
            width: 100%;
        }
        &-wrapper{
            border-radius: 16px;
            border: 1px solid $blue;
            padding: 16px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            gap: 32px;
            height: 100%;
        }
        &-info{
            display: flex;
            flex-direction: column;
            gap: 16px;
            justify-content: space-between;
            height: 100%;
        }
        &-name{
            font-size: 22px;
            line-height: 24px;
            color: #3C455A;
            margin-bottom: 16px;
        }
        &-country{
            font-size: 18px;
            line-height: 28px;
            margin-bottom: 4px;
            font-weight: 600;
        }
        &-address{
            font-size: 18px;
            line-height: 28px;
        }
        &-phone{
            position: relative;
            padding-left: 22px;
            font-size: 18px;
            line-height: 28px;
            &::before{
                content: '';
                display: block;
                width: 18px;
                height: 28px;
                background-image: url("data:image/svg+xml,%3Csvg width='18' height='18' viewBox='0 0 18 18' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M11.4353 12.0825L12.6953 10.8225C12.865 10.6549 13.0797 10.5402 13.3134 10.4923C13.547 10.4443 13.7896 10.4653 14.0116 10.5525L15.5472 11.1656C15.7715 11.2567 15.9639 11.4121 16.1 11.6123C16.2361 11.8125 16.31 12.0486 16.3122 12.2906V15.1031C16.3109 15.2678 16.2763 15.4306 16.2104 15.5815C16.1446 15.7325 16.0488 15.8685 15.929 15.9815C15.8092 16.0945 15.6677 16.1821 15.5132 16.239C15.3586 16.2959 15.1942 16.3209 15.0297 16.3125C4.26905 15.6431 2.0978 6.53065 1.68718 3.04315C1.66812 2.87189 1.68553 2.69853 1.73828 2.53448C1.79103 2.37044 1.87791 2.21942 1.99322 2.09136C2.10852 1.96331 2.24963 1.86111 2.40727 1.79151C2.5649 1.7219 2.73549 1.68647 2.9078 1.68752H5.62468C5.86712 1.68824 6.10381 1.76147 6.30429 1.8978C6.50477 2.03413 6.65989 2.22732 6.74968 2.45252L7.3628 3.98815C7.45295 4.20925 7.47594 4.45201 7.42892 4.6861C7.38191 4.9202 7.26695 5.13525 7.09843 5.3044L5.83843 6.5644C5.83843 6.5644 6.56405 11.475 11.4353 12.0825Z' fill='%2316213D' fill-opacity='0.7'/%3E%3C/svg%3E%0A");
                background-position: center left;
                background-repeat: no-repeat;
                position: absolute;
                left: 0;
                top: 0;
            }
        }
        &-phone-link{
            font-weight: 600;
            margin-left: 4px;
            &:hover{
                text-decoration: underline;
            }
        }
        &-button{
            @extend .arrow-btn-right; 
            font-weight: 600;
        }
    }
}