.lang-popup-box-center {
    top       : 50%;
    left      : 50%;
    transform : translate(-50%, -50%);
    position: fixed;
}
.lang-popup-consent-overlay{
    background-color: $dark;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 99999999;
    opacity: 0;
    display: none;
}
.lang-popup-consent-container.js-language-popup {
    direction : ltr;
    z-index   : 99999999;
    width     : 590px;
    max-width : calc(100% - 30px);
    background-color: $dark;
    border-radius: 20px;
    text-align: center;
    @include break(medium){
        max-width: 530px;
        width: calc(100% - 30px);
    }
    .lang-popup-consent-bar {
        padding : 48px 24px;
    }

    .lang-popup-close {
        position   : absolute;
        cursor     : pointer;
        top        : 20px;
        right      : 20px;
        transition : opacity .3s;

        &:hover {
            opacity : .5;
        }
    }

    .lang-popup-notice {
        .lang-popup-title {
            font-weight : 600;
            font-size   : 22px;
            line-height : 28px;
            font-family : $third_font;
            color: $white;
            margin-bottom: 16px;
        }

        .lang-popup-notice-group {
            .lang-popup-notice-des {
                p {
                    font-size   : 15px;
                    line-height : 22px;
                    text-align  : center;
                    color: $white;
                    font-family: $second_font;
                }
            }

            .lang-popup-notice-btn-wrapper {
                justify-content : center;
                gap             : 20px;
                margin-top      : 32px;
                display: flex;
                @include break(x-small){
                    flex-direction: column;
                    align-items: center;
                }
                .lang-popup-btn {
                    cursor: pointer;
                    margin  : 0;
                    flex    : unset;
                    padding : 6px 19px;
                    font-size: 15px;
                    line-height: 24px;
                    color: $white;
                    border: 1px solid $white;
                    border-radius: 10px;
                    background-color: transparent;
                    transition: .3s linear;
                    transition-property: background-color, color;
                    &:hover{
                        background-color: $white;
                        color: $dark;
                    }
                    &-accept {
                        background-color : $blue;
                        border-color: $blue;
                        &:hover{
                            background-color: $white;
                            color: $dark;
                            border-color: $white;
                        }
                    }
                }
            }
        }

    }
}