#primary-wrapper .webinar-speakers {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;

    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__title.h2-title {
        text-align    : center;
        margin-bottom : 32px;
        max-width     : none;
        font-size     : 40px;
        line-height   : 48px;
        @include break(medium) {
            font-size   : 22px;
            line-height : 28px;
            padding: 0 16px;
        }
        @include break(ss-small) {
            margin-bottom : 24px;
        }
    }

    &__wrapper {
        row-gap         : 20px;
        column-gap      : 20px;
        max-width: 972px;
        margin: 0 auto;
        display: grid;
        grid-template-columns: 1fr 1fr;

        &.single {
            display: flex;
            align-items : center;
            max-width: 476px;
        }

        @include break(medium) {
            display: flex;
            flex-direction : column;
            align-items : center;
        }
        @include break(ss-small) {
            padding-left: 16px;
            padding-right: 16px;
        }
    }

    &__item {
        width : 100%;
        padding: 16px;
        display: grid;
        grid-template-columns: 164px 1fr;
        border: 1px solid $blue;
        border-radius: 20px;
        gap: 16px;

        @include break(medium) {
            max-width: 476px;
        }
        @include break(s-small) {
            grid-template-columns: 1fr;
        }

        &-description {
            display : flex;
            flex-direction: column;
            gap: 8px;

            @include break(s-small) {
                text-align: center;
            }
        }

        &-image {
            border-radius : 20px;
            display       : block;
            width         : 100%;
            height        : auto;
            max-width     : 269px;
            margin-left   : auto;
            margin-right  : auto;

        }

        &-name {
            font-size     : 22px;
            line-height   : 28px;
        }

        &-position {
            font-size     : 15px;
            line-height   : 24px;
            font-family   : $main_font;
            margin-bottom : 0;
        }

        &-text {
            font-size     : 13px;
            line-height   : 18px;
            margin-bottom : 0;
        }
    }
}