.side-image-content-general {
    margin-top    : $desktop_margin;
    margin-bottom : $desktop_margin;
    @include break(medium) {
        margin-top    : $mobile_margin;
        margin-bottom : $mobile_margin;
    }

    &__container {
        &.js-animate-parent {
            &.animate {
                .js-animate-element {
                    opacity   : 1;
                    transform : translate3d(0, 0, 0);
                }
            }
        }

        .js-animate-element {
            transition : opacity .4s, transform .8s cubic-bezier(0.165, 0.84, 0.44, 1);
            opacity    : 0;
            transform  : translate3d(0, 50%, 0);
        }
    }

    &__wrapper {
        display               : grid;
        grid-column-gap       : 48px;
        grid-row-gap          : 20px;
        gap                   : 20px 48px;
        align-items           : center;
        grid-template-columns : 1fr 488px;
        @include break(desktop) {
            grid-template-columns : 1fr 400px;
            grid-column-gap       : 20px;
            gap                   : 20px;
        }
        @include break(medium850) {
            grid-template-columns : 1fr 334px;
        }
        @include break(s-small) {
            grid-template-columns : 1fr;
        }

        &.reverse {
            grid-template-columns :488px 1fr;
            @include break(desktop) {
                grid-template-columns :400px 1fr;
            }
            @include break(medium850) {
                grid-template-columns :334px 1fr;
            }
            @include break(s-small) {
                grid-template-columns : 1fr;
            }
        }

        &-v3 {

        }

        &-v4,
        &-v5 {
            @include break(medium) {
                grid-template-columns : 1fr;
            }

            &.reverse {
                @include break(medium) {
                    grid-template-columns : 1fr;
                }
            }
        }
    }

    &__media {
        position : relative;

        &.reverse {
            order : 1;
        }

        a.no-mask {
            display         : block;
            width           : 100%;
            height          : 372px;
            display         : flex;
            justify-content : center;
            align-items     : center;
            padding         : 30px;
            @include break(medium) {
                height : 298px;

            }
            @include break(s-small) {
                min-height : 280px;
                height     : auto;
            }
        }

        &-v5 {
            a.no-mask {
                @include break(medium) {
                    height : 372px;
                }
                @include break(s-small) {
                    min-height : 280px;
                    height     : auto;
                }
            }
        }

        @include break(medium) {
            &-v4,
            &-v5 {
                &,
                &.reverse {
                    order : 1;
                }
            }
        }
        @include break(s-small) {
            &,
            &.reverse {
                order : 2;
            }
        }

        .mask,
        .figure {
            position            : absolute;
            background-position : center;
            background-repeat   : no-repeat;
            display             : flex;
            z-index             : 10;

            &.top-right {
                right : 0;
                top   : 0;
            }

            &.top-left {
                left : 0;
                top  : 0;
            }

            &.bottom-left {
                left   : 0;
                bottom : 0;
            }
        }

