                @include break(medium) {
                    justify-content : center;
                }
            }

            img, svg {
                max-width     : 100%;
                max-height    : 372px;
                display       : block;
                width         : auto;
                height        : auto;
                border-radius : 0;

                @include break(s-small) {
                    width : 100%;
                    max-height    : 372px;
                }
            }
            svg {
                @include break(s-small) {
                    height    : 1000px;
                }
            }
        }
