    &__image {
        border-radius : 15px;
        display       : block;
        width         : 100%;
        height        : auto;

        &.no-mask {
            border-radius : 0;
        }
    }

    &__main-title {
        margin-bottom : 32px;
        text-align    : center;

        &-v4 {
            margin-bottom : 40px;
            @include break(medium) {
                margin-bottom : 32px;
            }
        }

        @include break(medium) {
            font-size   : 22px;
            line-height : 28px;
        }
    }

    &__content-wrapper {
        &.reverse {
            order : 2;
        }

        @include break(medium) {
            &-v5,
            &-v4 {
                &,
                &.reverse {
                    order : 2;
                }
            }
        }
        @include break(s-small) {
            &,
            &.reverse {
                order : 1;
            }
        }
    }

    &__subtitle {
        font-size     : 22px;
        line-height   : 28px;
        margin-bottom : 8px;
        @extend .styled-text;
    }

    &__title {
        margin-bottom : 16px;
        font-size     : 40px;
        line-height   : 48px;
        @include break(medium) {
            font-size   : 22px;
            line-height : 28px;
        }

        &-v3 {
            &.small {
                font-size     : 22px;
                line-height   : 28px;
                margin-bottom : 8px;
                @include break(medium) {
                    margin-bottom : 16px;
                }
            }
        }
    }

    &__text {
        @extend .a-tag;

        p, li {
            &:not(:last-child) {
                margin-bottom : 24px;
            }
        }

        ol,
        ul {
            &:not(:first-child) {
                margin-top : 24px;
            }

            &:not(:last-child) {
                margin-bottom : 24px;
            }
        }

        li {
            padding     : 0;
            font-family : $second_font;
            font-weight : 400;
            list-style  : inherit;
            position    : relative;
            font-size   : 16px;
            line-height : 24px;

            &::before {
                content             : '';
                display             : block;
                position            : absolute;
                left                : 0;
                top                 : 50%;
                transform           : translateY(-50%);
                background-color    : transparent;
                background-position : center;
                background-repeat   : no-repeat;
                border-radius       : 0;
            }
        }

        &.small-circle,
        &.small-hexagon {
            li {
                padding-left : 24px;
                font-size    : 15px;
                line-height  : 24px;

                &:not(:last-child) {
                    margin-bottom : 16px;
                }

