        h2, h3, h4, h5, h6 {
            &:not(:last-child) {
                margin-bottom : 16px;
            }
        }

        ol {
            list-style : decimal;
        }

        h2, h3, h4, h5, h6 {
            font-size   : 22px;
            line-height : 28px;

            &:not(:last-child) {
                margin-bottom : 8px;
            }

            @include break(desktop) {
                font-size : 18px;
            }
        }

        &-v5 {
            margin-top : 16px;

            * {
                color : $black;
            }

            p, li {
                &:not(:last-child) {
                    margin-bottom : 12px;
                }
            }
        }
    }

    &__button-wrapper {
        &:not(&-v5) {
            margin-top : 24px;
            @include break(s-small) {
                text-align : center;
                margin-top : 20px;
            }
        }

        &-v5 {
            margin-top : 16px;
        }
    }

    &__button {
        &:not(&-v5) {
            @extend .styled-btn;
        }

        &-v5 {
            font-size     : 15px;
            line-height   : 24px;
            color         : $purple;
            padding-right : 24px;
            font-family   : $third_font;
            font-weight   : 600;
            position      : relative;
            transition    : color .3s linear;
            display       : inline-block;

            &:hover {
                color : $dark;

                &::before {
                    background-image : url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M5 13L11 8.5L5 4' stroke='%2316213D' stroke-width='1.3' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E");
                }
            }

            &::before {
                content           : '';
                display           : block;
                position          : absolute;
                right             : 0;
                top               : 4px;
                width             : 16px;
                height            : 16px;
                background-image  : url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M5 13L11 8.5L5 4' stroke='%233B37E6' stroke-width='1.3' stroke-linecap='square' stroke-linejoin='bevel'/%3E%3C/svg%3E");
                background-repeat : no-repeat;
                transition        : background-image .3s linear;
            }
        }
    }
}